export enum Role {
  USER = 'user',
  ANORA = 'anora',
  SYSTEM = 'system'
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
}

export interface ChatState {
  messages: Message[];
  isThinking: boolean;
  isVoiceActive: boolean;
}

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { SYSTEM_PROMPT } from "../constants";

export class AnoraAI {
  private ai: GoogleGenAI;
  private chat: Chat;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    this.chat = this.ai.chats.create({
      model: 'gemini-2.5-flash',
      config: {
        systemInstruction: SYSTEM_PROMPT,
      },
    });
  }

  async sendMessage(message: string): Promise<string> {
    try {
      const response = await this.chat.sendMessage({ message });
      return response.text || "I apologize, Arjun, but I encountered an issue processing that request.";
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "Arjun, there seems to be a connection issue with my core systems. Please check your connectivity.";
    }
  }

  async *streamMessage(message: string) {
    try {
      const responseStream = await this.chat.sendMessageStream({ message });
      for await (const chunk of responseStream) {
        const response = chunk as GenerateContentResponse;
        yield response.text;
      }
    } catch (error) {
      console.error("Gemini Stream Error:", error);
      yield "I'm sorry Arjun, I lost the connection mid-thought.";
    }
  }
}

export const anoraService = new AnoraAI();

