export enum Role {
  OWNER = 'OWNER',
  PREMIUM = 'PREMIUM',
  USER = 'USER'
}

export enum SubscriptionTier {
  LIFETIME = 'LIFETIME',
  PRO = 'PRO',
  FREE = 'FREE'
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: Role;
  tier: SubscriptionTier;
  avatar?: string;
}

export interface Message {
  id: string;
  role: 'user' | 'anora' | 'system';
  content: string;
  timestamp: Date;
}

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { getSystemPrompt } from "../constants";
import { User, Role } from "../types";

export class AnoraAI {
  private ai: GoogleGenAI;
  private chat: Chat | null = null;
  private currentUser: User | null = null;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  initChat(user: User) {
    this.currentUser = user;
    const tools: any[] = [];

    // Enable grounding for Premium and Owner
    if (user.role === Role.OWNER || user.role === Role.PREMIUM) {
      tools.push({ googleSearch: {} });
      tools.push({ googleMaps: {} });
    }

    this.chat = this.ai.chats.create({
      model: 'gemini-2.5-flash',
      config: {
        systemInstruction: getSystemPrompt(user.name, user.role),
        tools: tools.length > 0 ? tools : undefined,
      },
    });
  }

  async *streamMessage(message: string) {
    if (!this.chat) throw new Error("Chat not initialized");

    try {
      const responseStream = await this.chat.sendMessageStream({ message });
      for await (const chunk of responseStream) {
        const response = chunk as GenerateContentResponse;
        yield response.text;
      }
    } catch (error) {
      console.error("Anora Stream Error:", error);
      yield "I'm sorry, I encountered a connection interruption.";
    }
  }

  async generateImage(prompt: string) {
    if (this.currentUser?.role !== Role.OWNER && this.currentUser?.role !== Role.PREMIUM) {
      return "Image generation is a Premium feature.";
    }
    const response = await this.ai.models.generateImages({
      model: 'imagen-4.0-generate-001',
      prompt,
      config: { numberOfImages: 1 }
    });
    return response.generatedImages[0].image.imageBytes;
  }
}

