import React, { useState } from 'react';
import { User, Role, SubscriptionTier } from '../types';
import { OWNER_EMAIL } from '../constants';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !name) return;

    setLoading(true);
    // Simulate API Auth
    setTimeout(() => {
      const isOwner = email.toLowerCase() === OWNER_EMAIL.toLowerCase();
      const user: User = {
        id: Math.random().toString(36).substr(2, 9),
        name: isOwner ? "Arjun Bharti Mina" : name,
        email: email,
        role: isOwner ? Role.OWNER : Role.USER,
        tier: isOwner ? SubscriptionTier.LIFETIME : SubscriptionTier.FREE
      };
      onLogin(user);
      setLoading(false);
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-black flex items-center justify-center p-6 bg-[radial-gradient(circle_at_center,_#111_0%,_#000_100%)]">
      <div className="w-full max-w-md space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
        <div className="text-center space-y-4">
          <div className="w-20 h-20 mx-auto rounded-3xl bg-gradient-to-br from-zinc-800 to-black border border-zinc-700/50 flex items-center justify-center shadow-2xl">
            <span className="text-4xl font-bold font-outfit text-zinc-200">A</span>
          </div>
          <div className="space-y-1">
            <h1 className="text-2xl font-bold font-outfit tracking-tight text-zinc-100">Welcome to Anora</h1>
            <p className="text-zinc-500 text-sm font-medium uppercase tracking-widest">Identify Yourself</p>
          </div>
        </div>

        <form onSubmit={handleLogin} className="bg-zinc-900/40 border border-zinc-800 p-8 rounded-[2rem] backdrop-blur-xl space-y-6">
          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2 px-1">Email Address</label>
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-zinc-200 focus:outline-none focus:ring-2 focus:ring-zinc-700/50 focus:border-zinc-600 transition-all placeholder:text-zinc-700"
                placeholder="Enter your email..."
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2 px-1">Display Name</label>
              <input
                type="text"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-zinc-200 focus:outline-none focus:ring-2 focus:ring-zinc-700/50 focus:border-zinc-600 transition-all placeholder:text-zinc-700"
                placeholder="How should I call you?"
              />
            </div>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-white text-black font-bold py-4 rounded-xl hover:bg-zinc-200 transition-all active:scale-[0.98] disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {loading ? (
              <div className="w-5 h-5 border-2 border-black/20 border-t-black rounded-full animate-spin"></div>
            ) : (
              "Initialize System"
            )}
          </button>

          <div className="pt-4 border-t border-zinc-800/50 text-center">
            <p className="text-[10px] text-zinc-600 font-medium uppercase tracking-widest leading-relaxed">
              System access restricted.<br/>Unauthorized attempts are logged.
            </p>
          </div>
        </form>
      </div>
    </div>
  );
};

