import { MessageList } from './components/MessageList';
import { VoiceIndicator } from './components/VoiceIndicator';
import { AuthScreen } from './components/AuthScreen';
import { PremiumBadge } from './components/PremiumBadge';

// Audio utility functions
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    anoraService.initChat(user);
    setMessages([{
      id: 'initial',
      role: 'anora',
      content: INITIAL_MESSAGE(user.name),
      timestamp: new Date()
    }]);
  };

  const handleSend = async (text: string) => {
    if (!text.trim() || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsThinking(true);

    let fullResponse = '';
    const assistantId = (Date.now() + 1).toString();

    setMessages(prev => [...prev, {
      id: assistantId,
      role: 'anora',
      content: '',
      timestamp: new Date()
    }]);

    try {
      const responseStream = anoraService.streamMessage(text);
      for await (const chunk of responseStream) {
        fullResponse += chunk;
        setMessages(prev => prev.map(m => 
          m.id === assistantId ? { ...m, content: fullResponse } : m
        ));
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsThinking(false);
    }
  };

  const toggleVoiceMode = async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(track => track.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }

    try {
      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) { int16[i] = inputData[i] * 32768; }
              const pcmData = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmData }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
          },
          onerror: (e) => console.error(e),
          onclose: () => setIsVoiceMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          systemInstruction: `You are Anora speaking to ${currentUser?.name}. Status: ${currentUser?.role}. Be helpful and warm.`
        }
      });
    } catch (err) {
      console.error(err);
      setIsVoiceMode(false);
    }
  };

  if (!currentUser) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  return (
    <div className="flex flex-col h-screen bg-black text-zinc-300 overflow-hidden font-inter selection:bg-zinc-800 selection:text-white">
      {/* Header */}
      <header className="flex items-center justify-between px-6 py-4 border-b border-zinc-900 bg-black/80 backdrop-blur-xl sticky top-0 z-20">
        <div className="flex items-center gap-4">
          <div className="w-11 h-11 rounded-[1.25rem] bg-gradient-to-br from-zinc-800 to-black border border-zinc-800 flex items-center justify-center shadow-lg transition-transform hover:scale-105 cursor-pointer">
            <span className="text-zinc-100 font-outfit font-bold text-xl tracking-tighter">A</span>
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-sm font-bold font-outfit text-zinc-100 uppercase tracking-[0.2em]">Anora</h1>
              <PremiumBadge role={currentUser.role} tier={currentUser.tier} />
            </div>
            <p className="text-[10px] text-zinc-500 font-medium uppercase tracking-widest mt-0.5">Core Interface 2.5</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <VoiceIndicator active={isVoiceMode} />
          <div className="flex items-center gap-3 pl-6 border-l border-zinc-800 hidden sm:flex">
            <div className="text-right">
              <p className="text-xs font-bold text-zinc-200 font-outfit leading-tight">{currentUser.name}</p>
              <p className="text-[9px] text-zinc-500 uppercase tracking-widest font-medium">Session ID: {currentUser.id.toUpperCase()}</p>
            </div>
            <div className="w-9 h-9 rounded-full bg-zinc-900 border border-zinc-800 flex items-center justify-center text-[10px] font-bold text-zinc-400 overflow-hidden">
               {currentUser.avatar ? <img src={currentUser.avatar} /> : currentUser.name.charAt(0)}
            </div>
          </div>
          <button 
            onClick={() => setCurrentUser(null)}
            className="p-2 text-zinc-600 hover:text-red-400 transition-colors"
            title="Terminate Session"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
          </button>
        </div>
      </header>

      {/* Main Chat Content */}
      <main className="flex-1 flex flex-col relative overflow-hidden bg-[radial-gradient(circle_at_50%_0%,_#0a0a0a_0%,_#000_100%)]">
        <MessageList messages={messages} isThinking={isThinking} />
      </main>

      {/* Input Area */}
      <footer className="p-4 sm:p-8 bg-gradient-to-t from-black via-black/95 to-transparent z-10">
        <div className="max-w-4xl mx-auto space-y-4">
          <div className="flex items-center gap-4">
            <button
              onClick={toggleVoiceMode}
              className={`p-4 rounded-2xl transition-all duration-500 group relative overflow-hidden shadow-xl ${
                isVoiceMode 
                  ? 'bg-blue-600 text-white ring-8 ring-blue-600/10' 
                  : 'bg-zinc-900 text-zinc-500 border border-zinc-800 hover:border-zinc-600 hover:text-zinc-200'
              }`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6 z-10 relative" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              </svg>
            </button>

            <div className="flex-1 relative group">
              <input
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isThinking ? "Thinking..." : "Communicate with Anora..."}
                className="w-full bg-zinc-900/40 border border-zinc-800 text-zinc-100 rounded-[1.5rem] px-8 py-5 focus:outline-none focus:ring-4 focus:ring-zinc-800/20 focus:border-zinc-700 transition-all placeholder:text-zinc-700 font-medium text-base shadow-2xl backdrop-blur-md"
              />
              <button
                disabled={!inputValue.trim() || isThinking}
                onClick={() => handleSend(inputValue)}
                className="absolute right-4 top-1/2 -translate-y-1/2 p-3 bg-white text-black rounded-xl hover:bg-zinc-200 disabled:opacity-30 transition-all active:scale-95 shadow-lg"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
                </svg>
              </button>
            </div>
          </div>

          <div className="flex justify-between items-center px-2">
             <div className="flex gap-4 text-[9px] font-bold text-zinc-700 uppercase tracking-widest">
               <span className="flex items-center gap-1.5"><div className="w-1 h-1 bg-green-500 rounded-full animate-pulse"></div> System Ready</span>
               <span>Encryption Active</span>
