export enum Role {
  OWNER = 'OWNER',
  PREMIUM = 'PREMIUM',
  USER = 'USER'
}

export enum SubscriptionTier {
  LIFETIME = 'LIFETIME',
  PRO = 'PRO',
  FREE = 'FREE'
}

export interface GroundingSource {
  title?: string;
  uri?: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: Role;
