        <div className="flex items-center gap-4">
          <div className="w-11 h-11 rounded-[1.25rem] bg-gradient-to-br from-zinc-800 to-black border border-zinc-800 flex items-center justify-center shadow-lg transition-transform hover:scale-105 cursor-pointer">
            <span className="text-zinc-100 font-outfit font-bold text-xl tracking-tighter">A</span>
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-sm font-bold font-outfit text-zinc-100 uppercase tracking-[0.2em]">Anora</h1>
              <PremiumBadge role={currentUser.role} tier={currentUser.tier} />
            </div>
            <p className="text-[10px] text-zinc-500 font-medium uppercase tracking-widest mt-0.5">Core Interface 2.5</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <VoiceIndicator active={isVoiceMode} />

          {(currentUser.role === Role.OWNER || currentUser.role === Role.PREMIUM) && (
            <button 
              onClick={() => setIsCommandCenterOpen(true)}
              className="p-2.5 rounded-xl bg-zinc-900 border border-zinc-800 text-zinc-400 hover:text-white hover:border-zinc-700 transition-all shadow-md group"
              title="Creative Command Center"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5 group-hover:rotate-12 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
              </svg>
            </button>
          )}

          <div className="flex items-center gap-3 pl-6 border-l border-zinc-800 hidden sm:flex">
            <div className="text-right">
              <p className="text-xs font-bold text-zinc-200 font-outfit leading-tight">{currentUser.name}</p>
              <p className="text-[9px] text-zinc-500 uppercase tracking-widest font-medium">Verified User</p>
            </div>
            <div className="w-9 h-9 rounded-full bg-zinc-900 border border-zinc-800 flex items-center justify-center text-[10px] font-bold text-zinc-400 overflow-hidden">
               {currentUser.avatar ? <img src={currentUser.avatar} /> : currentUser.name.charAt(0)}
            </div>
          </div>

          <button 
            onClick={() => {
              setCurrentUser(null);
              setMessages([]);
            }}
            className="p-2 text-zinc-600 hover:text-red-400 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
          </button>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden bg-[radial-gradient(circle_at_50%_0%,_#0a0a0a_0%,_#000_100%)]">
        <MessageList messages={messages} isThinking={isThinking} ownerName={currentUser.name} />
      </main>

      <footer className="p-4 sm:p-8 bg-gradient-to-t from-black via-black/95 to-transparent z-10">
        <div className="max-w-4xl mx-auto space-y-4">
          {pendingImages.length > 0 && (
            <div className="flex gap-2 p-2 bg-zinc-900/50 rounded-xl border border-zinc-800 animate-in slide-in-from-bottom-2">
              {pendingImages.map((img, i) => (
                <div key={i} className="relative group">
                  <img src={img} className="w-16 h-16 object-cover rounded-lg border border-zinc-700" />
                  <button 
                    onClick={() => setPendingImages(prev => prev.filter((_, idx) => idx !== i))}
                    className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
              ))}
            </div>
