            >
              <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6 z-10 relative" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              </svg>
            </button>

            <div className="flex-1 relative group">
              <input
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isThinking ? "Anora is processing..." : "Speak your intent..."}
                className="w-full bg-zinc-900/40 border border-zinc-800 text-zinc-100 rounded-[1.5rem] px-8 py-5 focus:outline-none focus:ring-4 focus:ring-zinc-800/20 focus:border-zinc-700 transition-all placeholder:text-zinc-700 font-medium text-base shadow-2xl backdrop-blur-md"
              />
              <button
                disabled={(!inputValue.trim() && pendingImages.length === 0) || isThinking}
                onClick={() => handleSend(inputValue)}
                className="absolute right-4 top-1/2 -translate-y-1/2 p-3 bg-white text-black rounded-xl hover:bg-zinc-200 disabled:opacity-30 transition-all active:scale-95 shadow-lg"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
                </svg>
              </button>
            </div>
          </div>

          <div className="flex justify-between items-center px-2">
             <div className="flex gap-4 text-[9px] font-bold text-zinc-700 uppercase tracking-widest">
               <span className="flex items-center gap-1.5"><div className="w-1 h-1 bg-green-500 rounded-full animate-pulse"></div> Secure Session</span>
               <span>Grounding Verified</span>
             </div>
             <p className="text-[10px] text-zinc-600 font-medium uppercase tracking-[0.2em] italic">
               Assistant for {currentUser.name}
             </p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

