import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier } from '../types';
import { OWNER_EMAIL } from '../constants';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const getUsers = (): User[] => {
    const data = localStorage.getItem('anora_users_db');
    return data ? JSON.parse(data) : [];
  };

  const saveUser = (user: User) => {
    const users = getUsers();
    users.push(user);
    localStorage.setItem('anora_users_db', JSON.stringify(users));
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    setTimeout(() => {
      const users = getUsers();
      const emailLower = email.toLowerCase();

      if (isLogin) {
        const found = users.find(u => u.email.toLowerCase() === emailLower && u.password === password);
        // Special case for owner hardcoded check if DB is empty or for first-time setup
        if (emailLower === OWNER_EMAIL && !found) {
           const ownerUser: User = {
            id: 'owner_root',
            name: "Arjun Bharti Mina",
            email: OWNER_EMAIL,
            password: password || 'admin', // Default if not found
            role: Role.OWNER,
            tier: SubscriptionTier.LIFETIME,
            preferences: { accentColor: '#3b82f6', aiMood: 'CALM', voiceName: 'Kore' },
            createdAt: new Date().toISOString()
          };
          saveUser(ownerUser);
          onLogin(ownerUser);
        } else if (found) {
          onLogin(found);
        } else {
          setError('Invalid email or password.');
        }
      } else {
        // Sign Up
        if (password !== confirmPassword) {
          setError('Passwords do not match.');
        } else if (users.some(u => u.email.toLowerCase() === emailLower)) {
          setError('User already exists.');
        } else {
          const isOwner = emailLower === OWNER_EMAIL;
          const newUser: User = {
            id: Math.random().toString(36).substr(2, 9),
            name: isOwner ? "Arjun Bharti Mina" : name,
            email: emailLower,
            password: password,
            role: isOwner ? Role.OWNER : Role.USER,
            tier: isOwner ? SubscriptionTier.LIFETIME : SubscriptionTier.FREE,
            preferences: { accentColor: '#3f3f46', aiMood: 'CALM', voiceName: 'Kore' },
            createdAt: new Date().toISOString()
          };
          saveUser(newUser);
          onLogin(newUser);
        }
      }
      setLoading(false);
    }, 1200);
  };

  return (
    <div className="min-h-screen bg-black flex items-center justify-center p-6 bg-[radial-gradient(circle_at_center,_#111_0%,_#000_100%)]">
      <div className="w-full max-w-md space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-1000">
        <div className="text-center space-y-4">
          <div className="w-20 h-20 mx-auto rounded-3xl bg-gradient-to-br from-zinc-800 to-black border border-zinc-700/50 flex items-center justify-center shadow-2xl relative">
             <div className="absolute inset-0 bg-blue-500/10 animate-pulse rounded-3xl"></div>
            <span className="text-4xl font-bold font-outfit text-zinc-200 relative z-10">A</span>
          </div>
          <div className="space-y-1">
            <h1 className="text-2xl font-bold font-outfit tracking-tight text-zinc-100">Anora Interface</h1>
            <p className="text-zinc-500 text-sm font-medium uppercase tracking-widest">{isLogin ? 'Welcome Back' : 'Create Credentials'}</p>
          </div>
        </div>

        <form onSubmit={handleAuth} className="bg-zinc-900/40 border border-zinc-800 p-8 rounded-[2.5rem] backdrop-blur-xl space-y-5 shadow-2xl">
          <div className="flex bg-black/40 p-1 rounded-2xl border border-zinc-800 mb-2">
            <button 
              type="button"
              onClick={() => setIsLogin(true)}
              className={`flex-1 py-2 text-xs font-bold uppercase tracking-widest rounded-xl transition-all ${isLogin ? 'bg-zinc-800 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
            >
              Login
            </button>
            <button 
              type="button"
              onClick={() => setIsLogin(false)}
              className={`flex-1 py-2 text-xs font-bold uppercase tracking-widest rounded-xl transition-all ${!isLogin ? 'bg-zinc-800 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
            >
              Sign Up
            </button>
          </div>

          {error && <p className="text-red-400 text-[10px] font-bold uppercase tracking-widest text-center animate-bounce">{error}</p>}

          <div className="space-y-4">
            {!isLogin && (
              <div>
                <label className="block text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2 px-1">Display Name</label>
                <input
                  type="text"
                  required
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-zinc-200 focus:outline-none focus:ring-2 focus:ring-zinc-700/50 transition-all"
                  placeholder="Enter name..."
                />
              </div>
            )}
            <div>
              <label className="block text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2 px-1">Email</label>
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-zinc-200 focus:outline-none focus:ring-2 focus:ring-zinc-700/50 transition-all"
                placeholder="email@example.com"
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2 px-1">Password</label>
              <input
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-zinc-200 focus:outline-none focus:ring-2 focus:ring-zinc-700/50 transition-all"
                placeholder="••••••••"
              />
            </div>
            {!isLogin && (
              <div>
                <label className="block text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2 px-1">Verify Password</label>
                <input
                  type="password"
                  required
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="w-full bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-zinc-200 focus:outline-none focus:ring-2 focus:ring-zinc-700/50 transition-all"
                  placeholder="••••••••"
                />
              </div>
            )}
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-white text-black font-bold py-4 rounded-xl hover:bg-zinc-200 transition-all active:scale-[0.98] disabled:opacity-50 flex items-center justify-center gap-2 mt-4"
          >
            {loading ? <div className="w-5 h-5 border-2 border-black/20 border-t-black rounded-full animate-spin"></div> : isLogin ? "Secure Entry" : "Create Account"}
          </button>

          <p className="text-[9px] text-zinc-600 text-center uppercase tracking-widest leading-relaxed mt-4">
            {email.toLowerCase() === OWNER_EMAIL ? 'OWNER ACCESS DETECTED' : 'STANDARD ENCRYPTION ACTIVE'}
          </p>
        </form>
      </div>
    </div>
  );
};

