import React, { useState } from 'react';
import { User, Reminder, Note, MemoryEntry } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  isOpen: boolean;
  onClose: () => void;
}

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, isOpen, onClose }) => {
  const [tab, setTab] = useState<'REMINDERS' | 'NOTES' | 'MEMORY'>('REMINDERS');
  const [newItem, setNewItem] = useState('');

  if (!isOpen) return null;

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };
    if (tab === 'REMINDERS') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, time: new Date().toLocaleTimeString(), completed: false });
    } else if (tab === 'NOTES') {
      updated.notes.push({ id: Date.now().toString(), title: 'New Note', content: newItem, timestamp: new Date().toISOString() });
    } else {
      updated.memory.push({ id: Date.now().toString(), fact: newItem, category: 'general', timestamp: new Date().toISOString() });
    }
    onUpdate(updated);
    setNewItem('');
  };

  const removeItem = (id: string) => {
    const updated = { ...user };
    if (tab === 'REMINDERS') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (tab === 'NOTES') updated.notes = updated.notes.filter(i => i.id !== id);
    if (tab === 'MEMORY') updated.memory = updated.memory.filter(i => i.id !== id);
    onUpdate(updated);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-end p-6 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
      <div className="w-full max-w-md h-full bg-zinc-900 border-l border-zinc-800 flex flex-col shadow-2xl overflow-hidden rounded-[2rem]">
        <div className="p-8 border-b border-zinc-800 flex items-center justify-between">
          <h2 className="text-xl font-bold font-outfit text-white">Neural Hub</h2>
          <button onClick={onClose} className="p-2 text-zinc-500 hover:text-white"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
        </div>

        <div className="flex bg-black/40 p-1 mx-6 my-4 rounded-xl border border-zinc-800">
          {(['REMINDERS', 'NOTES', 'MEMORY'] as const).map(t => (
            <button key={t} onClick={() => setTab(t)} className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-widest rounded-lg transition-all ${tab === t ? 'bg-zinc-800 text-white' : 'text-zinc-500'}`}>{t}</button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          <div className="flex gap-2">
            <input 
              value={newItem}
              onChange={e => setNewItem(e.target.value)}
              placeholder={`Add new ${tab.toLowerCase()}...`}
              className="flex-1 bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-1 focus:ring-zinc-700"
            />
            <button onClick={addItem} className="px-4 bg-white text-black rounded-xl font-bold">+</button>
          </div>

          <div className="space-y-3">
            {tab === 'REMINDERS' && user.reminders.map(r => (
              <div key={r.id} className="flex items-center justify-between p-4 bg-zinc-800/50 rounded-2xl border border-zinc-800 group">
                <span className="text-sm text-zinc-200">{r.text}</span>
                <button onClick={() => removeItem(r.id)} className="text-zinc-600 hover:text-red-400">×</button>
              </div>
            ))}
            {tab === 'NOTES' && user.notes.map(n => (
              <div key={n.id} className="p-4 bg-zinc-800/50 rounded-2xl border border-zinc-800">
                <div className="flex justify-between mb-1">
                  <p className="text-[10px] text-zinc-500 uppercase font-bold">{new Date(n.timestamp).toLocaleDateString()}</p>
                  <button onClick={() => removeItem(n.id)} className="text-zinc-600">×</button>
                </div>
                <p className="text-sm text-zinc-200">{n.content}</p>
              </div>
            ))}
            {tab === 'MEMORY' && user.memory.map(m => (
              <div key={m.id} className="flex items-center justify-between p-4 bg-zinc-800/50 rounded-2xl border border-zinc-800">
                <span className="text-sm text-zinc-200 italic">"{m.fact}"</span>
                <button onClick={() => removeItem(m.id)} className="text-zinc-600 hover:text-red-400">×</button>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

