          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name),
          timestamp: new Date()
        }]);
      }
    } else {
      localStorage.removeItem('anora_session');
      localStorage.removeItem('anora_history');
    }
  }, [currentUser]);

  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem('anora_history', JSON.stringify(messages));
    }
  }, [messages]);

  const playTTS = async (text: string) => {
    if (!currentUser?.preferences.autoRead) return;
    try {
      const base64 = await anoraService.speak(text, currentUser.preferences.voiceName);
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const buffer = await decodeAudioData(decode(base64), audioCtx, 24000, 1);
      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.destination);
      source.start();
    } catch (err) {
      console.error("TTS Error:", err);
    }
  };

  const handleSend = async (text: string) => {
    if ((!text.trim() && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      const response = await anoraService.sendMessageWithVision(text, userMsg.images || []);
      const assistantId = (Date.now() + 1).toString();

      setMessages(prev => [...prev, {
        id: assistantId,
        role: 'anora',
        content: response.text || "I apologize, but I couldn't process that.",
        sources: response.sources,
        timestamp: new Date()
      }]);

      if (currentUser.preferences.autoRead) {
        playTTS(response.text);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsThinking(false);
    }
  };

  const toggleVoiceMode = async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(track => track.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }

    try {
      setIsVoiceMode(true);
      // Corrected GoogleGenAI initialization with named parameter.
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              // Directly use the session from the resolved promise and send RealtimeInput.
              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => audioSourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) {
              for (const source of audioSourcesRef.current.values()) {
                source.stop();
                audioSourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error(e),
          onclose: () => setIsVoiceMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `You are Anora in voice mode. User is ${currentUser?.name}. Current mood: ${currentUser?.preferences.aiMood}.`
        }
      });
    } catch (err) {
      console.error(err);
      setIsVoiceMode(false);
    }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const accentColor = currentUser.preferences.accentColor;

  return (
    <div className="flex flex-col h-screen bg-black text-zinc-300 overflow-hidden font-inter selection:bg-zinc-800 selection:text-white transition-all duration-700">
      <style>{`
        .accent-border { border-color: ${accentColor}40 !important; }
        .accent-ring { --tw-ring-color: ${accentColor}40 !important; }
        .accent-text { color: ${accentColor} !important; }
        .accent-bg { background-color: ${accentColor} !important; }
        .accent-bg-soft { background-color: ${accentColor}15 !important; }
      `}</style>

      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <header className="flex items-center justify-between px-6 py-4 border-b border-zinc-900 bg-black/80 backdrop-blur-xl sticky top-0 z-20">
        <div className="flex items-center gap-4">
          <AnoraLogo size={48} color={accentColor} />
          <div className="hidden sm:block">
            <div className="flex items-center gap-2">
              <h1 className="text-sm font-bold font-outfit text-zinc-100 uppercase tracking-[0.2em]">Anora</h1>
              <PremiumBadge role={currentUser.role} tier={currentUser.tier} />
            </div>
            <p className="text-[10px] text-zinc-500 font-medium uppercase tracking-widest mt-0.5 opacity-60">Neural v2.5.5</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <VoiceIndicator active={isVoiceMode} />

          <div className="flex items-center gap-2 p-1 bg-zinc-900/50 rounded-2xl border border-zinc-800 shadow-lg">
            <button onClick={() => setIsHubOpen(true)} className="p-2.5 rounded-xl text-zinc-400 hover:text-white hover:bg-zinc-800 transition-all" title="Neural Hub">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
            </button>
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-2.5 rounded-xl text-zinc-400 hover:text-white hover:bg-zinc-800 transition-all" title="Creative Studio">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </button>
            <button onClick={() => setIsProfileOpen(true)} className="flex items-center gap-3 p-1 pl-3 border-l border-zinc-800 group transition-all">
              <div className="text-right hidden md:block">
                <p className="text-[10px] font-bold text-zinc-200 font-outfit uppercase leading-tight">{currentUser.name.split(' ')[0]}</p>
                <p className="text-[8px] text-zinc-500 uppercase tracking-tighter">Sync Active</p>
              </div>
              <div className="w-8 h-8 rounded-full bg-zinc-800 border accent-border flex items-center justify-center text-[10px] font-bold text-zinc-400 overflow-hidden shadow-inner group-hover:scale-105 transition-transform">
                 {currentUser.avatar ? <img src={currentUser.avatar} alt="Avatar" /> : currentUser.name.charAt(0)}
              </div>
            </button>
          </div>

          <button onClick={() => setCurrentUser(null)} className="p-2 text-zinc-600 hover:text-red-500 transition-colors">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
          </button>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden bg-[radial-gradient(circle_at_50%_0%,_#0a0a0a_0%,_#000_100%)]">
        <MessageList messages={messages} isThinking={isThinking} ownerName={currentUser.name} />
      </main>

      <footer className="p-4 sm:p-8 bg-gradient-to-t from-black via-black/95 to-transparent z-10">
        <div className="max-w-4xl mx-auto space-y-4">
          <div className="flex items-center gap-4">
            <button onClick={() => fileInputRef.current?.click()} className="p-4 rounded-[1.5rem] bg-zinc-900 text-zinc-500 border border-zinc-800 hover:border-zinc-700 hover:text-white transition-all shadow-lg" title="Neural Vision">
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M5 20h14a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
              <input type="file" ref={fileInputRef} hidden multiple accept="image/*" onChange={e => {
                const files = e.target.files;
                if (files) Array.from(files).forEach(f => {
                  const reader = new FileReader();
                  // Cast the reader result to string to match expectations.
                  reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]);
                  reader.readAsDataURL(f);
                });
              }} />
            </button>

            <button onClick={toggleVoiceMode} className={`p-4 rounded-[1.5rem] transition-all duration-500 group relative shadow-xl ${isVoiceMode ? 'bg-blue-600 text-white ring-8 ring-blue-600/10' : 'bg-zinc-900 text-zinc-500 border border-zinc-800 hover:border-zinc-700'}`}>
              <svg className="w-6 h-6 z-10 relative" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            </button>

            <div className="flex-1 relative group">
              <input
                type="text"
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isThinking ? "Processing..." : `Synchronized with ${currentUser.name.split(' ')[0]}...`}
                className="w-full bg-zinc-900/40 border border-zinc-800 text-zinc-100 rounded-[2rem] px-8 py-5 focus:outline-none focus:ring-4 accent-ring focus:border-zinc-600 transition-all placeholder:text-zinc-700 text-base shadow-2xl backdrop-blur-md"
              />
              <button disabled={!inputValue.trim() && pendingImages.length === 0 || isThinking} onClick={() => handleSend(inputValue)} className="absolute right-4 top-1/2 -translate-y-1/2 p-3 bg-white text-black rounded-xl hover:bg-zinc-200 disabled:opacity-30 transition-all active:scale-95 shadow-lg">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>
              </button>
            </div>
          </div>

          <div className="flex justify-between items-center px-4">
             <div className="flex gap-4 text-[9px] font-bold text-zinc-700 uppercase tracking-widest">
               <span className="flex items-center gap-1.5"><div className="w-1 h-1 bg-green-500 rounded-full animate-pulse"></div> Local Core Stable</span>
               <span className="accent-text opacity-70">Grounding Ver. 2</span>
             </div>
             <p className="text-[10px] text-zinc-600 font-medium uppercase tracking-[0.2em] italic">Intelligence Exclusively for Arjun</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

