import React, { useState } from 'react';
import { User, Reminder, Note, MemoryEntry, Project } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  isOpen: boolean;
  onClose: () => void;
}

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, isOpen, onClose }) => {
  const [tab, setTab] = useState<'REMINDERS' | 'NOTES' | 'MEMORY' | 'PROJECTS'>('PROJECTS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');

  if (!isOpen) return null;

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };
    if (tab === 'REMINDERS') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, time: new Date().toLocaleTimeString(), completed: false });
    } else if (tab === 'NOTES') {
      updated.notes.push({ id: Date.now().toString(), title: 'New Note', content: newItem, timestamp: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc || 'No description', status: 'ACTIVE' });
    } else {
      updated.memory.push({ id: Date.now().toString(), fact: newItem, category: 'general', timestamp: new Date().toISOString() });
    }
    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string) => {
    const updated = { ...user };
    if (tab === 'REMINDERS') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (tab === 'NOTES') updated.notes = updated.notes.filter(i => i.id !== id);
    if (tab === 'MEMORY') updated.memory = updated.memory.filter(i => i.id !== id);
    if (tab === 'PROJECTS') updated.projects = updated.projects.filter(i => i.id !== id);
    onUpdate(updated);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-end p-6 bg-black/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="w-full max-w-lg h-full bg-zinc-900 border-l border-zinc-800/50 flex flex-col shadow-2xl overflow-hidden rounded-[3rem]">

        {/* Hub Header */}
        <div className="p-10 border-b border-zinc-800/50 flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold font-outfit text-white">Neural Hub</h2>
            <p className="text-[10px] text-zinc-600 uppercase tracking-[0.3em] font-bold mt-1.5">Asset & Logic Storage</p>
          </div>
          <button onClick={onClose} className="p-3 text-zinc-500 hover:text-white hover:bg-white/5 rounded-2xl transition-all">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        {/* Tab Navigation */}
        <div className="flex bg-black/60 p-1.5 mx-8 mt-6 rounded-2xl border border-zinc-800/50">
          {(['PROJECTS', 'REMINDERS', 'NOTES', 'MEMORY'] as const).map(t => (
            <button key={t} onClick={() => setTab(t)} className={`flex-1 py-3 text-[9px] font-bold uppercase tracking-widest rounded-xl transition-all duration-500 ${tab === t ? 'bg-zinc-800 text-white shadow-lg' : 'text-zinc-600 hover:text-zinc-300'}`}>{t}</button>
          ))}
        </div>

        {/* List Content */}
        <div className="flex-1 overflow-y-auto p-10 space-y-8">

          {/* Quick Input Area */}
          <div className="space-y-3 bg-black/20 p-6 rounded-[2rem] border border-zinc-800/50">
            <div className="flex gap-2">
              <input 
                value={newItem}
                onChange={e => setNewItem(e.target.value)}
                placeholder={`Add new ${tab.toLowerCase().slice(0, -1)}...`}
                className="flex-1 bg-zinc-900/50 border border-zinc-800 rounded-2xl px-5 py-4 text-sm focus:outline-none focus:ring-1 focus:ring-zinc-700 transition-all"
              />
              <button onClick={addItem} className="px-6 bg-white text-black rounded-2xl font-bold hover:bg-zinc-200 transition-all">+</button>
            </div>
            {tab === 'PROJECTS' && (
              <input 
                value={newDesc}
                onChange={e => setNewDesc(e.target.value)}
                placeholder="Short description..."
                className="w-full bg-zinc-900/50 border border-zinc-800 rounded-2xl px-5 py-4 text-xs focus:outline-none focus:ring-1 focus:ring-zinc-700 transition-all"
              />
            )}
          </div>

          <div className="space-y-4">
            {tab === 'PROJECTS' && (user.projects || []).map(p => (
              <div key={p.id} className="p-6 bg-zinc-800/30 rounded-[2rem] border border-zinc-800/50 group hover:border-zinc-700 transition-all">
                <div className="flex justify-between items-start mb-2">
                  <h4 className="text-sm font-bold text-white uppercase tracking-wider">{p.name}</h4>
                  <button onClick={() => removeItem(p.id)} className="text-zinc-700 hover:text-red-400 p-1">×</button>
                </div>
                <p className="text-[11px] text-zinc-500 leading-relaxed italic">"{p.description}"</p>
                <div className="mt-4 flex gap-2">
                   <span className="text-[8px] px-2 py-0.5 bg-green-500/10 text-green-500 border border-green-500/20 rounded uppercase font-bold">In-Context</span>
                </div>
              </div>
            ))}

            {tab === 'REMINDERS' && user.reminders.map(r => (
              <div key={r.id} className="flex items-center justify-between p-5 bg-zinc-800/20 rounded-2xl border border-zinc-800/50 group">
                <div className="flex items-center gap-4">
                  <div className="w-1.5 h-1.5 bg-white/20 rounded-full"></div>
                  <span className="text-sm text-zinc-300 font-medium">{r.text}</span>
                </div>
                <button onClick={() => removeItem(r.id)} className="text-zinc-700 hover:text-red-400 px-2 text-xl">×</button>
              </div>
            ))}

            {tab === 'NOTES' && user.notes.map(n => (
              <div key={n.id} className="p-6 bg-zinc-800/20 rounded-[2rem] border border-zinc-800/50">
                <div className="flex justify-between mb-2">
                  <p className="text-[9px] text-zinc-600 uppercase font-bold tracking-widest">{new Date(n.timestamp).toLocaleDateString()}</p>
                  <button onClick={() => removeItem(n.id)} className="text-zinc-700 text-xl hover:text-red-400">×</button>
                </div>
                <p className="text-sm text-zinc-300 leading-relaxed">{n.content}</p>
              </div>
            ))}

            {tab === 'MEMORY' && user.memory.map(m => (
              <div key={m.id} className="flex items-center justify-between p-6 bg-black/40 rounded-[2rem] border border-zinc-800/50 border-l-white/20">
                <div>
                  <p className="text-[11px] text-zinc-200 font-medium italic">"{m.fact}"</p>
                  <p className="text-[8px] text-zinc-600 mt-2 uppercase tracking-widest font-bold">Stored Fact</p>
                </div>
                <button onClick={() => removeItem(m.id)} className="text-zinc-800 hover:text-red-500 text-xl px-2">×</button>
              </div>
            ))}
          </div>
        </div>

        {/* Statistics Area */}
        <div className="p-8 border-t border-zinc-800/50 bg-black/40">
           <div className="flex justify-around items-center opacity-60">
              <div className="text-center">
                 <p className="text-xl font-bold text-white font-outfit">{(user.memory || []).length}</p>
                 <p className="text-[8px] text-zinc-600 uppercase tracking-widest font-bold">Facts</p>
              </div>
              <div className="w-px h-8 bg-zinc-800"></div>
              <div className="text-center">
                 <p className="text-xl font-bold text-white font-outfit">{(user.projects || []).length}</p>
                 <p className="text-[8px] text-zinc-600 uppercase tracking-widest font-bold">Projects</p>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

