// Audio utility functions
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

function createBlob(data: Float32Array): Blob {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('anora_history');
    return saved ? JSON.parse(saved) : [];
  });
  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      const savedDb = localStorage.getItem('anora_users_db');
      const users: User[] = savedDb ? JSON.parse(savedDb) : [];
      const updatedUsers = users.map((u: User) => u.id === currentUser.id ? currentUser : u);
      localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));

      anoraService.initChat(currentUser);
      if (messages.length === 0) {
        setMessages([{
          id: 'initial',
          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name, currentUser.role),
          timestamp: new Date()
        }]);
      }
    } else {
      localStorage.removeItem('anora_session');
      localStorage.removeItem('anora_history');
    }
  }, [currentUser]);

  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem('anora_history', JSON.stringify(messages));
    }
  }, [messages]);

  const purgeNeuralLinks = () => {
    if (confirm('Sovereign Purge initialized. Clear all conversation records?')) {
      setMessages([{
        id: 'initial',
        role: 'anora',
        content: INITIAL_MESSAGE(currentUser!.name, currentUser!.role),
        timestamp: new Date()
      }]);
      localStorage.removeItem('anora_history');
    }
  };

  const playTTS = async (text: string) => {
    if (!currentUser?.preferences.autoRead) return;
    try {
      const base64 = await anoraService.speak(text, currentUser.preferences.voiceName);
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const buffer = await decodeAudioData(decode(base64), audioCtx, 24000, 1);
      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.destination);
      source.start();
    } catch (err) {
      console.error("TTS Error:", err);
    }
  };

  const handleSend = async (text: string) => {
    if ((!text.trim() && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      const response = await anoraService.sendMessageWithVision(text, userMsg.images || []);
      const assistantId = (Date.now() + 1).toString();

      setMessages(prev => [...prev, {
        id: assistantId,
        role: 'anora',
        content: response.text || "I apologize, but I couldn't process that.",
        sources: response.sources,
        timestamp: new Date()
      }]);

      if (currentUser.preferences.autoRead) {
        playTTS(response.text);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsThinking(false);
    }
  };

  const toggleVoiceMode = async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(track => track.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }

    try {
      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => audioSourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) {
              for (const source of audioSourcesRef.current.values()) {
                source.stop();
                audioSourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error(e),
          onclose: () => setIsVoiceMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `You are Anora in voice mode. User is ${currentUser?.name}. Current mood: ${currentUser?.preferences.aiMood}.`
        }
      });
    } catch (err) {
      console.error(err);
      setIsVoiceMode(false);
    }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const accentColor = currentUser.preferences.accentColor;
  const isOwner = currentUser.email.toLowerCase() === OWNER_EMAIL;

  return (
    <div className={`flex flex-col h-screen bg-black text-zinc-300 overflow-hidden font-inter selection:bg-zinc-800 selection:text-white transition-all duration-700 ${isOwner ? 'ring-inset ring-2 ring-amber-500/10' : ''}`}>
      <style>{`
        .accent-border { border-color: ${accentColor}40 !important; }
        .accent-ring { --tw-ring-color: ${accentColor}40 !important; }
        .accent-text { color: ${accentColor} !important; }
        .accent-bg { background-color: ${accentColor} !important; }
        .accent-bg-soft { background-color: ${accentColor}15 !important; }
        .owner-glow { text-shadow: 0 0 10px rgba(245, 158, 11, 0.3); }
      `}</style>

      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <header className="flex items-center justify-between px-8 py-6 border-b border-zinc-900 bg-black/80 backdrop-blur-3xl sticky top-0 z-20">
        <div className="flex items-center gap-6">
          <AnoraLogo size={52} color={accentColor} />
          <div className="hidden md:block">
            <div className="flex items-center gap-2">
              <PremiumBadge role={currentUser.role} tier={currentUser.tier} />
              <span className={`text-[9px] font-bold uppercase tracking-[0.4em] opacity-40 ml-2 ${isOwner ? 'text-amber-500' : 'text-zinc-500'}`}>Sovereign OS v3.0</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-5">
          {isOwner && (
            <button onClick={purgeNeuralLinks} className="p-2.5 text-zinc-700 hover:text-amber-500 hover:bg-amber-500/5 rounded-xl transition-all" title="Purge Conversation">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </button>
          )}

          <VoiceIndicator active={isVoiceMode} />

