                  className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-6 py-4 text-zinc-200 focus:outline-none focus:ring-2 focus:ring-white/10 transition-all placeholder:text-zinc-800 text-sm"
                  placeholder="name@domain.com"
                />
              </div>

              <div className="animate-in slide-in-from-top-2 duration-500">
                <label className="block text-[9px] font-bold text-zinc-600 uppercase tracking-widest mb-2 ml-1">Decryption Key</label>
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-6 py-4 text-zinc-200 focus:outline-none focus:ring-2 focus:ring-white/10 transition-all placeholder:text-zinc-800 text-sm"
                  placeholder="••••••••"
                />
              </div>

              {!isLogin && (
                <div className="animate-in slide-in-from-top-2 duration-600">
                  <label className="block text-[9px] font-bold text-zinc-600 uppercase tracking-widest mb-2 ml-1">Verify Key</label>
                  <input
                    type="password"
                    required
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-6 py-4 text-zinc-200 focus:outline-none focus:ring-2 focus:ring-white/10 transition-all placeholder:text-zinc-800 text-sm"
                    placeholder="••••••••"
                  />
                </div>
              )}
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-white text-black font-bold py-5 rounded-2xl hover:bg-zinc-200 transition-all active:scale-[0.98] disabled:opacity-50 flex items-center justify-center gap-3 shadow-2xl mt-8 overflow-hidden relative group/btn"
            >
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent -translate-x-full group-hover/btn:translate-x-full transition-transform duration-1000"></div>
              {loading ? (
                <div className="flex items-center gap-3">
                  <div className="w-4 h-4 border-2 border-black/20 border-t-black rounded-full animate-spin"></div>
                  <span className="text-[10px] uppercase tracking-[0.2em]">Synchronizing...</span>
                </div>
              ) : (
                <span className="text-[10px] uppercase tracking-[0.3em]">{isLogin ? "Neural Sync" : "Establish Link"}</span>
              )}
            </button>
          </form>
        </div>

        <p className="text-zinc-800 text-[8px] text-center font-bold uppercase tracking-[0.6em] mt-12 opacity-50">
          Secure Core v3.5 // Protected by Anora Architecture
        </p>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob as GenAIBlob } from '@google/genai';
import { Message, Role, User, SubscriptionTier, Persona } from './types';
import { INITIAL_MESSAGE, OWNER_EMAIL } from './constants';
import { anoraService } from './services/geminiService';
import { MessageList } from './components/MessageList';
import { VoiceIndicator } from './components/VoiceIndicator';
