// Audio utility functions
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

function createBlob(data: Float32Array): GenAIBlob {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('anora_history');
    return saved ? JSON.parse(saved) : [];
  });
  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      const savedDb = localStorage.getItem('anora_users_db');
      const users: User[] = savedDb ? JSON.parse(savedDb) : [];
      const updatedUsers = users.map((u: User) => u.id === currentUser.id ? currentUser : u);
      localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));

      anoraService.initChat(currentUser);
      if (messages.length === 0) {
        setMessages([{
          id: 'initial',
          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT'),
          timestamp: new Date()
        }]);
      }
    } else {
      localStorage.removeItem('anora_session');
      localStorage.removeItem('anora_history');
    }
  }, [currentUser]);

  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem('anora_history', JSON.stringify(messages));
    }
  }, [messages]);

  const purgeNeuralLinks = () => {
    if (confirm('Sovereign Purge initialized. Clear all conversation records?')) {
      setMessages([{
        id: 'initial',
        role: 'anora',
        content: INITIAL_MESSAGE(currentUser!.name, currentUser!.role, currentUser!.preferences.persona || 'DEFAULT'),
        timestamp: new Date()
      }]);
      localStorage.removeItem('anora_history');
    }
  };

  const playTTS = async (text: string) => {
    if (!currentUser?.preferences.autoRead) return;
    try {
      const base64 = await anoraService.speak(text, currentUser.preferences.voiceName);
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const buffer = await decodeAudioData(decode(base64), audioCtx, 24000, 1);
      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.destination);
      source.start();
    } catch (err) {
      console.error("TTS Error:", err);
    }
  };

  const handleSend = async (text: string) => {
    if ((!text.trim() && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      const response = await anoraService.sendMessageWithVision(text, userMsg.images || []);
      const assistantId = (Date.now() + 1).toString();

      setMessages(prev => [...prev, {
        id: assistantId,
        role: 'anora',
        content: response.text || "I apologize, but I couldn't process that.",
        sources: response.sources,
        timestamp: new Date()
      }]);

      if (currentUser.preferences.autoRead) {
        playTTS(response.text);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsThinking(false);
    }
  };

  const toggleVoiceMode = async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(track => track.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }

    try {
      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => audioSourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) {
              for (const source of audioSourcesRef.current.values()) {
                source.stop();
                audioSourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error(e),
          onclose: () => setIsVoiceMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `You are Anora in voice mode. User is ${currentUser?.name}. Persona: ${currentUser?.preferences.persona}.`
        }
      });
    } catch (err) {
      console.error(err);
      setIsVoiceMode(false);
    }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const accentColor = currentUser.preferences.accentColor;
  const isOwner = currentUser.email.toLowerCase() === OWNER_EMAIL;
  const theme = currentUser.preferences.theme || 'OBSIDIAN';
  const font = currentUser.preferences.font || 'INTER';
  const currentPersona = currentUser.preferences.persona || 'DEFAULT';

  const getBackground = () => {
    switch (theme) {
      case 'NEURAL_NOISE': return "bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-40 mix-blend-overlay pointer-events-none";
      case 'MESH_GRADIENT': return "bg-[radial-gradient(circle_at_50%_50%,_rgba(59,130,246,0.1)_0%,_transparent_50%),_radial-gradient(circle_at_20%_80%,_rgba(244,63,94,0.1)_0%,_transparent_50%)]";
      case 'MINIMAL': return "bg-black";
      default: return "bg-[radial-gradient(circle_at_50%_0%,_#0a0a0a_0%,_#000_100%)]";
    }
  };

  const getPersonaIcon = (p: Persona) => {
    switch(p) {
      case 'FRIEND': return '👋';
      case 'TEACHER': return '📚';
      case 'GIRLFRIEND': return '❤️';
      case 'BROTHER': return '💪';
      default: return '🤖';
    }
  };

  return (
    <div className={`flex flex-col h-screen bg-black text-zinc-300 overflow-hidden selection:bg-zinc-800 selection:text-white transition-all duration-700 ${font === 'OUTFIT' ? 'font-outfit' : 'font-inter'} ${isOwner ? 'ring-inset ring-2 ring-amber-500/10' : ''}`}>
      <style>{`
        .accent-border { border-color: ${accentColor}40 !important; }
        .accent-ring { --tw-ring-color: ${accentColor}40 !important; }
        .accent-text { color: ${accentColor} !important; }
        .accent-bg { background-color: ${accentColor} !important; }
        .accent-bg-soft { background-color: ${accentColor}15 !important; }
        .owner-glow { text-shadow: 0 0 10px rgba(245, 158, 11, 0.3); }
      `}</style>

      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <header className="flex items-center justify-between px-8 py-6 border-b border-zinc-900 bg-black/80 backdrop-blur-3xl sticky top-0 z-20 transition-all">
        <div className="flex items-center gap-6">
          <AnoraLogo size={52} color={accentColor} />
          <div className="hidden md:flex flex-col">
            <div className="flex items-center gap-2">
              <PremiumBadge role={currentUser.role} tier={currentUser.tier} />
              <span className={`text-[9px] font-bold uppercase tracking-[0.4em] opacity-40 ml-2 ${isOwner ? 'text-amber-500' : 'text-zinc-500'}`}>Sovereign OS v3.5</span>
            </div>
            <div className="flex items-center gap-2 mt-1">
              <span className="text-[10px] text-zinc-600 font-bold uppercase tracking-widest flex items-center gap-1.5 bg-white/5 px-2 py-0.5 rounded">
                <span className="text-xs">{getPersonaIcon(currentPersona)}</span>
                {currentPersona} Protocol
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-5">
          {isOwner && (
            <button onClick={purgeNeuralLinks} className="p-2.5 text-zinc-700 hover:text-amber-500 hover:bg-amber-500/5 rounded-xl transition-all group" title="Purge Conversation">
              <svg className="w-5 h-5 group-hover:scale-110" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </button>
          )}

          <VoiceIndicator active={isVoiceMode} />

          <div className="flex items-center gap-3 p-1.5 bg-zinc-900/40 rounded-[1.5rem] border border-zinc-800/50 shadow-2xl backdrop-blur-md ring-1 ring-white/5 transition-all hover:border-zinc-700">
            <button onClick={() => setIsHubOpen(true)} className="p-3 rounded-2xl text-zinc-500 hover:text-white hover:bg-white/5 transition-all" title="Neural Hub">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
            </button>
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-3 rounded-2xl text-zinc-500 hover:text-white hover:bg-white/5 transition-all" title="Command Center">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M5 20h14a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </button>
            <button onClick={() => setIsProfileOpen(true)} className="flex items-center gap-4 p-1 pl-4 border-l border-zinc-800 group transition-all">
              <div className="text-right hidden sm:block">
                <p className={`text-[10px] font-bold uppercase leading-tight ${isOwner ? 'text-amber-500 owner-glow' : 'text-zinc-200'}`}>{currentUser.name.split(' ')[0]}</p>
                <p className="text-[8px] text-zinc-600 uppercase tracking-widest font-bold mt-0.5">Core Active</p>
              </div>
              <div className={`w-10 h-10 rounded-full flex items-center justify-center text-[11px] font-bold overflow-hidden shadow-2xl transition-all duration-500 group-hover:scale-105 border ${isOwner ? 'border-amber-500/50 bg-zinc-800 text-amber-500 shadow-amber-500/10' : 'border-zinc-800 bg-zinc-900 text-zinc-400'}`}>
                 {currentUser.avatar ? <img src={currentUser.avatar} alt="Avatar" className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
              </div>
            </button>
          </div>

          <button onClick={() => setCurrentUser(null)} className="p-3 text-zinc-700 hover:text-red-500 transition-all rounded-full hover:bg-red-500/5" title="Neural Logout">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
          </button>
        </div>
      </header>

      <main className={`flex-1 flex flex-col relative overflow-hidden ${getBackground()}`}>
        {theme === 'MESH_GRADIENT' && (
          <div className="absolute inset-0 opacity-20 pointer-events-none">
            <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_0%_0%,_#3b82f6_0%,_transparent_40%),_radial-gradient(circle_at_100%_100%,_#f43f5e_0%,_transparent_40%)] animate-pulse"></div>
          </div>
        )}
        <MessageList messages={messages} isThinking={isThinking} ownerName={currentUser.name} isOwnerView={isOwner} />
      </main>

      <footer className="p-8 sm:p-12 bg-gradient-to-t from-black via-black/95 to-transparent z-10">
        <div className="max-w-5xl mx-auto space-y-6">
          <div className="flex items-center gap-5">
            <button onClick={() => fileInputRef.current?.click()} className="p-5 rounded-[2rem] bg-zinc-900 text-zinc-500 border border-zinc-800 hover:border-zinc-600 hover:text-white transition-all shadow-2xl ring-1 ring-white/5 active:scale-95" title="Upload Media">
              <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
              <input type="file" ref={fileInputRef} hidden multiple accept="image/*" onChange={e => {
                const files = e.currentTarget.files;
                if (files) Array.from(files).forEach((f: File) => {
                  const reader = new FileReader();
                  reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]);
                  reader.readAsDataURL(f);
                });
              }} />
            </button>

            <button onClick={toggleVoiceMode} className={`p-5 rounded-[2rem] transition-all duration-700 group relative shadow-2xl ring-4 active:scale-95 ${isVoiceMode ? 'bg-blue-600 text-white ring-blue-600/20' : 'bg-zinc-900 text-zinc-500 border border-zinc-800 hover:border-zinc-600 ring-transparent'}`}>
              <svg className="w-7 h-7 z-10 relative" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            </button>

            <div className="flex-1 relative group">
