          return;
        }

        const found = users.find(u => u.email.toLowerCase() === emailLower);
        if (!found) {
          setError('Neural ID not detected.');
        } else if (found.password !== password) {
          setError('Access Denied. Key mismatch.');
        } else {
          setPhase(2);
          setTimeout(() => onLogin(found), 1500);
        }
      } else {
        if (password !== confirmPassword) {
          setError('Encryption keys must match.');
        } else if (users.some(u => u.email.toLowerCase() === emailLower)) {
          setError('Neural ID already linked.');
        } else if (password.length < 6) {
          setError('Complexity requirements not met.');
        } else {
          const newUser: User = {
            id: Math.random().toString(36).substr(2, 9),
            name: name || 'Neural Link User',
            email: emailLower,
            password: password,
            role: Role.USER,
            tier: SubscriptionTier.FREE,
            preferences: { 
              accentColor: '#3f3f46', 
              aiMood: 'CALM' as AiMood, 
              voiceName: 'Kore',
              autoRead: true,
              continuousListening: false,
              intelligenceLevel: 'BALANCED' as IntelligenceLevel,
              language: 'English',
              theme: 'OBSIDIAN',
              font: 'INTER',
              soundEnabled: true,
              persona: 'DEFAULT'
            },
            createdAt: new Date().toISOString(),
            reminders: [],
            notes: [],
            memory: [],
            projects: []
          };
          saveUser(newUser);
          setPhase(2);
          setTimeout(() => onLogin(newUser), 1500);
        }
      }
      setLoading(false);
    }, 1500);
  };

  if (phase === 2) {
    return (
