            >
              {loading ? <div className="w-4 h-4 border-2 border-black/20 border-t-black rounded-full animate-spin"></div> : <span className="text-[10px] uppercase tracking-[0.3em] font-bold">{isLogin ? "Synchronize" : "Initialize Link"}</span>}
            </button>
          </form>
        </div>

        <p className="text-zinc-800 text-[8px] text-center font-bold uppercase tracking-[0.5em] mt-12 opacity-50">
          Neural-Lock Enabled // Sovereignty Protocol Active
