import { CommandCenter } from './components/CommandCenter';
import { ProfileModal } from './components/ProfileModal';
import { AnoraLogo } from './components/AnoraLogo';
import { AssistantFeatures } from './components/AssistantFeatures';

// Audio Encoding/Decoding Utilities
const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
};

const createBlob = (data: Float32Array): GenAIBlob => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
  return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
};

const COMMAND_SUGGESTIONS = [
  { label: "Brainstorm Story", cmd: "I want to start a new creative story about..." },
  { label: "AutoCAD Help", cmd: "Explain the best practices for site management in Civil Engineering." },
  { label: "Music Ideas", cmd: "Can you help me write lyrics for a tech-focused lo-fi track?" },
  { label: "Summarize Notes", cmd: "Help me organize my current project goals." }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('anora_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [inputFocused, setInputFocused] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      const savedDb = localStorage.getItem('anora_users_db');
      const users: User[] = savedDb ? JSON.parse(savedDb) : [];
      const updatedUsers = users.map((u: User) => u.id === currentUser.id ? currentUser : u);
      localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));

      anoraService.initChat(currentUser);
      if (messages.length === 0) {
        setMessages([{
          id: 'initial',
          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT'),
          timestamp: new Date()
        }]);
      }
    }
  }, [currentUser]);

  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem('anora_history', JSON.stringify(messages));
    }
  }, [messages]);

  const handleSend = async (text: string) => {
    const val = text.trim();
    if ((!val && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: val,
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      const response = await anoraService.sendMessageWithVision(val, userMsg.images || []);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'anora',
        content: response.text,
        sources: response.sources,
        timestamp: new Date()
      }]);

      if (currentUser.preferences.autoRead) {
        const base64 = await anoraService.speak(response.text, currentUser.preferences.voiceName);
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
        const buffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsThinking(false);
    }
  };

  const toggleVoiceMode = async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(t => t.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }
    try {
      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => session.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => audioSourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `Anora Voice. User: ${currentUser?.name}. Persona: ${currentUser?.preferences.persona}.`
        }
      });
    } catch (err) {
      console.error(err);
      setIsVoiceMode(false);
    }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const accentColor = currentUser.preferences.accentColor;
  const isOwner = currentUser.email.toLowerCase() === OWNER_EMAIL;
  const theme = currentUser.preferences.theme || 'OBSIDIAN';
  const font = currentUser.preferences.font || 'INTER';
  const currentPersona = currentUser.preferences.persona || 'DEFAULT';

  const getBackground = () => {
    switch (theme) {
      case 'NEURAL_NOISE': return "bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-30 mix-blend-overlay";
      case 'MESH_GRADIENT': return "bg-[radial-gradient(circle_at_50%_50%,_rgba(59,130,246,0.1)_0%,_transparent_60%),_radial-gradient(circle_at_20%_80%,_rgba(244,63,94,0.1)_0%,_transparent_60%)]";
      case 'MINIMAL': return "bg-black";
      default: return "bg-[radial-gradient(circle_at_50%_0%,_#0a0a0a_0%,_#000_100%)]";
    }
  };

  return (
    <div className={`flex flex-col h-screen bg-black text-zinc-300 overflow-hidden selection:bg-zinc-800 transition-all duration-700 ${font === 'OUTFIT' ? 'font-outfit' : 'font-inter'} ${isOwner ? 'ring-inset ring-1 ring-amber-500/5' : ''}`}>
      <style>{`
        .accent-text { color: ${accentColor}; }
        .accent-border { border-color: ${accentColor}40; }
        .accent-ring:focus { --tw-ring-color: ${accentColor}40; }
        .owner-glow { text-shadow: 0 0 8px ${accentColor}60; }
        .custom-gradient { background: linear-gradient(180deg, rgba(0,0,0,0) 0%, #000 100%); }
      `}</style>

      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <header className="flex items-center justify-between px-10 py-7 border-b border-zinc-900 bg-black/80 backdrop-blur-2xl z-20">
        <div className="flex items-center gap-6 animate-in slide-in-from-left duration-700">
          <AnoraLogo size={52} color={accentColor} />
          <div className="hidden lg:flex flex-col">
            <div className="flex items-center gap-2">
              <PremiumBadge role={currentUser.role} tier={currentUser.tier} />
              <span className="text-[9px] font-bold uppercase tracking-[0.4em] text-zinc-600 ml-2">Sovereign OS v3.5</span>
            </div>
            <div className="flex items-center gap-2 mt-1 px-3 py-1 bg-white/5 rounded-full border border-white/5 group hover:border-white/10 transition-all cursor-default">
               <span className="text-[9px] font-bold uppercase tracking-widest text-zinc-500 group-hover:text-zinc-300 transition-colors">{currentPersona} PROTOCOL ACTIVE</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-6 animate-in slide-in-from-right duration-700">
          <VoiceIndicator active={isVoiceMode} />

          <div className="flex items-center gap-3 p-1.5 bg-zinc-900/50 rounded-[2rem] border border-zinc-800/80 shadow-2xl backdrop-blur-md ring-1 ring-white/5">
            <button onClick={() => setIsHubOpen(true)} className="p-3.5 rounded-2xl text-zinc-500 hover:text-white hover:bg-white/5 transition-all" title="Neural Hub">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
            </button>
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-3.5 rounded-2xl text-zinc-500 hover:text-white hover:bg-white/5 transition-all" title="Command Center">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M5 20h14a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </button>
            <button onClick={() => setIsProfileOpen(true)} className="flex items-center gap-4 p-1 pl-4 border-l border-zinc-800 group transition-all">
              <div className="text-right hidden sm:block">
                <p className={`text-[10px] font-bold uppercase leading-tight ${isOwner ? 'accent-text owner-glow' : 'text-zinc-200'}`}>{currentUser.name.split(' ')[0]}</p>
                <div className="flex items-center gap-1 justify-end mt-0.5">
                   <div className="w-1 h-1 rounded-full bg-green-500 animate-pulse"></div>
                   <p className="text-[8px] text-zinc-600 uppercase tracking-widest font-bold">CORE ONLINE</p>
                </div>
              </div>
              <div className={`w-11 h-11 rounded-full flex items-center justify-center text-[12px] font-bold overflow-hidden shadow-2xl transition-all duration-500 group-hover:scale-105 border ${isOwner ? 'border-amber-500/50 bg-zinc-800' : 'border-zinc-800 bg-zinc-900 text-zinc-500'}`}>
                 {currentUser.avatar ? <img src={currentUser.avatar} alt="AV" className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
              </div>
            </button>
          </div>

          <button onClick={() => { localStorage.removeItem('anora_session'); setCurrentUser(null); }} className="p-3 text-zinc-700 hover:text-red-500 transition-all rounded-full hover:bg-red-500/5" title="Neural Break">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
          </button>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <div className={`absolute inset-0 transition-all duration-1000 ${getBackground()}`}></div>
        <MessageList messages={messages} isThinking={isThinking} ownerName={currentUser.name} isOwnerView={isOwner} />
      </main>

      <footer className="px-10 py-10 custom-gradient z-10 transition-all">
        <div className="max-w-5xl mx-auto space-y-6">

          {/* Command Suggestions */}
          <div className={`flex gap-3 overflow-x-auto no-scrollbar pb-2 transition-all duration-500 ${inputFocused ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none h-0'}`}>
            {COMMAND_SUGGESTIONS.map((s, i) => (
              <button 
                key={i} 
                onClick={() => setInputValue(s.cmd)}
                className="whitespace-nowrap px-5 py-2.5 rounded-2xl bg-white/5 border border-white/10 text-[10px] font-bold uppercase tracking-widest text-zinc-500 hover:text-white hover:border-white/20 transition-all active:scale-95 shadow-xl"
              >
                {s.label}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-5">
            <button onClick={() => fileInputRef.current?.click()} className="p-6 rounded-[2.5rem] bg-zinc-900/60 text-zinc-500 border border-zinc-800/80 hover:border-zinc-600 hover:text-white transition-all shadow-2xl active:scale-95 group">
              <svg className="w-8 h-8 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
              <input type="file" ref={fileInputRef} hidden multiple accept="image/*" onChange={e => {
                const files = e.currentTarget.files;
                if (files) Array.from(files).forEach((f: File) => {
                  const reader = new FileReader();
                  reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]);
                  reader.readAsDataURL(f);
                });
              }} />
            </button>

            <button onClick={toggleVoiceMode} className={`p-6 rounded-[2.5rem] transition-all duration-700 shadow-2xl active:scale-95 ${isVoiceMode ? 'bg-blue-600 text-white animate-glow' : 'bg-zinc-900/60 text-zinc-500 border border-zinc-800/80 hover:border-zinc-600'}`}>
              <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            </button>

            <div className="flex-1 relative group">
              <input
                type="text"
                value={inputValue}
                onFocus={() => setInputFocused(true)}
                onBlur={() => setTimeout(() => setInputFocused(false), 200)}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isThinking ? "Anora is contemplating..." : `Neural Command Authorized: Arjun Bharti Mina...`}
                className="w-full bg-zinc-900/40 border border-zinc-800/80 text-zinc-100 rounded-[3rem] px-12 py-7 focus:outline-none focus:ring-4 accent-ring transition-all placeholder:text-zinc-800 text-lg shadow-2xl backdrop-blur-3xl ring-1 ring-white/5"
              />
              <button disabled={!inputValue.trim() && pendingImages.length === 0 || isThinking} onClick={() => handleSend(inputValue)} className={`absolute right-5 top-1/2 -translate-y-1/2 p-4 rounded-2xl transition-all active:scale-95 shadow-2xl ${isOwner ? 'bg-amber-500 text-black hover:bg-amber-400' : 'bg-white text-black'} disabled:opacity-20`}>
                <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>
              </button>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row justify-between items-center px-10 gap-4 opacity-40 animate-in fade-in duration-1000">
             <div className="flex gap-8 text-[9px] font-bold text-zinc-500 uppercase tracking-[0.5em]">
               <span className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-green-500"></div> LINK STABLE</span>
               <span className="flex items-center gap-2"><div className="w-1.5 h-1.5 rounded-full bg-zinc-700"></div> VERSION 3.5</span>
             </div>
             <p className="text-[10px] font-bold uppercase tracking-[0.4em] italic text-zinc-600">Sovereign Asset: Arjun Bharti Mina</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import { Message, Role } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
}

export const MessageList: React.FC<MessageListProps> = ({ messages, isThinking, ownerName, isOwnerView }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  return (
    <div className="flex-1 overflow-y-auto px-8 py-16 space-y-16 max-w-5xl mx-auto w-full scroll-smooth no-scrollbar relative z-10">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-1000 fill-mode-both`}
            style={{ animationDelay: `${index * 100}ms` }}
          >
            <div className={`max-w-[95%] md:max-w-[85%] group relative`}>
              {/* Metadata Header */}
              <div className={`flex items-center gap-4 mb-3.5 px-4 transition-all duration-500 opacity-40 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[10px] font-bold uppercase tracking-[0.4em] ${isUser ? (isOwnerView ? 'text-amber-500' : 'text-zinc-400') : 'text-zinc-500'}`}>
                  {isUser ? (isOwnerView ? 'Sovereign' : ownerName.split(' ')[0]) : 'Anora OS'}
                </span>
                <div className="w-1 h-1 rounded-full bg-zinc-800"></div>
                <span className="text-[9px] text-zinc-700 font-bold uppercase tracking-widest">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>

              {/* Vision Content */}
              {msg.images && msg.images.length > 0 && (
                <div className={`flex flex-wrap gap-4 mb-5 animate-in zoom-in-95 duration-700 ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className="relative group/img overflow-hidden rounded-[3rem] border border-zinc-800/50 shadow-2xl transition-all hover:border-zinc-600">
                      <img src={img} alt="V" className="w-64 h-64 object-cover transition-transform duration-[2s] group-hover/img:scale-110" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-sm">
                         <span className="text-[9px] text-white font-bold uppercase tracking-[0.5em] bg-white/10 px-6 py-3 rounded-full border border-white/20">NEURAL ASSET</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {/* Message Bubble */}
              <div
                className={`rounded-[3.5rem] px-12 py-10 text-[16px] leading-[1.8] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.5)] transition-all duration-700 relative ring-1 ring-white/5
                  ${isUser 
                    ? `${isOwnerView ? 'bg-zinc-900 border-amber-500/10 text-white' : 'bg-zinc-800/80 text-zinc-100 border-zinc-700/50'} rounded-tr-none` 
                    : 'bg-zinc-900/30 text-zinc-200 border border-zinc-800/50 rounded-tl-none backdrop-blur-3xl'}`}
              >
                {isUser && isOwnerView && <div className="absolute -top-2 -right-2 w-5 h-5 bg-amber-500 rounded-full border-[3px] border-zinc-950 shadow-[0_0_15px_rgba(245,158,11,0.4)]"></div>}

                <div className="prose prose-invert max-w-none whitespace-pre-wrap font-medium tracking-tight">
                  {msg.content}
                </div>

                {/* Grounding Data */}
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-12 pt-10 border-t border-zinc-800/50 animate-in fade-in duration-1000">
                    <p className="text-[9px] font-bold text-zinc-600 uppercase tracking-[0.5em] mb-6 flex items-center gap-3">
                       <span className="w-6 h-px bg-zinc-800"></span> 
                       NEURAL GROUNDING SOURCE 
                       <span className="w-6 h-px bg-zinc-800"></span>
                    </p>
                    <div className="flex flex-wrap gap-4">
                      {msg.sources.map((source, idx) => (
                        <a
                          key={idx}
                          href={source.uri}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center gap-4 px-6 py-4 bg-black/50 border border-zinc-800/50 rounded-[2rem] text-[10px] text-zinc-400 hover:text-white hover:border-zinc-500 hover:bg-zinc-900 transition-all shadow-xl group/source"
                        >
                          <svg className="w-4 h-4 group-hover/source:rotate-12 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                          <span className="max-w-[200px] truncate font-bold tracking-wider">{source.title || 'Verified Intel'}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}

      {isThinking && (
        <div className="flex justify-start animate-in fade-in slide-in-from-left-6 duration-1000">
