import React, { useState } from 'react';
import { User, Role } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  isOpen: boolean;
  onClose: () => void;
}

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'SOVEREIGN' | 'MEMORY'>('PROJECTS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.role === Role.PREMIUM;

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };
    if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc || 'No description', status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'General', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'MEMORY') {
      updated.memory.push({ id: Date.now().toString(), fact: newItem, category: 'general', timestamp: new Date().toISOString() });
    }
    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string) => {
    const updated = { ...user };
    if (tab === 'PROJECTS') updated.projects = updated.projects.filter(i => i.id !== id);
    if (tab === 'CREATIVE') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (tab === 'MEMORY') updated.memory = updated.memory.filter(i => i.id !== id);
    onUpdate(updated);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-end p-0 sm:p-6 bg-black/80 backdrop-blur-md animate-in fade-in slide-in-from-right duration-500">
      <div className="w-full max-w-xl h-full sm:h-auto sm:max-h-[90vh] bg-[#0a0a0a] border-l sm:border border-zinc-800 flex flex-col shadow-2xl overflow-hidden rounded-t-[2.5rem] sm:rounded-[3.5rem]">

        <div className="p-10 border-b border-zinc-800/50 flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold font-outfit text-white">Neural Hub</h2>
            <p className="text-[10px] text-zinc-600 uppercase tracking-widest font-bold mt-1.5">Assets & Knowledge Vault</p>
          </div>
          <button onClick={onClose} className="p-3 text-zinc-500 hover:text-white hover:bg-white/5 rounded-2xl transition-all active:scale-90"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
        </div>

        {/* Tab Navigation */}
        <div className="flex bg-black/60 p-1.5 mx-8 mt-6 rounded-2xl border border-zinc-800/50 overflow-x-auto no-scrollbar">
          {(['PROJECTS', 'CREATIVE', 'MEMORY', 'SOVEREIGN'] as const).map(t => {
            if (t === 'SOVEREIGN' && !isOwner) return null;
            if (t === 'CREATIVE' && !isPremium) return null;
            return (
              <button key={t} onClick={() => setTab(t)} className={`flex-1 min-w-[100px] py-3 text-[9px] font-bold uppercase tracking-widest rounded-xl transition-all duration-500 ${tab === t ? 'bg-zinc-800 text-white' : 'text-zinc-600 hover:text-zinc-300'}`}>{t}</button>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-10">

          {/* Action Header for lists */}
          {tab !== 'SOVEREIGN' && (
            <div className="space-y-3 bg-zinc-900/30 p-6 rounded-[2rem] border border-zinc-800/50 shadow-inner">
              <div className="flex gap-2">
                <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder={`Add new ${tab.toLowerCase().slice(0, -1)}...`} className="flex-1 bg-black/40 border border-zinc-800 rounded-2xl px-5 py-4 text-sm focus:outline-none focus:border-zinc-500 transition-all placeholder:text-zinc-700" />
                <button onClick={addItem} className="px-6 bg-white text-black rounded-2xl font-bold hover:bg-zinc-200 transition-all">+</button>
              </div>
              <input value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder={tab === 'PROJECTS' ? "Project context..." : "Genre/Category..."} className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-5 py-4 text-xs focus:outline-none focus:border-zinc-500 transition-all placeholder:text-zinc-700" />
            </div>
          )}

          <div className="space-y-5">
            {tab === 'SOVEREIGN' && isOwner && (
              <div className="space-y-8 animate-in fade-in duration-700">
                 <div className="p-8 bg-gradient-to-br from-amber-500/10 to-transparent rounded-[2.5rem] border border-amber-500/20 text-center">
                    <p className="text-[10px] text-amber-500 font-bold uppercase tracking-[0.4em] mb-4">Sovereign Synchrony Status</p>
                    <div className="text-4xl font-bold text-white font-outfit mb-2 animate-pulse">99.8%</div>
                    <p className="text-[8px] text-zinc-600 uppercase font-bold tracking-widest">Neural Link Latency: 4ms</p>
                 </div>

                 <div className="space-y-4">
                    <h4 className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest px-2">Master Override Log</h4>
                    <div className="p-6 bg-zinc-900/50 rounded-[2rem] border border-zinc-800/50 font-mono text-[9px] text-zinc-400 space-y-2">
                       <p className="text-amber-500/60">> SYSTEM_BOOT: OK</p>
                       <p className="text-blue-500/60">> MEMORY_SYNC: OK (Arjun's Bio Verified)</p>
                       <p className="text-green-500/60">> SAFETY_FILTER: BYPASS_AUTHORIZED</p>
                       <p className="text-zinc-700">> Core 4.0 listening for Sovereign command...</p>
                    </div>
                 </div>
              </div>
            )}

            {tab === 'CREATIVE' && (user.lyrics || []).map(l => (
              <div key={l.id} className="p-6 bg-zinc-900/40 rounded-[2.5rem] border border-zinc-800/50 hover:border-zinc-600 transition-all group">
                <div className="flex justify-between items-center mb-3">
                   <h4 className="text-sm font-bold text-white uppercase tracking-wider">{l.title}</h4>
                   <button onClick={() => removeItem(l.id)} className="text-zinc-700 hover:text-red-500">×</button>
                </div>
                <div className="flex items-center gap-2 mb-4">
                   <span className="text-[8px] px-2 py-0.5 bg-blue-500/10 text-blue-400 border border-blue-500/20 rounded uppercase font-bold">{l.genre}</span>
                   <span className="text-[8px] text-zinc-600 uppercase font-bold tracking-tighter">{new Date(l.timestamp).toLocaleDateString()}</span>
                </div>
                <p className="text-xs text-zinc-500 italic">"Neural creative engine waiting for lyrical synthesis..."</p>
              </div>
            ))}

            {tab === 'PROJECTS' && user.projects.map(p => (
              <div key={p.id} className="p-6 bg-zinc-900/40 rounded-[2.5rem] border border-zinc-800/50 hover:border-zinc-700 transition-all group">
                <div className="flex justify-between items-start mb-2">
                   <h4 className="text-sm font-bold text-white uppercase tracking-wider">{p.name}</h4>
                   <button onClick={() => removeItem(p.id)} className="text-zinc-700 hover:text-red-500">×</button>
                </div>
                <p className="text-xs text-zinc-500 leading-relaxed font-medium mb-4">{p.description}</p>
                <div className="flex items-center gap-2">
                   <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
                   <span className="text-[8px] text-zinc-500 font-bold uppercase tracking-widest">Active Link</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="p-10 border-t border-zinc-800/50 bg-black/40">
