import React, { useState } from 'react';
import { Role, User } from '../types';
import { anoraService } from '../services/geminiService';

interface CommandCenterProps {
  user: User;
  isOpen: boolean;
  onClose: () => void;
}

export const CommandCenter: React.FC<CommandCenterProps> = ({ user, isOpen, onClose }) => {
  const [prompt, setPrompt] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState<'IMAGE' | 'VIDEO'>('IMAGE');

  if (!isOpen) return null;

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setLoading(true);
    setResult(null);

    try {
      if (mode === 'IMAGE') {
        const base64 = await anoraService.generateImage(prompt);
        setResult(`data:image/png;base64,${base64}`);
      } else {
        const videoUrl = await anoraService.generateVideo(prompt);
        setResult(videoUrl);
      }
    } catch (err: any) {
      alert(err.message);
    } finally {
      setLoading(false);
    }
  };

  const isOwner = user.role === Role.OWNER;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 bg-black/90 backdrop-blur-2xl animate-in fade-in zoom-in-95 duration-300">
      <div className="w-full max-w-3xl bg-[#0a0a0a] border border-zinc-800 rounded-[3rem] shadow-[0_0_80px_rgba(0,0,0,0.8)] overflow-hidden flex flex-col max-h-[90vh]">
        <div className="p-10 border-b border-zinc-800/50 flex items-center justify-between">
          <div>
            <h2 className={`text-xl font-bold font-outfit ${isOwner ? 'text-amber-500' : 'text-white'}`}>Visual Synthesis Hub</h2>
            <p className="text-[10px] text-zinc-600 uppercase tracking-widest font-bold mt-1.5">Direct Neural Rendering</p>
          </div>
          <button onClick={onClose} className="p-3 text-zinc-500 hover:text-white transition-all active:scale-90"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
        </div>

        <div className="flex bg-black/60 p-1.5 mx-10 mt-8 rounded-2xl border border-zinc-800/50">
          <button onClick={() => { setMode('IMAGE'); setResult(null); }} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest rounded-xl transition-all ${mode === 'IMAGE' ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-600'}`}>Image Core</button>
          {isOwner && <button onClick={() => { setMode('VIDEO'); setResult(null); }} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest rounded-xl transition-all ${mode === 'VIDEO' ? 'bg-amber-500 text-black shadow-xl' : 'text-zinc-600'}`}>Sovereign Video</button>}
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-8 no-scrollbar">
           <div className="space-y-4">
              <label className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest block px-2">Visualization Command</label>
              <textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} className="w-full bg-black border border-zinc-800/50 rounded-[2rem] p-6 text-zinc-200 focus:outline-none focus:border-zinc-500 min-h-[140px] resize-none text-sm placeholder:text-zinc-800" placeholder={`Describe the high-fidelity ${mode.toLowerCase()} to be rendered...`} />
              <button onClick={handleGenerate} disabled={loading || !prompt.trim()} className={`w-full font-bold py-5 rounded-[2rem] transition-all shadow-xl active:scale-95 text-[11px] tracking-[0.4em] uppercase ${isOwner ? 'bg-amber-500 text-black hover:bg-amber-400' : 'bg-white text-black hover:bg-zinc-200'} disabled:opacity-20`}>
                {loading ? 'Synthesizing from Void...' : `Render ${mode}`}
              </button>
           </div>

           {result && (
             <div className="pt-8 border-t border-zinc-800/50 animate-in zoom-in-95 duration-700">
                <div className="rounded-[2.5rem] overflow-hidden border border-zinc-800/50 bg-black shadow-inner relative group">
                   {mode === 'IMAGE' ? <img src={result} alt="G" className="w-full h-auto max-h-[500px] object-contain" /> : <video src={result} controls autoPlay className="w-full h-auto" />}
                   <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center pointer-events-none"><span className="text-[10px] font-bold uppercase tracking-[0.5em] text-white">Neural Output Optimized</span></div>
                </div>
                <div className="mt-6 flex justify-center">
                   <a href={result} download={`anora_${mode.toLowerCase()}_${Date.now()}`} className="px-8 py-3 bg-zinc-900 border border-zinc-800/50 rounded-full text-[10px] font-bold text-zinc-500 hover:text-white hover:border-zinc-500 transition-all uppercase tracking-[0.2em] flex items-center gap-3">
                      <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                      Extract Full Resolution
                   </a>
                </div>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

