                placeholder={isOwner ? "State master command..." : "Neural input authorized..."}
                className="w-full bg-zinc-950 border border-zinc-900 text-zinc-100 rounded-[3rem] px-8 sm:px-12 py-5 sm:py-8 focus:outline-none placeholder:text-zinc-800 text-base sm:text-xl"
              />
              <button onClick={() => handleSend(inputValue)} className={`absolute right-4 top-1/2 -translate-y-1/2 p-4 sm:p-6 rounded-3xl ${isOwner ? 'bg-amber-500 text-black' : 'bg-white text-black'}`}>
                <svg className="w-6 h-6 sm:w-8 sm:h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

