      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isSynthesis = !isUser && msg.images && msg.images.length > 0;

        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-700 fill-mode-both`}
