                <div className="w-0.5 h-0.5 rounded-full bg-zinc-800"></div>
                <span className="text-[8px] text-zinc-700 font-bold uppercase tracking-widest">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>

              {/* Vision Content (User Uploads or Model Generated) */}
              {msg.images && msg.images.length > 0 && (
                <div className={`grid gap-2 mb-3 animate-in zoom-in-95 duration-700 ${msg.images.length === 4 ? 'grid-cols-2' : (msg.images.length > 1 ? 'flex flex-wrap' : 'flex')} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[1.8rem] sm:rounded-[2.5rem] border shadow-2xl transition-all hover:border-zinc-400
                      ${isSynthesis ? 'border-amber-500/20' : 'border-zinc-800/50'} 
                      ${msg.images && msg.images.length === 1 ? 'w-64 h-64 sm:w-80 sm:h-80' : 'w-full aspect-square'}`}>
                      <img src={img} alt="V" className="w-full h-full object-cover transition-transform duration-[2s] group-hover/img:scale-110" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity flex flex-col items-center justify-center backdrop-blur-sm gap-3">
                         <span className="text-[7px] sm:text-[8px] text-white font-bold uppercase tracking-[0.4em] bg-white/10 px-3 sm:px-5 py-1.5 sm:py-2.5 rounded-full border border-white/20 text-center">
                           {isSynthesis ? 'SOVEREIGN ASSET' : 'NEURAL ASSET'}
                         </span>
                         {isSynthesis && (
                           <a href={img} download={`synthesis_${Date.now()}_${i}.png`} className="pointer-events-auto bg-white text-black px-3 sm:px-5 py-1.5 sm:py-2.5 rounded-full text-[7px] sm:text-[8px] font-bold uppercase tracking-widest hover:bg-zinc-200 transition-all">
                             Export
