                  ${isUser 
                    ? `${isOwnerView ? 'bg-zinc-900 border-amber-500/10 text-white' : 'bg-zinc-800/80 text-zinc-100 border-zinc-700/50'} rounded-tr-none` 
                    : `${isSynthesis ? 'bg-black/80 border-amber-500/20 text-white' : 'bg-zinc-900/30 text-zinc-200 border-zinc-800/50'} rounded-tl-none backdrop-blur-3xl`}`}
              >
                {isUser && isOwnerView && <div className="absolute -top-1 -right-1 w-3 h-3 bg-amber-500 rounded-full border-2 border-zinc-950 shadow-[0_0_10px_rgba(245,158,11,0.4)]"></div>}

                <div className="prose prose-invert max-w-none whitespace-pre-wrap font-medium tracking-tight">
                  {msg.content}
