                {/* Grounding Data */}
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-8 pt-8 border-t border-zinc-800/50 animate-in fade-in duration-1000">
                    <p className="text-[8px] font-bold text-zinc-600 uppercase tracking-[0.4em] mb-4 flex items-center gap-2">
