                          <span className="max-w-[150px] truncate font-bold tracking-wider">{source.title || 'Intel'}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}

      {isThinking && (
        <div className="flex justify-start animate-in fade-in slide-in-from-left-2 duration-700">
          <div className="bg-zinc-900/40 border border-zinc-800/80 rounded-[1.8rem] rounded-tl-none px-6 py-4 shadow-2xl backdrop-blur-3xl ring-1 ring-white/5">
            <div className="flex gap-1.5">
              <div className="w-1.5 h-1.5 bg-zinc-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              <div className="w-1.5 h-1.5 bg-zinc-600 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
              <div className="w-1.5 h-1.5 bg-zinc-600 rounded-full animate-bounce"></div>
            </div>
          </div>
        </div>
      )}
      <div ref={bottomRef} className="h-10" />
    </div>
  );
};

import React, { useState } from 'react';
import { User, Role, SiteLog, LyricDraft, VaultItem } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  isOpen: boolean;
  onClose: () => void;
}

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'ENGINEERING' | 'UTILITIES' | 'VAULT'>('PROJECTS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [vaultLocked, setVaultLocked] = useState(true);
  const [vaultPass, setVaultPass] = useState('');

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.role === Role.PREMIUM;

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };
    if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'General', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'ENGINEERING') {
      if (!updated.siteLogs) updated.siteLogs = [];
      updated.siteLogs.push({ id: Date.now().toString(), project: newItem, date: new Date().toLocaleDateString(), details: newDesc });
    }
    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const utilityModules = [
    { title: "Rhyme Matrix", icon: "🎵", desc: "Expert songwriting dictionary." },
    { title: "Concrete Estimator", icon: "🏗️", desc: "Quick volume slab calculator." },
    { title: "CAD Logic Pro", icon: "📐", desc: "Advanced AutoCAD command database." },
    { title: "BPM Pulse", icon: "⏱️", desc: "Tap-to-tempo lyric rhythm tool." },
    { title: "RHB Site Tracker", icon: "🗺️", desc: "Specialized project monitoring." },
    { title: "Unit Bridge", icon: "🔄", desc: "Civil engineering unit converter." },
    { title: "Neural Alarms", icon: "🔔", desc: "Context-aware project reminders." },
    { title: "Code Forge", icon: "💻", desc: "Sandbox for automation snippets." },
    { title: "Mood Board AI", icon: "🎨", desc: "Lyric-to-visual mood generator." },
    { title: "Blueprint Audit", icon: "👁️", desc: "AI-based drawing analysis (Vision)." }
  ];

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/90 backdrop-blur-3xl animate-in fade-in slide-in-from-right duration-500">
      <div className="w-full max-w-2xl h-[92dvh] sm:h-auto bg-[#0a0a0a] border-t sm:border-l border-zinc-900 flex flex-col shadow-2xl overflow-hidden rounded-t-[3rem] sm:rounded-none ring-1 ring-white/5 pt-safe">

        {/* Header */}
        <div className="px-8 py-8 border-b border-zinc-900 flex items-center justify-between">
          <div>
            <h2 className={`text-xl font-bold font-outfit ${isOwner ? 'text-amber-500' : 'text-white'}`}>Neural Hub</h2>
            <p className="text-[9px] text-zinc-600 uppercase tracking-widest font-bold mt-1">Sovereign Core Assets</p>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-500 hover:text-white transition-all bg-white/5 rounded-2xl group active:scale-90">
            <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        {/* Navigation */}
        <div className="flex bg-black/60 p-1.5 mx-6 mt-6 rounded-2xl border border-zinc-900 overflow-x-auto no-scrollbar gap-1">
          {(['PROJECTS', 'CREATIVE', 'ENGINEERING', 'UTILITIES', 'VAULT'] as const).map(t => {
            if (t === 'ENGINEERING' && !isOwner) return null;
            if (t === 'CREATIVE' && !isPremium) return null;
            return (
              <button key={t} onClick={() => setTab(t)} className={`flex-1 min-w-[100px] py-3 text-[8px] font-bold uppercase tracking-[0.15em] rounded-xl transition-all ${tab === t ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-700 hover:text-zinc-400'}`}>{t}</button>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar">

          {(tab === 'PROJECTS' || tab === 'CREATIVE' || tab === 'ENGINEERING') && (
            <div className="space-y-3 bg-zinc-900/20 p-6 rounded-[2rem] border border-zinc-800/50 shadow-inner group animate-in slide-in-from-top-4 duration-500">
              <div className="flex gap-3">
                <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder={`Label...`} className="flex-1 bg-black/50 border border-zinc-900 rounded-xl px-5 py-3.5 text-xs focus:outline-none focus:border-zinc-700 transition-all font-medium text-zinc-100" />
                <button onClick={addItem} className={`px-6 rounded-xl font-bold transition-all active:scale-90 ${isOwner ? 'bg-amber-500 text-black' : 'bg-white text-black'}`}>+</button>
              </div>
              <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Metadata context..." className="w-full bg-black/30 border border-zinc-900 rounded-xl px-5 py-3.5 text-[10px] focus:outline-none focus:border-zinc-700 transition-all text-zinc-400 h-20 resize-none" />
            </div>
          )}

          <div className="space-y-4">
            {tab === 'UTILITIES' && (
              <div className="grid grid-cols-2 gap-3 animate-in fade-in zoom-in-95 duration-700">
                 {utilityModules.map((u, i) => (
                   <div key={i} className="p-5 bg-zinc-900/30 border border-zinc-800/30 rounded-[1.8rem] hover:border-zinc-600 transition-all group cursor-pointer relative overflow-hidden active:scale-95">
                      <div className="absolute top-0 right-0 p-3 text-white/5 group-hover:text-white/10 text-4xl transition-colors">{u.icon}</div>
                      <h4 className="text-white text-[10px] font-bold uppercase tracking-widest mb-1.5">{u.title}</h4>
                      <p className="text-[8px] text-zinc-700 font-bold uppercase tracking-tight leading-relaxed">{u.desc}</p>
                   </div>
                 ))}
              </div>
            )}

            {tab === 'VAULT' && vaultLocked && (
              <div className="flex flex-col items-center justify-center py-10 space-y-8 animate-in zoom-in-95 duration-700">
                <div className="w-20 h-20 bg-zinc-900 border border-zinc-800 rounded-full flex items-center justify-center text-amber-500 shadow-2xl relative">
                  <div className="absolute inset-0 bg-amber-500/10 blur-xl rounded-full animate-pulse"></div>
                  <svg className="w-10 h-10 relative z-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
                </div>
                <div className="w-full max-w-xs space-y-3 px-6">
                  <input type="password" value={vaultPass} onChange={e => setVaultPass(e.target.value)} placeholder="ENCRYPTION KEY" className="w-full bg-zinc-900 border border-zinc-900 rounded-xl px-5 py-4 text-center tracking-widest text-white focus:outline-none focus:border-amber-500/50 text-xs" />
                  <button onClick={() => { if(vaultPass === 'aman1887') setVaultLocked(false); else alert("Invalid Key"); }} className="w-full py-4 bg-white text-black rounded-xl font-bold uppercase text-[9px] tracking-[0.4em] hover:bg-zinc-200 transition-all active:scale-95">Authorize Access</button>
                </div>
              </div>
            )}

            {tab === 'PROJECTS' && user.projects.map(p => (
