            <button 
              onClick={() => setIsSynthesisMode(!isSynthesisMode)} 
              className={`p-4 sm:p-5 rounded-3xl border transition-all ${isSynthesisMode ? 'bg-amber-500 text-black border-amber-500 shadow-xl' : 'bg-zinc-950 text-zinc-500 border-zinc-900'}`}
