const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

const createBlob = (data: Float32Array): GenAIBlob => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
  return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('anora_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [isSynthesisMode, setIsSynthesisMode] = useState(false);

  // Speech Control State
  const [speakingId, setSpeakingId] = useState<string | null>(null);
  const currentAudioSource = useRef<AudioBufferSourceNode | null>(null);
  const audioContext = useRef<AudioContext | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      const savedDb = localStorage.getItem('anora_users_db');
      const users: User[] = savedDb ? JSON.parse(savedDb) : [];
      const updatedUsers = users.map((u: User) => u.id === currentUser.id ? currentUser : u);
      localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));

      anoraService.initChat(currentUser);
      if (messages.length === 0) {
        setMessages([{
          id: 'initial',
          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT'),
          timestamp: new Date()
        }]);
      }
    }
  }, [currentUser]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey || e.metaKey) {
        if (e.key === 'k') { e.preventDefault(); setIsCommandCenterOpen(prev => !prev); }
        if (e.key === 'p') { e.preventDefault(); setIsProfileOpen(prev => !prev); }
        if (e.key === 'h') { e.preventDefault(); setIsHubOpen(prev => !prev); }
        if (e.key === 'i') { e.preventDefault(); setIsSynthesisMode(prev => !prev); }
        if (e.key === 'b') { e.preventDefault(); setIsSidebarOpen(prev => !prev); }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem('anora_history', JSON.stringify(messages));
    }
  }, [messages]);

  const stopSpeech = () => {
    if (currentAudioSource.current) {
      try {
        currentAudioSource.current.stop();
      } catch (e) {}
      currentAudioSource.current = null;
    }
    setSpeakingId(null);
  };

  const handleSpeak = async (messageId: string, content: string) => {
    if (!currentUser) return;

    // If clicking same message while it's speaking, stop it
    if (speakingId === messageId) {
      stopSpeech();
      return;
    }

    stopSpeech();
    setSpeakingId(messageId);

    try {
      const base64 = await anoraService.speak(content, currentUser.preferences.voiceName);

      if (!audioContext.current) {
        audioContext.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      }

      const buffer = await decodeAudioData(decode(base64), audioContext.current, 24000, 1);
      const source = audioContext.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContext.current.destination);

      source.onended = () => {
        if (speakingId === messageId) {
          setSpeakingId(null);
        }
      };

      currentAudioSource.current = source;
      source.start();
    } catch (err) {
      console.error("Speech synthesis error:", err);
      setSpeakingId(null);
    }
  };

  const handleSend = async (text: string) => {
    const val = text.trim();
    if ((!val && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: val || (isSynthesisMode ? "Synthesizing visual asset..." : "Sharing visual asset..."),
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      let response;
      if (isSynthesisMode) {
        response = await anoraService.generateChatImage(val || "Create an aesthetic abstract vision.", userMsg.images || []);
      } else {
        response = await anoraService.sendMessageWithVision(val, userMsg.images || []);
      }

      const anoraMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'anora',
        content: response.text,
        sources: (response as any).sources,
        images: response.images,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, anoraMsg]);

      if (currentUser.preferences.autoRead && response.text) {
        handleSpeak(anoraMsg.id, response.text);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsThinking(false);
      setIsSynthesisMode(false);
    }
  };

  const toggleVoiceMode = async () => {
    if (isVoiceMode) {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
        streamRef.current = null;
      }
      if (inputAudioContextRef.current) {
        await inputAudioContextRef.current.close();
        inputAudioContextRef.current = null;
      }
      if (outputAudioContextRef.current) {
        await outputAudioContextRef.current.close();
        outputAudioContextRef.current = null;
      }
      setIsVoiceMode(false);
      return;
    }

    if (!currentUser) return;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      inputAudioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser.preferences.voiceName || 'Zephyr' } },
          },
          systemInstruction: `You are Anora, talking to ${currentUser.name}. Keep responses concise and engaging for a real-time conversation.`,
        },
        callbacks: {
          onopen: () => {
            const source = inputCtx.createMediaStreamSource(stream);
            const scriptProcessor = inputCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const audioBuffer = await decodeAudioData(decode(base64Audio), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputCtx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              audioSourcesRef.current.add(source);
              source.onended = () => audioSourcesRef.current.delete(source);
            }
            if (message.serverContent?.interrupted) {
              audioSourcesRef.current.forEach(s => s.stop());
              audioSourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error("Live API Error:", e),
          onclose: () => setIsVoiceMode(false),
        },
      });

      setIsVoiceMode(true);
    } catch (err) {
      console.error("Failed to start voice mode:", err);
      setIsVoiceMode(false);
    }
  };

  const saveToVault = (content: string) => {
    if (!currentUser) return;
    const newItem: VaultItem = {
      id: Date.now().toString(),
      title: content.slice(0, 30) + '...',
      content,
      type: 'TEXT'
    };
    const updatedUser = { ...currentUser, vault: [...(currentUser.vault || []), newItem] };
    setCurrentUser(updatedUser);
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const isOwner = currentUser.email.toLowerCase() === OWNER_EMAIL;
  const accent = currentUser.preferences.accentColor;

  return (
    <div className={`flex flex-col h-[100dvh] bg-black text-zinc-300 overflow-hidden transition-all duration-700 ${currentUser.preferences.font === 'OUTFIT' ? 'font-outfit' : 'font-inter'} ${isOwner ? 'ring-inset ring-1 ring-amber-500/10' : ''}`}>
      <style>{`
        .accent-text { color: ${accent}; }
        .accent-bg { background-color: ${accent}; }
        .accent-border { border-color: ${accent}40; }
        .custom-gradient { background: linear-gradient(180deg, rgba(0,0,0,0) 0%, #000 100%); }
        .sidebar-transition { transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1); }
      `}</style>

      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      {/* Sidebar Overlay */}
      <div 
        className={`fixed inset-0 bg-black/40 backdrop-blur-sm z-[150] transition-opacity duration-500 ${isSidebarOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
        onClick={() => setIsSidebarOpen(false)}
      ></div>

      {/* Persistent Sidebar */}
      <aside className={`fixed top-0 left-0 h-full w-[280px] sm:w-[340px] bg-zinc-950/98 border-r border-zinc-900 z-[200] sidebar-transition ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} backdrop-blur-3xl pt-[calc(var(--sat)+1.5rem)] shadow-2xl shadow-black`}>
        <div className="flex flex-col h-full p-8">
           <div className="flex items-center justify-between mb-12">
              <AnoraLogo size={32} color={accent} showName={false} />
              <button onClick={() => setIsSidebarOpen(false)} className="p-3 text-zinc-600 hover:text-white transition-all bg-white/5 rounded-2xl active:scale-90">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
              </button>
           </div>

           <div className="space-y-12 flex-1 overflow-y-auto no-scrollbar">
              <div className="space-y-4 animate-reveal" style={{ animationDelay: '0.1s' }}>
                 <p className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em] mb-4 px-2">Sovereign Intel</p>
                 <div className="p-6 bg-zinc-900/40 rounded-[2.5rem] border border-zinc-800 space-y-4 group hover:border-zinc-700 transition-colors">
                    <div className="flex justify-between items-center">
                       <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">Logic Tier</span>
                       <span className="text-[10px] text-white font-bold uppercase tracking-widest accent-text">{currentUser.preferences.intelligenceLevel}</span>
                    </div>
                    <div className="flex justify-between items-center">
                       <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">Aura Sync</span>
                       <div className="w-3.5 h-3.5 rounded-full shadow-lg" style={{ backgroundColor: accent, boxShadow: `0 0 10px ${accent}40` }}></div>
                    </div>
                 </div>
              </div>

              <div className="space-y-4 animate-reveal" style={{ animationDelay: '0.2s' }}>
                 <p className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em] mb-4 px-2">Neural Vault</p>
                 <div className="space-y-3">
                    {currentUser.vault?.slice(-4).reverse().map((item, idx) => (
                      <div key={item.id} 
                           className="p-5 bg-white/[0.03] border border-zinc-900 rounded-[1.8rem] hover:bg-white/[0.06] hover:border-zinc-700 transition-all cursor-pointer group animate-reveal"
                           style={{ animationDelay: `${0.3 + idx * 0.1}s` }}>
                        <p className="text-[11px] text-zinc-500 font-medium group-hover:text-white transition-colors truncate">{item.title}</p>
                      </div>
                    ))}
                    <button onClick={() => { setIsHubOpen(true); setIsSidebarOpen(false); }} className="w-full py-4 text-[9px] font-bold text-zinc-700 uppercase tracking-[0.3em] hover:text-white transition-all group">
                      Explore Full Archive <span className="inline-block transition-transform group-hover:translate-x-1">→</span>
                    </button>
                 </div>
              </div>
           </div>

           <div className="pt-8 border-t border-zinc-900 animate-reveal" style={{ animationDelay: '0.6s' }}>
              <button onClick={() => { setIsProfileOpen(true); setIsSidebarOpen(false); }} className="flex items-center gap-4 w-full p-4 rounded-[2rem] hover:bg-white/5 transition-all group">
                <div className="w-12 h-12 rounded-full bg-zinc-900 border border-zinc-800 overflow-hidden shrink-0 group-hover:border-zinc-600 transition-colors">
                  {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-zinc-700 font-bold">{currentUser.name.charAt(0)}</div>}
                </div>
                <div className="text-left overflow-hidden">
                   <p className="text-[12px] font-bold text-white uppercase tracking-wider truncate group-hover:accent-text transition-colors">{currentUser.name}</p>
                   <p className="text-[9px] text-zinc-600 uppercase tracking-widest">{currentUser.role}</p>
                </div>
              </button>
           </div>
        </div>
      </aside>

      {/* Header */}
      <header className="flex items-center justify-between px-6 sm:px-12 pt-[calc(var(--sat)+1.5rem)] pb-6 border-b border-zinc-900 bg-black/95 backdrop-blur-3xl z-[100] shrink-0">
        <div className="flex items-center gap-4 sm:gap-8">
          <button onClick={() => setIsSidebarOpen(true)} className="p-3 text-zinc-500 hover:text-white transition-all bg-zinc-950 rounded-2xl border border-zinc-900 hover:border-zinc-700 active:scale-90">
             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
          </button>
          <div className="hidden sm:block">
            <AnoraLogo size={36} color={accent} />
          </div>
        </div>

        <div className="flex items-center gap-4 sm:gap-8">
          <VoiceIndicator active={isVoiceMode} />
          <div className="flex items-center gap-2 p-1.5 bg-zinc-950 rounded-[3rem] border border-zinc-900">
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-3.5 sm:p-4 text-zinc-500 hover:text-white transition-all rounded-full hover:bg-white/5"><svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></button>
            <button onClick={toggleVoiceMode} className={`p-3.5 sm:p-4 rounded-full transition-all active:scale-90 ${isVoiceMode ? 'bg-blue-500 text-white shadow-[0_0_20px_rgba(59,130,246,0.5)]' : 'text-zinc-500 hover:text-white hover:bg-white/5'}`}>
              <svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col relative overflow-hidden bg-black">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(255,255,255,0.01)_0%,_transparent_70%)] pointer-events-none"></div>
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          onSaveToVault={saveToVault}
          speakingId={speakingId}
          onSpeak={handleSpeak}
        />
      </main>

      {/* Interaction Layer */}
      <footer className="px-4 sm:px-12 lg:px-24 pt-2 pb-[calc(var(--sab)+1.2rem)] bg-black/98 backdrop-blur-3xl border-t border-zinc-900 z-[100] shrink-0">
        <div className="max-w-[1200px] mx-auto">

          {/* Action Chips */}
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-4 px-2 pt-2 scroll-smooth">
            {['Draft Lyric', 'CAD Logic', 'Concrete Estimate', 'Imagine Vision', 'Neural Vault'].map((chip, idx) => (
              <button 
                key={chip} 
                onClick={() => setInputValue(prev => prev + chip + ": ")}
                className="shrink-0 px-6 py-3 bg-zinc-900/40 border border-zinc-800 rounded-full text-[9px] font-bold text-zinc-600 uppercase tracking-widest hover:border-zinc-500 hover:text-white transition-all active:scale-95 animate-reveal"
                style={{ animationDelay: `${idx * 0.05}s` }}
              >
                {chip}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-3 sm:gap-5 mt-2">
            <button onClick={() => fileInputRef.current?.click()} className="p-4 sm:p-5 rounded-[2rem] bg-zinc-950 text-zinc-600 border border-zinc-900 hover:border-zinc-600 hover:text-zinc-300 transition-all active:scale-90 shadow-lg">
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              <input type="file" ref={fileInputRef} hidden multiple onChange={e => {
                const files = e.currentTarget.files;
                if (files) Array.from(files).forEach((f: File) => {
                  const reader = new FileReader();
                  reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]);
                  reader.readAsDataURL(f);
                });
              }} />
            </button>

            <button 
              onClick={() => setIsSynthesisMode(!isSynthesisMode)} 
              className={`p-4 sm:p-5 rounded-[2rem] border transition-all duration-500 active:scale-90 shadow-lg ${isSynthesisMode ? 'bg-amber-500 text-black border-amber-500 shadow-amber-500/20' : 'bg-zinc-950 text-zinc-600 border-zinc-900 hover:border-zinc-600 hover:text-zinc-300'}`}
              title="Synthesis Protocol"
            >
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </button>

            <div className="flex-1 relative flex items-center group">
              <input
                type="text"
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isSynthesisMode ? "Vision request..." : "State directive..."}
                className={`w-full bg-zinc-950 border text-zinc-100 rounded-[2.5rem] pl-8 pr-16 py-4.5 sm:py-5 focus:outline-none placeholder:text-zinc-800 text-sm sm:text-base transition-all duration-500 ${isSynthesisMode ? 'border-amber-500/40 shadow-[0_0_20px_rgba(245,158,11,0.05)] focus:border-amber-500' : 'border-zinc-900 group-hover:border-zinc-700 focus:border-zinc-600'}`}
              />
              <button onClick={() => handleSend(inputValue)} className={`absolute right-1.5 p-3.5 sm:p-4 rounded-full transition-all active:scale-[0.8] ${isSynthesisMode || isOwner ? 'bg-amber-500 text-black shadow-xl hover:bg-amber-400' : 'bg-white text-black hover:bg-zinc-200 shadow-lg'}`}>
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { Message, Role } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
  onSaveToVault?: (content: string) => void;
  speakingId?: string | null;
  onSpeak?: (id: string, content: string) => void;
}

export const MessageList: React.FC<MessageListProps> = ({ 
  messages, 
  isThinking, 
  ownerName, 
  isOwnerView, 
  onSaveToVault,
  speakingId,
  onSpeak
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-10 pt-10 pb-20 space-y-14 max-w-5xl mx-auto w-full scroll-smooth no-scrollbar relative z-10">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isSynthesis = !isUser && msg.images && msg.images.length > 0;
        const isSpeaking = speakingId === msg.id;

        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-reveal relative group`}
            style={{ animationDelay: `${Math.min(index * 0.05, 0.5)}s` }}
          >
            <div className={`max-w-[94%] sm:max-w-[85%] relative`}>

              {/* Context Actions (Desktop) */}
              {!isUser && (
                <div className="absolute -top-12 left-6 opacity-0 group-hover:opacity-100 transition-all duration-500 transform translate-y-2 group-hover:translate-y-0 flex gap-2 z-20">
                  <button 
                    onClick={() => onSpeak?.(msg.id, msg.content)}
                    className={`p-2.5 bg-zinc-950 border border-zinc-800 rounded-2xl transition-all shadow-2xl backdrop-blur-xl ${isSpeaking ? 'text-blue-500 border-blue-500/50' : 'text-zinc-500 hover:text-white hover:border-zinc-600'}`}
                    title={isSpeaking ? "Stop Synthesis" : "Narrate Logic"}
                  >
                    {isSpeaking ? (
                      <svg className="w-4 h-4 animate-pulse" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
                    ) : (
                      <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                    )}
                  </button>
                  <button 
                    onClick={() => onSaveToVault?.(msg.content)}
                    className="p-2.5 bg-zinc-950 border border-zinc-800 rounded-2xl text-zinc-500 hover:text-white hover:border-zinc-600 transition-all shadow-2xl backdrop-blur-xl"
                    title="Archive to Vault"
                  >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                  </button>
                  <button 
                    onClick={() => handleCopy(msg.content)}
                    className="p-2.5 bg-zinc-950 border border-zinc-800 rounded-2xl text-zinc-500 hover:text-white hover:border-zinc-600 transition-all shadow-2xl backdrop-blur-xl"
                    title="Copy Logic"
                  >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" /></svg>
                  </button>
                </div>
              )}

              {/* Metadata */}
              <div className={`flex items-center gap-3 mb-3 px-3 transition-all duration-700 opacity-30 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[9px] font-bold uppercase tracking-[0.3em] ${isUser ? (isOwnerView ? 'text-amber-500' : 'text-zinc-400') : 'text-zinc-500'}`}>
                  {isUser ? (isOwnerView ? 'Sovereign' : ownerName.split(' ')[0]) : (isSynthesis ? 'Synthesis Module' : 'Anora OS')}
                </span>
                <div className="w-1 h-1 rounded-full bg-zinc-800"></div>
                <span className="text-[8px] text-zinc-800 font-bold uppercase tracking-widest">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
                {isSpeaking && (
                   <div className="flex gap-0.5 items-end h-2 ml-1">
                      <div className="w-0.5 bg-blue-500 animate-[bounce_0.6s_infinite_ease-in-out]"></div>
                      <div className="w-0.5 bg-blue-500 animate-[bounce_0.8s_infinite_ease-in-out_0.1s]"></div>
                      <div className="w-0.5 bg-blue-500 animate-[bounce_0.5s_infinite_ease-in-out_0.2s]"></div>
                   </div>
                )}
              </div>

              {/* Media Blocks */}
              {msg.images && msg.images.length > 0 && (
                <div className={`grid gap-4 mb-5 animate-reveal ${msg.images.length === 4 ? 'grid-cols-2' : (msg.images.length > 1 ? 'flex flex-wrap' : 'flex')} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[2.5rem] border shadow-2xl transition-all duration-1000 hover:border-zinc-500
                      ${isSynthesis ? 'border-amber-500/20' : 'border-zinc-900'} 
                      ${msg.images && msg.images.length === 1 ? 'w-64 h-64 sm:w-[480px] sm:h-[480px]' : 'w-full aspect-square'}`}>
                      <img src={img} alt="V" className="w-full h-full object-cover transition-transform duration-[4s] group-hover/img:scale-110 group-hover/img:rotate-1" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity duration-700 flex flex-col items-center justify-center backdrop-blur-sm gap-4 pointer-events-none">
                         <span className="text-[9px] text-white font-bold uppercase tracking-[0.4em] bg-white/10 px-6 py-3 rounded-full border border-white/20">
                           {isSynthesis ? 'SOVEREIGN RENDER' : 'NEURAL ASSET'}
                         </span>
                         {isSynthesis && (
                           <a href={img} download={`anora_${Date.now()}.png`} className="pointer-events-auto bg-white text-black px-6 py-3 rounded-full text-[9px] font-bold uppercase tracking-widest hover:bg-zinc-200 transition-all active:scale-90">
                             Save to disk
                           </a>
                         )}
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {/* Message Bubble */}
              <div
