const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

const createBlob = (data: Float32Array): GenAIBlob => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
  return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('anora_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [isSynthesisMode, setIsSynthesisMode] = useState(false);
  const [currentEmotion, setCurrentEmotion] = useState<'HAPPY' | 'SAD' | 'NEUTRAL' | 'SOVEREIGN'>('NEUTRAL');

  const [speakingId, setSpeakingId] = useState<string | null>(null);
  const currentAudioSource = useRef<AudioBufferSourceNode | null>(null);
  const audioContext = useRef<AudioContext | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const wakeWordRecognition = useRef<any>(null);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      anoraService.initChat(currentUser);
      if (messages.length === 0) {
        setMessages([{
          id: 'initial',
          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT'),
          timestamp: new Date()
        }]);
      }

      // Start Wake Word Detection if owner
      if (currentUser.role === Role.OWNER && !wakeWordRecognition.current) {
        initWakeWord();
      }
    }
  }, [currentUser]);

  const initWakeWord = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      wakeWordRecognition.current = new SpeechRecognition();
      wakeWordRecognition.current.continuous = true;
      wakeWordRecognition.current.lang = 'en-US';
      wakeWordRecognition.current.onresult = (event: any) => {
        const transcript = event.results[event.results.length - 1][0].transcript.toLowerCase();
        if (transcript.includes('hey anora') || transcript.includes('anora')) {
          handleWakeAction();
        }
      };
      wakeWordRecognition.current.start();
    }
  };

  const handleWakeAction = () => {
    if (!isVoiceMode) {
      toggleVoiceMode();
      // Simple audio ping
      const ping = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
      ping.volume = 0.2;
      ping.play();
    }
  };

  const handleToolCalls = (calls: any[]) => {
    calls.forEach(call => {
      if (call.name === 'openApp') {
        const app = call.args.appName.toLowerCase();
        if (app === 'youtube') window.open('https://youtube.com', '_blank');
        if (app === 'calendar') window.open('https://calendar.google.com', '_blank');
      }
      if (call.name === 'setReminder') {
        const newReminder: Reminder = {
          id: Date.now().toString(),
          text: call.args.text,
          time: call.args.time,
          triggered: false
        };
        if (currentUser) {
          setCurrentUser({ ...currentUser, reminders: [...(currentUser.reminders || []), newReminder] });
        }
      }
      if (call.name === 'analyzeEmotion') {
        setCurrentEmotion(call.args.emotion);
      }
    });
  };

  const stopSpeech = () => {
    if (currentAudioSource.current) {
      try { currentAudioSource.current.stop(); } catch (e) {}
      currentAudioSource.current = null;
    }
    setSpeakingId(null);
  };

  const handleSpeak = async (messageId: string, content: string) => {
    if (!currentUser) return;
    if (speakingId === messageId) { stopSpeech(); return; }
    stopSpeech();
    setSpeakingId(messageId);
    try {
      const base64 = await anoraService.speak(content, currentUser.preferences.voiceName);
      if (!audioContext.current) audioContext.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const buffer = await decodeAudioData(decode(base64), audioContext.current, 24000, 1);
      const source = audioContext.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContext.current.destination);
      source.onended = () => { if (speakingId === messageId) setSpeakingId(null); };
      currentAudioSource.current = source;
      source.start();
    } catch (err) { setSpeakingId(null); }
  };

  const handleSend = async (text: string) => {
    const val = text.trim();
    if ((!val && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: val || "Sharing visual asset...",
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      let response;
      if (isSynthesisMode) {
        response = await anoraService.generateChatImage(val || "Synthesize vision.", userMsg.images || []);
      } else {
        response = await anoraService.sendMessageWithVision(val, userMsg.images || []);
      }

      if (response.toolCalls) handleToolCalls(response.toolCalls);

      const anoraMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'anora',
        content: response.text,
        sources: (response as any).sources,
        images: response.images,
