            <button onClick={toggleVoiceMode} className={`p-4 rounded-full transition-all active:scale-90 ${isVoiceMode ? 'bg-blue-500 text-white shadow-[0_0_20px_rgba(59,130,246,0.5)]' : 'text-zinc-500 hover:text-white hover:bg-white/5'}`}>
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden bg-black">
        <div className="absolute inset-0 emotion-aura pointer-events-none transition-all duration-1000"></div>
        {isOwner && <div className="absolute inset-0 bg-[radial-gradient(circle_at_20%_20%,_rgba(212,175,55,0.03)_0%,_transparent_50%)] pointer-events-none"></div>}
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          onSaveToVault={(c) => {
            const newItem: VaultItem = { id: Date.now().toString(), title: c.slice(0, 30) + '...', content: c, type: 'TEXT' };
            setCurrentUser({ ...currentUser, vault: [...(currentUser.vault || []), newItem] });
          }}
          speakingId={speakingId}
          onSpeak={handleSpeak}
        />
