          <div className="flex gap-2.5 overflow-x-auto no-scrollbar pb-5 px-2 pt-2 scroll-smooth">
            {['Hey Anora', 'Open YouTube', 'Set a reminder', 'Draft Lyric', 'Viral Hook Generator', 'CAD Site Log', 'Engineering Logic'].map((chip, idx) => (
              <button key={chip} onClick={() => setInputValue(chip + ": ")} className="shrink-0 px-7 py-3.5 bg-zinc-900/40 border border-zinc-800 rounded-full text-[10px] font-bold text-zinc-600 uppercase tracking-widest hover:border-zinc-500 hover:text-white transition-all active:scale-95">
                {chip}
