            </button>
            <div className="flex-1 relative flex items-center group">
              <input
                type="text"
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isOwner ? "Direct Command, Arjun..." : "Anora OS directive..."}
                className={`w-full bg-zinc-950 border text-zinc-100 rounded-[3rem] pl-10 pr-20 py-5 sm:py-6 focus:outline-none placeholder:text-zinc-800 text-base transition-all duration-500 border-zinc-900 group-hover:border-zinc-700 ${isOwner ? 'focus:border-amber-500/50' : 'focus:border-zinc-600'}`}
              />
              <button onClick={() => handleSend(inputValue)} className={`absolute right-2 p-4.5 sm:p-5 rounded-full transition-all active:scale-[0.8] shadow-2xl ${isOwner ? 'bg-amber-500 text-black hover:bg-amber-400' : 'bg-white text-black hover:bg-zinc-100'}`}>
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, AiMood, IntelligenceLevel, AppTheme, AppFont, Persona, CustomMood } from '../types';
import { ACCENT_COLORS, AI_MOODS, THEMES, LANGUAGES } from '../constants';
import { anoraService } from '../services/geminiService';

interface ProfileModalProps {
  user: User;
  isOpen: boolean;
  onClose: () => void;
  onUpdate: (updatedUser: User) => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ user, isOpen, onClose, onUpdate }) => {
  const [tab, setTab] = useState<'IDENTITY' | 'MOODS' | 'PERFORMANCE' | 'USERS'>('IDENTITY');
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || '');
  const [avatar, setAvatar] = useState(user.avatar || '');
  const [mood, setMood] = useState<AiMood>(user.preferences.aiMood);
  const [accent, setAccent] = useState(user.preferences.accentColor);
  const [intel, setIntel] = useState<IntelligenceLevel>(user.preferences.intelligenceLevel || 'BALANCED');
  const [lang, setLang] = useState(user.preferences.language || 'English');
  const [theme, setTheme] = useState<AppTheme>(user.preferences.theme || 'OBSIDIAN');
  const [font, setFont] = useState<AppFont>(user.preferences.font || 'INTER');
  const [sound, setSound] = useState(user.preferences.soundEnabled ?? true);
  const [persona, setPersona] = useState<Persona>(user.preferences.persona || 'DEFAULT');

  const [customMoods, setCustomMoods] = useState<CustomMood[]>(user.customMoods || []);
  const [editingMood, setEditingMood] = useState<Partial<CustomMood> | null>(null);

  const [avatarPrompt, setAvatarPrompt] = useState('');
  const [generatingAvatar, setGeneratingAvatar] = useState(false);
  const [showToast, setShowToast] = useState(false);
  const [allUsers, setAllUsers] = useState<User[]>([]);

  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(false), 2500);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  useEffect(() => {
    if (user.role === Role.OWNER && isOpen) {
      const usersRaw = localStorage.getItem('anora_users_db');
      setAllUsers(usersRaw ? JSON.parse(usersRaw) : []);
    }
  }, [isOpen, user.role]);

  if (!isOpen) return null;

  const handleSave = () => {
    onUpdate({
      ...user,
      name,
      bio,
      avatar,
      customMoods,
      preferences: {
        ...user.preferences,
        aiMood: mood,
        accentColor: accent,
        intelligenceLevel: intel,
        language: lang,
        theme,
        font,
        soundEnabled: sound,
        persona
      }
    });
    setShowToast(true);
    setTimeout(onClose, 1200);
  };

  const handleGenerateAvatar = async () => {
    if (!avatarPrompt.trim()) return;
    setGeneratingAvatar(true);
    try {
      const base64 = await anoraService.generateImage(`Cinematic high-fidelity portrait, aesthetic AI art: ${avatarPrompt}`);
      setAvatar(`data:image/png;base64,${base64}`);
      setAvatarPrompt('');
    } catch (err: any) {
      alert(`Synthesis Failed: ${err.message}`);
    } finally {
      setGeneratingAvatar(false);
    }
  };

  const isOwner = user.role === Role.OWNER;
  const personaIcons: Record<Persona, string> = {
    DEFAULT: '🤖', FRIEND: '👋', TEACHER: '📚', MENTOR: '💼', GIRLFRIEND: '❤️',
    BOYFRIEND: '🤝', BROTHER: '🤜', SISTER: '🧚', SOVEREIGN_AI: '🌌'
  };

  const toggleUserRole = (userId: string) => {
    const updatedUsers = allUsers.map(u => {
      if (u.id === userId && u.role !== Role.OWNER) {
        const newRole = u.role === Role.USER ? Role.PREMIUM : Role.USER;
        const newTier = newRole === Role.PREMIUM ? SubscriptionTier.PRO : SubscriptionTier.FREE;
        return { ...u, role: newRole, tier: newTier };
      }
      return u;
    });
    setAllUsers(updatedUsers);
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
  };

  const deleteUser = (userId: string) => {
    const userToDelete = allUsers.find(u => u.id === userId);
    if (userToDelete?.role === Role.OWNER) {
      alert("Sovereign protection active: Cannot delete Owner.");
      return;
    }
    const updatedUsers = allUsers.filter(u => u.id !== userId);
    setAllUsers(updatedUsers);
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-0 sm:p-6 bg-black/98 backdrop-blur-3xl animate-in fade-in duration-300">

      {showToast && (
        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[220] animate-in slide-in-from-top-6 duration-500">
          <div className="bg-white text-black px-12 py-4 rounded-[3rem] font-bold text-[10px] uppercase tracking-[0.5em] shadow-[0_0_60px_rgba(255,255,255,0.2)]">
            Neural State Synced
          </div>
        </div>
      )}

      <div className={`w-full max-w-6xl bg-[#050505] border-t sm:border border-zinc-900 rounded-none sm:rounded-[5rem] shadow-[0_0_150px_rgba(0,0,0,1)] flex flex-col h-[100dvh] sm:h-auto sm:max-h-[96vh] transition-all duration-700 ${isOwner ? 'ring-2 ring-amber-500/10' : ''} animate-in zoom-in-95 duration-500 overflow-hidden`}>

        <div className="shrink-0 px-8 sm:px-16 py-12 border-b border-zinc-900 flex items-center justify-between bg-[#050505] z-20">
          <div className="flex items-center gap-6">
            {isOwner && (
              <div className="w-12 h-12 rounded-2xl bg-amber-500/10 border border-amber-500/30 flex items-center justify-center text-amber-500">
                <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5 2a1 1 0 011 1v1h1a1 1 0 010 2H6v1a1 1 0 01-2 0V6H3a1 1 0 010-2h1V3a1 1 0 011-1zm0 10a1 1 0 011 1v1h1a1 1 0 110 2H6v1a1 1 0 11-2 0v-1H3a1 1 0 110-2h1v-1a1 1 0 011-1zM12 2a1 1 0 01.967.744L14.146 7.2l5.256.916a1 1 0 01.516 1.626l-3.398 3.38.801 5.237a1 1 0 01-1.451 1.054L11 16.926l-4.87 2.487a1 1 0 01-1.451-1.054l.801-5.237-3.398-3.38a1 1 0 01.516-1.626l5.256-.916 1.213-4.456a1 1 0 01.967-.744z" clipRule="evenodd"/></svg>
              </div>
            )}
            <div className="animate-in slide-in-from-left duration-700">
              <h2 className={`text-2xl sm:text-4xl font-bold font-outfit ${isOwner ? 'text-amber-500' : 'text-white'}`}>{isOwner ? 'Sovereign Control' : 'Neural Config'}</h2>
              <p className="text-[10px] sm:text-xs text-zinc-700 uppercase tracking-[0.5em] font-bold mt-2">Omni-System Interface v8.2</p>
            </div>
          </div>
          <button onClick={onClose} className="p-6 text-zinc-600 hover:text-white transition-all bg-white/5 rounded-[3rem] group active:scale-90 hover:bg-white/10">
            <svg xmlns="http://www.w3.org/2000/svg" className="w-8 h-8 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-black/40 p-2 mx-16 mt-8 rounded-3xl border border-zinc-900 gap-1 overflow-x-auto no-scrollbar">
          {(['IDENTITY', 'MOODS', 'PERFORMANCE', 'USERS'] as const).map(t => {
            if (t === 'USERS' && !isOwner) return null;
            return (
              <button key={t} onClick={() => setTab(t)} className={`flex-1 min-w-[120px] py-4 text-[10px] font-bold uppercase tracking-[0.3em] rounded-2xl transition-all ${tab === t ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-600 hover:text-zinc-400'}`}>{t}</button>
            );
