        </div>

        <div className="flex-1 overflow-y-auto px-8 sm:px-16 py-12 space-y-16 no-scrollbar scroll-smooth">

          {tab === 'IDENTITY' && (
            <section className="flex flex-col md:flex-row gap-16 p-12 bg-zinc-900/10 rounded-[5rem] border border-zinc-900/50 animate-in slide-in-from-bottom-8 duration-700 shadow-inner">
               <div className="flex flex-col items-center gap-8 shrink-0">
                  <div className={`w-52 h-52 rounded-full flex items-center justify-center text-7xl font-bold border-2 transition-all duration-1000 overflow-hidden relative shadow-2xl ${isOwner ? 'border-amber-500/50 shadow-amber-500/20' : 'border-zinc-800'}`}>
                    {avatar ? <img src={avatar} className="w-full h-full object-cover" alt="AV" /> : user.name.charAt(0)}
                    {generatingAvatar && (
                      <div className="absolute inset-0 bg-black/95 flex items-center justify-center backdrop-blur-xl">
                        <div className="w-16 h-16 border-4 border-white/5 border-t-white rounded-full animate-spin"></div>
                      </div>
                    )}
                  </div>
                  <div className="w-full space-y-4">
                     <input type="text" placeholder="Visual asset description..." value={avatarPrompt} onChange={(e) => setAvatarPrompt(e.target.value)} className="w-full bg-black/60 border border-zinc-900 rounded-[2rem] px-8 py-5 text-[11px] outline-none focus:border-zinc-600 transition-all font-bold text-center text-white placeholder:text-zinc-800" />
