                    <div key={u.id} className={`p-8 bg-zinc-900/10 border rounded-[3rem] flex items-center justify-between gap-6 group hover:border-zinc-700 transition-all ${u.role === Role.OWNER ? 'border-amber-500/20 bg-amber-500/5' : 'border-zinc-900'}`}>
                       <div className="flex items-center gap-8">
