            <button onClick={() => setIsCommandCenterOpen(true)} className="p-4 text-zinc-500 hover:text-white transition-all rounded-full hover:bg-white/5 active:scale-90"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></button>
            <button onClick={toggleVoiceMode} className={`p-4 rounded-full transition-all active:scale-90 ${isVoiceMode ? 'bg-blue-500 text-white shadow-[0_0_25px_rgba(59,130,246,0.6)]' : 'text-zinc-500 hover:text-white hover:bg-white/5'}`}>
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            </button>
          </div>
        </div>
      </header>

      <main className={`flex-1 flex flex-col relative overflow-hidden bg-black ${isOwner ? 'owner-royal-bg' : ''}`}>
        <div className="absolute inset-0 emotion-aura pointer-events-none transition-all duration-1000"></div>
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          onSaveToVault={(c) => {
            const newItem: VaultItem = { id: Date.now().toString(), title: c.slice(0, 30) + '...', content: c, type: 'TEXT' };
            setCurrentUser({ ...currentUser, vault: [...(currentUser.vault || []), newItem] });
          }}
          speakingId={speakingId}
          onSpeak={handleSpeak}
        />
      </main>

      <footer className="px-6 sm:px-12 lg:px-24 pt-4 pb-[calc(var(--sab)+1.5rem)] bg-black/98 backdrop-blur-3xl border-t border-zinc-900 z-[100] shrink-0">
        <div className="max-w-[1200px] mx-auto">
          <div className="flex gap-3 overflow-x-auto no-scrollbar pb-6 px-2 pt-2 scroll-smooth">
            {['Hey Anora', 'Open YouTube', 'Set a reminder', 'Script viral hook', 'Draft Lyrics', 'Imagine visual art', 'CAD Logic'].map((chip, idx) => (
              <button key={chip} onClick={() => setInputValue(chip + ": ")} className="shrink-0 px-8 py-4 bg-zinc-900/40 border border-zinc-800 rounded-full text-[10px] font-bold text-zinc-500 uppercase tracking-widest hover:border-zinc-500 hover:text-white transition-all active:scale-95">
                {chip}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-4 sm:gap-6 mt-2">
            <button onClick={() => setIsHubOpen(true)} className="p-5 sm:p-6 rounded-[2.5rem] bg-zinc-950 text-zinc-600 border border-zinc-900 hover:border-zinc-600 shadow-xl group transition-all">
              <svg className="w-8 h-8 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
            </button>
            <div className="flex-1 relative flex items-center group">
              <input
                type="text"
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isOwner ? "Sovereign Command..." : "Anora OS directive..."}
                className={`w-full bg-zinc-950 border text-zinc-100 rounded-[3.5rem] pl-10 pr-24 py-6 sm:py-7 focus:outline-none placeholder:text-zinc-800 text-base transition-all duration-500 border-zinc-900 group-hover:border-zinc-700 ${isOwner ? 'focus:border-amber-500/40 shadow-[0_0_30px_rgba(212,175,55,0.05)]' : 'focus:border-zinc-600'}`}
              />
              <button onClick={() => handleSend(inputValue)} className={`absolute right-2.5 p-5 sm:p-6 rounded-full transition-all active:scale-[0.8] shadow-2xl ${isOwner ? 'bg-amber-500 text-black hover:bg-amber-400' : 'bg-white text-black hover:bg-zinc-100'}`}>
                <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, AiMood, IntelligenceLevel, AppTheme, AppFont, Persona, CustomMood } from '../types';
import { ACCENT_COLORS, AI_MOODS, THEMES, LANGUAGES } from '../constants';
import { anoraService } from '../services/geminiService';

interface ProfileModalProps {
  user: User;
  isOpen: boolean;
  onClose: () => void;
  onUpdate: (updatedUser: User) => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ user, isOpen, onClose, onUpdate }) => {
  const [tab, setTab] = useState<'IDENTITY' | 'MOODS' | 'PERFORMANCE' | 'USERS'>('IDENTITY');
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || '');
  const [avatar, setAvatar] = useState(user.avatar || '');
  const [mood, setMood] = useState<AiMood>(user.preferences.aiMood);
  const [accent, setAccent] = useState(user.preferences.accentColor);
  const [intel, setIntel] = useState<IntelligenceLevel>(user.preferences.intelligenceLevel || 'BALANCED');
  const [lang, setLang] = useState(user.preferences.language || 'English');
  const [theme, setTheme] = useState<AppTheme>(user.preferences.theme || 'OBSIDIAN');
  const [font, setFont] = useState<AppFont>(user.preferences.font || 'INTER');
  const [sound, setSound] = useState(user.preferences.soundEnabled ?? true);
  const [persona, setPersona] = useState<Persona>(user.preferences.persona || 'DEFAULT');

  const [customMoods, setCustomMoods] = useState<CustomMood[]>(user.customMoods || []);
  const [editingMood, setEditingMood] = useState<Partial<CustomMood> | null>(null);

  const [avatarPrompt, setAvatarPrompt] = useState('');
  const [generatingAvatar, setGeneratingAvatar] = useState(false);
  const [showToast, setShowToast] = useState(false);
  const [allUsers, setAllUsers] = useState<User[]>([]);

  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(false), 2500);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  useEffect(() => {
    if (user.role === Role.OWNER && isOpen) {
      const usersRaw = localStorage.getItem('anora_users_db');
      setAllUsers(usersRaw ? JSON.parse(usersRaw) : []);
    }
  }, [isOpen, user.role]);

  if (!isOpen) return null;

  const handleSave = () => {
    onUpdate({
      ...user,
      name,
      bio,
      avatar,
      customMoods,
      preferences: {
        ...user.preferences,
        aiMood: mood,
        accentColor: accent,
        intelligenceLevel: intel,
        language: lang,
        theme,
        font,
        soundEnabled: sound,
        persona
      }
    });
    setShowToast(true);
    setTimeout(onClose, 1200);
  };

  const handleGenerateAvatar = async () => {
    if (!avatarPrompt.trim()) return;
    setGeneratingAvatar(true);
    try {
      const base64 = await anoraService.generateImage(`Cinematic high-fidelity portrait, royal aesthetic AI art: ${avatarPrompt}`);
      setAvatar(`data:image/png;base64,${base64}`);
      setAvatarPrompt('');
    } catch (err: any) {
      alert(`Synthesis Failed: ${err.message}`);
    } finally {
      setGeneratingAvatar(false);
    }
  };

  const isOwner = user.role === Role.OWNER;

  const toggleUserRole = (userId: string) => {
    const updatedUsers = allUsers.map(u => {
      if (u.id === userId && u.role !== Role.OWNER) {
        const newRole = u.role === Role.USER ? Role.PREMIUM : Role.USER;
        const newTier = newRole === Role.PREMIUM ? SubscriptionTier.PRO : SubscriptionTier.FREE;
        return { ...u, role: newRole, tier: newTier };
      }
      return u;
    });
    setAllUsers(updatedUsers);
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
  };

  const deleteUser = (userId: string) => {
    const userToDelete = allUsers.find(u => u.id === userId);
    if (userToDelete?.role === Role.OWNER) {
      alert("Sovereign protection active: System Architect remains absolute.");
      return;
    }
    const updatedUsers = allUsers.filter(u => u.id !== userId);
    setAllUsers(updatedUsers);
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-0 sm:p-6 bg-black/98 backdrop-blur-3xl animate-in fade-in duration-300">

      {showToast && (
        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[220] animate-in slide-in-from-top-6 duration-500">
          <div className="bg-white text-black px-12 py-4 rounded-[3rem] font-bold text-[10px] uppercase tracking-[0.5em] shadow-[0_0_60px_rgba(255,255,255,0.3)]">
            Neural Matrix Synchronized
          </div>
        </div>
      )}

      <div className={`w-full max-w-6xl bg-[#050505] border-t sm:border border-zinc-900 rounded-none sm:rounded-[5rem] shadow-[0_0_150px_rgba(0,0,0,1)] flex flex-col h-[100dvh] sm:h-auto sm:max-h-[96vh] transition-all duration-1000 ${isOwner ? 'royal-border' : ''} animate-in zoom-in-95 duration-500 overflow-hidden`}>

        <div className="shrink-0 px-10 sm:px-20 py-16 border-b border-zinc-900 flex items-center justify-between bg-[#050505] z-20">
          <div className="flex items-center gap-8">
            {isOwner && (
              <div className="w-16 h-16 rounded-[2rem] bg-amber-500/10 border border-amber-500/30 flex items-center justify-center text-amber-500 royal-glow-active">
                <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5 2a1 1 0 011 1v1h1a1 1 0 010 2H6v1a1 1 0 01-2 0V6H3a1 1 0 010-2h1V3a1 1 0 011-1zm0 10a1 1 0 011 1v1h1a1 1 0 110 2H6v1a1 1 0 11-2 0v-1H3a1 1 0 110-2h1v-1a1 1 0 011-1zM12 2a1 1 0 01.967.744L14.146 7.2l5.256.916a1 1 0 01.516 1.626l-3.398 3.38.801 5.237a1 1 0 01-1.451 1.054L11 16.926l-4.87 2.487a1 1 0 01-1.451-1.054l.801-5.237-3.398-3.38a1 1 0 01.516-1.626l5.256-.916 1.213-4.456a1 1 0 01.967-.744z" clipRule="evenodd"/></svg>
              </div>
            )}
            <div className="animate-in slide-in-from-left duration-1000">
              <h2 className={`text-3xl sm:text-5xl font-bold font-outfit ${isOwner ? 'gold-gradient' : 'text-white'}`}>{isOwner ? 'Sovereign Protocol' : 'Neural Config'}</h2>
              <p className="text-[10px] sm:text-xs text-zinc-700 uppercase tracking-[0.6em] font-bold mt-3">Universal Link Established • v8.5</p>
            </div>
          </div>
          <button onClick={onClose} className="p-8 text-zinc-600 hover:text-white transition-all bg-white/5 rounded-[4rem] group active:scale-90 hover:bg-white/10">
            <svg xmlns="http://www.w3.org/2000/svg" className="w-10 h-10 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-black/40 p-2.5 mx-20 mt-10 rounded-3xl border border-zinc-900 gap-2 overflow-x-auto no-scrollbar">
          {(['IDENTITY', 'MOODS', 'PERFORMANCE', 'USERS'] as const).map(t => {
            if (t === 'USERS' && !isOwner) return null;
            return (
              <button key={t} onClick={() => setTab(t)} className={`flex-1 min-w-[140px] py-5 text-[11px] font-bold uppercase tracking-[0.4em] rounded-2xl transition-all duration-500 ${tab === t ? 'bg-zinc-800 text-white shadow-2xl' : 'text-zinc-700 hover:text-zinc-400'}`}>{t}</button>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto px-10 sm:px-20 py-16 space-y-20 no-scrollbar scroll-smooth">

          {tab === 'IDENTITY' && (
            <section className="flex flex-col xl:flex-row gap-20 p-16 bg-zinc-900/10 rounded-[6rem] border border-zinc-900/50 animate-in slide-in-from-bottom-12 duration-1000 shadow-inner relative">
               {isOwner && <div className="absolute inset-0 bg-gradient-to-tr from-amber-500/5 via-transparent to-amber-500/5 pointer-events-none rounded-[6rem]"></div>}
               <div className="flex flex-col items-center gap-10 shrink-0 relative z-10">
                  <div className={`w-64 h-64 rounded-full flex items-center justify-center text-8xl font-bold border-2 transition-all duration-1000 overflow-hidden relative shadow-2xl ${isOwner ? 'border-amber-500/50 royal-glow-active' : 'border-zinc-800'}`}>
                    {avatar ? <img src={avatar} className="w-full h-full object-cover" alt="AV" /> : user.name.charAt(0)}
                    {generatingAvatar && (
                      <div className="absolute inset-0 bg-black/98 flex items-center justify-center backdrop-blur-3xl">
                        <div className="w-20 h-20 border-[6px] border-white/5 border-t-white rounded-full animate-spin"></div>
                      </div>
                    )}
                  </div>
                  <div className="w-full space-y-5">
                     <input type="text" placeholder="Visual asset directive..." value={avatarPrompt} onChange={(e) => setAvatarPrompt(e.target.value)} className="w-full bg-black/60 border border-zinc-900 rounded-[2.5rem] px-10 py-6 text-[12px] outline-none focus:border-zinc-600 transition-all font-bold text-center text-white placeholder:text-zinc-900" />
                     <button onClick={handleGenerateAvatar} disabled={generatingAvatar || !avatarPrompt.trim()} className={`w-full py-6 rounded-[3rem] text-[12px] font-bold uppercase tracking-[0.5em] transition-all active:scale-95 shadow-2xl ${isOwner ? 'bg-amber-500 text-black hover:bg-amber-400' : 'bg-white text-black hover:bg-zinc-200'}`}>Synthesize Identity</button>
                  </div>
               </div>

               <div className="flex-1 space-y-12 relative z-10">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-12">
                     <div className="space-y-6">
                        <label className={`text-[12px] font-bold uppercase tracking-[0.6em] block ml-6 ${isOwner ? 'gold-gradient' : 'text-zinc-700'}`}>System Alias</label>
                        <input value={name} onChange={(e) => setName(e.target.value)} className="bg-zinc-950/50 border border-zinc-900 rounded-[3rem] px-12 py-8 text-white font-bold text-3xl w-full outline-none focus:border-zinc-700 transition-all shadow-inner" />
                     </div>
                     <div className="space-y-6">
                        <label className={`text-[12px] font-bold uppercase tracking-[0.6em] block ml-6 ${isOwner ? 'gold-gradient' : 'text-zinc-700'}`}>Core Language</label>
                        <select value={lang} onChange={(e) => setLang(e.target.value)} className="w-full bg-zinc-950/50 border border-zinc-900 rounded-[3rem] px-12 py-8 text-zinc-300 focus:outline-none appearance-none text-[12px] font-bold uppercase tracking-[0.3em] hover:border-zinc-700 cursor-pointer shadow-inner">
                          {LANGUAGES.map(l => <option key={l} value={l} className="bg-[#050505]">{l}</option>)}
                        </select>
                     </div>
                  </div>
                  <div className="space-y-6">
                     <label className={`text-[12px] font-bold uppercase tracking-[0.6em] block ml-6 ${isOwner ? 'gold-gradient' : 'text-zinc-700'}`}>Neural Context Bank</label>
                     <textarea value={bio} onChange={(e) => setBio(e.target.value)} rows={5} className="bg-zinc-950/50 border border-zinc-900 rounded-[4rem] p-12 focus:border-zinc-700 text-zinc-300 text-xl w-full outline-none transition-all resize-none leading-relaxed shadow-inner" placeholder="Inject core personality directives for AI alignment..." />
                  </div>
               </div>
            </section>
          )}

          {tab === 'USERS' && isOwner && (
            <section className="space-y-12 animate-in slide-in-from-bottom-12 duration-1000">
               <div className="flex items-center justify-between px-10">
                  <h3 className="text-2xl font-bold font-outfit gold-gradient tracking-[0.4em] uppercase">ID Registry Dashboard</h3>
                  <span className="text-[11px] font-bold text-zinc-700 uppercase tracking-[0.3em]">{allUsers.length} Active System Nodes</span>
               </div>
               <div className="grid grid-cols-1 gap-8">
                  {allUsers.map(u => (
                    <div key={u.id} className={`p-10 bg-zinc-900/10 border rounded-[4rem] flex items-center justify-between gap-10 group transition-all duration-500 hover:scale-[1.01] ${u.role === Role.OWNER ? 'royal-border bg-amber-500/5' : 'border-zinc-900 hover:border-zinc-700'}`}>
                       <div className="flex items-center gap-10">
                          <div className={`w-20 h-20 rounded-full border-[3px] overflow-hidden flex items-center justify-center text-2xl font-bold ${u.role === Role.OWNER ? 'border-amber-500 shadow-xl' : 'border-zinc-800'}`}>
                             {u.avatar ? <img src={u.avatar} className="w-full h-full object-cover" /> : u.name.charAt(0)}
                          </div>
                          <div>
                             <h4 className={`font-bold text-2xl uppercase tracking-widest ${u.role === Role.OWNER ? 'gold-gradient' : 'text-zinc-200'}`}>{u.name}</h4>
                             <p className="text-[11px] text-zinc-700 font-bold uppercase mt-1 tracking-[0.2em]">{u.email}</p>
                          </div>
                       </div>
                       <div className="flex items-center gap-8">
                          {u.role !== Role.OWNER && (
                            <button 
                              onClick={() => toggleUserRole(u.id)}
                              className={`px-10 py-5 rounded-full text-[11px] font-bold uppercase tracking-[0.4em] transition-all active:scale-95 border ${u.role === Role.PREMIUM ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-transparent border-zinc-800 text-zinc-600 hover:border-blue-500 hover:text-blue-500'}`}
                            >
                              {u.role === Role.PREMIUM ? 'Revoke Premium' : 'Grant Sovereign Tier'}
                            </button>
                          )}
                          <div className={`px-8 py-3 rounded-2xl text-[10px] font-bold uppercase tracking-[0.3em] border ${u.role === Role.OWNER ? 'bg-amber-500 text-black border-amber-500 shadow-xl' : 'bg-zinc-950 border-zinc-900 text-zinc-800'}`}>
                             {u.role}
                          </div>
                          {u.role !== Role.OWNER && (
                            <button onClick={() => deleteUser(u.id)} className="p-5 text-zinc-800 hover:text-red-500 transition-all bg-red-500/5 rounded-3xl hover:bg-red-500/20 active:scale-90 shadow-lg">
                               <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                            </button>
                          )}
                       </div>
                    </div>
                  ))}
               </div>
            </section>
          )}

          {tab === 'MOODS' && (
            <section className="space-y-20 animate-in slide-in-from-bottom-12 duration-1000">
               <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-8">
                 {Object.keys(AI_MOODS).map(m => (
                   <button key={m} onClick={() => setMood(m)} className={`py-14 px-8 rounded-[4rem] border transition-all duration-700 flex flex-col items-center gap-8 relative group ${mood === m ? 'bg-white border-white text-black shadow-2xl scale-110' : 'bg-zinc-950/40 border-zinc-900 text-zinc-800 hover:border-zinc-700 hover:text-zinc-500'}`}>
                      <span className="text-[12px] font-bold tracking-[0.3em] uppercase text-center leading-tight">{m}</span>
                   </button>
                 ))}
                 {customMoods.map(m => (
                    <button key={m.id} onClick={() => setMood(m.id)} className={`py-14 px-8 rounded-[4rem] border transition-all duration-700 flex flex-col items-center gap-8 relative group ${mood === m.id ? 'bg-amber-500 border-amber-500 text-black scale-110 shadow-2xl' : 'bg-zinc-950/40 border-zinc-900 text-zinc-800'}`}>
                      <span className="text-[12px] font-bold tracking-[0.3em] uppercase text-center leading-tight">{m.name}</span>
                    </button>
                 ))}
               </div>

               {isOwner && (
                 <div className={`p-16 bg-zinc-950 border border-amber-500/10 rounded-[5rem] space-y-16 ${isOwner ? 'royal-border shadow-2xl' : ''}`}>
                    <div className="flex justify-between items-center">
                       <h3 className="text-2xl font-bold font-outfit gold-gradient tracking-[0.4em] uppercase">Emotion Logic Synthesis</h3>
