    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      wakeWordRecognition.current = new SpeechRecognition();
      wakeWordRecognition.current.continuous = true;
      wakeWordRecognition.current.lang = 'en-US';
      wakeWordRecognition.current.onresult = (event: any) => {
        const transcript = event.results[event.results.length - 1][0].transcript.toLowerCase();
        if (transcript.includes('hey anora') || transcript.includes('anora')) {
          handleWakeAction();
        }
      };
      try { wakeWordRecognition.current.start(); } catch (e) {
        console.warn("Wake word start failed:", e);
      }
    }
  };

  const handleWakeAction = () => {
    if (!isVoiceMode) {
      toggleVoiceMode();
      const ping = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
      ping.volume = 0.1;
      ping.play().catch(() => {});
    }
  };

  const handleToolCalls = (calls: any[]) => {
    calls.forEach(call => {
      if (call.name === 'openApp') {
        const app = call.args.appName.toLowerCase();
        if (app.includes('youtube')) window.open('https://youtube.com', '_blank');
        else if (app.includes('calendar')) window.open('https://calendar.google.com', '_blank');
        else if (app.includes('whatsapp')) window.open('https://web.whatsapp.com', '_blank');
        else if (app.includes('google')) window.open('https://google.com', '_blank');
      }
      if (call.name === 'setReminder') {
        const newReminder: Reminder = {
          id: Date.now().toString(),
          text: call.args.text,
          time: call.args.time,
          triggered: false
        };
        if (currentUser) {
          setCurrentUser({ ...currentUser, reminders: [...(currentUser.reminders || []), newReminder] });
        }
      }
      if (call.name === 'analyzeEmotion') {
        setCurrentEmotion(call.args.emotion as any);
      }
    });
  };

  const stopSpeech = () => {
    if (currentAudioSource.current) {
      try { currentAudioSource.current.stop(); } catch (e) {}
      currentAudioSource.current = null;
    }
    setSpeakingId(null);
  };

  const handleSpeak = async (messageId: string, content: string) => {
    if (!currentUser) return;
    if (speakingId === messageId) { stopSpeech(); return; }
    stopSpeech();
    setSpeakingId(messageId);
    try {
      const base64 = await anoraService.speak(content, currentUser.preferences.voiceName);
      if (!audioContext.current) audioContext.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const buffer = await decodeAudioData(decode(base64), audioContext.current, 24000, 1);
      const source = audioContext.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContext.current.destination);
      source.onended = () => { if (speakingId === messageId) setSpeakingId(null); };
      currentAudioSource.current = source;
      source.start();
    } catch (err) { 
      console.error("Speech synthesis failed", err);
      setSpeakingId(null); 
    }
  };

  const handleSend = async (text: string) => {
    const val = text.trim();
    if ((!val && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: val || "Neural input received.",
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      let response;
      if (isSynthesisMode || val.toLowerCase().includes('generate image') || val.toLowerCase().includes('imagine')) {
        response = await anoraService.generateChatImage(val || "Synthesize visual concept.", userMsg.images || []);
      } else {
        response = await anoraService.sendMessageWithVision(val, userMsg.images || []);
      }

      if (response.toolCalls) handleToolCalls(response.toolCalls);

      const anoraMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'anora',
        content: response.text,
        sources: (response as any).sources,
        images: response.images,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, anoraMsg]);
      // Explicitly NO auto-speak logic here to satisfy "off by default" requirement
    } catch (err) { console.error(err); } finally { setIsThinking(false); setIsSynthesisMode(false); }
  };

  const toggleVoiceMode = async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Neural capture not supported on this device.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = currentUser?.preferences.language === 'Hindi' ? 'hi-IN' : 'en-US';
    recognition.onresult = (e: any) => {
      const text = e.results[0][0].transcript;
      handleSend(text);
      setIsVoiceMode(false);
    };
    recognition.onerror = () => setIsVoiceMode(false);
    recognition.onend = () => setIsVoiceMode(false);
    recognition.start();
    setIsVoiceMode(true);
  };

  const isOwner = currentUser.role === Role.OWNER;
  const accent = currentUser.preferences.accentColor;

  return (
    <div className={`flex flex-col h-[100dvh] bg-black text-zinc-300 overflow-hidden transition-all duration-700 ${currentUser.preferences.font === 'OUTFIT' ? 'font-outfit' : 'font-inter'} ${isOwner ? 'ring-inset ring-2 ring-amber-500/10' : ''}`}>
      <div className="absolute inset-0 neural-noise"></div>
      <style>{`
        .accent-text { color: ${accent}; }
        .accent-bg { background-color: ${accent}; }
        .emotion-aura { 
          background: radial-gradient(circle at 50% 50%, 
            ${currentEmotion === 'HAPPY' ? 'rgba(34,197,94,0.06)' : currentEmotion === 'SAD' ? 'rgba(59,130,246,0.06)' : currentEmotion === 'SOVEREIGN' ? 'rgba(212,175,55,0.1)' : 'rgba(255,255,255,0.01)'} 0%, 
            transparent 70%); 
        }
        .owner-royal-bg {
          background: radial-gradient(circle at 10% 10%, rgba(191, 149, 63, 0.05) 0%, transparent 40%),
                      radial-gradient(circle at 90% 90%, rgba(179, 135, 40, 0.05) 0%, transparent 40%),
                      black;
        }
      `}</style>

      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <div className={`fixed inset-0 bg-black/80 backdrop-blur-2xl z-[150] transition-opacity duration-700 ${isSidebarOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`} onClick={() => setIsSidebarOpen(false)}></div>

      <aside className={`fixed top-0 left-0 h-full w-[290px] sm:w-[380px] bg-zinc-950/98 border-r border-zinc-900 z-[200] sidebar-transition ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} backdrop-blur-3xl pt-[calc(var(--sat)+1.5rem)] shadow-2xl overflow-hidden`}>
        {isOwner && <div className="absolute inset-0 bg-gradient-to-b from-amber-500/5 to-transparent pointer-events-none"></div>}
        <div className="flex flex-col h-full p-8 relative z-10">
           <div className="flex items-center justify-between mb-12">
              <AnoraLogo size={40} color={accent} showName={false} />
              <button onClick={() => setIsSidebarOpen(false)} className="p-3.5 text-zinc-600 hover:text-white transition-all bg-white/5 rounded-2xl active:scale-90 hover:bg-white/10">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
              </button>
           </div>
           <div className="space-y-14 flex-1 overflow-y-auto no-scrollbar">
              <div className="space-y-4">
                 <p className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em] mb-4 px-3">Logic Status</p>
                 <div className={`p-6 bg-zinc-900/40 rounded-[2.8rem] border border-zinc-800 space-y-4 ${isOwner ? 'royal-glow-active border-amber-500/20 shadow-amber-500/5' : ''}`}>
                    <div className="flex justify-between items-center">
                       <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">Compute Tier</span>
                       <span className={`text-[10px] font-bold uppercase tracking-widest ${isOwner ? 'gold-gradient' : 'text-white'}`}>{currentUser.preferences.intelligenceLevel}</span>
                    </div>
                    <div className="flex justify-between items-center">
                       <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">Aura Sync</span>
                       <div className="w-4 h-4 rounded-full shadow-lg animate-pulse" style={{ backgroundColor: accent, boxShadow: `0 0 20px ${accent}` }}></div>
                    </div>
                 </div>
              </div>
              <div className="space-y-5">
                 <p className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em] mb-4 px-3">Neural Feed</p>
                 <div className="space-y-3 px-1">
                    {currentUser.reminders?.filter(r => !r.triggered).map(rem => (
                      <div key={rem.id} className="p-5 bg-white/5 border border-zinc-900 rounded-[2.2rem] hover:border-zinc-700 transition-all group cursor-default">
                        <p className="text-[11px] text-zinc-300 font-bold uppercase tracking-tight group-hover:text-white transition-colors">{rem.text}</p>
                        <p className="text-[9px] text-zinc-600 mt-2 font-bold uppercase tracking-widest">{rem.time}</p>
                      </div>
                    ))}
                    {(!currentUser.reminders || currentUser.reminders.length === 0) && (
                      <div className="py-12 flex flex-col items-center gap-4 opacity-20">
                         <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <p className="text-[9px] text-zinc-400 uppercase tracking-widest font-bold">Quiescent Matrix</p>
                      </div>
                    )}
                 </div>
              </div>
           </div>
           <div className="pt-8 border-t border-zinc-900">
              <button onClick={() => { setIsProfileOpen(true); setIsSidebarOpen(false); }} className={`flex items-center gap-5 w-full p-5 rounded-[3rem] hover:bg-white/10 transition-all group ${isOwner ? 'royal-border' : ''}`}>
                <div className={`w-14 h-14 rounded-full border overflow-hidden shrink-0 transition-all duration-500 group-hover:scale-105 ${isOwner ? 'border-amber-500/40 shadow-2xl' : 'border-zinc-800'}`}>
                  {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-zinc-700 font-bold text-xl bg-zinc-900">{currentUser.name.charAt(0)}</div>}
                </div>
                <div className="text-left overflow-hidden">
                   <p className={`text-[14px] font-bold uppercase tracking-wider truncate transition-colors ${isOwner ? 'gold-gradient' : 'text-zinc-200'}`}>{currentUser.name}</p>
                   <p className="text-[10px] text-zinc-600 uppercase tracking-widest mt-0.5 font-bold">{isOwner ? 'Royal Architect' : currentUser.role}</p>
                </div>
              </button>
           </div>
        </div>
      </aside>

      <header className={`flex items-center justify-between px-6 sm:px-12 pt-[calc(var(--sat)+1.5rem)] pb-7 border-b border-zinc-900 bg-black/95 backdrop-blur-3xl z-[100] shrink-0 ${isOwner ? 'shadow-[0_4px_60px_rgba(212,175,55,0.08)]' : ''}`}>
        <div className="flex items-center gap-4 sm:gap-10">
          <button onClick={() => setIsSidebarOpen(true)} className="p-4 text-zinc-500 hover:text-white transition-all bg-zinc-950 rounded-2xl border border-zinc-900 hover:border-zinc-700 active:scale-90 shadow-xl">
             <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
          </button>
          <div className="hidden sm:block">
            <AnoraLogo size={46} color={accent} />
