            <button onClick={toggleVoiceMode} className={`p-4.5 rounded-full transition-all active:scale-90 ${isVoiceMode ? 'bg-blue-600 text-white shadow-[0_0_35px_rgba(37,99,235,0.5)]' : 'text-zinc-500 hover:text-white hover:bg-white/5'}`} title="Voice Command">
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            </button>
          </div>
        </div>
      </header>

      <main className={`flex-1 flex flex-col relative overflow-hidden bg-black ${isOwner ? 'owner-royal-bg' : ''}`}>
        <div className="absolute inset-0 emotion-aura pointer-events-none transition-all duration-1000"></div>
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          onSaveToVault={(c) => {
            const newItem: VaultItem = { id: Date.now().toString(), title: c.slice(0, 30) + '...', content: c, type: 'TEXT' };
            setCurrentUser({ ...currentUser, vault: [...(currentUser.vault || []), newItem] });
          }}
          speakingId={speakingId}
          onSpeak={handleSpeak}
        />
      </main>

      <footer className="px-6 sm:px-12 lg:px-24 pt-5 pb-[calc(var(--sab)+1.8rem)] bg-black/98 backdrop-blur-3xl border-t border-zinc-900 z-[100] shrink-0 relative">
        <div className="max-w-[1250px] mx-auto">
          <div className="flex gap-3.5 overflow-x-auto no-scrollbar pb-7 px-2 pt-2 scroll-smooth">
            {['Hey Anora', 'Open YouTube', 'Set a reminder', 'Script viral hook', 'AutoCAD Log', 'Imagine cinematic art', 'Draft Lyric Forge'].map((chip, idx) => (
              <button key={chip} onClick={() => setInputValue(chip + ": ")} className={`shrink-0 px-9 py-4.5 bg-zinc-900/40 border border-zinc-800 rounded-full text-[10px] font-bold text-zinc-500 uppercase tracking-[0.2em] hover:border-zinc-500 hover:text-white transition-all active:scale-95 ${isOwner ? 'hover:shadow-[0_0_20px_rgba(212,175,55,0.1)]' : ''}`}>
                {chip}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-5 sm:gap-8 mt-1">
            <button onClick={() => setIsHubOpen(true)} className="p-6 sm:p-7 rounded-[3.2rem] bg-zinc-950 text-zinc-600 border border-zinc-900 hover:border-zinc-500 shadow-2xl group transition-all active:scale-90 hover:text-white">
              <svg className="w-8 h-8 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
            </button>
            <div className="flex-1 relative flex items-center group">
              <input
                type="text"
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isOwner ? "Direct Command, Arjun..." : "Initiate Anora directive..."}
                className={`w-full bg-zinc-950 border text-zinc-100 rounded-[4.5rem] pl-14 pr-28 py-7 sm:py-9 focus:outline-none placeholder:text-zinc-900 text-lg transition-all duration-500 border-zinc-900 group-hover:border-zinc-700 ${isOwner ? 'focus:border-amber-500/40 shadow-[0_0_50px_rgba(212,175,55,0.08)]' : 'focus:border-zinc-600'}`}
              />
              <button onClick={() => handleSend(inputValue)} className={`absolute right-3 p-6 sm:p-7 rounded-full transition-all active:scale-[0.85] shadow-2xl ${isOwner ? 'bg-amber-500 text-black hover:bg-amber-400' : 'bg-white text-black hover:bg-zinc-200'}`}>
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, AiMood, IntelligenceLevel, AppTheme, AppFont, Persona, CustomMood } from '../types';
import { ACCENT_COLORS, AI_MOODS, THEMES, LANGUAGES } from '../constants';
import { anoraService } from '../services/geminiService';

interface ProfileModalProps {
  user: User;
  isOpen: boolean;
  onClose: () => void;
  onUpdate: (updatedUser: User) => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ user, isOpen, onClose, onUpdate }) => {
  const [tab, setTab] = useState<'IDENTITY' | 'MOODS' | 'PERFORMANCE' | 'USERS'>('IDENTITY');
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || '');
  const [avatar, setAvatar] = useState(user.avatar || '');
  const [mood, setMood] = useState<AiMood>(user.preferences.aiMood);
  const [accent, setAccent] = useState(user.preferences.accentColor);
  const [intel, setIntel] = useState<IntelligenceLevel>(user.preferences.intelligenceLevel || 'BALANCED');
  const [lang, setLang] = useState(user.preferences.language || 'English');
  const [theme, setTheme] = useState<AppTheme>(user.preferences.theme || 'OBSIDIAN');
  const [font, setFont] = useState<AppFont>(user.preferences.font || 'INTER');
  const [sound, setSound] = useState(user.preferences.soundEnabled ?? true);
  const [persona, setPersona] = useState<Persona>(user.preferences.persona || 'DEFAULT');

  const [customMoods, setCustomMoods] = useState<CustomMood[]>(user.customMoods || []);
  const [editingMood, setEditingMood] = useState<Partial<CustomMood> | null>(null);

  const [avatarPrompt, setAvatarPrompt] = useState('');
  const [generatingAvatar, setGeneratingAvatar] = useState(false);
  const [showToast, setShowToast] = useState(false);
  const [allUsers, setAllUsers] = useState<User[]>([]);

  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(false), 2500);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  useEffect(() => {
    if (user.role === Role.OWNER && isOpen) {
      const usersRaw = localStorage.getItem('anora_users_db');
      setAllUsers(usersRaw ? JSON.parse(usersRaw) : []);
    }
  }, [isOpen, user.role]);

  if (!isOpen) return null;

  const handleSave = () => {
    onUpdate({
      ...user,
      name,
      bio,
      avatar,
      customMoods,
      preferences: {
        ...user.preferences,
        aiMood: mood,
        accentColor: accent,
        intelligenceLevel: intel,
        language: lang,
        theme,
        font,
        soundEnabled: sound,
        persona
      }
    });
    setShowToast(true);
    setTimeout(onClose, 1200);
  };

  const handleGenerateAvatar = async () => {
    if (!avatarPrompt.trim()) return;
    setGeneratingAvatar(true);
    try {
      const base64 = await anoraService.generateImage(`Cinematic royal digital portrait, hyper-realistic, gold atmosphere: ${avatarPrompt}`);
      setAvatar(`data:image/png;base64,${base64}`);
      setAvatarPrompt('');
    } catch (err: any) {
      alert(`Neural Synthesis Failed: ${err.message}`);
    } finally {
      setGeneratingAvatar(false);
    }
  };

  const isOwner = user.role === Role.OWNER;

  const toggleUserRole = (userId: string) => {
    const updatedUsers = allUsers.map(u => {
      if (u.id === userId && u.role !== Role.OWNER) {
        const newRole = u.role === Role.USER ? Role.PREMIUM : Role.USER;
        const newTier = newRole === Role.PREMIUM ? SubscriptionTier.PRO : SubscriptionTier.FREE;
        return { ...u, role: newRole, tier: newTier };
      }
      return u;
    });
    setAllUsers(updatedUsers);
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
  };

  const deleteUser = (userId: string) => {
    const userToDelete = allUsers.find(u => u.id === userId);
    if (userToDelete?.role === Role.OWNER) {
      alert("Absolute Protocol Error: The Sovereign Architect cannot be deleted.");
      return;
    }
    const updatedUsers = allUsers.filter(u => u.id !== userId);
    setAllUsers(updatedUsers);
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-0 sm:p-6 lg:p-12 bg-black/98 backdrop-blur-3xl animate-in fade-in duration-500">

      {showToast && (
        <div className="fixed top-14 left-1/2 -translate-x-1/2 z-[220] animate-in slide-in-from-top-10 duration-700">
          <div className="bg-white text-black px-14 py-5 rounded-[4rem] font-bold text-[11px] uppercase tracking-[0.6em] shadow-[0_0_80px_rgba(255,255,255,0.4)]">
            Neural Core Synced
          </div>
        </div>
      )}

      <div className={`w-full max-w-6xl bg-[#030303] border-t sm:border border-zinc-900 rounded-none sm:rounded-[6rem] shadow-[0_0_200px_rgba(0,0,0,1)] flex flex-col h-[100dvh] sm:h-auto sm:max-h-[96vh] transition-all duration-1000 ${isOwner ? 'royal-border shadow-[0_0_100px_rgba(212,175,55,0.05)]' : ''} animate-in zoom-in-95 duration-700 overflow-hidden`}>

        <div className="shrink-0 px-12 sm:px-24 py-16 border-b border-zinc-900 flex items-center justify-between bg-[#030303] z-20">
          <div className="flex items-center gap-10">
            {isOwner && (
              <div className="w-18 h-18 rounded-[2.5rem] bg-amber-500/10 border border-amber-500/30 flex items-center justify-center text-amber-500 royal-glow-active">
                <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5 2a1 1 0 011 1v1h1a1 1 0 010 2H6v1a1 1 0 01-2 0V6H3a1 1 0 010-2h1V3a1 1 0 011-1zm0 10a1 1 0 011 1v1h1a1 1 0 110 2H6v1a1 1 0 11-2 0v-1H3a1 1 0 110-2h1v-1a1 1 0 011-1zM12 2a1 1 0 01.967.744L14.146 7.2l5.256.916a1 1 0 01.516 1.626l-3.398 3.38.801 5.237a1 1 0 01-1.451 1.054L11 16.926l-4.87 2.487a1 1 0 01-1.451-1.054l.801-5.237-3.398-3.38a1 1 0 01.516-1.626l5.256-.916 1.213-4.456a1 1 0 01.967-.744z" clipRule="evenodd"/></svg>
              </div>
