import React, { useEffect, useRef, useState } from 'react';
import { Message, Role } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
  onSaveToVault?: (content: string) => void;
  speakingId?: string | null;
  onSpeak?: (id: string, content: string) => void;
}

export const MessageList: React.FC<MessageListProps> = ({ 
  messages, 
  isThinking, 
  ownerName, 
  isOwnerView, 
  onSaveToVault,
  speakingId,
  onSpeak
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-12 pt-12 pb-24 space-y-16 max-w-[1300px] mx-auto w-full scroll-smooth no-scrollbar relative z-10">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isSynthesis = !isUser && msg.images && msg.images.length > 0;
        const isSpeaking = speakingId === msg.id;

        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-reveal relative group`}
            style={{ animationDelay: `${Math.min(index * 0.04, 0.4)}s` }}
          >
            <div className={`max-w-[96%] sm:max-w-[82%] relative`}>

              {/* Manual Speech & Context Controls */}
              {!isUser && (
                <div className="absolute -top-14 left-8 opacity-0 group-hover:opacity-100 transition-all duration-700 transform translate-y-3 group-hover:translate-y-0 flex gap-3 z-20">
                  <button 
                    onClick={() => onSpeak?.(msg.id, msg.content)}
                    className={`p-3 bg-zinc-950 border border-zinc-800 rounded-2xl transition-all shadow-2xl backdrop-blur-2xl ${isSpeaking ? 'text-blue-500 border-blue-500/50 ring-4 ring-blue-500/10' : 'text-zinc-600 hover:text-white hover:border-zinc-500'}`}
                    title={isSpeaking ? "Stop Synthesis" : "Establish Audio Link"}
                  >
                    {isSpeaking ? (
                      <svg className="w-5 h-5 animate-pulse" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
                    ) : (
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                    )}
                  </button>
                  <button 
                    onClick={() => onSaveToVault?.(msg.content)}
                    className="p-3 bg-zinc-950 border border-zinc-800 rounded-2xl text-zinc-600 hover:text-white hover:border-zinc-500 transition-all shadow-2xl backdrop-blur-2xl"
                    title="Archive to Vault"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                  </button>
                  <button 
                    onClick={() => handleCopy(msg.content)}
                    className="p-3 bg-zinc-950 border border-zinc-800 rounded-2xl text-zinc-600 hover:text-white hover:border-zinc-500 transition-all shadow-2xl backdrop-blur-2xl"
                    title="Copy Neural Logic"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" /></svg>
                  </button>
                </div>
              )}

              {/* Message Header */}
              <div className={`flex items-center gap-4 mb-4 px-4 transition-all duration-700 opacity-40 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[10px] font-bold uppercase tracking-[0.4em] ${isUser ? (isOwnerView ? 'gold-gradient' : 'text-zinc-400') : 'text-zinc-500'}`}>
                  {isUser ? (isOwnerView ? 'The Sovereign' : ownerName.split(' ')[0]) : (isSynthesis ? 'Visual Engine' : 'Anora Core')}
                </span>
                <div className="w-1 h-1 rounded-full bg-zinc-800"></div>
                <span className="text-[9px] text-zinc-800 font-bold uppercase tracking-widest">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
                {isSpeaking && (
                   <div className="flex gap-1 items-end h-2.5 ml-2">
                      <div className="w-0.5 bg-blue-500 animate-[bounce_0.6s_infinite_ease-in-out]"></div>
                      <div className="w-0.5 bg-blue-500 animate-[bounce_0.8s_infinite_ease-in-out_0.1s]"></div>
                      <div className="w-0.5 bg-blue-500 animate-[bounce_0.5s_infinite_ease-in-out_0.2s]"></div>
                   </div>
                )}
              </div>

              {/* Content Block */}
              <div
                className={`rounded-[3rem] sm:rounded-[4.5rem] px-10 sm:px-16 py-9 sm:py-14 text-base sm:text-lg leading-[1.7] shadow-[0_50px_100px_-30px_rgba(0,0,0,0.8)] transition-all duration-1000 relative ring-1 ring-white/[0.04]
                  ${isUser 
                    ? `${isOwnerView ? 'bg-zinc-900/90 border border-amber-500/30 text-white royal-border' : 'bg-zinc-800/80 text-zinc-100 border-zinc-700/50'} rounded-tr-none` 
                    : `${isSynthesis ? 'bg-black/98 border border-amber-500/40 text-white royal-border' : 'bg-zinc-900/30 text-zinc-200 border-zinc-800/60'} rounded-tl-none backdrop-blur-3xl`}
                  ${isSpeaking ? 'ring-blue-500/30 ring-2' : ''}`}
              >
                {/* Crown badge for Owner's messages */}
                {isUser && isOwnerView && (
                    <div className="absolute -top-3 -right-3 w-7 h-7 bg-amber-500 rounded-full border-[5px] border-zinc-950 flex items-center justify-center text-black shadow-[0_0_25px_rgba(245,158,11,0.6)]">
                        <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" /></svg>
                    </div>
                )}

                <div className="prose prose-invert max-w-none whitespace-pre-wrap font-medium tracking-tight overflow-hidden">
                  {msg.content}
                </div>

                {/* Grounding Info UI */}
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-14 pt-14 border-t border-zinc-800/50 animate-reveal">
                    <p className="text-[9px] font-bold text-zinc-800 uppercase tracking-[0.6em] mb-7 flex items-center gap-5">
                       <span className="w-8 h-px bg-zinc-900"></span> 
                       Sovereign Verified Intelligence
                       <span className="w-8 h-px bg-zinc-900"></span>
                    </p>
                    <div className="flex flex-wrap gap-4">
                      {msg.sources.map((source, idx) => (
                        <a
                          key={idx}
                          href={source.uri}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center gap-4 px-7 py-5 bg-black/70 border border-zinc-800/60 rounded-full text-[11px] text-zinc-600 hover:text-white hover:border-zinc-500 hover:bg-zinc-900 transition-all shadow-2xl group/source active:scale-95"
                        >
                          <svg className="w-4 h-4 group-hover/source:rotate-45 transition-transform text-zinc-700 group-hover:text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                          <span className="max-w-[220px] truncate font-bold tracking-[0.2em] uppercase">{source.title || 'EXTERNAL INTEL'}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Visual Assets Block */}
              {msg.images && msg.images.length > 0 && (
                <div className={`mt-8 grid gap-6 animate-reveal ${msg.images.length === 4 ? 'grid-cols-2' : (msg.images.length > 1 ? 'flex flex-wrap' : 'flex')} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[3.5rem] border shadow-2xl transition-all duration-1000 hover:border-zinc-500
                      ${isSynthesis ? 'border-amber-500/30' : 'border-zinc-900'} 
                      ${msg.images && msg.images.length === 1 ? 'w-full max-w-[600px] aspect-square' : 'w-full aspect-square'}`}>
                      <img src={img} alt="Synthesis" className="w-full h-full object-cover transition-transform duration-[6s] group-hover/img:scale-110" />
                      <div className="absolute inset-0 bg-black/50 opacity-0 group-hover/img:opacity-100 transition-opacity duration-1000 flex flex-col items-center justify-center backdrop-blur-md gap-6 pointer-events-none">
                         <span className="text-[10px] text-white font-bold uppercase tracking-[0.5em] bg-white/10 px-8 py-4 rounded-full border border-white/20 shadow-2xl">
                           {isSynthesis ? 'SOVEREIGN RENDERED' : 'NEURAL ASSET'}
                         </span>
                         {isSynthesis && (
                           <a href={img} download={`anora_render_${Date.now()}.png`} className="pointer-events-auto bg-white text-black px-8 py-4 rounded-full text-[10px] font-bold uppercase tracking-[0.4em] hover:bg-zinc-200 transition-all active:scale-90 shadow-2xl">
                             Extract Asset
                           </a>
                         )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        );
      })}

      {isThinking && (
        <div className="flex justify-start animate-reveal">
          <div className="bg-zinc-950 border border-zinc-900 rounded-[2.8rem] rounded-tl-none px-12 py-8 shadow-2xl backdrop-blur-3xl ring-1 ring-white/[0.03] relative overflow-hidden shimmer">
            <div className="flex gap-6 items-center relative z-10">
              <div className="flex gap-2.5">
                <div className="w-2 h-2 bg-white/50 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                <div className="w-2 h-2 bg-white/50 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-2 h-2 bg-white/50 rounded-full animate-bounce"></div>
              </div>
              <span className="text-[11px] text-zinc-600 font-bold uppercase tracking-[0.5em]">Synthesizing Neural Logic...</span>
            </div>
          </div>
        </div>
      )}
      <div ref={bottomRef} className="h-16" />
    </div>
  );
};

