  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [isSynthesisMode, setIsSynthesisMode] = useState(false);
  const [currentEmotion, setCurrentEmotion] = useState<'HAPPY' | 'SAD' | 'NEUTRAL' | 'SOVEREIGN'>('NEUTRAL');

  const [speakingId, setSpeakingId] = useState<string | null>(null);
  const currentAudioSource = useRef<AudioBufferSourceNode | null>(null);
  const audioContext = useRef<AudioContext | null>(null);

  const streamRef = useRef<MediaStream | null>(null);
  const wakeWordRecognition = useRef<any>(null);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      anoraService.initChat(currentUser);

      const usersRaw = localStorage.getItem('anora_users_db');
      const users: User[] = usersRaw ? JSON.parse(usersRaw) : [];
      const userIndex = users.findIndex(u => u.email === currentUser.email);
      if (userIndex !== -1) {
        users[userIndex] = currentUser;
        localStorage.setItem('anora_users_db', JSON.stringify(users));
      }

      if (messages.length === 0) {
        setMessages([{
          id: 'initial',
          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT'),
          timestamp: new Date()
        }]);
      }

      if (!wakeWordRecognition.current) {
        initWakeWord();
      }
    }
    if (messages.length > 0) {
      localStorage.setItem('anora_history', JSON.stringify(messages.slice(-50)));
    }
  }, [currentUser, messages]);

  const initWakeWord = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      wakeWordRecognition.current = new SpeechRecognition();
      wakeWordRecognition.current.continuous = true;
      wakeWordRecognition.current.lang = 'en-US';
      wakeWordRecognition.current.onresult = (event: any) => {
        const transcript = event.results[event.results.length - 1][0].transcript.toLowerCase();
        if (transcript.includes('hey anora') || transcript.includes('hey anora')) {
          handleWakeAction();
        }
      };
      try { wakeWordRecognition.current.start(); } catch (e) {
        console.warn("Wake word start failed:", e);
      }
    }
  };

  const handleWakeAction = () => {
    if (!isVoiceMode) {
      const ping = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
      ping.volume = 0.1;
      ping.play().catch(() => {});
      toggleVoiceMode();
    }
  };

  const handleToolCalls = (calls: any[]) => {
    calls.forEach(call => {
      if (call.name === 'openApp') {
        const app = call.args.appName.toLowerCase();
        if (app.includes('youtube')) window.open('https://youtube.com', '_blank');
        else if (app.includes('calendar')) window.open('https://calendar.google.com', '_blank');
        else if (app.includes('whatsapp')) window.open('https://web.whatsapp.com', '_blank');
        else if (app.includes('google')) window.open('https://google.com', '_blank');
      }
      if (call.name === 'setReminder') {
        const newReminder: Reminder = {
          id: Date.now().toString(),
          text: call.args.text,
          time: call.args.time,
          triggered: false
        };
        if (currentUser) {
          setCurrentUser({ ...currentUser, reminders: [...(currentUser.reminders || []), newReminder] });
        }
      }
      if (call.name === 'analyzeEmotion') {
        setCurrentEmotion(call.args.emotion as any);
      }
    });
  };

  const stopSpeech = () => {
    if (currentAudioSource.current) {
      try { currentAudioSource.current.stop(); } catch (e) {}
      currentAudioSource.current = null;
    }
    setSpeakingId(null);
  };

  const handleSpeak = async (messageId: string, content: string) => {
    if (!currentUser) return;
    if (speakingId === messageId) { stopSpeech(); return; }
    stopSpeech();
    setSpeakingId(messageId);
    try {
      const base64 = await anoraService.speak(content, currentUser.preferences.voiceName);
      if (!audioContext.current) audioContext.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const buffer = await decodeAudioData(decode(base64), audioContext.current, 24000, 1);
      const source = audioContext.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContext.current.destination);
      source.onended = () => { if (speakingId === messageId) setSpeakingId(null); };
      currentAudioSource.current = source;
      source.start();
    } catch (err) { 
      console.error("Speech synthesis failed", err);
      setSpeakingId(null); 
    }
  };

  const handleSend = async (text: string, source: 'text' | 'voice' = 'text') => {
    const val = text.trim();
    if ((!val && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: val || "Neural input received.",
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      let response;
      if (isSynthesisMode || val.toLowerCase().includes('generate image') || val.toLowerCase().includes('imagine')) {
        response = await anoraService.generateChatImage(val || "Synthesize visual concept.", userMsg.images || []);
      } else {
        response = await anoraService.sendMessageWithVision(val, userMsg.images || []);
      }

      if (response.toolCalls) handleToolCalls(response.toolCalls);

      const anoraMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'anora',
        content: response.text,
        sources: (response as any).sources,
        images: response.images,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, anoraMsg]);

      if (source === 'voice' || (currentUser.preferences.autoRead && response.text)) {
        setTimeout(() => handleSpeak(anoraMsg.id, response.text), 500);
      }
    } catch (err) { console.error(err); } finally { setIsThinking(false); setIsSynthesisMode(false); }
  };

  const toggleVoiceMode = async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Neural capture not supported on this device.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = currentUser?.preferences.language === 'Hindi' ? 'hi-IN' : 'en-US';
    recognition.onresult = (e: any) => {
      const text = e.results[0][0].transcript;
      handleSend(text, 'voice');
      setIsVoiceMode(false);
    };
    recognition.onerror = () => setIsVoiceMode(false);
    recognition.onend = () => setIsVoiceMode(false);
    recognition.start();
    setIsVoiceMode(true);
  };

  const isOwner = currentUser?.role === Role.OWNER;
  const accent = currentUser?.preferences.accentColor || '#d4af37';

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  return (
    <div className={`flex flex-col h-[100dvh] bg-black text-zinc-300 overflow-hidden transition-all duration-700 ${currentUser.preferences.font === 'OUTFIT' ? 'font-outfit' : 'font-inter'} ${isOwner ? 'ring-inset ring-2 ring-amber-500/10' : ''}`}>
      <div className="absolute inset-0 neural-noise"></div>
      <style>{`
        .accent-text { color: ${accent}; }
        .accent-bg { background-color: ${accent}; }
        .emotion-aura { 
          background: radial-gradient(circle at 50% 50%, 
            ${currentEmotion === 'HAPPY' ? 'rgba(34,197,94,0.06)' : currentEmotion === 'SAD' ? 'rgba(59,130,246,0.06)' : currentEmotion === 'SOVEREIGN' ? 'rgba(212,175,55,0.1)' : 'rgba(255,255,255,0.01)'} 0%, 
            transparent 70%); 
        }
        .owner-royal-bg {
          background: radial-gradient(circle at 10% 10%, rgba(191, 149, 63, 0.05) 0%, transparent 40%),
                      radial-gradient(circle at 90% 90%, rgba(179, 135, 40, 0.05) 0%, transparent 40%),
                      black;
        }
        .anora-fade-reveal {
          animation: reveal 1.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
      `}</style>

      <NeuralOrb active={isVoiceMode} speaking={speakingId !== null} color={accent} />

      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <div className={`fixed inset-0 bg-black/80 backdrop-blur-2xl z-[150] transition-opacity duration-700 ${isSidebarOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`} onClick={() => setIsSidebarOpen(false)}></div>

      <header className={`flex items-center justify-between px-6 sm:px-12 pt-[calc(var(--sat)+1.5rem)] pb-7 border-b border-zinc-900 bg-black/95 backdrop-blur-3xl z-[100] shrink-0 ${isOwner ? 'shadow-[0_4px_60px_rgba(212,175,55,0.08)]' : ''}`}>
        <div className="flex items-center gap-4 sm:gap-10">
          <button onClick={() => setIsSidebarOpen(true)} className="p-4 text-zinc-500 hover:text-white transition-all bg-zinc-950 rounded-2xl border border-zinc-900 hover:border-zinc-700 active:scale-90 shadow-xl">
             <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
          </button>
          <div className="flex items-center gap-4">
             <AnoraPresence isThinking={isThinking} isSpeaking={speakingId !== null} accentColor={accent} />
             <div className="hidden sm:block">
               <AnoraLogo size={46} color={accent} />
             </div>
          </div>
        </div>
        <div className="flex items-center gap-4 sm:gap-10">
          <VoiceIndicator active={isVoiceMode} />
          <div className="flex items-center gap-2.5 p-2 bg-zinc-950 rounded-[3.8rem] border border-zinc-900 shadow-2xl ring-1 ring-white/5">
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-4.5 text-zinc-500 hover:text-white transition-all rounded-full hover:bg-white/5 active:scale-90" title="Neural Render Engine"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></button>
            <button onClick={toggleVoiceMode} className={`p-4.5 rounded-full transition-all active:scale-90 ${isVoiceMode ? 'bg-blue-600 text-white shadow-[0_0_35px_rgba(37,99,235,0.5)]' : 'text-zinc-500 hover:text-white hover:bg-white/5'}`} title="Voice Command">
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            </button>
          </div>
        </div>
      </header>

      <main className={`flex-1 flex flex-col relative overflow-hidden bg-black anora-fade-reveal ${isOwner ? 'owner-royal-bg' : ''}`}>
        <div className="absolute inset-0 emotion-aura pointer-events-none transition-all duration-1000"></div>
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          onSaveToVault={(c) => {
            const newItem: VaultItem = { id: Date.now().toString(), title: c.slice(0, 30) + '...', content: c, type: 'TEXT' };
            setCurrentUser({ ...currentUser, vault: [...(currentUser.vault || []), newItem] });
          }}
          speakingId={speakingId}
          onSpeak={handleSpeak}
          accentColor={accent}
        />
      </main>

      <footer className="px-6 sm:px-12 lg:px-24 pt-5 pb-[calc(var(--sab)+1.8rem)] bg-black/98 backdrop-blur-3xl border-t border-zinc-900 z-[100] shrink-0 relative">
        <div className="max-w-[1250px] mx-auto">
          <div className="flex gap-3.5 overflow-x-auto no-scrollbar pb-7 px-2 pt-2 scroll-smooth">
            {['Hey Anora', 'Open YouTube', 'Set a reminder', 'Imagine art'].map((chip, idx) => (
              <button key={chip} onClick={() => setInputValue(chip + ": ")} className={`shrink-0 px-9 py-4.5 bg-zinc-900/40 border border-zinc-800 rounded-full text-[10px] font-bold text-zinc-500 uppercase tracking-[0.2em] hover:border-zinc-500 hover:text-white transition-all active:scale-95 ${isOwner ? 'hover:shadow-[0_0_20px_rgba(212,175,55,0.1)]' : ''}`}>
                {chip}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-5 sm:gap-8 mt-1">
            <button onClick={() => setIsHubOpen(true)} className="p-6 sm:p-7 rounded-[3.2rem] bg-zinc-950 text-zinc-600 border border-zinc-900 hover:border-zinc-500 shadow-2xl group transition-all active:scale-90 hover:text-white">
              <svg className="w-8 h-8 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
            </button>
            <div className="flex-1 relative flex items-center group">
              <input
                type="text"
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isOwner ? "Direct Command, Arjun..." : "Initiate Anora directive..."}
                className={`w-full bg-zinc-950 border text-zinc-100 rounded-[4.5rem] pl-14 pr-28 py-7 sm:py-9 focus:outline-none placeholder:text-zinc-900 text-lg transition-all duration-500 border-zinc-900 group-hover:border-zinc-700 ${isOwner ? 'focus:border-amber-500/40 shadow-[0_0_50px_rgba(212,175,55,0.08)]' : 'focus:border-zinc-600'}`}
              />
              <button onClick={() => handleSend(inputValue)} className={`absolute right-3 p-6 sm:p-7 rounded-full transition-all active:scale-[0.85] shadow-2xl ${isOwner ? 'bg-amber-500 text-black hover:bg-amber-400' : 'bg-white text-black hover:bg-zinc-200'}`}>
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { Message, Role } from '../types';
import { AnoraPresence } from './AnoraPresence';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
  onSaveToVault?: (content: string) => void;
  speakingId?: string | null;
  onSpeak?: (id: string, content: string) => void;
  accentColor: string;
}

export const MessageList: React.FC<MessageListProps> = ({ 
  messages, 
  isThinking, 
  ownerName, 
  isOwnerView, 
  onSaveToVault,
  speakingId,
  onSpeak,
  accentColor
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-12 pt-12 pb-24 space-y-16 max-w-[1300px] mx-auto w-full scroll-smooth no-scrollbar relative z-10">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isSynthesis = !isUser && msg.images && msg.images.length > 0;
        const isSpeaking = speakingId === msg.id;

        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-reveal relative group`}
            style={{ animationDelay: `${Math.min(index * 0.04, 0.4)}s` }}
          >
            <div className={`max-w-[96%] sm:max-w-[82%] relative flex gap-6 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

              {/* Anora Avatar Presence */}
              {!isUser && (
                <div className="hidden sm:flex flex-col items-center mt-4">
                  <div className="w-10 h-10">
                     <AnoraPresence isThinking={false} isSpeaking={isSpeaking} accentColor={accentColor} />
                  </div>
                </div>
              )}

              <div className="flex-1">
                {/* Manual Speech & Context Controls */}
                {!isUser && (
                  <div className="absolute -top-14 left-8 opacity-0 group-hover:opacity-100 transition-all duration-700 transform translate-y-3 group-hover:translate-y-0 flex gap-3 z-20">
                    <button 
                      onClick={() => onSpeak?.(msg.id, msg.content)}
                      className={`p-3 bg-zinc-950 border border-zinc-800 rounded-2xl transition-all shadow-2xl backdrop-blur-2xl ${isSpeaking ? 'text-blue-500 border-blue-500/50 ring-4 ring-blue-500/10' : 'text-zinc-600 hover:text-white hover:border-zinc-500'}`}
                      title={isSpeaking ? "Stop Synthesis" : "Establish Audio Link"}
                    >
                      {isSpeaking ? (
                        <svg className="w-5 h-5 animate-pulse" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
                      ) : (
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                      )}
                    </button>
                    <button 
                      onClick={() => onSaveToVault?.(msg.content)}
                      className="p-3 bg-zinc-950 border border-zinc-800 rounded-2xl text-zinc-600 hover:text-white hover:border-zinc-500 transition-all shadow-2xl backdrop-blur-2xl"
                      title="Archive to Vault"
                    >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                    </button>
                    <button 
                      onClick={() => handleCopy(msg.content)}
                      className="p-3 bg-zinc-950 border border-zinc-800 rounded-2xl text-zinc-600 hover:text-white hover:border-zinc-500 transition-all shadow-2xl backdrop-blur-2xl"
                      title="Copy Neural Logic"
                    >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" /></svg>
                    </button>
                  </div>
                )}

                {/* Message Header */}
                <div className={`flex items-center gap-4 mb-4 px-4 transition-all duration-700 opacity-40 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                  <span className={`text-[10px] font-bold uppercase tracking-[0.4em] ${isUser ? (isOwnerView ? 'gold-gradient' : 'text-zinc-400') : 'text-zinc-500'}`}>
                    {isUser ? (isOwnerView ? 'The Sovereign' : ownerName.split(' ')[0]) : (isSynthesis ? 'Visual Engine' : 'Anora Core')}
                  </span>
                  <div className="w-1 h-1 rounded-full bg-zinc-800"></div>
                  <span className="text-[9px] text-zinc-800 font-bold uppercase tracking-widest">
                    {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                  {isSpeaking && (
                    <div className="flex gap-1 items-end h-2.5 ml-2">
                        <div className="w-0.5 bg-blue-500 animate-[bounce_0.6s_infinite_ease-in-out]"></div>
                        <div className="w-0.5 bg-blue-500 animate-[bounce_0.8s_infinite_ease-in-out_0.1s]"></div>
                        <div className="w-0.5 bg-blue-500 animate-[bounce_0.5s_infinite_ease-in-out_0.2s]"></div>
                    </div>
                  )}
                </div>

                {/* Content Block */}
                <div
                  className={`rounded-[3rem] sm:rounded-[4.5rem] px-10 sm:px-16 py-9 sm:py-14 text-base sm:text-lg leading-[1.7] shadow-[0_50px_100px_-30px_rgba(0,0,0,0.8)] transition-all duration-1000 relative ring-1 ring-white/[0.04]
                    ${isUser 
                      ? `${isOwnerView ? 'bg-zinc-900/90 border border-amber-500/30 text-white royal-border' : 'bg-zinc-800/80 text-zinc-100 border-zinc-700/50'} rounded-tr-none` 
                      : `${isSynthesis ? 'bg-black/98 border border-amber-500/40 text-white royal-border' : 'bg-zinc-900/30 text-zinc-200 border-zinc-800/60'} rounded-tl-none backdrop-blur-3xl`}
                    ${isSpeaking ? 'ring-blue-500/30 ring-2' : ''}`}
                >
                  {/* Crown badge for Owner's messages */}
                  {isUser && isOwnerView && (
                      <div className="absolute -top-3 -right-3 w-7 h-7 bg-amber-500 rounded-full border-[5px] border-zinc-950 flex items-center justify-center text-black shadow-[0_0_25px_rgba(245,158,11,0.6)]">
                          <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" /></svg>
                      </div>
                  )}

                  <div className="prose prose-invert max-w-none whitespace-pre-wrap font-medium tracking-tight overflow-hidden">
                    {msg.content}
                  </div>

                  {/* Grounding Info UI */}
                  {msg.sources && msg.sources.length > 0 && (
                    <div className="mt-14 pt-14 border-t border-zinc-800/50 animate-reveal">
                      <p className="text-[9px] font-bold text-zinc-800 uppercase tracking-[0.6em] mb-7 flex items-center gap-5">
                        <span className="w-8 h-px bg-zinc-900"></span> 
                        Sovereign Verified Intelligence
                        <span className="w-8 h-px bg-zinc-900"></span>
                      </p>
                      <div className="flex flex-wrap gap-4">
                        {msg.sources.map((source, idx) => (
                          <a
                            key={idx}
                            href={source.uri}
                            target="_blank"
