interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [isRecovering, setIsRecovering] = useState(false);
  const [recoveryStep, setRecoveryStep] = useState(0);
  const [recoveryCode, setRecoveryCode] = useState('');
  const [userInputCode, setUserInputCode] = useState('');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [phase, setPhase] = useState(1); // 1: Ready, 2: Neural Booting

  const getUsers = (): User[] => {
    try {
      const data = localStorage.getItem('anora_users_db');
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  };

  const saveUser = (user: User) => {
    const users = getUsers();
    users.push(user);
    localStorage.setItem('anora_users_db', JSON.stringify(users));
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    setTimeout(() => {
      const users = getUsers();
      const emailLower = email.toLowerCase().trim();

      if (isLogin) {
        if (emailLower === OWNER_EMAIL && password === OWNER_PASSWORD) {
          let owner = users.find(u => u.email.toLowerCase() === OWNER_EMAIL);
          if (!owner) {
            owner = {
              id: 'sovereign_arj',
              name: "Arjun Bharti Mina",
              email: OWNER_EMAIL,
              password: OWNER_PASSWORD,
              role: Role.OWNER,
              tier: SubscriptionTier.LIFETIME,
              bio: ARJUN_DETAILED_BIO,
              preferences: { 
                accentColor: '#d4af37', 
                aiMood: 'CREATIVE' as AiMood, 
                voiceName: 'Puck',
                autoRead: false,
                continuousListening: false,
                intelligenceLevel: 'DEEP' as IntelligenceLevel,
                language: 'English',
                theme: 'OBSIDIAN',
                font: 'OUTFIT',
                soundEnabled: true,
                persona: 'DEFAULT'
              },
              createdAt: new Date().toISOString(),
              reminders: [],
              notes: [],
              memory: [],
              projects: []
            };
            saveUser(owner);
          }
          setPhase(2);
          setTimeout(() => onLogin(owner!), 1500);
          return;
        }

        const found = users.find(u => u.email.toLowerCase() === emailLower);
        if (!found) {
          setError('Neural ID not recognized.');
        } else if (found.password !== password) {
          setError('Security mismatch.');
        } else {
          setPhase(2);
          setTimeout(() => onLogin(found), 1500);
        }
      } else {
        if (password !== confirmPassword) {
          setError('Encryption keys must be identical.');
        } else if (users.some(u => u.email.toLowerCase() === emailLower)) {
          setError('Neural ID already established.');
        } else {
          const newUser: User = {
            id: Math.random().toString(36).substr(2, 9),
            name: name || 'Neural Link User',
            email: emailLower,
            password: password,
            role: Role.USER,
            tier: SubscriptionTier.FREE,
            preferences: { 
              accentColor: '#3f3f46', 
              aiMood: 'CALM' as AiMood, 
              voiceName: 'Puck',
              autoRead: false,
              continuousListening: false,
              intelligenceLevel: 'BALANCED' as IntelligenceLevel,
              language: 'English',
              theme: 'OBSIDIAN',
              font: 'INTER',
              soundEnabled: true,
              persona: 'DEFAULT'
            },
            createdAt: new Date().toISOString(),
            reminders: [],
            notes: [],
            memory: [],
            projects: []
          };
          saveUser(newUser);
          setPhase(2);
          setTimeout(() => onLogin(newUser), 1500);
        }
      }
      setLoading(false);
    }, 1000);
  };

  if (phase === 2) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-8 space-y-12 font-outfit text-center">
        <AnoraLogo size={120} color="#fff" showName={false} />
        <div className="space-y-4">
          <h2 className="text-white text-xl font-bold tracking-[0.5em] animate-pulse uppercase">Booting Anora Core</h2>
          <div className="w-64 h-1 bg-zinc-900 rounded-full overflow-hidden mx-auto">
            <div className="h-full bg-white animate-[shimmer-anim_2s_infinite]"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black flex items-center justify-center p-6 font-outfit">
      <div className="w-full max-w-md animate-reveal">
        <div className="text-center mb-12">
          <div className="flex justify-center mb-6"><AnoraLogo size={80} color="#fff" showName={false} /></div>
          <h1 className="text-4xl font-bold tracking-[0.4em] text-white">ANORA</h1>
          <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.6em] mt-2">Sovereign Intel v9.2</p>
        </div>

        <div className="bg-zinc-900/40 border border-zinc-800 p-8 sm:p-10 rounded-[3rem] backdrop-blur-3xl shadow-2xl">
          <div className="flex bg-black p-1.5 rounded-2xl border border-zinc-800 mb-8">
            <button onClick={() => setIsLogin(true)} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest rounded-xl transition-all ${isLogin ? 'bg-zinc-800 text-white' : 'text-zinc-600'}`}>Access</button>
            <button onClick={() => setIsLogin(false)} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest rounded-xl transition-all ${!isLogin ? 'bg-zinc-800 text-white' : 'text-zinc-600'}`}>Link</button>
          </div>

          <form onSubmit={handleAuth} className="space-y-5">
            {error && <p className="text-red-500 text-[10px] font-bold uppercase text-center bg-red-500/10 p-3 rounded-xl border border-red-500/20">{error}</p>}

            {!isLogin && (
              <input type="text" required value={name} onChange={e => setName(e.target.value)} placeholder="Identity Signature" className="w-full bg-black border border-zinc-800 rounded-2xl px-6 py-4 text-white text-sm outline-none focus:border-zinc-600 transition-all" />
