            <input type="password" required value={password} onChange={e => setPassword(e.target.value)} placeholder="Access Key" className="w-full bg-black border border-zinc-800 rounded-2xl px-6 py-4 text-white text-sm outline-none focus:border-zinc-600 transition-all" />

            {!isLogin && (
              <input type="password" required value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} placeholder="Confirm Key" className="w-full bg-black border border-zinc-800 rounded-2xl px-6 py-4 text-white text-sm outline-none focus:border-zinc-600 transition-all" />
            )}

            <button type="submit" disabled={loading} className="w-full bg-white text-black font-bold py-5 rounded-[2rem] hover:bg-zinc-200 transition-all active:scale-95 text-[10px] uppercase tracking-[0.4em] mt-6">
              {loading ? "Synthesizing..." : isLogin ? "Neural Sync" : "Initialize Link"}
