import { GoogleGenAI, Chat, GenerateContentResponse, Modality, Type, FunctionDeclaration } from "@google/genai";
import { getSystemPrompt } from "../constants";
import { User, Role, GroundingSource } from "../types";

const controlTools: FunctionDeclaration[] = [
  {
    name: 'setReminder',
    parameters: {
      type: Type.OBJECT,
      properties: {
        text: { type: Type.STRING, description: 'Content of the reminder' },
        time: { type: Type.STRING, description: 'Time or duration' }
      },
      required: ['text', 'time']
    }
  },
  {
    name: 'openApp',
    parameters: {
      type: Type.OBJECT,
      properties: {
        appName: { type: Type.STRING, description: 'Name of the app to open' }
      },
      required: ['appName']
    }
  }
];

export class AnoraAI {
  private chat: Chat | null = null;
  private currentUser: User | null = null;

  initChat(user: User) {
    try {
      this.currentUser = user;
      const apiKey = process.env.API_KEY || '';
      const ai = new GoogleGenAI({ apiKey });

      const tools: any[] = [{ functionDeclarations: controlTools }];
      if (user.role === Role.OWNER || user.role === Role.PREMIUM) {
        tools.push({ googleSearch: {} });
      }

      let modelName = 'gemini-2.5-flash';
      if (user.preferences?.intelligenceLevel === 'DEEP') modelName = 'gemini-2.5-pro';

      this.chat = ai.chats.create({
        model: modelName,
        config: {
          systemInstruction: getSystemPrompt(user),
          tools: tools,
        },
      });
    } catch (e) {
      console.error("Neural Initialization Failed:", e);
    }
  }

  async speak(text: string, voiceName: string = 'Puck'): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) throw new Error("Audio generation failed");
    return base64Audio;
  }

  async generateChatImage(text: string, images: string[] = []) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
    const resp = await ai.models.generateImages({
      model: 'imagen-4.0-generate-001',
      prompt: text,
      config: { numberOfImages: 1, aspectRatio: '1:1', outputMimeType: 'image/jpeg' },
    });
    return {
      text: "Visual synthesis complete.",
      images: [`data:image/jpeg;base64,${resp.generatedImages[0].image.imageBytes}`]
    };
  }

  async sendMessageWithVision(text: string, images: string[]) {
    if (!this.chat) throw new Error("Neural link not ready.");

    const parts: any[] = images.map(img => ({
      inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] || img }
    }));
    parts.push({ text });

    const response = await this.chat.sendMessage({ message: parts });

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web) sources.push({ title: chunk.web.title, uri: chunk.web.uri });
      });
    }

    return {
      text: response.text || "...",
      sources,
      images: [],
      toolCalls: response.candidates?.[0]?.content?.parts.filter(p => p.functionCall).map(tc => tc.functionCall) || []
    };
  }
}

