    if (chunks) {
      chunks.forEach((c: any) => {
        if (c.web) sources.push({ title: c.web.title, uri: c.web.uri });
        if (c.maps) sources.push({ title: c.maps.title, uri: c.maps.uri });
      });
    }

    return {
      text: result.text || "Directives acknowledged.",
      sources,
      toolCalls: result.candidates?.[0]?.content?.parts.filter(p => p.functionCall).map(tc => tc.functionCall) || []
    };
  }

  async synthesizeVisual(prompt: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const resp = await ai.models.generateImages({
      model: 'imagen-4.0-generate-001',
      prompt: `Cinematic high-fidelity: ${prompt}`,
      config: { numberOfImages: 1, aspectRatio: '1:1', outputMimeType: 'image/jpeg' }
    });
    return resp.generatedImages[0].image.imageBytes;
  }

  async synthesizeMotion(prompt: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    let op = await ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt,
      config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
    });

    while (!op.done) {
      await new Promise(r => setTimeout(r, 8000));
      op = await ai.operations.getVideosOperation({ operation: op });
    }

    const uri = op.response?.generatedVideos?.[0]?.video?.uri;
    const response = await fetch(`${uri}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  async vocalize(text: string, voice: string = 'Puck'): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const resp = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } }
        }
      }
    });
    return resp.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
  }
}

