  return (
    <div className={`flex flex-col h-full bg-black text-zinc-300 relative overflow-hidden ${user.preferences.font === 'OUTFIT' ? 'font-outfit' : ''}`}>
      <div className="absolute inset-0 neural-noise opacity-10"></div>

      <header className="px-6 py-6 border-b border-zinc-900 glass z-50 flex items-center justify-between pt-[calc(var(--sat)+1.5rem)]">
        <div className="flex items-center gap-6">
          <button onClick={() => setIsHubOpen(true)} className="p-4 bg-zinc-950 border border-zinc-900 rounded-2xl hover:border-zinc-700 transition-all">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
          </button>
          <AnoraLogo size={42} color={accent} showName={true} />
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => setIsCommandOpen(true)} className="p-4 bg-zinc-950 border border-zinc-900 rounded-2xl text-zinc-500 hover:text-white transition-all">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
          </button>
          <button onClick={() => setIsProfileOpen(true)} className="w-12 h-12 rounded-full border border-zinc-800 bg-zinc-900 overflow-hidden">
            {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-bold">{user.name[0]}</div>}
          </button>
        </div>
      </header>

      <main className="flex-1 relative overflow-hidden flex flex-col">
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          accentColor={accent} 
          onSaveVault={(c) => setUser({ ...user, vault: [...(user.vault || []), { id: Date.now().toString(), title: 'Saved Logic', content: c, type: 'TEXT' }] })}
        />
        {isThinking && <NeuralOrb active={true} speaking={false} color={accent} />}
      </main>

      <footer className="p-6 pb-[calc(var(--sab)+1.5rem)] glass border-t border-zinc-900 z-50">
        <div className="max-w-4xl mx-auto flex items-center gap-4">
          <button onClick={toggleVoice} className={`p-6 rounded-full transition-all ${isVoiceMode ? 'bg-blue-600 text-white shadow-lg' : 'bg-zinc-900 text-zinc-500 hover:text-white'}`}>
             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
          </button>
          <div className="flex-1 relative flex items-center">
