            </button>
          </div>
        </div>
      </footer>

      {isProfileOpen && <ProfileModal user={user} onClose={() => setIsProfileOpen(false)} onUpdate={setUser} />}
      {isHubOpen && <AssistantFeatures user={user} onUpdate={setUser} onClose={() => setIsHubOpen(false)} />}
      {isCommandOpen && <CommandCenter user={user} onClose={() => setIsCommandOpen(false)} />}
    </div>
  );
