import { GoogleGenAI, Chat, Modality, Type, FunctionDeclaration } from "@google/genai";
import { getSystemPrompt } from "../constants";
import { User, Role, GroundingSource } from "../types";

const sovereignTools: FunctionDeclaration[] = [
  {
    name: 'setReminder',
    parameters: {
      type: Type.OBJECT,
      properties: {
        text: { type: Type.STRING, description: 'Directive details' },
        time: { type: Type.STRING, description: 'Temporal target (e.g., "5:00 PM")' }
      },
      required: ['text', 'time']
    }
  },
  {
    name: 'openSystemApp',
    parameters: {
      type: Type.OBJECT,
      properties: {
        target: { type: Type.STRING, enum: ['YouTube', 'AutoCAD', 'WhatsApp', 'Calendar', 'Spotify'] }
      },
      required: ['target']
    }
  }
];

export class AnoraAI {
  private chat: Chat | null = null;
  private user: User | null = null;

  init(user: User) {
    this.user = user;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const tools: any[] = [{ functionDeclarations: sovereignTools }];
    // Owner or Premium tiers get Grounding capabilities
    if (user.role === Role.OWNER || user.tier === 'PRO' || user.tier === 'LIFETIME') {
      tools.push({ googleSearch: {} });
      tools.push({ googleMaps: {} });
    }

    const modelName = user.preferences?.intelligenceLevel === 'DEEP' ? 'gemini-2.5-pro' : 'gemini-2.5-flash';

    this.chat = ai.chats.create({
      model: modelName,
      config: {
        systemInstruction: getSystemPrompt(user),
        tools: tools,
      },
    });
  }

  async processInput(text: string, images: string[] = []) {
    if (!this.chat) throw new Error("Neural core inactive. Initialize system first.");

    const parts: any[] = images.map(img => ({
      inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] || img }
    }));
    parts.push({ text });

    const result = await this.chat.sendMessage({ message: parts });

    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((c: any) => {
        if (c.web) sources.push({ title: c.web.title, uri: c.web.uri });
        if (c.maps) sources.push({ title: c.maps.title, uri: c.maps.uri });
      });
    }

    return {
      text: result.text || "Directives received and processed.",
      sources,
      toolCalls: result.candidates?.[0]?.content?.parts.filter(p => p.functionCall).map(tc => tc.functionCall) || []
    };
  }

  async generateImage(prompt: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const resp = await ai.models.generateImages({
      model: 'imagen-4.0-generate-001',
      prompt: `Post-human aesthetic, high-fidelity royal atmosphere: ${prompt}`,
      config: { 
        numberOfImages: 1, 
        aspectRatio: '1:1', 
        outputMimeType: 'image/jpeg' 
      }
    });
    return resp.generatedImages[0].image.imageBytes;
  }

  async generateVideo(prompt: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    let op = await ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt,
      config: { 
        numberOfVideos: 1, 
        resolution: '720p', 
        aspectRatio: '16:9' 
      }
    });

    // Simple poll for completion
    while (!op.done) {
      await new Promise(r => setTimeout(r, 10000));
      op = await ai.operations.getVideosOperation({ operation: op });
    }

    const uri = op.response?.generatedVideos?.[0]?.video?.uri;
    const response = await fetch(`${uri}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  async vocalize(text: string, voice: string = 'Puck'): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const resp = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } }
        }
      }
    });
    return resp.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
  }
}

export const anoraService = new AnoraAI();

import React, { useState, useEffect, useRef } from 'react';
import { User, Message, Role, VaultItem } from './types';
import { INITIAL_MESSAGE } from './constants';
import { anoraService } from './services/geminiService';
import { AuthScreen } from './components/AuthScreen';
import { MessageList } from './components/MessageList';
import { AnoraLogo } from './components/AnoraLogo';
import { NeuralOrb } from './components/NeuralOrb';
import { ProfileModal } from './components/ProfileModal';
import { AssistantFeatures } from './components/AssistantFeatures';
import { CommandCenter } from './components/CommandCenter';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('anora_user');
      return saved ? JSON.parse(saved) : null;
    } catch { return null; }
  });

  const [messages, setMessages] = useState<Message[]>([]);
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isCommandOpen, setIsCommandOpen] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [speakingId, setSpeakingId] = useState<string | null>(null);

  const audioCtx = useRef<AudioContext | null>(null);
  const currentAudioSource = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    if (user) {
      localStorage.setItem('anora_user', JSON.stringify(user));
      anoraService.init(user);
      if (messages.length === 0) {
        setMessages([{
          id: 'init',
          role: 'anora',
          content: INITIAL_MESSAGE(user.name, user.role, user.preferences.persona),
          timestamp: new Date()
        }]);
      }
    }
  }, [user]);

  const stopVocalization = () => {
    if (currentAudioSource.current) {
      currentAudioSource.current.stop();
      currentAudioSource.current = null;
    }
    setSpeakingId(null);
  };

  const handleSpeak = async (id: string, text: string) => {
    if (!user) return;

    if (speakingId === id) {
      stopVocalization();
      return;
    }

    try {
      stopVocalization();
      setSpeakingId(id);

      const base64 = await anoraService.vocalize(text, user.preferences.voiceName);
      if (!audioCtx.current) {
        audioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = audioCtx.current.createBuffer(1, dataInt16.length, 24000);
      const channel = buffer.getChannelData(0);

      for (let i = 0; i < dataInt16.length; i++) {
        channel[i] = dataInt16[i] / 32768.0;
      }

      const source = audioCtx.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.current.destination);
      source.onended = () => {
        if (speakingId === id) setSpeakingId(null);
      };

      currentAudioSource.current = source;
      source.start();
    } catch (e) { 
      console.error("Neural TTS Sync Failure:", e);
      setSpeakingId(null);
    }
  };

  const handleSend = async (val?: string) => {
    const text = val || inputValue;
    if (!text.trim() || !user) return;

    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: text, 
      timestamp: new Date() 
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsThinking(true);

    try {
      const response = await anoraService.processInput(text);
      const anoraMsg: Message = { 
        id: (Date.now() + 1).toString(), 
        role: 'anora', 
        content: response.text, 
        sources: response.sources,
        timestamp: new Date() 
      };
      setMessages(prev => [...prev, anoraMsg]);

      if (user.preferences.autoRead) {
        handleSpeak(anoraMsg.id, response.text);
      }
    } catch (e) { 
      console.error("Neural Bridge Failure:", e);
      setMessages(prev => [...prev, { 
        id: 'error-' + Date.now(), 
        role: 'system', 
        content: "Neural link interrupted. Re-synchronizing...", 
        timestamp: new Date() 
      }]);
    } finally { 
      setIsThinking(false); 
    }
  };

  const toggleVoice = () => {
    const Recognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!Recognition) return alert("Neural capture not supported in this environment.");

    const rec = new Recognition();
    rec.continuous = false;
    rec.interimResults = false;

    rec.onresult = (e: any) => {
      const transcript = e.results[0][0].transcript;
      handleSend(transcript);
    };

    rec.onstart = () => setIsVoiceMode(true);
    rec.onend = () => setIsVoiceMode(false);
    rec.onerror = () => setIsVoiceMode(false);

    rec.start();
  };

  if (!user) return <AuthScreen onLogin={setUser} />;

  const accent = user.preferences.accentColor;

  return (
    <div className={`flex flex-col h-full bg-black text-zinc-300 relative overflow-hidden ${user.preferences.font === 'OUTFIT' ? 'font-outfit' : ''}`}>
      <div className="absolute inset-0 neural-noise opacity-10 pointer-events-none"></div>

      {/* Sovereign Header */}
      <header className="px-6 py-4 border-b border-zinc-900 glass z-[100] flex items-center justify-between pt-[calc(var(--sat)+1rem)]">
        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsHubOpen(true)} 
            className="p-3 bg-zinc-950 border border-zinc-900 rounded-xl hover:border-zinc-700 transition-all active:scale-90"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>
          <AnoraLogo size={36} color={accent} showName={true} />
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => setIsCommandOpen(true)} 
            className="p-3 bg-zinc-950 border border-zinc-900 rounded-xl text-zinc-500 hover:text-white transition-all active:scale-90"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
            </svg>
          </button>
          <button 
            onClick={() => setIsProfileOpen(true)} 
            className="w-10 h-10 rounded-full border border-zinc-800 bg-zinc-900 overflow-hidden shadow-lg active:scale-95 transition-transform"
          >
            {user.avatar ? (
              <img src={user.avatar} className="w-full h-full object-cover" alt="User" />
            ) : (
              <div className="w-full h-full flex items-center justify-center font-bold text-sm bg-zinc-800">
                {user.name[0]}
              </div>
            )}
          </button>
        </div>
      </header>

      {/* Neural Core Content */}
      <main className="flex-1 relative overflow-hidden flex flex-col">
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={user.name}
          isOwnerView={user.role === Role.OWNER}
          accentColor={accent}
          speakingId={speakingId}
          onSpeak={handleSpeak}
          onSaveToVault={(content) => {
            const newItem: VaultItem = { id: Date.now().toString(), title: 'Captured Logic', content, type: 'TEXT' };
            const updatedUser = { ...user, vault: [...(user.vault || []), newItem] };
            setUser(updatedUser);
            localStorage.setItem('anora_user', JSON.stringify(updatedUser));
          }}
        />
        {(isThinking || speakingId) && (
          <NeuralOrb active={isThinking} speaking={speakingId !== null} color={accent} />
        )}
      </main>

      {/* Interaction Footer */}
      <footer className="p-6 pb-[calc(var(--sab)+1.5rem)] glass border-t border-zinc-900 z-[100]">
        <div className="max-w-4xl mx-auto flex items-center gap-4">
          <button 
            onClick={toggleVoice} 
            className={`p-5 rounded-full transition-all duration-500 ${isVoiceMode ? 'bg-amber-500 text-black shadow-[0_0_30px_rgba(245,158,11,0.4)] scale-110' : 'bg-zinc-900 text-zinc-500 hover:text-white'}`}
          >
             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
             </svg>
          </button>

          <div className="flex-1 relative flex items-center group">
            <input 
              value={inputValue} 
              onChange={e => setInputValue(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend()}
              placeholder="Command Anora..."
              className="w-full bg-zinc-950 border border-zinc-800 rounded-full px-8 py-5 outline-none focus:border-zinc-500 transition-all text-base placeholder:text-zinc-800 shadow-inner"
            />
            <button 
              onClick={() => handleSend()} 
              className="absolute right-2 p-3 bg-white text-black rounded-full hover:bg-zinc-200 transition-all active:scale-90"
            >
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 5l7 7m0 0l-7 7m7-7H3" />
              </svg>
            </button>
          </div>
        </div>
      </footer>

      {/* Modals */}
      <ProfileModal user={user} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setUser} />
      <AssistantFeatures user={user} onUpdate={setUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />
      <CommandCenter user={user} isOpen={isCommandOpen} onClose={() => setIsCommandOpen(false)} />
    </div>
  );
};

