import { GoogleGenAI, Chat, Modality, Type, FunctionDeclaration } from "@google/genai";
import { getSystemPrompt } from "../constants";
import { User, Role, GroundingSource } from "../types";

const sovereignTools: FunctionDeclaration[] = [
  {
    name: 'setDirective',
    parameters: {
      type: Type.OBJECT,
      properties: {
        text: { type: Type.STRING, description: 'Task details' },
        urgency: { type: Type.STRING, enum: ['CRITICAL', 'HIGH', 'STANDARD'] }
      },
      required: ['text']
    }
  }
];

export class AnoraAI {
  private chat: Chat | null = null;
  private user: User | null = null;

  init(user: User) {
    this.user = user;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const tools: any[] = [{ functionDeclarations: sovereignTools }];
    if (user.role === Role.OWNER || user.tier === 'PRO' || user.tier === 'LIFETIME') {
      tools.push({ googleSearch: {} });
      tools.push({ googleMaps: {} });
    }

    const modelName = user.preferences?.intelligenceLevel === 'DEEP' ? 'gemini-2.5-pro' : 'gemini-2.5-flash';

    this.chat = ai.chats.create({
      model: modelName,
      config: {
        systemInstruction: getSystemPrompt(user),
        tools: tools,
      },
    });
  }

  async processInput(text: string, images: string[] = []) {
    if (!this.chat) throw new Error("Neural Link inactive.");

    const parts: any[] = images.map(img => ({
      inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] || img }
    }));
    parts.push({ text });

    const result = await this.chat.sendMessage({ message: parts });

    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((c: any) => {
        if (c.web) sources.push({ title: c.web.title, uri: c.web.uri });
        if (c.maps) sources.push({ title: c.maps.title, uri: c.maps.uri });
      });
    }

    return {
      text: result.text || "Directives received.",
      sources,
      toolCalls: result.candidates?.[0]?.content?.parts.filter(p => p.functionCall).map(tc => tc.functionCall) || []
    };
  }

  async generateImage(prompt: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const resp = await ai.models.generateImages({
      model: 'imagen-4.0-generate-001',
      prompt: `Sovereign high-fidelity art: ${prompt}`,
      config: { numberOfImages: 1, aspectRatio: '1:1', outputMimeType: 'image/jpeg' }
    });
    return resp.generatedImages[0].image.imageBytes;
  }

  async generateVideo(prompt: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    let op = await ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt,
      config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
    });

    while (!op.done) {
      await new Promise(r => setTimeout(r, 10000));
      op = await ai.operations.getVideosOperation({ operation: op });
    }

    const uri = op.response?.generatedVideos?.[0]?.video?.uri;
    const response = await fetch(`${uri}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  async vocalize(text: string, voice: string = 'Kore'): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const resp = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } } }
      }
    });
    return resp.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
  }
}

export const anoraService = new AnoraAI();

import React, { useState, useEffect, useRef } from 'react';
import { User, Message, Role, VaultItem } from './types';
import { INITIAL_MESSAGE } from './constants';
import { anoraService } from './services/geminiService';
import { AuthScreen } from './components/AuthScreen';
import { MessageList } from './components/MessageList';
import { AnoraLogo } from './components/AnoraLogo';
import { NeuralOrb } from './components/NeuralOrb';
import { ProfileModal } from './components/ProfileModal';
import { AssistantFeatures } from './components/AssistantFeatures';
import { CommandCenter } from './components/CommandCenter';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('anora_user');
      return saved ? JSON.parse(saved) : null;
    } catch { return null; }
  });

  const [messages, setMessages] = useState<Message[]>([]);
  const [isThinking, setIsThinking] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isCommandOpen, setIsCommandOpen] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [speakingId, setSpeakingId] = useState<string | null>(null);
  const [pendingImages, setPendingImages] = useState<string[]>([]);

  const audioCtx = useRef<AudioContext | null>(null);
  const currentAudioSource = useRef<AudioBufferSourceNode | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (user) {
      localStorage.setItem('anora_user', JSON.stringify(user));
      anoraService.init(user);
      if (messages.length === 0) {
        setMessages([{
          id: 'init',
          role: 'anora',
          content: INITIAL_MESSAGE(user.name, user.role, user.preferences.persona),
          timestamp: new Date()
        }]);
      }
    }
  }, [user]);

  const handleSpeak = async (id: string, text: string) => {
    if (!user) return;
    if (speakingId === id) {
      if (currentAudioSource.current) {
        currentAudioSource.current.stop();
        currentAudioSource.current = null;
      }
      setSpeakingId(null);
      return;
    }

    try {
      if (!audioCtx.current) {
        audioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (audioCtx.current.state === 'suspended') await audioCtx.current.resume();

      setSpeakingId(id);
      const base64 = await anoraService.vocalize(text, user.preferences.voiceName);

      const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = audioCtx.current.createBuffer(1, dataInt16.length, 24000);
      const channel = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) {
        channel[i] = dataInt16[i] / 32768.0;
      }

      if (currentAudioSource.current) currentAudioSource.current.stop();
      const source = audioCtx.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.current.destination);
      source.onended = () => {
        if (speakingId === id) setSpeakingId(null);
      };
      currentAudioSource.current = source;
      source.start();
    } catch (e) {
      setSpeakingId(null);
    }
  };

  const handleSend = async (val?: string) => {
    const text = val || inputValue;
    if ((!text.trim() && pendingImages.length === 0) || !user) return;

    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: text, 
      images: pendingImages.length > 0 ? [...pendingImages] : undefined,
      timestamp: new Date() 
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      const response = await anoraService.processInput(text, userMsg.images);
      const anoraMsg: Message = { 
        id: (Date.now() + 1).toString(), 
        role: 'anora', 
        content: response.text, 
        sources: response.sources,
        timestamp: new Date() 
      };
      setMessages(prev => [...prev, anoraMsg]);
      if (user.preferences.autoRead) handleSpeak(anoraMsg.id, response.text);
    } catch (e) {
      setMessages(prev => [...prev, { 
        id: 'err', role: 'system', content: "Neural bridge unstable. Synchronizing...", timestamp: new Date() 
      }]);
    } finally { setIsThinking(false); }
  };

  if (!user) return <AuthScreen onLogin={setUser} />;

  const accent = user.preferences.accentColor;

  return (
    <div className={`flex flex-col h-full bg-black text-zinc-300 relative overflow-hidden ${user.preferences.font === 'OUTFIT' ? 'font-outfit' : ''}`}>
      <header className="px-6 py-4 border-b border-zinc-900 glass z-[100] flex items-center justify-between pt-safe">
        <div className="flex items-center gap-4">
          <button onClick={() => setIsHubOpen(true)} className="p-3 bg-zinc-950 border border-zinc-900 rounded-xl hover:border-zinc-700 transition-all active:scale-90">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
          </button>
          <AnoraLogo size={36} color={accent} showName={true} />
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setIsCommandOpen(true)} className="p-3 bg-zinc-950 border border-zinc-900 rounded-xl text-zinc-500 hover:text-white transition-all active:scale-90">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
          </button>
          <button onClick={() => setIsProfileOpen(true)} className="w-10 h-10 rounded-full border border-zinc-800 bg-zinc-900 overflow-hidden shadow-lg active:scale-95 transition-transform">
            {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center bg-zinc-800 text-xs font-bold">{user.name[0]}</div>}
          </button>
        </div>
      </header>

      <main className="flex-1 relative overflow-hidden">
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={user.name} 
          isOwnerView={user.role === Role.OWNER} 
          accentColor={accent}
          speakingId={speakingId}
          onSpeak={handleSpeak}
          onSaveToVault={(content) => {
             const updated = { ...user, vault: [...(user.vault || []), { id: Date.now().toString(), title: 'Logic Capture', content, type: 'TEXT' as const }] };
             setUser(updated);
             localStorage.setItem('anora_user', JSON.stringify(updated));
          }}
        />
        <NeuralOrb active={isThinking} speaking={speakingId !== null} color={accent} />
      </main>

      <footer className="p-6 pb-safe glass border-t border-zinc-900 z-[100]">
        <div className="max-w-4xl mx-auto space-y-4">
          {pendingImages.length > 0 && (
            <div className="flex gap-2 overflow-x-auto no-scrollbar py-2">
              {pendingImages.map((img, i) => (
                <div key={i} className="relative w-16 h-16 rounded-xl overflow-hidden border border-zinc-800">
                  <img src={img} className="w-full h-full object-cover" />
                  <button onClick={() => setPendingImages(p => p.filter((_, idx) => idx !== i))} className="absolute top-0 right-0 p-1 bg-black/60 text-white rounded-bl-xl"><svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              ))}
            </div>
          )}
          <div className="flex items-center gap-4">
            <label className="p-5 bg-zinc-950 border border-zinc-900 rounded-full text-zinc-500 hover:text-white transition-all cursor-pointer">
              <input type="file" hidden multiple accept="image/*" onChange={e => {
                const files = e.target.files;
                if (files) {
                  Array.from(files).forEach(file => {
                    const reader = new FileReader();
                    reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]);
                    reader.readAsDataURL(file);
                  });
                }
              }} />
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </label>
            <div className="flex-1 relative">
              <input 
                value={inputValue} 
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="Direct command..."
                className="w-full bg-zinc-950 border border-zinc-900 rounded-full px-8 py-5 outline-none focus:border-zinc-700 transition-all text-sm"
              />
              <button onClick={() => handleSend()} className="absolute right-2 top-1/2 -translate-y-1/2 p-3 bg-white text-black rounded-full hover:bg-zinc-200 active:scale-90 transition-all">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </div>
      </footer>

      <ProfileModal user={user} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setUser} />
      <AssistantFeatures user={user} onUpdate={setUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />
      <CommandCenter user={user} isOpen={isCommandOpen} onClose={() => setIsCommandOpen(false)} />
