import React, { useState, useEffect, useRef } from 'react';
import { Message, User, Role } from './types';
import { INITIAL_MESSAGE, OWNER_EMAIL } from './constants';
import { anoraService } from './services/geminiService';
import { MessageList } from './components/MessageList';
import { AuthScreen } from './components/AuthScreen';
import { ProfileModal } from './components/ProfileModal';
import { AssistantFeatures } from './components/AssistantFeatures';
import { CommandCenter } from './components/CommandCenter';
import { AnoraLogo } from './components/AnoraLogo';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isCommandOpen, setIsCommandOpen] = useState(false);
  const [isSynthesisMode, setIsSynthesisMode] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [speakingId, setSpeakingId] = useState<string | null>(null);

  const audioCtx = useRef<AudioContext | null>(null);
  const currentSource = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      anoraService.initChat(currentUser);
      if (messages.length === 0) {
        setMessages([{
          id: 'init',
          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona),
          timestamp: new Date()
        }]);
      }
    }
  }, [currentUser]);

  const handleVocalize = async (id: string, text: string) => {
    if (speakingId === id) {
      currentSource.current?.stop();
      setSpeakingId(null);
      return;
    }

    try {
      if (!audioCtx.current) {
        audioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (audioCtx.current.state === 'suspended') await audioCtx.current.resume();

      setSpeakingId(id);
      const base64 = await anoraService.speak(text, currentUser?.preferences.voiceName);

      const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = audioCtx.current.createBuffer(1, dataInt16.length, 24000);
      const channel = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) channel[i] = dataInt16[i] / 32768.0;

      if (currentSource.current) currentSource.current.stop();
      const source = audioCtx.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.current.destination);
      source.onended = () => { if (speakingId === id) setSpeakingId(null); };
      currentSource.current = source;
      source.start();
    } catch (e) {
      setSpeakingId(null);
    }
  };

  const handleSend = async (val?: string) => {
    const text = val || inputValue;
    if ((!text.trim() && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      const response = isSynthesisMode 
        ? await anoraService.generateChatImage(text, userMsg.images)
        : await anoraService.sendMessageWithVision(text, userMsg.images || []);

      const anoraMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'anora',
        content: response.text,
        images: response.images,
        sources: (response as any).sources,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, anoraMsg]);
      if (currentUser.preferences.autoRead) handleVocalize(anoraMsg.id, response.text);
    } catch (e) {
      setMessages(prev => [...prev, { id: 'err', role: 'system', content: "Neural bridge unstable. Synchronizing...", timestamp: new Date() }]);
    } finally {
      setIsThinking(false);
      setIsSynthesisMode(false);
    }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const isOwner = currentUser.role === Role.OWNER;
  const accent = currentUser.preferences.accentColor;

  return (
    <div className={`flex flex-col h-[100dvh] text-zinc-300 relative overflow-hidden transition-all duration-1000 ${currentUser.preferences.font === 'OUTFIT' ? 'font-outfit' : ''}`}>

      <header className="px-6 py-5 border-b border-zinc-900 glass z-[100] flex items-center justify-between pt-[calc(var(--sat)+1.5rem)]">
        <div className="flex items-center gap-5">
          <button onClick={() => setIsHubOpen(true)} className="p-3.5 bg-zinc-950 border border-zinc-900 rounded-2xl hover:border-zinc-700 transition-all active:scale-90 shadow-xl">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
          </button>
          <AnoraLogo size={42} color={accent} showName={true} />
        </div>

        <div className="flex items-center gap-4">
          <button onClick={() => setIsCommandOpen(true)} className="p-3.5 bg-zinc-950 border border-zinc-900 rounded-2xl text-zinc-500 hover:text-white transition-all active:scale-90 shadow-xl">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
          </button>
          <button onClick={() => setIsProfileOpen(true)} className={`w-11 h-11 rounded-full border border-zinc-800 bg-zinc-900 overflow-hidden shadow-2xl active:scale-95 transition-all ${isOwner ? 'owner-glow' : ''}`}>
            {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-bold text-sm bg-zinc-800">{currentUser.name[0]}</div>}
          </button>
        </div>
      </header>

      <main className="flex-1 relative overflow-hidden flex flex-col">
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          accentColor={accent}
          onVocalize={handleVocalize}
          speakingId={speakingId}
        />
      </main>

      <footer className="p-6 pb-[calc(var(--sab)+1.5rem)] glass border-t border-zinc-900 z-[100]">
        <div className="max-w-4xl mx-auto space-y-5">
          {pendingImages.length > 0 && (
            <div className="flex gap-3 overflow-x-auto no-scrollbar py-2 px-1">
              {pendingImages.map((img, i) => (
                <div key={i} className="relative w-20 h-20 rounded-[1.5rem] overflow-hidden border-2 border-zinc-800/50 shadow-2xl animate-in zoom-in-90 duration-500 shrink-0">
                  <img src={img} className="w-full h-full object-cover" />
                  <button onClick={() => setPendingImages(p => p.filter((_, idx) => idx !== i))} className="absolute top-1 right-1 p-1 bg-black/60 text-white rounded-full hover:bg-red-500 transition-all"><svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              ))}
            </div>
          )}

          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSynthesisMode(!isSynthesisMode)} 
              className={`p-5 rounded-[2rem] border transition-all duration-700 active:scale-90 ${isSynthesisMode ? 'bg-amber-500 text-black border-amber-500 shadow-[0_0_20px_rgba(212,175,55,0.3)]' : 'bg-zinc-950 text-zinc-500 border-zinc-900 hover:border-zinc-700'}`}
            >
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a2 2 0 00-1.96 1.414l-.722 2.166a2 2 0 00.177 1.76l1.325 1.987a2 2 0 001.664.89h1.121a2 2 0 001.664-.89l1.325-1.987a2 2 0 00.177-1.76l-.722-2.166a2 2 0 00-1.542-1.442z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.672 6.328a2 2 0 011.022.547l2.387.477a2 2 0 011.96-1.414l.722-2.166a2 2 0 01-.177-1.76L14.261.025a2 2 0 01-1.664-.89h-1.121a2 2 0 01-1.664.89L8.486 2.022a2 2 0 01-.177 1.76l.722 2.166a2 2 0 011.542 1.442z" /></svg>
            </button>

            <div className="flex-1 relative group">
              <input
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder={isSynthesisMode ? "Describe vision to synthesize..." : "Direct command to Anora..."}
                className={`w-full bg-zinc-950 border rounded-[2.2rem] px-8 py-5.5 outline-none transition-all duration-700 text-sm font-medium shadow-inner ${isSynthesisMode ? 'border-amber-500/50 shadow-[0_0_20px_rgba(212,175,55,0.05)]' : 'border-zinc-900 focus:border-zinc-600'} ${isOwner ? 'hover:border-amber-500/20' : ''}`}
              />
              <button 
                onClick={() => handleSend()} 
                className={`absolute right-2.5 top-1/2 -translate-y-1/2 p-3.5 rounded-[1.5rem] transition-all active:scale-90 shadow-2xl ${isSynthesisMode || isOwner ? 'bg-amber-500 text-black' : 'bg-white text-black hover:bg-zinc-200'}`}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </div>
      </footer>

      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />
      <CommandCenter user={currentUser} isOpen={isCommandOpen} onClose={() => setIsCommandOpen(false)} />
    </div>
  );
};

