      if (mode === 'IMAGE') {
        const base64 = await anoraService.generateImage(targetPrompt);
        setResult(`data:image/png;base64,${base64}`);
      } else {
        const videoUrl = await anoraService.generateVideo(targetPrompt);
        setResult(videoUrl);
      }
    } catch (err: any) {
      alert(err.message);
    } finally {
      setLoading(false);
    }
  };

