    { label: 'Lyrical Visualizer', icon: '🎵', prompt: 'Aesthetic abstract representation of soulful lyrics, cinematic lighting, post-human art style, deep emotions.' },
    { label: 'RHB Site Visualization', icon: '🏗️', prompt: 'High-fidelity civil engineering site overview, realistic construction equipment, Jaipur landscape, aerial photography.' },
    { label: 'Neural Portrait', icon: '🌌', prompt: 'Cinematic portrait of a post-human intelligence, glowing neural networks, hyper-realistic 8k.' }
