const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

const createBlob = (data: Float32Array): GenAIBlob => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
  return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('anora_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [isSynthesisMode, setIsSynthesisMode] = useState(false);
  const [speakingId, setSpeakingId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      anoraService.initChat(currentUser);
      if (messages.length === 0) {
        setMessages([{
          id: 'initial',
          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT'),
          timestamp: new Date()
        }]);
      }
    }
  }, [currentUser]);

  const handleVocalize = async (id: string, text: string) => {
    if (speakingId === id) {
      activeSourceRef.current?.stop();
      setSpeakingId(null);
      return;
    }

    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      }
      if (audioCtxRef.current.state === 'suspended') await audioCtxRef.current.resume();

      setSpeakingId(id);
      const base64 = await anoraService.speak(text, currentUser?.preferences.voiceName);
      const buffer = await decodeAudioData(decode(base64), audioCtxRef.current, 24000, 1);

      activeSourceRef.current?.stop();
      const source = audioCtxRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtxRef.current.destination);
      source.onended = () => { if (speakingId === id) setSpeakingId(null); };
      activeSourceRef.current = source;
      source.start();
    } catch (err) {
      setSpeakingId(null);
    }
  };

  const handleSend = async (text: string) => {
    const val = text.trim();
    if ((!val && pendingImages.length === 0) || !currentUser) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: val || (isSynthesisMode ? "Synthesizing visual asset..." : "Sharing visual asset..."),
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);

    try {
      let response;
      if (isSynthesisMode) {
        response = await anoraService.generateChatImage(val || "Neural synthesis render.", userMsg.images || []);
      } else {
        response = await anoraService.sendMessageWithVision(val, userMsg.images || []);
      }

      const anoraMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'anora',
        content: response.text,
        sources: (response as any).sources,
        images: response.images,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, anoraMsg]);
      if (currentUser.preferences.autoRead) handleVocalize(anoraMsg.id, response.text);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'system', content: "Neural link timeout. Check synchronization.", timestamp: new Date() }]);
    } finally {
      setIsThinking(false);
      setIsSynthesisMode(false);
    }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const isOwner = currentUser.email.toLowerCase() === OWNER_EMAIL;
  const accent = currentUser.preferences.accentColor;

  return (
    <div className={`flex flex-col h-[100dvh] text-zinc-300 relative overflow-hidden transition-all duration-1000 ${currentUser.preferences.font === 'OUTFIT' ? 'font-outfit' : 'font-inter'}`}>

      <header className="px-6 py-5 border-b border-zinc-900 glass z-[100] flex items-center justify-between pt-[calc(var(--sat)+1.5rem)] shadow-2xl">
        <div className="flex items-center gap-5">
          <button onClick={() => setIsHubOpen(true)} className="p-3.5 bg-zinc-950 border border-zinc-900 rounded-2xl hover:border-zinc-700 transition-all active:scale-90 shadow-xl">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
          </button>
          <AnoraLogo size={42} color={accent} showName={true} />
        </div>

        <div className="flex items-center gap-4">
          <button onClick={() => setIsCommandCenterOpen(true)} className="p-3.5 bg-zinc-950 border border-zinc-900 rounded-2xl text-zinc-500 hover:text-white transition-all active:scale-90 shadow-xl">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
          </button>
          <button onClick={() => setIsProfileOpen(true)} className={`w-11 h-11 rounded-full border border-zinc-800 bg-zinc-900 overflow-hidden shadow-2xl active:scale-95 transition-all ${isOwner ? 'ring-2 ring-amber-500/30' : ''}`}>
            {currentUser.avatar ? <img src={currentUser.avatar} alt="AV" className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-bold text-sm bg-zinc-800">{currentUser.name[0]}</div>}
          </button>
        </div>
      </header>

      <main className="flex-1 relative overflow-hidden flex flex-col">
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          accentColor={accent}
          onVocalize={handleVocalize}
          speakingId={speakingId}
        />
      </main>

      <footer className="p-6 pb-[calc(var(--sab)+1.5rem)] glass border-t border-zinc-900 z-[100]">
        <div className="max-w-4xl mx-auto space-y-5">
          {pendingImages.length > 0 && (
            <div className="flex gap-3 overflow-x-auto no-scrollbar py-2 px-1">
              {pendingImages.map((img, i) => (
                <div key={i} className="relative w-20 h-20 rounded-[1.5rem] overflow-hidden border-2 border-zinc-800/50 shadow-2xl animate-in zoom-in-90 duration-500 shrink-0">
                  <img src={img} className="w-full h-full object-cover" />
                  <button onClick={() => setPendingImages(p => p.filter((_, idx) => idx !== i))} className="absolute top-1 right-1 p-1 bg-black/60 text-white rounded-full hover:bg-red-500 transition-all"><svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              ))}
            </div>
          )}

          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSynthesisMode(!isSynthesisMode)} 
              className={`p-5 rounded-[1.8rem] border transition-all duration-500 active:scale-90 ${isSynthesisMode ? 'bg-amber-500 text-black border-amber-500 shadow-[0_0_20px_rgba(212,175,55,0.3)]' : 'bg-zinc-950 text-zinc-500 border-zinc-900 hover:border-zinc-700'}`}
              title="Toggle Synthesis Mode"
            >
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a2 2 0 00-1.96 1.414l-.722 2.166a2 2 0 00.177 1.76l1.325 1.987a2 2 0 001.664.89h1.121a2 2 0 001.664-.89l1.325-1.987a2 2 0 00.177-1.76l-.722-2.166a2 2 0 00-1.542-1.442z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.672 6.328a2 2 0 011.022.547l2.387.477a2 2 0 011.96-1.414l.722-2.166a2 2 0 01-.177-1.76L14.261.025a2 2 0 01-1.664-.89h-1.121a2 2 0 01-1.664.89L8.486 2.022a2 2 0 01-.177 1.76l.722 2.166a2 2 0 011.542 1.442z" /></svg>
            </button>

            <div className="flex-1 relative group">
              <input
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isSynthesisMode ? "Describe vision..." : "Direct command..."}
                className={`w-full bg-zinc-950 border rounded-[2rem] px-8 py-5.5 outline-none transition-all duration-700 text-sm font-medium shadow-inner ${isSynthesisMode ? 'border-amber-500/50 synthesis-pulse' : 'border-zinc-900 focus:border-zinc-600'}`}
              />
