                        <svg className="w-3.5 h-3.5 group-hover/link:rotate-12 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                        <span className="truncate max-w-[140px] font-bold tracking-widest uppercase">{source.title || 'Intel'}</span>
                      </a>
                    ))}
