                className={`w-full bg-zinc-950 border text-zinc-100 rounded-[2rem] pl-6 pr-14 py-4 sm:py-5 focus:outline-none placeholder:text-zinc-800 text-sm sm:text-base transition-all ${isSynthesisMode ? 'border-amber-500/50 shadow-inner' : 'border-zinc-900'}`}
              />
