                <button onClick={() => setSound(!sound)} className={`w-full p-8 rounded-[3rem] border transition-all flex items-center justify-between active:scale-95 ${sound ? 'bg-white/5 border-white/20 text-white' : 'bg-zinc-900/20 border-zinc-900 text-zinc-800'}`}>
                  <span className="text-[11px] font-bold uppercase tracking-[0.3em]">{sound ? 'Sensors Active' : 'Silent Protocol'}</span>
                  <div className={`w-16 h-8 rounded-full relative transition-all duration-700 ${sound ? (isOwner ? 'bg-amber-500' : 'bg-white') : 'bg-zinc-800'}`}>
                    <div className={`absolute top-1.5 w-5 h-5 bg-black rounded-full transition-all duration-700 ${sound ? 'right-1.5' : 'left-1.5'}`}></div>
                  </div>
