          <div className="flex flex-1 gap-4">
            <button onClick={onLogout} className="flex-1 py-8 rounded-[3.5rem] bg-red-500/10 border border-red-500/30 text-red-500 font-bold uppercase text-[11px] tracking-[0.3em] hover:bg-red-500 hover:text-white transition-all active:scale-95">Sign Out</button>
            <button onClick={onClose} className="flex-1 py-8 rounded-[3.5rem] bg-zinc-900 border border-zinc-800 text-zinc-600 font-bold uppercase text-[11px] tracking-[0.3em] hover:text-white hover:bg-zinc-800 transition-all active:scale-95">Cancel</button>
