import React, { useEffect, useRef } from 'react';
import { Message, Role } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
  onVocalize?: (id: string, content: string) => void;
  speakingId?: string | null;
}

export const MessageList: React.FC<MessageListProps> = ({ 
  messages, 
  isThinking, 
  ownerName, 
  isOwnerView,
  onVocalize,
  speakingId
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-8 pt-10 pb-20 space-y-10 max-w-5xl mx-auto w-full scroll-smooth no-scrollbar relative z-10">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isAnora = msg.role === 'anora';
        const isSynthesis = !isUser && msg.images && msg.images.length > 0;
        const isSpeaking = speakingId === msg.id;

        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-1000 fill-mode-both ease-out`}
            style={{ animationDelay: `${index * 30}ms` }}
          >
            <div className={`max-w-[92%] sm:max-w-[85%] group relative`}>
              {/* Metadata Header */}
              <div className={`flex items-center gap-3 mb-2 px-2 transition-all duration-500 opacity-40 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[9px] font-bold uppercase tracking-[0.2em] ${isUser ? (isOwnerView ? 'text-amber-500' : 'text-zinc-400') : 'text-zinc-500'}`}>
                  {isUser ? (isOwnerView ? 'Sovereign' : ownerName.split(' ')[0]) : (isSynthesis ? 'Synthesis' : 'Anora')}
                </span>
                <div className="w-0.5 h-0.5 rounded-full bg-zinc-800"></div>
                <span className="text-[8px] text-zinc-700 font-bold uppercase tracking-widest">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>

              {/* Vision Content */}
              {msg.images && msg.images.length > 0 && (
                <div className={`grid gap-2 mb-3 animate-in zoom-in-95 duration-700 ${msg.images.length === 4 ? 'grid-cols-2' : (msg.images.length > 1 ? 'flex flex-wrap' : 'flex')} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[1.8rem] sm:rounded-[2.5rem] border shadow-2xl transition-all hover:border-zinc-400
