const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

const createBlob = (data: Float32Array): GenAIBlob => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
  return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('anora_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [inputFocused, setInputFocused] = useState(false);
  const [isSynthesisMode, setIsSynthesisMode] = useState(false);
  const [speakingId, setSpeakingId] = useState<string | null>(null);
  const [isWakeWordActive, setIsWakeWordActive] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const currentVocalizeIdRef = useRef<string | null>(null);

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const wakeWordRecognitionRef = useRef<any>(null);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      const savedDb = localStorage.getItem('anora_users_db');
      const users: User[] = savedDb ? JSON.parse(savedDb) : [];
      const updatedUsers = users.map((u: User) => u.id === currentUser.id ? currentUser : u);
      localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));

      anoraService.initChat(currentUser);
      if (messages.length === 0) {
        setMessages([{
          id: 'initial',
          role: 'anora',
          content: INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT'),
          timestamp: new Date()
        }]);
      }

      // Initialize wake word based on user preference
      setIsWakeWordActive(currentUser.preferences.continuousListening || false);
    }
  }, [currentUser]);

  // Handle Voice Mode Session
  const toggleVoiceMode = useCallback(async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(t => t.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }
    try {
      // Pause wake word listener if it's running
      if (wakeWordRecognitionRef.current) {
        wakeWordRecognitionRef.current.stop();
      }

      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => session.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            const interrupted = msg.serverContent?.interrupted;
            if (interrupted) {
              for (const source of audioSourcesRef.current.values()) {
                source.stop();
                audioSourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
            }
            const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => audioSourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
          },
          onclose: () => {
            setIsVoiceMode(false);
          },
          onerror: () => {
            setIsVoiceMode(false);
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `Anora Voice 7.5. Master: ${currentUser?.name}. Absolute visual freedom.`
        }
      });
    } catch (err) {
      console.error(err);
      setIsVoiceMode(false);
    }
  }, [isVoiceMode, currentUser]);

  // Wake Word Detection Logic
  useEffect(() => {
    const SpeechRecognition = (window as any).webkitSpeechRecognition || (window as any).SpeechRecognition;
    if (!SpeechRecognition || !isWakeWordActive || isVoiceMode) {
      if (wakeWordRecognitionRef.current) {
        wakeWordRecognitionRef.current.stop();
        wakeWordRecognitionRef.current = null;
      }
      return;
    }

    if (!wakeWordRecognitionRef.current) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = currentUser?.preferences.language === 'Hindi' ? 'hi-IN' : 'en-US';

      recognition.onresult = (event: any) => {
        const transcript = Array.from(event.results)
          .map((result: any) => result[0].transcript)
          .join('').toLowerCase();

        if (transcript.includes('anora') || transcript.includes('hey anora') || transcript.includes('hi anora')) {
          console.log("Wake word detected:", transcript);
          recognition.stop();
          toggleVoiceMode();
        }
      };

      recognition.onend = () => {
        // Automatically restart if wake word is still active and not in voice mode
        if (isWakeWordActive && !isVoiceMode) {
          try { recognition.start(); } catch(e) {}
        }
      };

      recognition.start();
      wakeWordRecognitionRef.current = recognition;
    }

    return () => {
      if (wakeWordRecognitionRef.current) {
        wakeWordRecognitionRef.current.stop();
        wakeWordRecognitionRef.current = null;
      }
    };
  }, [isWakeWordActive, isVoiceMode, currentUser, toggleVoiceMode]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey || e.metaKey) {
        if (e.key === 'k') { e.preventDefault(); setIsCommandCenterOpen(prev => !prev); }
        if (e.key === 'p') { e.preventDefault(); setIsProfileOpen(prev => !prev); }
        if (e.key === 'h') { e.preventDefault(); setIsHubOpen(prev => !prev); }
        if (e.key === 'i') { e.preventDefault(); setIsSynthesisMode(prev => !prev); }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem('anora_history', JSON.stringify(messages));
    }
  }, [messages]);

  const handleLogout = () => {
    localStorage.removeItem('anora_session');
    localStorage.removeItem('anora_history');
    setCurrentUser(null);
    setMessages([]);
    setIsProfileOpen(false);
    setIsHubOpen(false);
  };

  const handleClearHistory = () => {
    const initial: Message = {
      id: 'initial',
      role: 'anora',
      content: INITIAL_MESSAGE(currentUser!.name, currentUser!.role, currentUser!.preferences.persona || 'DEFAULT'),
      timestamp: new Date()
    };
    setMessages([initial]);
    localStorage.setItem('anora_history', JSON.stringify([initial]));
  };

  const toggleAutoVocalize = () => {
    if (!currentUser) return;
    const updated = {
      ...currentUser,
      preferences: {
        ...currentUser.preferences,
        autoRead: !currentUser.preferences.autoRead
      }
    };
    setCurrentUser(updated);
  };

  const toggleWakeWordMode = () => {
    if (!currentUser) return;
    const newState = !isWakeWordActive;
    setIsWakeWordActive(newState);
    const updated = {
      ...currentUser,
      preferences: {
        ...currentUser.preferences,
        continuousListening: newState
      }
    };
    setCurrentUser(updated);
  };

  const handleVocalize = async (id: string, text: string) => {
    if (activeSourceRef.current) {
      try { activeSourceRef.current.stop(); } catch (e) {}
      activeSourceRef.current = null;
    }
    if (speakingId === id) {
      setSpeakingId(null);
      currentVocalizeIdRef.current = null;
      return;
    }
    setSpeakingId(id);
    currentVocalizeIdRef.current = id;

    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      }
      if (audioCtxRef.current.state === 'suspended') await audioCtxRef.current.resume();
      const voiceName = currentUser?.preferences.voiceName || 'Kore';
      const base64 = await anoraService.speak(text, voiceName);
      if (currentVocalizeIdRef.current !== id) return;
      const buffer = await decodeAudioData(decode(base64), audioCtxRef.current, 24000, 1);
      if (currentVocalizeIdRef.current !== id) return;
      const source = audioCtxRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtxRef.current.destination);
      source.onended = () => {
        if (currentVocalizeIdRef.current === id) {
          setSpeakingId(null);
          currentVocalizeIdRef.current = null;
        }
      };
      activeSourceRef.current = source;
      source.start();
    } catch (err) {
      console.error("Vocalization failed:", err);
      if (currentVocalizeIdRef.current === id) {
        setSpeakingId(null);
        currentVocalizeIdRef.current = null;
      }
    }
  };

  const handleSend = async (text: string) => {
    const val = text.trim();
    if ((!val && pendingImages.length === 0) || !currentUser) return;
    if (activeSourceRef.current) {
      try { activeSourceRef.current.stop(); } catch(e) {}
      setSpeakingId(null);
      currentVocalizeIdRef.current = null;
    }
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: val || (isSynthesisMode ? "Synthesizing visual asset..." : "Sharing visual asset..."),
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined
    };
    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    setIsThinking(true);
    try {
      let response;
      if (isSynthesisMode) {
        response = await anoraService.generateChatImage(val || "Create an aesthetic abstract vision.", userMsg.images || []);
      } else {
        response = await anoraService.sendMessageWithVision(val, userMsg.images || []);
      }
      const anoraMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'anora',
        content: response.text,
        sources: (response as any).sources,
        images: response.images,
        timestamp: new Date()
      };
      setMessages(prev => [...prev, anoraMsg]);
      if (currentUser.preferences.autoRead && anoraMsg.content) {
        handleVocalize(anoraMsg.id, anoraMsg.content);
      }
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { id: 'err', role: 'system', content: "Neural bridge unstable. Synchronizing...", timestamp: new Date() }]);
    } finally {
      setIsThinking(false);
      setIsSynthesisMode(false);
    }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const isOwner = currentUser.email.toLowerCase() === OWNER_EMAIL;
  const font = currentUser.preferences.font || 'INTER';
  const accent = currentUser.preferences.accentColor || '#d4af37';

  return (
    <div className={`flex flex-col h-[100dvh] bg-black text-zinc-300 overflow-hidden transition-all duration-700 ${font === 'OUTFIT' ? 'font-outfit' : 'font-inter'} ${isOwner ? 'ring-inset ring-2 ring-amber-500/10' : ''}`}>
      <style>{`
        .accent-text { color: ${accent}; }
        .accent-border { border-color: ${accent}40; }
        .owner-glow { text-shadow: 0 0 20px ${accent}60; }
        .custom-gradient { background: linear-gradient(180deg, rgba(0,0,0,0) 0%, #000 100%); }
        @keyframes owner-pulse { 0%, 100% { opacity: 0.3; } 50% { opacity: 0.6; } }
        .sovereign-pulse { animation: owner-pulse 4s ease-in-out infinite; }
        @keyframes wake-pulse { 0% { box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.4); } 70% { box-shadow: 0 0 0 10px rgba(59, 130, 246, 0); } 100% { box-shadow: 0 0 0 0 rgba(59, 130, 246, 0); } }
        .wake-active-glow { animation: wake-pulse 2s infinite; }

        .input-glow-focus {
          box-shadow: 0 0 20px -2px ${isOwner ? 'rgba(212,175,55,0.1)' : 'rgba(255,255,255,0.05)'};
          border-color: ${isOwner ? 'rgba(212,175,55,0.3)' : 'rgba(255,255,255,0.2)'};
        }
      `}</style>

      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal 
        user={currentUser} 
        isOpen={isProfileOpen} 
        onClose={() => setIsProfileOpen(false)} 
        onUpdate={setCurrentUser} 
        onLogout={handleLogout}
      />
      <AssistantFeatures 
        user={currentUser} 
        onUpdate={setCurrentUser} 
        onClearHistory={handleClearHistory}
        messagesCount={messages.length}
        isOpen={isHubOpen} 
        onClose={() => setIsHubOpen(false)} 
      />

      <header className="flex items-center justify-between px-6 sm:px-12 lg:px-20 pt-[calc(var(--sat)+1.5rem)] pb-6 border-b border-zinc-900 bg-black/95 backdrop-blur-3xl z-[100] shrink-0 relative overflow-hidden">
        {isOwner && <div className="absolute inset-0 bg-gradient-to-r from-amber-500/5 via-transparent to-amber-500/5 sovereign-pulse pointer-events-none"></div>}

        <div className="flex items-center gap-4 sm:gap-8 relative z-10">
          <AnoraLogo size={44} color={isOwner ? '#d4af37' : accent} />
          <div className="hidden lg:flex flex-col">
            <PremiumBadge role={currentUser.role} tier={currentUser.tier} />
          </div>
        </div>

        <div className="flex items-center gap-4 sm:gap-10 relative z-10">
          <VoiceIndicator active={isVoiceMode} />
          <div className={`flex items-center gap-2 sm:gap-3 p-1 bg-zinc-950 rounded-[3rem] border shadow-2xl backdrop-blur-md ${isOwner ? 'border-amber-500/20' : 'border-zinc-900'}`}>
            <button onClick={() => setIsHubOpen(true)} className="p-2.5 sm:p-4 text-zinc-500 hover:text-white transition-all" title="Assistant Hub"><svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg></button>
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-2.5 sm:p-4 text-zinc-500 hover:text-white transition-all" title="Visual Synthesis"><svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></button>
            <button onClick={() => setIsProfileOpen(true)} className={`w-9 h-9 sm:w-11 sm:h-11 rounded-full border border-zinc-800 bg-zinc-900 overflow-hidden ml-1 flex items-center justify-center text-xs font-bold text-zinc-400 ${isOwner ? 'ring-2 ring-amber-500/50 shadow-[0_0_15px_rgba(212,175,55,0.3)]' : ''}`}>
              {currentUser.avatar ? <img src={currentUser.avatar} alt="AV" className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden bg-black">
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          onVocalize={handleVocalize}
          speakingId={speakingId}
        />
        <NeuralOrb active={isThinking} speaking={speakingId !== null} listening={isWakeWordActive && !isVoiceMode} color={isOwner ? '#d4af37' : accent} />
      </main>

      <footer className="px-4 sm:px-12 lg:px-24 pt-4 pb-[calc(var(--sab)+1.5rem)] bg-black/95 backdrop-blur-3xl border-t border-zinc-900 z-[100] shrink-0">
        <div className="max-w-[1440px] mx-auto space-y-4">
          {pendingImages.length > 0 && (
            <div className="flex flex-wrap gap-2 p-3 bg-zinc-900/40 border border-zinc-800 rounded-3xl mb-2 overflow-x-auto no-scrollbar animate-in slide-in-from-bottom-2 duration-300">
              {pendingImages.map((img, i) => (
                <div key={i} className="relative w-14 h-14 sm:w-20 sm:h-20 rounded-xl overflow-hidden border border-zinc-700 shrink-0">
                  <img src={img} className="w-full h-full object-cover" />
                  <button onClick={() => setPendingImages(p => p.filter((_, idx) => idx !== i))} className="absolute top-0.5 right-0.5 bg-black/60 rounded-full p-1 text-white hover:bg-red-500 transition-colors">
                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                </div>
              ))}
            </div>
          )}

          <div className="flex items-center gap-3 sm:gap-4 transition-all duration-500">
            <button onClick={() => fileInputRef.current?.click()} className={`p-3.5 sm:p-5 rounded-[1.8rem] bg-zinc-950 text-zinc-500 border transition-all flex items-center justify-center active:scale-95 ${isOwner ? 'border-amber-500/10 hover:border-amber-500/40' : 'border-zinc-900 hover:border-zinc-600'}`}>
              <svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
              <input type="file" ref={fileInputRef} hidden multiple onChange={e => {
                const files = e.currentTarget.files;
                if (files) Array.from(files).forEach((f: File) => {
                  const reader = new FileReader();
                  reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]);
                  reader.readAsDataURL(f);
                });
              }} />
            </button>

            <button 
              onClick={() => setIsSynthesisMode(!isSynthesisMode)} 
              className={`p-3.5 sm:p-5 rounded-[1.8rem] border transition-all flex items-center justify-center active:scale-95 ${isSynthesisMode ? 'bg-amber-500 text-black border-amber-500 shadow-[0_0_25px_rgba(245,158,11,0.3)]' : 'bg-zinc-950 text-zinc-500 border-zinc-900 hover:border-zinc-600'}`}
              title="Toggle Visual Synthesis Mode"
            >
              <svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </button>

            <div className="flex-1 relative flex items-center group">
              <input
                type="text"
                value={inputValue}
                onFocus={() => setInputFocused(true)}
                onBlur={() => setInputFocused(false)}
                onChange={e => setInputValue(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
                placeholder={isSynthesisMode ? "Vision request..." : (isOwner ? "Direct command..." : "Neural input...")}
                className={`w-full bg-zinc-950 border text-zinc-100 rounded-[2rem] pl-6 pr-32 py-4 sm:py-5 outline-none placeholder:text-zinc-800 text-sm sm:text-base transition-all duration-500 ${inputFocused ? 'input-glow-focus' : 'border-zinc-900'} ${isSynthesisMode ? 'border-amber-500/50 shadow-[inset_0_0_15px_rgba(212,175,55,0.05)]' : ''}`}
              />

              <div className="absolute right-14 flex items-center gap-1">
                {/* Wake Word Toggle */}
                <button 
                  onClick={toggleWakeWordMode}
                  className={`p-2 rounded-xl transition-all active:scale-90 ${isWakeWordActive ? 'text-blue-400 bg-blue-500/10 border border-blue-500/20 wake-active-glow' : 'text-zinc-700 hover:text-zinc-500'}`}
                  title={isWakeWordActive ? "Listening for 'Hey Anora'" : "Wake Word: OFF"}
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                  </svg>
                </button>

                {/* Vocalize Toggle */}
                <button 
                  onClick={toggleAutoVocalize}
                  className={`p-2 rounded-xl transition-all active:scale-90 ${currentUser.preferences.autoRead ? 'text-amber-500 bg-amber-500/10 border border-amber-500/20' : 'text-zinc-700 hover:text-zinc-500'}`}
                  title={currentUser.preferences.autoRead ? "Auto-Vocalize: ON" : "Auto-Vocalize: OFF"}
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                  </svg>
                </button>
              </div>

              <button 
                onClick={() => handleSend(inputValue)} 
                className={`absolute right-1.5 p-3 sm:p-4 rounded-2xl transition-all active:scale-90 ${isSynthesisMode || isOwner ? 'bg-amber-500 text-black shadow-lg hover:shadow-amber-500/20' : 'bg-white text-black hover:bg-zinc-200'} ${!inputValue.trim() && pendingImages.length === 0 ? 'opacity-30 cursor-not-allowed' : 'opacity-100'}`}
                disabled={!inputValue.trim() && pendingImages.length === 0}
              >
                <svg className="w-4 h-4 sm:w-5 sm:h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
              </button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, AiMood, IntelligenceLevel } from '../types';
import { OWNER_EMAIL, OWNER_PASSWORD, ARJUN_DETAILED_BIO } from '../constants';
import { AnoraLogo } from './AnoraLogo';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [phase, setPhase] = useState(0); // 0: Start, 1: Form, 2: Neural Booting, 3: Recovery
  const [recoverySuccess, setRecoverySuccess] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setPhase(1), 800);
    return () => clearTimeout(timer);
  }, []);

  const getUsers = (): User[] => {
    const data = localStorage.getItem('anora_users_db');
    return data ? JSON.parse(data) : [];
  };

  const saveUser = (user: User) => {
    const users = getUsers();
    users.push(user);
    localStorage.setItem('anora_users_db', JSON.stringify(users));
  };

  const updateUsers = (updatedUsers: User[]) => {
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    setTimeout(() => {
      const users = getUsers();
      const emailLower = email.toLowerCase().trim();

      if (isLogin) {
        if (emailLower === OWNER_EMAIL && password === OWNER_PASSWORD) {
          let owner = users.find(u => u.email.toLowerCase() === OWNER_EMAIL);
          if (!owner) {
            owner = {
              id: 'sovereign_arj',
              name: "Arjun Bharti Mina",
              email: OWNER_EMAIL,
              password: OWNER_PASSWORD,
              role: Role.OWNER,
              tier: SubscriptionTier.LIFETIME,
              bio: ARJUN_DETAILED_BIO,
              preferences: { 
                accentColor: '#d4af37', 
                aiMood: 'CREATIVE' as AiMood, 
                voiceName: 'Kore',
                autoRead: false,
                continuousListening: false,
                intelligenceLevel: 'DEEP' as IntelligenceLevel,
                language: 'English',
                theme: 'OBSIDIAN',
                font: 'OUTFIT',
                soundEnabled: true,
                persona: 'DEFAULT'
              },
              createdAt: new Date().toISOString(),
              reminders: [],
              notes: [],
              memory: [],
              projects: []
            };
            saveUser(owner);
          }
          setPhase(2);
          setTimeout(() => onLogin(owner!), 2500);
          return;
        }

        const found = users.find(u => u.email.toLowerCase() === emailLower);
        if (!found) {
          setError('Neural ID not recognized in database.');
        } else if (found.password !== password) {
          setError('Security mismatch. Verify encryption key.');
        } else {
          setPhase(2);
          setTimeout(() => onLogin(found), 2000);
        }
      } else {
        if (password !== confirmPassword) {
          setError('Encryption keys must be identical.');
        } else if (users.some(u => u.email.toLowerCase() === emailLower)) {
          setError('Neural ID already established.');
        } else if (password.length < 6) {
          setError('Key complexity requirements not met.');
        } else {
          const newUser: User = {
            id: Math.random().toString(36).substr(2, 9),
            name: name || 'Neural Link User',
            email: emailLower,
            password: password,
            role: Role.USER,
            tier: SubscriptionTier.FREE,
            preferences: { 
              accentColor: '#3f3f46', 
              aiMood: 'CALM' as AiMood, 
              voiceName: 'Kore',
              autoRead: false,
              continuousListening: false,
              intelligenceLevel: 'BALANCED' as IntelligenceLevel,
              language: 'English',
              theme: 'OBSIDIAN',
              font: 'INTER',
              soundEnabled: true,
              persona: 'DEFAULT'
            },
            createdAt: new Date().toISOString(),
            reminders: [],
            notes: [],
            memory: [],
            projects: []
          };
          saveUser(newUser);
          setPhase(2);
          setTimeout(() => onLogin(newUser), 2000);
        }
      }
      setLoading(false);
    }, 1800);
  };

  const handleRecovery = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    setTimeout(() => {
      const users = getUsers();
      const emailLower = email.toLowerCase().trim();
      const foundIdx = users.findIndex(u => u.email.toLowerCase() === emailLower);

      if (foundIdx === -1) {
        setError("Neural ID not found in database.");
        setLoading(false);
      } else if (emailLower === OWNER_EMAIL) {
        setError("Sovereign recovery requires manual protocol. Reference 'aman1887'.");
        setLoading(false);
      } else {
        const updatedUsers = [...users];
        updatedUsers[foundIdx] = { ...updatedUsers[foundIdx], password: password };
        updateUsers(updatedUsers);
        setRecoverySuccess(true);
        setLoading(false);
        setTimeout(() => {
          setPhase(1);
          setRecoverySuccess(false);
          setIsLogin(true);
        }, 3000);
      }
    }, 2000);
  };

  if (phase === 2) {
    return (
      <div className="min-h-screen bg-[#050505] flex flex-col items-center justify-center p-8 space-y-12 font-outfit overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(255,255,255,0.05)_0%,_transparent_70%)] animate-pulse"></div>
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 pointer-events-none"></div>

        <div className="animate-bounce transition-all duration-1000 scale-125">
          <AnoraLogo size={140} color="#fff" showName={false} />
        </div>

        <div className="text-center space-y-8 relative z-10 w-full max-w-sm">
          <div className="space-y-2">
            <h2 className="text-white text-2xl font-bold tracking-[0.5em] animate-pulse">BOOTING ANORA CORE</h2>
            <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.3em]">Neural Integration in progress...</p>
          </div>

          <div className="w-full h-1 bg-zinc-900 rounded-full overflow-hidden border border-zinc-800/50 shadow-[0_0_15px_rgba(255,255,255,0.05)]">
            <div className="h-full bg-white animate-neural-progress"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#050505] flex items-center justify-center p-6 relative overflow-hidden font-outfit">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_#0a0a0a_0%,_#000_100%)]"></div>

      <div className={`w-full max-w-md transition-all duration-1000 transform ${phase === 1 || phase === 3 ? 'translate-y-0 opacity-100' : 'translate-y-16 opacity-0'}`}>
        <div className="text-center mb-16 space-y-4 animate-in fade-in slide-in-from-top-4 duration-1000">
          <div className="flex justify-center transform hover:scale-110 transition-transform duration-700">
            <AnoraLogo size={80} color="#fff" showName={false} />
          </div>
          <div className="space-y-1">
            <h1 className="text-4xl font-bold tracking-[0.4em] text-white">ANORA</h1>
            <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.6em] animate-pulse">Sovereign Intel v3.5</p>
          </div>
        </div>

        <div className="bg-zinc-900/40 border border-zinc-800/50 p-10 sm:p-12 rounded-[4rem] backdrop-blur-3xl shadow-[0_0_80px_rgba(0,0,0,0.5)] ring-1 ring-white/5 relative group animate-in zoom-in-95 duration-700">

          {phase === 1 ? (
            <>
              <div className="flex bg-black/60 p-2 rounded-2xl border border-zinc-800/50 mb-10 relative z-10">
                <button 
                  type="button"
                  onClick={() => { setIsLogin(true); setError(''); }}
                  className={`flex-1 py-3.5 text-[10px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all duration-700 ${isLogin ? 'bg-zinc-800 text-white shadow-2xl' : 'text-zinc-600 hover:text-zinc-300'}`}
                >
                  Access Core
                </button>
                <button 
                  type="button"
                  onClick={() => { setIsLogin(false); setError(''); }}
                  className={`flex-1 py-3.5 text-[10px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all duration-700 ${!isLogin ? 'bg-zinc-800 text-white shadow-2xl' : 'text-zinc-600 hover:text-zinc-300'}`}
                >
                  Establish Link
                </button>
              </div>

              <form onSubmit={handleAuth} className="space-y-6 relative z-10">
                {error && (
                  <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl animate-in shake-in duration-500">
                    <p className="text-red-400 text-[9px] font-bold uppercase tracking-widest text-center">{error}</p>
                  </div>
                )}

                <div className="space-y-5">
                  {!isLogin && (
                    <div className="animate-in fade-in slide-in-from-top-1 duration-300">
                      <label className="block text-[9px] font-bold text-zinc-600 uppercase tracking-widest mb-2 ml-2">Identity Signature</label>
                      <input
                        type="text" required value={name} onChange={(e) => setName(e.target.value)}
                        className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-6 py-4.5 text-zinc-200 outline-none focus:ring-1 focus:ring-white/20 transition-all text-sm placeholder:text-zinc-800"
                        placeholder="E.g. Arjun"
                      />
                    </div>
                  )}

                  <div className="animate-in fade-in slide-in-from-top-1 duration-500">
                    <label className="block text-[9px] font-bold text-zinc-600 uppercase tracking-widest mb-2 ml-2">Neural ID (Email)</label>
                    <input
                      type="email" required value={email} onChange={(e) => setEmail(e.target.value)}
                      className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-6 py-4.5 text-zinc-200 outline-none focus:ring-1 focus:ring-white/20 transition-all text-sm placeholder:text-zinc-800"
                      placeholder="identity@neural.link"
                    />
                  </div>

                  <div className="animate-in fade-in slide-in-from-top-1 duration-700">
                    <label className="block text-[9px] font-bold text-zinc-600 uppercase tracking-widest mb-2 ml-2">Access Key (Password)</label>
                    <input
                      type="password" required value={password} onChange={(e) => setPassword(e.target.value)}
                      className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-6 py-4.5 text-zinc-200 outline-none focus:ring-1 focus:ring-white/20 transition-all text-sm placeholder:text-zinc-800"
                      placeholder="••••••••"
                    />
                  </div>

                  {!isLogin && (
                    <div className="animate-in fade-in slide-in-from-top-1 duration-900">
                      <label className="block text-[9px] font-bold text-zinc-600 uppercase tracking-widest mb-2 ml-2">Verify Encryption Key</label>
                      <input
                        type="password" required value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)}
                        className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-6 py-4.5 text-zinc-200 outline-none focus:ring-1 focus:ring-white/20 transition-all text-sm placeholder:text-zinc-800"
                        placeholder="••••••••"
                      />
                    </div>
                  )}
                </div>

                {isLogin && (
                  <div className="flex justify-end px-2">
                    <button type="button" onClick={() => setPhase(3)} className="text-[9px] font-bold text-zinc-600 uppercase tracking-widest hover:text-zinc-400 transition-colors">
                      Forgot Access Key?
                    </button>
                  </div>
                )}

                <button
                  type="submit" disabled={loading}
                  className="w-full bg-white text-black font-bold py-5 rounded-[2rem] hover:bg-zinc-200 transition-all active:scale-[0.98] disabled:opacity-50 mt-6 overflow-hidden relative"
                >
                  {loading ? "Synthesizing..." : (isLogin ? "Neural Sync" : "Initialize Link")}
                </button>
              </form>
            </>
          ) : (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
              <h3 className="text-white text-center text-sm font-bold uppercase tracking-[0.3em] mb-8">Neural Key Recovery</h3>

              {recoverySuccess ? (
                <div className="text-center space-y-4 py-8 animate-in zoom-in duration-500">
                   <div className="w-16 h-16 bg-green-500/20 border border-green-500/50 rounded-full mx-auto flex items-center justify-center">
                     <svg className="w-8 h-8 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                   </div>
                   <p className="text-green-400 text-[10px] font-bold uppercase tracking-widest">Access Key Re-Synchronized</p>
                   <p className="text-zinc-600 text-[8px] font-bold uppercase tracking-widest">Returning to Core Access...</p>
                </div>
              ) : (
                <form onSubmit={handleRecovery} className="space-y-6">
                  {error && (
                    <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl text-center">
                      <p className="text-red-400 text-[9px] font-bold uppercase tracking-widest">{error}</p>
                    </div>
                  )}
                  <div className="space-y-5">
                    <div>
                      <label className="block text-[9px] font-bold text-zinc-600 uppercase tracking-widest mb-2 ml-2">Neural ID (Email)</label>
                      <input
                        type="email" required value={email} onChange={(e) => setEmail(e.target.value)}
                        className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-6 py-4.5 text-zinc-200 outline-none focus:ring-1 focus:ring-white/20 transition-all text-sm"
                        placeholder="Verify email associated with link..."
                      />
                    </div>
                    <div>
                      <label className="block text-[9px] font-bold text-zinc-600 uppercase tracking-widest mb-2 ml-2">New Access Key</label>
                      <input
                        type="password" required value={password} onChange={(e) => setPassword(e.target.value)}
                        className="w-full bg-black/40 border border-zinc-800 rounded-2xl px-6 py-4.5 text-zinc-200 outline-none focus:ring-1 focus:ring-white/20 transition-all text-sm"
                        placeholder="Define new encryption sequence..."
                      />
                    </div>
                  </div>
                  <div className="pt-4 flex flex-col gap-4">
                    <button type="submit" disabled={loading} className="w-full bg-white text-black font-bold py-5 rounded-[2rem] uppercase text-[9px] tracking-widest hover:bg-zinc-200 transition-all">
                      {loading ? "Validating Neural ID..." : "Reset Encryption Key"}
                    </button>
                    <button type="button" onClick={() => setPhase(1)} className="w-full text-zinc-600 font-bold uppercase text-[9px] tracking-widest hover:text-white transition-colors">
                      Return to Sync
                    </button>
                  </div>
                </form>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export enum Role {
  OWNER = 'OWNER',
  PREMIUM = 'PREMIUM',
  USER = 'USER'
}

export enum SubscriptionTier {
  LIFETIME = 'LIFETIME',
  PRO = 'PRO',
  FREE = 'FREE',
