            Neural State Synced
          </div>
        </div>
      )}

      <div className={`w-full max-w-5xl bg-[#020202] border-t sm:border border-zinc-900 rounded-none sm:rounded-[5rem] shadow-[0_0_150px_rgba(0,0,0,1)] flex flex-col h-[100dvh] sm:h-auto sm:max-h-[94vh] transition-all duration-700 ${isOwner ? 'ring-2 ring-amber-500/20' : ''} animate-in zoom-in-95 duration-500 overflow-hidden relative`}>

