        )}

        <div className="shrink-0 px-8 sm:px-16 py-10 border-b border-zinc-900 flex items-center justify-between bg-[#020202]/80 backdrop-blur-xl z-20">
          <div className="animate-in slide-in-from-left duration-700 flex items-center gap-4">
            {isOwner && (
              <div className="w-12 h-12 bg-amber-500/10 rounded-full flex items-center justify-center text-amber-500 shadow-[0_0_15px_rgba(212,175,55,0.2)]">
                <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M5 16L3 5L8.5 10L12 4L15.5 10L21 5L19 16H5M19 19C19 19.6 18.6 20 18 20H6C5.4 20 5 19.6 5 19V18H19V19Z" /></svg>
              </div>
