  "Seeding neural motion vectors...",
  "Synthesizing temporal frames...",
  "Compiling high-fidelity physics...",
  "Optimizing cinematic sovereign lighting...",
  "Finalizing high-bandwidth video asset...",
  "Stabilizing neural bridge for delivery...",
];

export const CommandCenter: React.FC<CommandCenterProps> = ({ user, isOpen, onClose }) => {
  const [prompt, setPrompt] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState<'IMAGE' | 'VIDEO'>('IMAGE');
  const [statusIdx, setStatusIdx] = useState(0);
  const [hasApiKey, setHasApiKey] = useState(false);

  useEffect(() => {
    if (isOpen) {
      checkApiKey();
    }
  }, [isOpen, mode]);

  useEffect(() => {
    let interval: any;
    if (loading && mode === 'VIDEO') {
      interval = setInterval(() => {
        setStatusIdx(prev => (prev + 1) % VIDEO_STATUS_MESSAGES.length);
      }, 12000);
    } else {
      setStatusIdx(0);
    }
    return () => clearInterval(interval);
  }, [loading, mode]);

  const checkApiKey = async () => {
    if (mode === 'VIDEO') {
      const selected = await (window as any).aistudio.hasSelectedApiKey();
      setHasApiKey(selected);
    } else {
      setHasApiKey(true); // Default behavior for images/text
    }
  };

  const handleOpenKeyDialog = async () => {
    await (window as any).aistudio.openSelectKey();
    checkApiKey();
  };

  if (!isOpen) return null;

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setLoading(true);
    setResult(null);

    try {
      if (mode === 'IMAGE') {
        const base64 = await anoraService.generateImage(prompt);
        setResult(`data:image/png;base64,${base64}`);
      } else {
        const videoUrl = await anoraService.generateVideo(prompt);
        setResult(videoUrl);
      }
