           {result && (
             <div className="pt-12 border-t border-zinc-900 animate-in zoom-in-95 duration-700">
                <div className="rounded-[4rem] overflow-hidden border border-zinc-800 bg-black shadow-[0_0_80px_rgba(0,0,0,0.5)] relative group">
                   {mode === 'IMAGE' ? <img src={result} alt="G" className="w-full h-auto max-h-[70vh] object-contain" /> : <video src={result} controls autoPlay className="w-full h-auto max-h-[70vh]" />}
                   <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center p-10 pointer-events-none">
                      <p className="text-[10px] sm:text-xs font-bold uppercase tracking-[0.6em] text-white">Neural Output Optimized</p>
                   </div>
                </div>
                <div className="mt-10 flex flex-wrap justify-center gap-6">
                   <a href={result} download={`anora_${mode.toLowerCase()}_${Date.now()}`} className="px-10 py-4 bg-zinc-900 border border-zinc-800 rounded-full text-[10px] font-bold text-zinc-500 hover:text-white hover:border-white transition-all uppercase tracking-[0.3em] flex items-center gap-4">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                      Extract High-Resolution Assets
                   </a>
                </div>
             </div>
           )}
           <div className="h-12" />
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, CustomTier, IntelligenceLevel } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'ENGINEERING' | 'UTILITIES' | 'VAULT' | 'USERS' | 'HISTORY' | 'TIER_FORGE' | 'NEURAL_MEMORY'>('PROJECTS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const [customTiers, setCustomTiers] = useState<CustomTier[]>([]);
  const [editingTier, setEditingTier] = useState<Partial<CustomTier> | null>(null);

  useEffect(() => {
    if (isOpen) {
      const usersData = localStorage.getItem('anora_users_db');
      if (usersData) setAllUsers(JSON.parse(usersData));

      const tiersData = localStorage.getItem('anora_custom_tiers');
      if (tiersData) setCustomTiers(JSON.parse(tiersData));
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.role === Role.PREMIUM;

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };
    if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'General', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'ENGINEERING') {
      if (!updated.siteLogs) updated.siteLogs = [];
      updated.siteLogs.push({ id: Date.now().toString(), project: newItem, date: new Date().toLocaleDateString(), details: newDesc });
    }
    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    if (list === 'memory') updated.memory = updated.memory.filter(i => i.id !== id);
    onUpdate(updated);
  };

  const handleSetUserTier = (userId: string, tierId: string) => {
    const updatedUsers = allUsers.map(u => {
      if (u.id === userId) {
        if (tierId === 'FREE') return { ...u, role: Role.USER, tier: SubscriptionTier.FREE, customTierId: undefined };
        if (tierId === 'PRO') return { ...u, role: Role.PREMIUM, tier: SubscriptionTier.PRO, customTierId: undefined };
        return { ...u, role: Role.PREMIUM, tier: SubscriptionTier.CUSTOM, customTierId: tierId };
      }
      return u;
    });
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
    setAllUsers(updatedUsers);
  };

  const handleDeleteUser = (userId: string) => {
    if (!window.confirm("Purge this neural link from the database? This cannot be undone.")) return;
    const updatedUsers = allUsers.filter(u => u.id !== userId);
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
    setAllUsers(updatedUsers);
  };

  const startNewTier = () => {
    setEditingTier({
      id: `tier_${Date.now()}`,
      name: '',
      capabilities: {
        googleSearch: false,
        googleMaps: false,
        imageSynthesis: false,
        videoSynthesis: false,
        maxIntelligence: 'BALANCED',
        advancedReasoning: false,
        reasoningBudget: 0
      }
    });
  };

  const saveTier = () => {
    if (!editingTier || !editingTier.name) return;
    const tierToSave = editingTier as CustomTier;
    const exists = customTiers.find(t => t.id === tierToSave.id);
    const updated = exists 
      ? customTiers.map(t => t.id === tierToSave.id ? tierToSave : t)
      : [...customTiers, tierToSave];

    localStorage.setItem('anora_custom_tiers', JSON.stringify(updated));
    setCustomTiers(updated);
    setEditingTier(null);
  };

  const deleteTier = (id: string) => {
    const updated = customTiers.filter(t => t.id !== id);
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updated));
    setCustomTiers(updated);
  };

  const filteredUsers = allUsers.filter(u => 
    u.email.toLowerCase() !== user.email.toLowerCase() &&
    (u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
     u.email.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/90 backdrop-blur-3xl animate-in fade-in slide-in-from-right duration-500">
      <div className="w-full max-w-2xl h-[92dvh] sm:h-auto bg-[#0a0a0a] border-t sm:border-l border-zinc-900 flex flex-col shadow-2xl overflow-hidden rounded-t-[3rem] sm:rounded-none ring-1 ring-white/5 pt-safe">

        <div className="px-8 py-8 border-b border-zinc-900 flex items-center justify-between shrink-0">
          <div>
            <h2 className={`text-xl font-bold font-outfit ${isOwner ? 'text-amber-500' : 'text-white'}`}>Neural Hub</h2>
            <p className="text-[9px] text-zinc-600 uppercase tracking-widest font-bold mt-1">Sovereign Core Assets</p>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-500 hover:text-white transition-all bg-white/5 rounded-2xl group active:scale-90">
            <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-black/60 p-1.5 mx-6 mt-6 rounded-2xl border border-zinc-900 overflow-x-auto no-scrollbar gap-1 shrink-0">
          {(['PROJECTS', 'HISTORY', 'NEURAL_MEMORY', 'CREATIVE', 'ENGINEERING', 'UTILITIES', 'VAULT', 'USERS', 'TIER_FORGE'] as const).map(t => {
            if ((t === 'ENGINEERING' || t === 'USERS' || t === 'TIER_FORGE') && !isOwner) return null;
            if (t === 'CREATIVE' && !isPremium) return null;
            return (
              <button key={t} onClick={() => setTab(t)} className={`flex-1 min-w-[90px] py-3 text-[8px] font-bold uppercase tracking-[0.15em] rounded-xl transition-all ${tab === t ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-700 hover:text-zinc-400'}`}>{t.replace('_', ' ')}</button>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar">

          {tab === 'NEURAL_MEMORY' && (
              <div className="space-y-6 animate-in fade-in duration-700">
                  <div className="px-2">
                      <h3 className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em]">Active Cognitive State</h3>
                      <p className="text-[8px] text-zinc-800 font-bold uppercase tracking-widest mt-1">Distilled facts and preferences retained by Anora</p>
                  </div>
                  <div className="grid grid-cols-1 gap-4">
                      {user.memory && user.memory.length > 0 ? user.memory.map(m => (
                          <div key={m.id} className="p-6 bg-zinc-900/20 border border-zinc-800 rounded-[2.5rem] flex items-center justify-between group">
                              <div className="flex-1">
                                  <div className="flex items-center gap-3 mb-2">
                                      <span className={`px-2 py-0.5 rounded-full text-[6px] font-bold uppercase tracking-widest ${m.category === 'PREFERENCE' ? 'bg-blue-500/10 text-blue-500' : m.category === 'PROJECT' ? 'bg-purple-500/10 text-purple-500' : 'bg-zinc-800 text-zinc-500'}`}>{m.category}</span>
                                      <div className="flex gap-0.5">
                                          {[...Array(5)].map((_, i) => (
                                              <div key={i} className={`w-1 h-1 rounded-full ${i < m.strength ? 'bg-amber-500' : 'bg-zinc-800'}`}></div>
                                          ))}
                                      </div>
                                  </div>
                                  <p className="text-sm text-zinc-100 font-medium leading-relaxed">{m.content}</p>
                              </div>
                              <button onClick={() => removeItem(m.id, 'memory')} className="p-2 text-zinc-800 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                              </button>
                          </div>
                      )) : (
                          <div className="py-20 text-center text-zinc-800">
                              <p className="text-[10px] uppercase font-bold tracking-[0.5em]">No Memory Artifacts Synthesized Yet</p>
                          </div>
                      )}
                  </div>
              </div>
          )}

          {tab === 'HISTORY' && (
            <div className="space-y-10 animate-in fade-in duration-700">
              <div className="p-10 bg-zinc-900/10 border border-zinc-900 rounded-[3rem] text-center space-y-6">
                <div className="text-4xl font-bold font-outfit text-white">{messagesCount}</div>
                <div className="text-[10px] font-bold text-zinc-600 uppercase tracking-[0.5em]">Active Neural Exchanges</div>
                <p className="text-xs text-zinc-500 leading-relaxed px-4">This reflects the total volume of data currently maintained in the primary neural buffer for this session.</p>
                <button 
                  onClick={onClearHistory}
                  className="w-full py-5 bg-red-500/10 border border-red-500/30 text-red-500 text-[10px] font-bold uppercase tracking-[0.3em] rounded-[2rem] hover:bg-red-500 hover:text-white transition-all active:scale-95"
                >
                  Purge Neural History
                </button>
              </div>
            </div>
          )}

          {tab === 'USERS' && isOwner && (
            <div className="space-y-8 animate-in fade-in duration-700">
              <div className="px-2 space-y-6">
                <h3 className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em]">Neural Link Database</h3>
                <div className="relative group">
                  <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={e => setSearchTerm(e.target.value)} 
                    placeholder="Interrogate Neural IDs..." 
                    className="w-full bg-black border border-zinc-900 rounded-2xl px-12 py-4 text-xs focus:border-amber-500/30 transition-all outline-none"
                  />
                  <svg className="w-4 h-4 absolute left-4 top-1/2 -translate-y-1/2 text-zinc-800" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {filteredUsers.map((u, i) => (
                  <div key={u.id} className="p-6 bg-zinc-900/20 border border-zinc-900 rounded-[2.5rem] flex flex-col gap-6 animate-in slide-in-from-bottom-2 duration-500" style={{ animationDelay: `${i * 50}ms` }}>
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-full bg-zinc-800 border border-zinc-700 flex items-center justify-center text-xs font-bold text-zinc-500 overflow-hidden">
                          {u.avatar ? <img src={u.avatar} className="w-full h-full object-cover" /> : u.name.charAt(0)}
                        </div>
                        <div>
                          <h4 className="text-sm font-bold text-white">{u.name}</h4>
                          <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-wider">{u.email}</p>
                        </div>
                      </div>
                      <button onClick={() => handleDeleteUser(u.id)} className="p-2 text-zinc-800 hover:text-red-500 transition-colors">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                      </button>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                      <button 
                        onClick={() => handleSetUserTier(u.id, 'FREE')}
                        className={`py-3 rounded-xl border text-[8px] font-bold uppercase tracking-widest transition-all ${u.tier === 'FREE' ? 'bg-zinc-800 text-white border-zinc-700' : 'bg-black text-zinc-800 border-zinc-900'}`}
                      >
                        Free
                      </button>
                      <button 
                        onClick={() => handleSetUserTier(u.id, 'PRO')}
                        className={`py-3 rounded-xl border text-[8px] font-bold uppercase tracking-widest transition-all ${u.tier === 'PRO' ? 'bg-indigo-500/10 text-indigo-400 border-indigo-500/30' : 'bg-black text-zinc-800 border-zinc-900'}`}
                      >
                        Pro Access
                      </button>
                    </div>

                    <div className="space-y-2">
                       <label className="text-[7px] font-bold text-zinc-800 uppercase tracking-[0.4em] ml-2">Assigned Custom Protocols</label>
                       <div className="flex flex-wrap gap-2">
                         {customTiers.map(t => (
                           <button 
                            key={t.id} 
                            onClick={() => handleSetUserTier(u.id, t.id)}
                            className={`px-3 py-2 rounded-lg border text-[7px] font-bold uppercase tracking-widest transition-all ${u.customTierId === t.id ? 'bg-amber-500/10 text-amber-500 border-amber-500/30' : 'bg-black text-zinc-800 border-zinc-900'}`}
                           >
                             {t.name}
                           </button>
                         ))}
                         {customTiers.length === 0 && <span className="text-[7px] text-zinc-900 font-bold uppercase tracking-widest italic ml-2">No protocols forged</span>}
                       </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {tab === 'TIER_FORGE' && (
            <div className="space-y-8 animate-in fade-in duration-700">
                <div className="flex items-center justify-between">
                   <h3 className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em]">Neural Access Protocols</h3>
                   <button onClick={startNewTier} className="px-6 py-2 bg-amber-500 text-black text-[9px] font-bold uppercase tracking-widest rounded-full">Forge Protocol</button>
                </div>

                {editingTier && (
                  <div className="p-8 bg-zinc-900 border border-amber-500/20 rounded-[3rem] space-y-8 animate-in zoom-in-95 duration-500">
                    <input value={editingTier.name} onChange={e => setEditingTier({...editingTier, name: e.target.value})} placeholder="Protocol Name (e.g. Architect)" className="w-full bg-black border border-zinc-800 rounded-2xl px-6 py-4 text-white text-sm" />

                    <div className="grid grid-cols-2 gap-4">
                      {[
                        { label: 'Google Search', key: 'googleSearch' },
                        { label: 'Google Maps', key: 'googleMaps' },
                        { label: 'Image Synthesis', key: 'imageSynthesis' },
                        { label: 'Video (Veo)', key: 'videoSynthesis' },
                        { label: 'Quantum Reasoning', key: 'advancedReasoning' }
                      ].map(cap => (
                        <button 
                          key={cap.key}
                          onClick={() => setEditingTier({
                            ...editingTier, 
                            capabilities: { ...editingTier.capabilities!, [cap.key]: !(editingTier.capabilities as any)[cap.key] }
                          })}
                          className={`p-4 rounded-2xl border text-[9px] font-bold uppercase tracking-widest flex items-center justify-between transition-all ${ (editingTier.capabilities as any)[cap.key] ? 'bg-amber-500/10 border-amber-500/50 text-amber-500' : 'bg-black border-zinc-800 text-zinc-700'}`}
                        >
                          {cap.label}
                          <div className={`w-2 h-2 rounded-full ${ (editingTier.capabilities as any)[cap.key] ? 'bg-amber-500' : 'bg-zinc-800' }`} />
                        </button>
                      ))}
                    </div>

                    {editingTier.capabilities?.advancedReasoning && (
                        <div className="space-y-4 p-6 bg-black rounded-3xl border border-zinc-800">
                            <div className="flex justify-between">
                                <label className="text-[9px] font-bold text-zinc-600 uppercase tracking-[0.3em]">Reasoning Budget (Tokens)</label>
                                <span className="text-[10px] font-bold text-amber-500">{editingTier.capabilities.reasoningBudget}</span>
                            </div>
                            <input 
                                type="range" min="0" max="24000" step="1000"
                                value={editingTier.capabilities.reasoningBudget}
                                onChange={e => setEditingTier({ ...editingTier, capabilities: { ...editingTier.capabilities!, reasoningBudget: parseInt(e.target.value) }})}
                                className="w-full h-1.5 accent-amber-500 bg-zinc-900 rounded-full cursor-pointer" 
                            />
                        </div>
                    )}

                    <div className="space-y-4">
                      <label className="text-[9px] font-bold text-zinc-600 uppercase tracking-[0.3em] block">Max Compute IQ</label>
                      <div className="flex gap-2">
                         {(['LITE', 'BALANCED', 'DEEP'] as IntelligenceLevel[]).map(l => (
                           <button 
                            key={l}
                            onClick={() => setEditingTier({ ...editingTier, capabilities: { ...editingTier.capabilities!, maxIntelligence: l }})}
                            className={`flex-1 py-3 rounded-xl border text-[8px] font-bold uppercase transition-all ${ editingTier.capabilities?.maxIntelligence === l ? 'bg-white text-black border-white' : 'bg-black text-zinc-700 border-zinc-800' }`}
                           >
                             {l}
                           </button>
                         ))}
                      </div>
                    </div>

                    <div className="flex gap-4">
                      <button onClick={saveTier} className="flex-1 py-4 bg-white text-black rounded-2xl font-bold uppercase text-[9px] tracking-widest">Flash Protocol</button>
                      <button onClick={() => setEditingTier(null)} className="flex-1 py-4 bg-zinc-800 text-zinc-500 rounded-2xl font-bold uppercase text-[9px] tracking-widest">Abort</button>
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {customTiers.map(t => (
                    <div key={t.id} className="p-6 bg-zinc-900/20 rounded-[2rem] border border-zinc-800 flex flex-col justify-between group">
                       <div className="flex justify-between items-start mb-4">
                          <h4 className="text-white text-xs font-bold uppercase tracking-widest">{t.name}</h4>
                          <button onClick={() => deleteTier(t.id)} className="text-zinc-800 hover:text-red-500 text-sm">×</button>
                       </div>
                       <div className="flex flex-wrap gap-1.5 mb-6">
                          {t.capabilities.googleSearch && <span className="px-2 py-0.5 bg-blue-500/10 text-blue-500 rounded-full text-[6px] font-bold uppercase">Search</span>}
                          {t.capabilities.advancedReasoning && <span className="px-2 py-0.5 bg-amber-500/10 text-amber-500 rounded-full text-[6px] font-bold uppercase">Reasoning</span>}
                          <span className="px-2 py-0.5 bg-zinc-800 text-zinc-500 rounded-full text-[6px] font-bold uppercase">{t.capabilities.maxIntelligence} IQ</span>
                       </div>
                       <button onClick={() => setEditingTier(t)} className="w-full py-2 bg-zinc-800/50 hover:bg-zinc-800 text-zinc-500 hover:text-white transition-all rounded-xl text-[8px] font-bold uppercase tracking-widest">Re-Forge</button>
                    </div>
                  ))}
                </div>
            </div>
          )}

          {(tab === 'PROJECTS' || tab === 'CREATIVE' || tab === 'ENGINEERING') && (
            <div className="space-y-3 bg-zinc-900/20 p-6 rounded-[2rem] border border-zinc-800/50 shadow-inner group animate-in slide-in-from-top-4 duration-500">
              <div className="flex gap-3">
                <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder={`Label...`} className="flex-1 bg-black/50 border border-zinc-900 rounded-xl px-5 py-3.5 text-xs focus:outline-none focus:border-zinc-700 transition-all font-medium text-zinc-100" />
                <button onClick={addItem} className={`px-6 rounded-xl font-bold transition-all active:scale-90 ${isOwner ? 'bg-amber-500 text-black' : 'bg-white text-black'}`}>+</button>
              </div>
              <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Metadata context..." className="w-full bg-black/30 border border-zinc-900 rounded-xl px-5 py-3.5 text-[10px] focus:outline-none focus:border-zinc-700 transition-all text-zinc-400 h-20 resize-none" />
            </div>
          )}

          <div className="space-y-4">
            {tab === 'PROJECTS' && user.projects.map(p => (
              <div key={p.id} className="p-6 bg-zinc-900/10 rounded-[2rem] border border-zinc-900 hover:border-zinc-700 transition-all group animate-in slide-in-from-right-2 duration-500">
                <div className="flex justify-between items-start mb-2">
                   <h4 className="text-white text-[11px] font-bold tracking-[0.1em] uppercase group-hover:text-amber-500 transition-colors">{p.name}</h4>
                   <button onClick={() => removeItem(p.id, 'projects')} className="text-zinc-800 hover:text-red-500 text-[8px] font-bold">PURGE</button>
                </div>
                <p className="text-[11px] text-zinc-600 leading-relaxed font-medium">{p.description}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export enum Role {
  OWNER = 'OWNER',
  PREMIUM = 'PREMIUM',
  USER = 'USER'
}

export enum SubscriptionTier {
  LIFETIME = 'LIFETIME',
  PRO = 'PRO',
  FREE = 'FREE',
  CUSTOM = 'CUSTOM'
}

