          className={`absolute inset-0 rounded-full transition-all duration-1000 ${active || speaking || listening ? 'scale-110 opacity-100' : 'scale-75 opacity-20'}`}
          style={{ 
            backgroundColor: orbColor, 
            boxShadow: `0 0 60px ${orbColor}80` 
          }}
        />

        {/* Animated Rings */}
        <div 
          className={`absolute -inset-6 border rounded-full transition-all duration-1000 ${active ? 'opacity-40 scale-125' : listening ? 'opacity-20 scale-100' : 'opacity-0 scale-50'}`}
          style={{ 
            borderColor: orbColor, 
            animation: active ? 'orb-pulse 2s infinite' : listening ? 'orb-listen 4s infinite' : 'none' 
          }}
        />

        <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 whitespace-nowrap text-center">
          <span className={`text-[9px] font-bold uppercase tracking-[0.5em] transition-colors duration-700 ${listening && !active && !speaking ? 'text-blue-500' : 'text-zinc-600'}`}>
            {active ? `${intent} SYNTHESIS ACTIVE` : speaking ? 'VOCALIZING NEURAL OUTPUT' : listening ? "AWAITING MASTER PROTOCOL" : ''}
          </span>
          {active && <div className="mt-2 h-0.5 bg-white/10 w-full animate-pulse rounded-full overflow-hidden"><div className="h-full bg-white/40 animate-neural-progress"></div></div>}
        </div>
      </div>
      <style>{`
        @keyframes orb-pulse {
          0% { transform: scale(1); opacity: 0.4; }
          50% { transform: scale(1.4); opacity: 0.1; }
          100% { transform: scale(1); opacity: 0.4; }
        }
        @keyframes orb-listen {
          0% { transform: scale(1); opacity: 0.1; }
          50% { transform: scale(1.1); opacity: 0.3; }
          100% { transform: scale(1); opacity: 0.1; }
        }
        @keyframes neural-progress {
          0% { transform: translateX(-100%); }
