import React, { useEffect, useRef, useState } from 'react';
import { Message, Role, SubscriptionTier } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
  userTier: SubscriptionTier;
  onVocalize?: (id: string, content: string) => void;
  onEditMessage?: (id: string, newContent: string) => void;
  speakingId?: string | null;
}

export const MessageList: React.FC<MessageListProps> = ({ 
  messages, 
  isThinking, 
  ownerName, 
  isOwnerView,
  userTier,
  onVocalize,
  onEditMessage,
  speakingId
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  const handleStartEdit = (msg: Message) => {
    setEditingId(msg.id);
    setEditValue(msg.content);
  };

  const handleSaveEdit = () => {
    if (editingId && onEditMessage) {
      onEditMessage(editingId, editValue);
    }
    setEditingId(null);
  };

  const isPro = userTier === SubscriptionTier.PRO || isOwnerView;

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-8 pt-10 pb-20 space-y-10 max-w-5xl mx-auto w-full scroll-smooth no-scrollbar relative z-10">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isAnora = msg.role === 'anora';
        const isSynthesis = !isUser && msg.images && msg.images.length > 0;
        const isSpeaking = speakingId === msg.id;
        const isEditing = editingId === msg.id;

        // Define bubble styles based on tier
        let bubbleClass = "";
        if (isUser) {
          if (isOwnerView) {
            bubbleClass = "bg-zinc-900 border-amber-500/30 text-white shadow-[0_0_30px_rgba(212,175,55,0.1)] rounded-tr-none";
          } else if (isPro) {
            bubbleClass = "bg-indigo-950/40 border-indigo-500/20 text-zinc-100 rounded-tr-none";
          } else {
            bubbleClass = "bg-zinc-800/80 text-zinc-300 border-zinc-700/50 rounded-tr-none";
          }
        } else {
          if (isOwnerView) {
            bubbleClass = "bg-black/40 border-amber-500/10 text-zinc-200 rounded-tl-none backdrop-blur-3xl";
          } else {
            bubbleClass = "bg-zinc-900/30 text-zinc-300 border-zinc-800/50 rounded-tl-none backdrop-blur-3xl";
          }
        }

        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-1000 fill-mode-both ease-out`}
            style={{ animationDelay: `${index * 30}ms` }}
          >
            <div className={`max-w-[92%] sm:max-w-[85%] group relative`}>
              {/* Metadata Header */}
              <div className={`flex items-center gap-3 mb-2 px-2 transition-all duration-500 opacity-40 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[9px] font-bold uppercase tracking-[0.2em] ${isUser ? (isOwnerView ? 'text-amber-500' : isPro ? 'text-indigo-400' : 'text-zinc-500') : 'text-zinc-600'}`}>
                  {isUser ? (isOwnerView ? 'Sovereign' : isPro ? 'Neural Pro' : ownerName.split(' ')[0]) : (isSynthesis ? 'Synthesis' : 'Anora')}
                </span>
                <div className="w-0.5 h-0.5 rounded-full bg-zinc-800"></div>
                <span className="text-[8px] text-zinc-700 font-bold uppercase tracking-widest">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>

              {/* Vision Content */}
              {msg.images && msg.images.length > 0 && !isEditing && (
                <div className={`grid gap-2 mb-3 animate-in zoom-in-95 duration-700 ${msg.images.length === 4 ? 'grid-cols-2' : (msg.images.length > 1 ? 'flex flex-wrap' : 'flex')} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[1.8rem] sm:rounded-[2.5rem] border shadow-2xl transition-all hover:border-zinc-400
                      ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-800/50'} 
                      ${msg.images && msg.images.length === 1 ? 'w-64 h-64 sm:w-80 sm:h-80' : 'w-full aspect-square'}`}>
                      <img src={img} alt="V" className="w-full h-full object-cover transition-transform duration-[2s] group-hover/img:scale-110" />
                    </div>
                  ))}
                </div>
              )}

              {/* Message Bubble */}
              <div className={`rounded-[2rem] sm:rounded-[3rem] px-6 sm:px-10 py-5 sm:py-8 text-sm sm:text-base leading-relaxed shadow-[0_20px_40px_-10px_rgba(0,0,0,0.5)] transition-all duration-700 relative ring-1 ring-white/5 ${bubbleClass}`}>
                {isUser && isOwnerView && <div className="absolute -top-1 -right-1 w-3 h-3 bg-amber-500 rounded-full border-2 border-zinc-950 shadow-[0_0_10px_rgba(245,158,11,0.4)]"></div>}

                {isEditing ? (
                  <div className="space-y-4 py-2 animate-in fade-in duration-300">
                    <textarea 
                      value={editValue}
                      onChange={(e) => setEditValue(e.target.value)}
                      className="w-full bg-black/40 border border-zinc-800 rounded-2xl p-4 text-sm sm:text-base text-white outline-none focus:border-amber-500/30 transition-all resize-none min-h-[100px]"
                      autoFocus
                    />
                    <div className="flex gap-2 justify-end">
                      <button onClick={() => setEditingId(null)} className="px-4 py-2 text-[10px] font-bold uppercase tracking-widest text-zinc-600 hover:text-white transition-colors">Abort</button>
                      <button onClick={handleSaveEdit} className={`px-6 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest active:scale-95 transition-all ${isOwnerView ? 'bg-amber-500 text-black' : 'bg-white text-black'}`}>Synchronize</button>
                    </div>
                  </div>
                ) : (
                  <div className="prose prose-invert max-w-none whitespace-pre-wrap font-medium tracking-tight">
                    {msg.content}
                  </div>
                )}

                {/* Vocalize Action */}
                {isAnora && onVocalize && !isEditing && (
                  <div className="absolute top-4 -right-12 flex flex-col gap-2 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-all duration-300 translate-x-4 sm:translate-x-4 sm:group-hover:translate-x-0">
                    <button 
                      onClick={() => onVocalize(msg.id, msg.content)}
                      className={`p-3 rounded-2xl border transition-all hover:scale-110 active:scale-90 shadow-2xl ${isSpeaking ? (isOwnerView ? 'text-amber-500 border-amber-500/50' : 'text-indigo-400 border-indigo-500/50') : 'text-zinc-500 border-zinc-800 bg-zinc-900 hover:text-white'}`}
                    >
                      <svg className={`w-5 h-5 ${isSpeaking ? 'animate-pulse' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                      </svg>
                    </button>
                  </div>
                )}

                {/* Grounding Data */}
                {msg.sources && msg.sources.length > 0 && !isEditing && (
                  <div className="mt-8 pt-8 border-t border-zinc-800/50 animate-in fade-in duration-1000">
                    <p className="text-[8px] font-bold text-zinc-700 uppercase tracking-[0.4em] mb-4">VERIFIED INTEL</p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((source, idx) => (
                        <a
                          key={idx}
                          href={source.uri}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center gap-3 px-4 py-3 bg-black/50 border border-zinc-800/50 rounded-2xl text-[9px] text-zinc-500 hover:text-white hover:border-zinc-600 transition-all group/source"
                        >
                          <span className="max-w-[150px] truncate font-bold tracking-wider">{source.title || 'Intel'}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}

      {isThinking && (
        <div className="flex justify-start animate-in fade-in slide-in-from-left-2 duration-700">
          <div className={`bg-zinc-900/40 border rounded-[1.8rem] rounded-tl-none px-6 py-4 shadow-2xl backdrop-blur-3xl ring-1 ring-white/5 ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-800/80'}`}>
            <div className="flex gap-1.5">
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.3s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-600'}`}></div>
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.15s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-600'}`}></div>
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-600'}`}></div>
            </div>
          </div>
        </div>
      )}
      <div ref={bottomRef} className="h-10" />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, CustomTier, Reminder, SiteLog, LyricDraft } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'ENGINEERING' | 'TIMELINE' | 'VAULT' | 'USERS' | 'HISTORY' | 'TIER_FORGE' | 'NEURAL_MEMORY'>('TIMELINE');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [priority, setPriority] = useState<Reminder['priority']>('MEDIUM');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [customTiers, setCustomTiers] = useState<CustomTier[]>([]);
  const [editingTier, setEditingTier] = useState<Partial<CustomTier> | null>(null);

  useEffect(() => {
    if (isOpen) {
      const usersData = localStorage.getItem('anora_users_db');
      if (usersData) setAllUsers(JSON.parse(usersData));
      const tiersData = localStorage.getItem('anora_custom_tiers');
      if (tiersData) setCustomTiers(JSON.parse(tiersData));
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.tier === SubscriptionTier.PRO || user.tier === SubscriptionTier.LIFETIME;

  // Render a lock screen for restricted tabs
  const renderLockScreen = (moduleName: string, tierRequired: string) => (
    <div className="flex flex-col items-center justify-center py-24 px-12 text-center space-y-8 animate-in fade-in zoom-in-95 duration-700">
      <div className="w-20 h-20 rounded-full bg-zinc-900 border border-zinc-800 flex items-center justify-center text-zinc-600 mb-4">
        <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
      </div>
      <div>
        <h3 className="text-xl font-bold text-white mb-3 uppercase tracking-widest">{moduleName} Restricted</h3>
        <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.2em] max-w-xs mx-auto leading-relaxed">
          This neural module requires {tierRequired} protocols to bypass the cognitive firewall.
        </p>
      </div>
      <button className="px-10 py-4 bg-white text-black rounded-full font-bold uppercase text-[9px] tracking-[0.3em] hover:scale-105 transition-all">Request Upgrade</button>
    </div>
  );

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ 
        id: Date.now().toString(), 
        text: newItem, 
        priority, 
        completed: false, 
        dueDate: new Date().toISOString() 
      });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'Pop', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'ENGINEERING') {
      if (!updated.siteLogs) updated.siteLogs = [];
      updated.siteLogs.push({ id: Date.now().toString(), project: newItem, date: new Date().toLocaleDateString(), details: newDesc, status: 'PENDING' });
    }

    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    if (list === 'memory') updated.memory = updated.memory.filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    onUpdate(updated);
  };

  const toggleReminder = (id: string) => {
    const updated = { ...user };
    updated.reminders = updated.reminders.map(r => r.id === id ? { ...r, completed: !r.completed } : r);
    onUpdate(updated);
  };

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/95 backdrop-blur-3xl animate-in fade-in slide-in-from-right duration-500">
      <div className={`w-full max-w-2xl h-[94dvh] bg-[#050505] border-t sm:border-l flex flex-col shadow-2xl overflow-hidden rounded-t-[4rem] sm:rounded-none transition-all ${isOwner ? 'border-amber-500/10' : 'border-white/5'}`}>

        <div className="px-10 py-10 border-b border-white/5 flex items-center justify-between shrink-0">
          <div>
            <h2 className={`text-2xl font-bold font-outfit ${isOwner ? 'text-amber-500' : 'text-white'}`}>Neural Hub</h2>
            <p className={`text-[10px] uppercase tracking-[0.4em] font-bold mt-2 ${isOwner ? 'text-amber-500/40' : 'text-zinc-600'}`}>
              {isOwner ? 'Sovereign Core' : isPremium ? 'Premium Access' : 'Neural Link v1.0'}
            </p>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-600 hover:text-white transition-all bg-white/5 rounded-3xl group active:scale-90">
            <svg className="w-6 h-6 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-black/40 p-1.5 mx-8 mt-6 rounded-2xl border border-white/5 overflow-x-auto no-scrollbar gap-1 shrink-0">
          {(['TIMELINE', 'PROJECTS', 'ENGINEERING', 'CREATIVE', 'NEURAL_MEMORY', 'VAULT', 'USERS', 'HISTORY', 'TIER_FORGE'] as const).map(t => {
            const isTabLocked = (t === 'ENGINEERING' || t === 'TIER_FORGE' || t === 'USERS') && !isOwner;
            if (isTabLocked) return null;
            return (
              <button key={t} onClick={() => setTab(t)} className={`flex-1 min-w-[100px] py-3 text-[9px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all relative ${tab === t ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-700 hover:text-zinc-400'}`}>
                {t.replace('_', ' ')}
                {t === 'CREATIVE' && !isPremium && <span className="absolute -top-1 -right-1 text-[8px] text-amber-500">🔒</span>}
              </button>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-10 no-scrollbar">

          {tab === 'CREATIVE' && !isPremium ? renderLockScreen("Lyric Harmony Lab", "Neural Pro") : null}
          {tab === 'ENGINEERING' && !isOwner ? renderLockScreen("Blueprint Matrix", "Sovereign") : null}

          {/* Timeline Section */}
          {tab === 'TIMELINE' && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6 shadow-inner">
                  <div className="flex gap-4">
                     <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Establish new objective..." className="flex-1 bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs font-medium text-white outline-none focus:border-amber-500/30 transition-all" />
                     <button onClick={addItem} className={`px-8 rounded-2xl font-bold text-xl active:scale-95 transition-all ${isOwner ? 'bg-amber-500 text-black' : 'bg-white text-black'}`}>+</button>
                  </div>
               </div>

               <div className="space-y-4">
                  {user.reminders.length > 0 ? user.reminders.map(r => (
                    <div key={r.id} className={`group p-6 bg-zinc-900/10 border rounded-[2.5rem] flex items-center justify-between transition-all ${r.completed ? 'opacity-30 border-zinc-900' : 'border-white/5 hover:border-zinc-700'}`}>
                       <div className="flex items-center gap-6">
                          <button onClick={() => toggleReminder(r.id)} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${r.completed ? (isOwner ? 'bg-amber-500 border-amber-500' : 'bg-zinc-700 border-zinc-700') : 'border-zinc-800 hover:border-white'}`}>
                             {r.completed && <svg className="w-4 h-4 text-black" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"/></svg>}
                          </button>
                          <div>
                             <p className={`text-sm font-medium ${r.completed ? 'line-through text-zinc-600' : 'text-white'}`}>{r.text}</p>
                             <span className={`text-[8px] font-bold uppercase tracking-widest ${r.priority === 'SOVEREIGN' ? 'text-amber-500' : r.priority === 'HIGH' ? 'text-red-500' : 'text-zinc-600'}`}>Priority: {r.priority}</span>
                          </div>
                       </div>
                       <button onClick={() => removeItem(r.id, 'reminders')} className="opacity-0 group-hover:opacity-100 transition-opacity p-2 text-zinc-800 hover:text-red-500">
                          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                       </button>
                    </div>
                  )) : (
                    <div className="py-20 text-center text-zinc-800 uppercase text-[9px] tracking-[0.5em] font-bold">No Neural Objectives Assigned</div>
                  )}
               </div>
            </div>
          )}

          {tab === 'PROJECTS' && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                  <div className="flex gap-4">
                    <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Project Label..." className="flex-1 bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs text-white outline-none" />
                    <button onClick={addItem} className={`px-8 rounded-2xl font-bold ${isOwner ? 'bg-amber-500 text-black' : 'bg-white text-black'}`}>+</button>
                  </div>
                  <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Strategic mission description..." className="w-full bg-black/30 border border-zinc-900 rounded-2xl p-6 text-[10px] text-zinc-400 h-24 resize-none outline-none" />
               </div>
               {user.projects.map(p => (
                 <div key={p.id} className={`p-8 bg-zinc-900/10 border rounded-[3rem] group transition-all ${isOwner ? 'border-amber-500/10 hover:border-amber-500/30' : 'border-white/5 hover:border-zinc-700'}`}>
                    <div className="flex justify-between items-start mb-4">
