                    <p className="text-[11px] text-zinc-500 leading-relaxed font-medium">{p.description}</p>
                 </div>
               ))}
            </div>
          )}

          {/* ... USERS, HISTORY, TIER_FORGE sections continue with similar styling based on role ... */}
        </div>
      </div>
    </div>
  );
};

