                   <button onClick={() => testVoice(voiceName)} className="w-full py-4 bg-zinc-800 rounded-2xl text-[9px] font-bold uppercase tracking-widest text-zinc-500 hover:text-white transition-all">Test Sync</button>
                </div>

                <div className="p-10 bg-zinc-900/20 border border-zinc-900 rounded-[3.5rem] space-y-6">
                   <h4 className="text-[11px] font-bold uppercase tracking-widest text-zinc-400">Compute Tier</h4>
                   <div className="flex flex-col gap-3">
                     {(['LITE', 'BALANCED', 'DEEP'] as IntelligenceLevel[]).map(i => (
                       <button 
                         key={i} 
                         onClick={() => setIntel(i)} 
                         className={`py-4 rounded-xl border text-[9px] font-bold uppercase transition-all flex items-center justify-between px-6 ${intel === i ? 'bg-white text-black border-white' : 'bg-black text-zinc-700 border-zinc-800'}`}
                       >
                         {i}
                       </button>
                     ))}
                   </div>
                </div>

                <div className="p-10 bg-zinc-900/20 border border-zinc-900 rounded-[3.5rem] space-y-6">
                   <h4 className="text-[11px] font-bold uppercase tracking-widest text-zinc-400">Neural Aura</h4>
                   <div className="flex flex-wrap gap-3">
                     {ACCENT_COLORS.map(c => (
                       <button 
                        key={c.name} 
                        onClick={() => setAccent(c.value)} 
                        className={`w-10 h-10 rounded-full border-2 transition-all ${accent === c.value ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-40 hover:opacity-100'}`} 
                        style={{ backgroundColor: c.value }} 
                       />
                     ))}
                   </div>
                </div>
             </div>
          </section>
        </div>

        <div className="shrink-0 p-10 sm:p-16 border-t border-zinc-900 flex flex-col sm:flex-row gap-8 bg-black z-20">
          <button onClick={handleSave} className={`flex-[2] font-bold py-8 rounded-[3.5rem] transition-all text-[12px] tracking-[0.6em] uppercase border ${isOwner ? 'bg-amber-500 text-black border-amber-500' : 'bg-white text-black border-white'}`}>Apply Changes</button>
          <button onClick={onLogout} className="flex-1 py-8 rounded-[3.5rem] bg-red-500/10 border border-red-500/30 text-red-500 font-bold uppercase text-[11px] tracking-[0.3em] hover:bg-red-500 hover:text-white transition-all">Sign Out</button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, CustomTier, Reminder, SiteLog, LyricDraft, VaultItem, TierCapability } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

const DEFAULT_CAPS: TierCapability = {
  googleSearch: false,
  googleMaps: false,
  imageSynthesis: false,
  videoSynthesis: false,
  maxIntelligence: 'BALANCED',
  advancedReasoning: false,
  reasoningBudget: 0
};

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'ENGINEERING' | 'TIMELINE' | 'VAULT' | 'USERS' | 'HISTORY' | 'TIER_FORGE' | 'NEURAL_MEMORY'>('TIMELINE');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [priority, setPriority] = useState<Reminder['priority']>('MEDIUM');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [customTiers, setCustomTiers] = useState<CustomTier[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  // Forge State
  const [forgeName, setForgeName] = useState('');
  const [forgeCaps, setForgeCaps] = useState<TierCapability>(DEFAULT_CAPS);

  useEffect(() => {
    if (isOpen) {
      refreshData();
    }
  }, [isOpen]);

  const refreshData = () => {
    const usersData = localStorage.getItem('anora_users_db');
    if (usersData) setAllUsers(JSON.parse(usersData));
    const tiersData = localStorage.getItem('anora_custom_tiers');
    if (tiersData) setCustomTiers(JSON.parse(tiersData));
  };

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.tier === SubscriptionTier.PRO || user.tier === SubscriptionTier.LIFETIME;

  const renderLockScreen = (moduleName: string, tierRequired: string) => (
    <div className="flex flex-col items-center justify-center py-24 px-12 text-center space-y-8 animate-in fade-in zoom-in-95 duration-700">
      <div className="w-20 h-20 rounded-full bg-zinc-900 border border-zinc-800 flex items-center justify-center text-zinc-600 mb-4">
        <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
      </div>
      <div>
        <h3 className="text-xl font-bold text-white mb-3 uppercase tracking-widest">{moduleName} Restricted</h3>
        <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.2em] max-w-xs mx-auto leading-relaxed">
          This neural module requires {tierRequired} protocols to bypass the cognitive firewall.
        </p>
      </div>
    </div>
  );

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, priority, completed: false, dueDate: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'Pop', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'ENGINEERING') {
      if (!updated.siteLogs) updated.siteLogs = [];
      updated.siteLogs.push({ id: Date.now().toString(), project: newItem, date: new Date().toLocaleDateString(), details: newDesc, status: 'PENDING' });
    } else if (tab === 'VAULT') {
      if (!updated.vault) updated.vault = [];
      updated.vault.push({ id: Date.now().toString(), title: newItem, content: newDesc, type: 'TEXT' });
    }

    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    if (list === 'memory') updated.memory = updated.memory.filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (list === 'vault') updated.vault = (updated.vault || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const updateUserTier = (targetUser: User, tier: SubscriptionTier, customId?: string) => {
    const updatedUsers = allUsers.map(u => {
      if (u.id === targetUser.id) {
        return { ...u, tier, customTierId: customId };
      }
      return u;
    });
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
    setAllUsers(updatedUsers);
  };

  const handleCreateForgeTier = () => {
    if (!forgeName.trim()) return;
    const newTier: CustomTier = {
      id: `forge_${Date.now()}`,
      name: forgeName,
      capabilities: { ...forgeCaps }
    };
    const updatedTiers = [...customTiers, newTier];
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updatedTiers));
    setCustomTiers(updatedTiers);
    setForgeName('');
    setForgeCaps(DEFAULT_CAPS);
  };

  const deleteForgeTier = (id: string) => {
    const updated = customTiers.filter(t => t.id !== id);
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updated));
    setCustomTiers(updated);
  };

  const toggleReminder = (id: string) => {
    const updated = { ...user };
    updated.reminders = updated.reminders.map(r => r.id === id ? { ...r, completed: !r.completed } : r);
    onUpdate(updated);
  };

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/95 backdrop-blur-3xl animate-in fade-in slide-in-from-right duration-500">
      <div className={`w-full max-w-2xl h-[94dvh] bg-[#050505] border-t sm:border-l flex flex-col shadow-2xl overflow-hidden rounded-t-[4rem] sm:rounded-none transition-all ${isOwner ? 'border-amber-500/10' : 'border-white/5'}`}>

        <div className="px-10 py-10 border-b border-white/5 flex items-center justify-between shrink-0">
          <div>
            <h2 className={`text-2xl font-bold font-outfit ${isOwner ? 'text-amber-500' : 'text-white'}`}>Neural Hub</h2>
            <p className={`text-[10px] uppercase tracking-[0.4em] font-bold mt-2 ${isOwner ? 'text-amber-500/40' : 'text-zinc-600'}`}>
              {isOwner ? 'Sovereign Core' : isPremium ? 'Premium Access' : 'Neural Link v1.0'}
            </p>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-600 hover:text-white transition-all bg-white/5 rounded-3xl group">
            <svg className="w-6 h-6 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-black/40 p-1.5 mx-8 mt-6 rounded-2xl border border-white/5 overflow-x-auto no-scrollbar gap-1 shrink-0">
          {(['TIMELINE', 'PROJECTS', 'VAULT', 'NEURAL_MEMORY', 'ENGINEERING', 'CREATIVE', 'USERS', 'TIER_FORGE', 'HISTORY'] as const).map(t => {
            const isTabLocked = (t === 'ENGINEERING' || t === 'USERS' || t === 'TIER_FORGE') && !isOwner;
            if (isTabLocked) return null;
            return (
              <button key={t} onClick={() => setTab(t)} className={`flex-1 min-w-[100px] py-3 text-[9px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all relative ${tab === t ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-700 hover:text-zinc-400'}`}>
                {t.replace('_', ' ')}
                {(t === 'CREATIVE' || t === 'VAULT') && !isPremium && <span className="absolute -top-1 -right-1 text-[8px] text-amber-500">🔒</span>}
              </button>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-10 no-scrollbar">

          {tab === 'CREATIVE' && !isPremium ? renderLockScreen("Lyric Harmony Lab", "Neural Pro") : null}
          {tab === 'ENGINEERING' && !isOwner ? renderLockScreen("Blueprint Matrix", "Sovereign") : null}
          {tab === 'VAULT' && !isPremium ? renderLockScreen("Sovereign Vault", "Neural Pro") : null}

          {tab === 'TIMELINE' && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                  <div className="flex gap-4">
                     <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Establish objective..." className="flex-1 bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs font-medium text-white outline-none focus:border-amber-500/30 transition-all" />
                     <button onClick={addItem} className={`px-8 rounded-2xl font-bold text-xl ${isOwner ? 'bg-amber-500 text-black' : 'bg-white text-black'}`}>+</button>
                  </div>
               </div>
               <div className="space-y-4">
                  {user.reminders.map(r => (
                    <div key={r.id} className={`group p-6 bg-zinc-900/10 border rounded-[2.5rem] flex items-center justify-between transition-all ${r.completed ? 'opacity-30 border-zinc-900' : 'border-white/5'}`}>
                       <div className="flex items-center gap-6">
                          <button onClick={() => toggleReminder(r.id)} className={`w-6 h-6 rounded-full border-2 transition-all ${r.completed ? 'bg-zinc-700 border-zinc-700' : 'border-zinc-800'}`}></button>
                          <div>
                             <p className={`text-sm font-medium ${r.completed ? 'line-through text-zinc-600' : 'text-white'}`}>{r.text}</p>
                             <span className="text-[8px] font-bold uppercase tracking-widest text-zinc-600">Priority: {r.priority}</span>
                          </div>
                       </div>
                       <button onClick={() => removeItem(r.id, 'reminders')} className="text-zinc-800 hover:text-red-500">×</button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'USERS' && isOwner && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="px-4">
                  <input 
                    value={searchTerm} 
                    onChange={e => setSearchTerm(e.target.value)}
                    placeholder="Search neural identities..." 
                    className="w-full bg-zinc-900/20 border border-white/5 rounded-2xl px-6 py-4 text-xs text-white outline-none focus:border-amber-500/30 transition-all"
                  />
               </div>
               <div className="grid gap-4">
                  {allUsers.filter(u => u.name.toLowerCase().includes(searchTerm.toLowerCase()) || u.email.toLowerCase().includes(searchTerm.toLowerCase())).map(u => (
                    <div key={u.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group">
                       <div className="flex justify-between items-center mb-6">
                          <div>
                             <h4 className="text-sm font-bold text-white">{u.name}</h4>
                             <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-widest">{u.email}</p>
                          </div>
                          <span className={`px-4 py-1.5 rounded-full text-[8px] font-bold uppercase tracking-widest ${u.role === Role.OWNER ? 'bg-amber-500 text-black' : 'bg-zinc-800 text-zinc-400'}`}>
                            {u.role}
                          </span>
                       </div>
                       <div className="flex flex-wrap gap-2">
                          {(['FREE', 'PRO', 'LIFETIME', 'CUSTOM'] as SubscriptionTier[]).map(t => (
                            <button 
                              key={t}
                              onClick={() => {
                                if (t === 'CUSTOM' && customTiers.length > 0) {
                                  updateUserTier(u, t, customTiers[0].id);
                                } else {
                                  updateUserTier(u, t);
                                }
                              }}
                              className={`px-4 py-2 rounded-xl text-[8px] font-bold uppercase tracking-widest transition-all ${u.tier === t ? 'bg-white text-black' : 'bg-black/50 text-zinc-600 border border-zinc-900 hover:border-zinc-700'}`}
                            >
                              {t}
                            </button>
                          ))}
                       </div>
                       {u.tier === 'CUSTOM' && customTiers.length > 0 && (
                         <div className="mt-4 pt-4 border-t border-zinc-900">
                            <select 
                              value={u.customTierId} 
                              onChange={(e) => updateUserTier(u, 'CUSTOM' as SubscriptionTier, e.target.value)}
                              className="w-full bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-[9px] font-bold uppercase text-zinc-400 outline-none"
                            >
                              {customTiers.map(ct => <option key={ct.id} value={ct.id}>{ct.name}</option>)}
                            </select>
                         </div>
                       )}
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'TIER_FORGE' && isOwner && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-8">
                  <div className="space-y-4">
                     <label className="text-[9px] font-bold text-zinc-600 uppercase tracking-widest ml-2">Protocol Name</label>
                     <input 
                       value={forgeName} 
                       onChange={e => setForgeName(e.target.value)} 
                       placeholder="E.g. Engineering Lead" 
                       className="w-full bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs text-white outline-none"
                     />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                     {[
                       { id: 'googleSearch', label: 'Google Search' },
                       { id: 'googleMaps', label: 'Google Maps' },
                       { id: 'imageSynthesis', label: 'Image Synth' },
                       { id: 'videoSynthesis', label: 'Video Synth' },
                       { id: 'advancedReasoning', label: 'Adv. Reasoning' }
                     ].map(cap => (
                       <button 
                         key={cap.id}
                         onClick={() => setForgeCaps(prev => ({ ...prev, [cap.id]: !prev[cap.id as keyof TierCapability] }))}
                         className={`p-4 rounded-2xl border text-[9px] font-bold uppercase tracking-widest transition-all flex items-center justify-between ${forgeCaps[cap.id as keyof TierCapability] ? 'bg-amber-500/10 border-amber-500/50 text-amber-500' : 'bg-black/50 border-zinc-900 text-zinc-700'}`}
                       >
                         {cap.label}
                         {forgeCaps[cap.id as keyof TierCapability] && <div className="w-1.5 h-1.5 bg-amber-500 rounded-full"></div>}
                       </button>
                     ))}
                  </div>
                  <div className="space-y-4">
                     <label className="text-[9px] font-bold text-zinc-600 uppercase tracking-widest ml-2">Max Intelligence Level</label>
                     <div className="flex gap-2">
                        {(['LITE', 'BALANCED', 'DEEP'] as const).map(intel => (
                          <button 
                            key={intel}
                            onClick={() => setForgeCaps(prev => ({ ...prev, maxIntelligence: intel }))}
                            className={`flex-1 py-3 rounded-xl border text-[9px] font-bold uppercase transition-all ${forgeCaps.maxIntelligence === intel ? 'bg-white text-black' : 'bg-black text-zinc-700 border-zinc-900'}`}
                          >
                            {intel}
                          </button>
                        ))}
                     </div>
                  </div>
                  <button onClick={handleCreateForgeTier} className="w-full py-6 bg-white text-black rounded-[2rem] font-bold uppercase text-[10px] tracking-[0.3em] active:scale-95 transition-all">Establish Protocol</button>
               </div>

               <div className="grid gap-4">
                  {customTiers.map(ct => (
                    <div key={ct.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group">
                       <div className="flex justify-between items-center mb-6">
                          <h4 className="text-sm font-bold text-white uppercase tracking-widest">{ct.name}</h4>
                          <button onClick={() => deleteForgeTier(ct.id)} className="text-red-500/50 hover:text-red-500 text-[10px] font-bold uppercase">Purge</button>
                       </div>
                       <div className="flex flex-wrap gap-2">
                          {Object.entries(ct.capabilities).map(([key, val]) => {
                             if (typeof val === 'boolean' && val) {
                               return <span key={key} className="px-3 py-1 bg-white/5 rounded-lg text-[8px] font-bold text-zinc-500 uppercase">{key.replace(/([A-Z])/g, ' $1')}</span>
                             }
                             if (key === 'maxIntelligence') {
                               return <span key={key} className="px-3 py-1 bg-amber-500/10 rounded-lg text-[8px] font-bold text-amber-500 uppercase">IQ: {val}</span>
                             }
                             return null;
                          })}
                       </div>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'NEURAL_MEMORY' && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="px-4">
                  <h3 className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em]">Cognitive Patterns</h3>
                  <p className="text-[8px] text-zinc-800 font-bold uppercase tracking-widest mt-2">Data persistence currently established in Anora's core</p>
               </div>
               <div className="grid grid-cols-1 gap-4">
                  {user.memory && user.memory.length > 0 ? user.memory.map(m => (
                    <div key={m.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group">
                       <div className="flex justify-between items-start mb-4">
                          <span className="text-[8px] bg-white/5 px-3 py-1 rounded-full text-zinc-500 font-bold uppercase tracking-widest">{m.category}</span>
                          <span className={`text-[8px] font-bold uppercase tracking-widest ${m.strength > 3 ? 'text-amber-500' : 'text-zinc-600'}`}>Synapse Strength: {m.strength}/5</span>
                       </div>
                       <p className="text-xs text-zinc-300 font-medium leading-relaxed">{m.content}</p>
                    </div>
                  )) : (
                    <div className="py-20 text-center text-zinc-800 uppercase text-[9px] tracking-[0.5em]">No Patterns Established</div>
                  )}
               </div>
            </div>
          )}

          {tab === 'VAULT' && isPremium && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Asset Label..." className="w-full bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs text-white outline-none" />
                  <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Neural content/code..." className="w-full bg-black/30 border border-zinc-900 rounded-2xl p-6 text-[10px] text-zinc-400 h-24 resize-none outline-none" />
                  <button onClick={addItem} className="w-full py-4 bg-white text-black rounded-2xl font-bold uppercase text-[10px] tracking-widest">Store Asset</button>
               </div>
               <div className="grid grid-cols-1 gap-4">
                  {user.vault?.map(item => (
                    <div key={item.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group">
                       <div className="flex justify-between items-start mb-4">
                          <h4 className="text-xs font-bold text-white uppercase tracking-widest">{item.title}</h4>
                          <button onClick={() => removeItem(item.id, 'vault')} className="text-zinc-800 hover:text-red-500">×</button>
                       </div>
                       <pre className="text-[10px] bg-black/40 p-6 rounded-2xl text-zinc-500 overflow-x-auto no-scrollbar border border-white/5">{item.content}</pre>
                    </div>
                  ))}
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, CustomTier, Reminder, SiteLog, LyricDraft, VaultItem, TierCapability } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

const DEFAULT_CAPS: TierCapability = {
  googleSearch: false,
  googleMaps: false,
  imageSynthesis: false,
  videoSynthesis: false,
  maxIntelligence: 'BALANCED',
  advancedReasoning: false,
  reasoningBudget: 0
};

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'ENGINEERING' | 'TIMELINE' | 'VAULT' | 'USERS' | 'HISTORY' | 'TIER_FORGE' | 'NEURAL_MEMORY' | 'PROTOCOLS'>('TIMELINE');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [priority, setPriority] = useState<Reminder['priority']>('MEDIUM');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [customTiers, setCustomTiers] = useState<CustomTier[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  // Forge State
  const [forgeName, setForgeName] = useState('');
  const [forgeCaps, setForgeCaps] = useState<TierCapability>(DEFAULT_CAPS);

  useEffect(() => {
    if (isOpen) {
      refreshData();
    }
  }, [isOpen]);

  const refreshData = () => {
    const usersData = localStorage.getItem('anora_users_db');
    if (usersData) setAllUsers(JSON.parse(usersData));
    const tiersData = localStorage.getItem('anora_custom_tiers');
    if (tiersData) setCustomTiers(JSON.parse(tiersData));
  };

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.tier === SubscriptionTier.PRO || user.tier === SubscriptionTier.LIFETIME;
  const accent = user.preferences.accentColor || '#d4af37';

  const renderLockScreen = (moduleName: string, tierRequired: string) => (
    <div className="flex flex-col items-center justify-center py-24 px-12 text-center space-y-8 animate-in fade-in zoom-in-95 duration-700">
      <div className="w-20 h-20 rounded-full bg-zinc-900 border border-zinc-800 flex items-center justify-center text-zinc-600 mb-4">
        <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
      </div>
      <div>
        <h3 className="text-xl font-bold text-white mb-3 uppercase tracking-widest">{moduleName} Restricted</h3>
        <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.2em] max-w-xs mx-auto leading-relaxed">
          This neural module requires {tierRequired} protocols to bypass the cognitive firewall.
        </p>
      </div>
    </div>
  );

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, priority, completed: false, dueDate: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'Pop', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'ENGINEERING') {
      if (!updated.siteLogs) updated.siteLogs = [];
      updated.siteLogs.push({ id: Date.now().toString(), project: newItem, date: new Date().toLocaleDateString(), details: newDesc, status: 'PENDING' });
    } else if (tab === 'VAULT') {
      if (!updated.vault) updated.vault = [];
      updated.vault.push({ id: Date.now().toString(), title: newItem, content: newDesc, type: 'TEXT' });
    }

    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    if (list === 'memory') updated.memory = updated.memory.filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (list === 'vault') updated.vault = (updated.vault || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const updateUserTier = (targetUser: User, tier: SubscriptionTier, customId?: string) => {
    const updatedUsers = allUsers.map(u => {
      if (u.id === targetUser.id) {
        return { ...u, tier, customTierId: customId };
      }
      return u;
    });
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
    setAllUsers(updatedUsers);
  };

  const handleCreateForgeTier = () => {
    if (!forgeName.trim()) return;
    const newTier: CustomTier = {
      id: `forge_${Date.now()}`,
      name: forgeName,
      capabilities: { ...forgeCaps }
    };
    const updatedTiers = [...customTiers, newTier];
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updatedTiers));
    setCustomTiers(updatedTiers);
    setForgeName('');
    setForgeCaps(DEFAULT_CAPS);
  };

  const deleteForgeTier = (id: string) => {
    const updated = customTiers.filter(t => t.id !== id);
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updated));
    setCustomTiers(updated);
  };

  const toggleReminder = (id: string) => {
    const updated = { ...user };
    updated.reminders = updated.reminders.map(r => r.id === id ? { ...r, completed: !r.completed } : r);
    onUpdate(updated);
  };

  const ProtocolsData = [
    { title: "Timeline Protocol", detail: "Sequence of objectives and temporal reminders for high-velocity focus.", icon: "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" },
    { title: "Neural Memory", detail: "Persistent repository of user preferences and facts synthesized during chat.", icon: "M9 3v2m6-2v2M9 19v2m6-2v2M5 9H3m2 6H3m18-6h-2m2 6h-2M7 19h10a2 2 0 002-2V7a2 2 0 00-2-2H7a2 2 0 00-2 2v10a2 2 0 002 2zM9 9h6v6H9V9z" },
    { title: "Sovereign Vault", detail: "Encrypted storage for sensitive text, code snippets, and neural assets.", icon: "M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" },
    { title: "Blueprint Matrix", detail: "Engineering logs and AutoCAD project management modules (Owner only).", icon: "M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m-1 4h1m5-10h1m-1 4h1m-1 4h1" },
    { title: "Harmony Lab", detail: "Lyric synthesis and rhythmic structure modeling for music creation.", icon: "M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3" },
    { title: "Visual Synthesis", detail: "High-fidelity image and temporal video generation from the void.", icon: "M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" },
    { title: "Authority Matrix", detail: "Global directory for managing and Promoting neural identities (Owner only).", icon: "M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" },
    { title: "Tier Forge", detail: "Custom permission templates and neural capability overrides (Owner only).", icon: "M11 4a2 2 0 114 0v1a1 1 0 001 1h3a1 1 0 011 1v3a1 1 0 01-1 1h-1a2 2 0 100 4h1a1 1 0 011 1v3a1 1 0 01-1 1h-3a1 1 0 01-1-1v-1a2 2 0 11-4 0v1a1 1 0 01-1 1H7a1 1 0 01-1-1v-3a1 1 0 00-1-1H4a2 2 0 110-4h1a1 1 0 001-1V7a1 1 0 011-1h3a1 1 0 001-1V4z" }
  ];

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/95 backdrop-blur-3xl animate-in fade-in slide-in-from-right duration-500">
      <div className={`w-full max-w-2xl h-[94dvh] bg-[#050505] border-t sm:border-l flex flex-col shadow-2xl overflow-hidden rounded-t-[4rem] sm:rounded-none transition-all ${isOwner ? 'border-amber-500/10' : 'border-white/5'}`}>

        <div className="px-10 py-10 border-b border-white/5 flex items-center justify-between shrink-0">
          <div>
            <h2 className={`text-2xl font-bold font-outfit ${isOwner ? 'text-amber-500' : 'text-white'}`}>Neural Hub</h2>
            <p className={`text-[10px] uppercase tracking-[0.4em] font-bold mt-2 ${isOwner ? 'text-amber-500/40' : 'text-zinc-600'}`}>
              {isOwner ? 'Sovereign Core' : isPremium ? 'Premium Access' : 'Neural Link v1.0'}
            </p>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-600 hover:text-white transition-all bg-white/5 rounded-3xl group">
            <svg className="w-6 h-6 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-black/40 p-1.5 mx-8 mt-6 rounded-2xl border border-white/5 overflow-x-auto no-scrollbar gap-1 shrink-0">
          {(['TIMELINE', 'PROJECTS', 'VAULT', 'NEURAL_MEMORY', 'ENGINEERING', 'CREATIVE', 'USERS', 'TIER_FORGE', 'PROTOCOLS', 'HISTORY'] as const).map(t => {
            const isTabLocked = (t === 'ENGINEERING' || t === 'USERS' || t === 'TIER_FORGE') && !isOwner;
            if (isTabLocked) return null;
            return (
              <button key={t} onClick={() => setTab(t)} className={`flex-1 min-w-[100px] py-3 text-[9px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all relative ${tab === t ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-700 hover:text-zinc-400'}`}>
                {t.replace('_', ' ')}
                {(t === 'CREATIVE' || t === 'VAULT') && !isPremium && <span className="absolute -top-1 -right-1 text-[8px] text-amber-500">🔒</span>}
              </button>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-10 no-scrollbar">

          {tab === 'CREATIVE' && !isPremium ? renderLockScreen("Lyric Harmony Lab", "Neural Pro") : null}
          {tab === 'ENGINEERING' && !isOwner ? renderLockScreen("Blueprint Matrix", "Sovereign") : null}
          {tab === 'VAULT' && !isPremium ? renderLockScreen("Sovereign Vault", "Neural Pro") : null}

          {tab === 'PROTOCOLS' && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
              <div className="px-4">
                <h3 className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em]">System Glossary</h3>
                <p className="text-[8px] text-zinc-800 font-bold uppercase tracking-widest mt-2">Functional protocols of the Anora neural network</p>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {ProtocolsData.map((p, i) => (
                  <div key={i} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group hover:border-zinc-700 transition-all">
                    <div className="w-12 h-12 rounded-2xl bg-black/40 border border-white/5 flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                      <svg className="w-6 h-6" style={{ color: accent }} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={p.icon} />
                      </svg>
                    </div>
                    <h4 className="text-xs font-bold text-white uppercase tracking-widest mb-3">{p.title}</h4>
                    <p className="text-[10px] text-zinc-500 font-medium leading-relaxed uppercase tracking-wider">{p.detail}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {tab === 'TIMELINE' && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                  <div className="flex gap-4">
                     <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Establish objective..." className="flex-1 bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs font-medium text-white outline-none focus:border-amber-500/30 transition-all" />
                     <button onClick={addItem} className={`px-8 rounded-2xl font-bold text-xl ${isOwner ? 'bg-amber-500 text-black' : 'bg-white text-black'}`}>+</button>
                  </div>
               </div>
               <div className="space-y-4">
                  {user.reminders.map(r => (
                    <div key={r.id} className={`group p-6 bg-zinc-900/10 border rounded-[2.5rem] flex items-center justify-between transition-all ${r.completed ? 'opacity-30 border-zinc-900' : 'border-white/5'}`}>
                       <div className="flex items-center gap-6">
                          <button onClick={() => toggleReminder(r.id)} className={`w-6 h-6 rounded-full border-2 transition-all ${r.completed ? 'bg-zinc-700 border-zinc-700' : 'border-zinc-800'}`}></button>
                          <div>
                             <p className={`text-sm font-medium ${r.completed ? 'line-through text-zinc-600' : 'text-white'}`}>{r.text}</p>
                             <span className="text-[8px] font-bold uppercase tracking-widest text-zinc-600">Priority: {r.priority}</span>
                          </div>
                       </div>
                       <button onClick={() => removeItem(r.id, 'reminders')} className="text-zinc-800 hover:text-red-500">×</button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'USERS' && isOwner && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="px-4">
                  <input 
                    value={searchTerm} 
                    onChange={e => setSearchTerm(e.target.value)}
                    placeholder="Search neural identities..." 
                    className="w-full bg-zinc-900/20 border border-white/5 rounded-2xl px-6 py-4 text-xs text-white outline-none focus:border-amber-500/30 transition-all"
                  />
               </div>
               <div className="grid gap-4">
                  {allUsers.filter(u => u.name.toLowerCase().includes(searchTerm.toLowerCase()) || u.email.toLowerCase().includes(searchTerm.toLowerCase())).map(u => (
                    <div key={u.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group">
                       <div className="flex justify-between items-center mb-6">
                          <div>
                             <h4 className="text-sm font-bold text-white">{u.name}</h4>
                             <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-widest">{u.email}</p>
                          </div>
                          <span className={`px-4 py-1.5 rounded-full text-[8px] font-bold uppercase tracking-widest ${u.role === Role.OWNER ? 'bg-amber-500 text-black' : 'bg-zinc-800 text-zinc-400'}`}>
                            {u.role}
                          </span>
                       </div>
                       <div className="flex flex-wrap gap-2">
                          {(['FREE', 'PRO', 'LIFETIME', 'CUSTOM'] as SubscriptionTier[]).map(t => (
                            <button 
                              key={t}
                              onClick={() => {
                                if (t === 'CUSTOM' && customTiers.length > 0) {
                                  updateUserTier(u, t, customTiers[0].id);
                                } else {
                                  updateUserTier(u, t);
                                }
                              }}
                              className={`px-4 py-2 rounded-xl text-[8px] font-bold uppercase tracking-widest transition-all ${u.tier === t ? 'bg-white text-black' : 'bg-black/50 text-zinc-600 border border-zinc-900 hover:border-zinc-700'}`}
                            >
                              {t}
                            </button>
                          ))}
                       </div>
                       {u.tier === 'CUSTOM' && customTiers.length > 0 && (
                         <div className="mt-4 pt-4 border-t border-zinc-900">
                            <select 
                              value={u.customTierId} 
                              onChange={(e) => updateUserTier(u, 'CUSTOM' as SubscriptionTier, e.target.value)}
                              className="w-full bg-black/50 border border-zinc-800 rounded-xl px-4 py-3 text-[9px] font-bold uppercase text-zinc-400 outline-none"
                            >
                              {customTiers.map(ct => <option key={ct.id} value={ct.id}>{ct.name}</option>)}
                            </select>
                         </div>
                       )}
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'TIER_FORGE' && isOwner && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-8">
                  <div className="space-y-4">
                     <label className="text-[9px] font-bold text-zinc-600 uppercase tracking-widest ml-2">Protocol Name</label>
                     <input 
                       value={forgeName} 
                       onChange={e => setForgeName(e.target.value)} 
                       placeholder="E.g. Engineering Lead" 
                       className="w-full bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs text-white outline-none"
                     />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                     {[
                       { id: 'googleSearch', label: 'Google Search' },
                       { id: 'googleMaps', label: 'Google Maps' },
                       { id: 'imageSynthesis', label: 'Image Synth' },
                       { id: 'videoSynthesis', label: 'Video Synth' },
                       { id: 'advancedReasoning', label: 'Adv. Reasoning' }
                     ].map(cap => (
                       <button 
                         key={cap.id}
                         onClick={() => setForgeCaps(prev => ({ ...prev, [cap.id]: !prev[cap.id as keyof TierCapability] }))}
                         className={`p-4 rounded-2xl border text-[9px] font-bold uppercase tracking-widest transition-all flex items-center justify-between ${forgeCaps[cap.id as keyof TierCapability] ? 'bg-amber-500/10 border-amber-500/50 text-amber-500' : 'bg-black/50 border-zinc-900 text-zinc-700'}`}
                       >
                         {cap.label}
                         {forgeCaps[cap.id as keyof TierCapability] && <div className="w-1.5 h-1.5 bg-amber-500 rounded-full"></div>}
                       </button>
                     ))}
                  </div>
                  <div className="space-y-4">
                     <label className="text-[9px] font-bold text-zinc-600 uppercase tracking-widest ml-2">Max Intelligence Level</label>
                     <div className="flex gap-2">
                        {(['LITE', 'BALANCED', 'DEEP'] as const).map(intel => (
                          <button 
                            key={intel}
                            onClick={() => setForgeCaps(prev => ({ ...prev, maxIntelligence: intel }))}
                            className={`flex-1 py-3 rounded-xl border text-[9px] font-bold uppercase transition-all ${forgeCaps.maxIntelligence === intel ? 'bg-white text-black' : 'bg-black text-zinc-700 border-zinc-900'}`}
                          >
                            {intel}
                          </button>
                        ))}
                     </div>
                  </div>
                  <button onClick={handleCreateForgeTier} className="w-full py-6 bg-white text-black rounded-[2rem] font-bold uppercase text-[10px] tracking-[0.3em] active:scale-95 transition-all">Establish Protocol</button>
               </div>

               <div className="grid gap-4">
                  {customTiers.map(ct => (
                    <div key={ct.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group">
                       <div className="flex justify-between items-center mb-6">
                          <h4 className="text-sm font-bold text-white uppercase tracking-widest">{ct.name}</h4>
                          <button onClick={() => deleteForgeTier(ct.id)} className="text-red-500/50 hover:text-red-500 text-[10px] font-bold uppercase">Purge</button>
                       </div>
                       <div className="flex flex-wrap gap-2">
                          {Object.entries(ct.capabilities).map(([key, val]) => {
                             if (typeof val === 'boolean' && val) {
                               return <span key={key} className="px-3 py-1 bg-white/5 rounded-lg text-[8px] font-bold text-zinc-500 uppercase">{key.replace(/([A-Z])/g, ' $1')}</span>
                             }
                             if (key === 'maxIntelligence') {
                               return <span key={key} className="px-3 py-1 bg-amber-500/10 rounded-lg text-[8px] font-bold text-amber-500 uppercase">IQ: {val}</span>
                             }
                             return null;
                          })}
                       </div>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'NEURAL_MEMORY' && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="px-4">
                  <h3 className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em]">Cognitive Patterns</h3>
                  <p className="text-[8px] text-zinc-800 font-bold uppercase tracking-widest mt-2">Data persistence currently established in Anora's core</p>
               </div>
               <div className="grid grid-cols-1 gap-4">
                  {user.memory && user.memory.length > 0 ? user.memory.map(m => (
                    <div key={m.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group">
                       <div className="flex justify-between items-start mb-4">
                          <span className="text-[8px] bg-white/5 px-3 py-1 rounded-full text-zinc-500 font-bold uppercase tracking-widest">{m.category}</span>
                          <span className={`text-[8px] font-bold uppercase tracking-widest ${m.strength > 3 ? 'text-amber-500' : 'text-zinc-600'}`}>Synapse Strength: {m.strength}/5</span>
                       </div>
                       <p className="text-xs text-zinc-300 font-medium leading-relaxed">{m.content}</p>
                    </div>
                  )) : (
                    <div className="py-20 text-center text-zinc-800 uppercase text-[9px] tracking-[0.5em]">No Patterns Established</div>
                  )}
               </div>
            </div>
          )}

          {tab === 'VAULT' && isPremium && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Asset Label..." className="w-full bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs text-white outline-none" />
                  <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Neural content/code..." className="w-full bg-black/30 border border-zinc-900 rounded-2xl p-6 text-[10px] text-zinc-400 h-24 resize-none outline-none" />
                  <button onClick={addItem} className="w-full py-4 bg-white text-black rounded-2xl font-bold uppercase text-[10px] tracking-widest">Store Asset</button>
               </div>
               <div className="grid grid-cols-1 gap-4">
                  {user.vault?.map(item => (
                    <div key={item.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group">
                       <div className="flex justify-between items-start mb-4">
                          <h4 className="text-xs font-bold text-white uppercase tracking-widest">{item.title}</h4>
                          <button onClick={() => removeItem(item.id, 'vault')} className="text-zinc-800 hover:text-red-500">×</button>
                       </div>
                       <pre className="text-[10px] bg-black/40 p-6 rounded-2xl text-zinc-500 overflow-x-auto no-scrollbar border border-white/5">{item.content}</pre>
                    </div>
                  ))}
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

