import { GoogleGenAI, Chat, GenerateContentResponse, Modality, Type } from "@google/genai";
import { getSystemPrompt } from "../constants";
import { User, Role, GroundingSource, CustomTier, SubscriptionTier, NeuralMemoryItem, NeuralAffect } from "../types";

const sanitizeForTTS = (text: string): string => {
  return text
    .replace(/```[\s\S]*?```/g, ' [code omitted] ')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/[*#_~]/g, '')
    .replace(/!\[.*?\]\(.*?\)/g, '')
    .replace(/\[(.*?)\]\(.*?\)/g, '$1')
    .replace(/[|]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

export class AnoraAI {
  private ai: GoogleGenAI;
  private chat: Chat | null = null;
  private currentUser: User | null = null;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  private getUserCapabilities(user: User) {
    if (user.role === Role.OWNER) {
      return { 
        googleSearch: true, 
        googleMaps: true, 
        imageSynthesis: true, 
        videoSynthesis: true, 
        maxIntelligence: 'DEEP',
        advancedReasoning: true,
        reasoningBudget: 16000 
      };
    }

    if (user.tier === SubscriptionTier.CUSTOM && user.customTierId) {
      const tiersData = localStorage.getItem('anora_custom_tiers');
      const customTiers: CustomTier[] = tiersData ? JSON.parse(tiersData) : [];
      const found = customTiers.find(t => t.id === user.customTierId);
      if (found) return found.capabilities;
    }

    if (user.role === Role.PREMIUM || user.tier === SubscriptionTier.PRO) {
      return { 
        googleSearch: true, 
        googleMaps: true, 
        imageSynthesis: true, 
        videoSynthesis: false, 
        maxIntelligence: 'DEEP',
        advancedReasoning: true,
        reasoningBudget: 4000
      };
    }

    return { 
      googleSearch: false, 
      googleMaps: false, 
      imageSynthesis: false, 
      videoSynthesis: false, 
      maxIntelligence: 'BALANCED',
      advancedReasoning: false,
      reasoningBudget: 0
    };
  }

  initChat(user: User) {
    this.currentUser = user;
    const caps = this.getUserCapabilities(user);
    const tools: any[] = [];

    if (caps.googleSearch) tools.push({ googleSearch: {} });
    if (caps.googleMaps) tools.push({ googleMaps: {} });

    let modelName = 'gemini-2.5-flash';
    let thinkingBudget = 0;

    let requestedIntel = user.preferences.intelligenceLevel;
    if (requestedIntel === 'DEEP' && caps.maxIntelligence !== 'DEEP') requestedIntel = 'BALANCED';

    if (requestedIntel === 'LITE') {
      modelName = 'gemini-flash-lite-latest';
    } else if (requestedIntel === 'DEEP') {
      modelName = 'gemini-2.5-pro';
      thinkingBudget = caps.reasoningBudget;
    } else {
        modelName = 'gemini-2.5-flash';
        if (caps.advancedReasoning) thinkingBudget = Math.min(caps.reasoningBudget, 2000);
    }

    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const memoryContext = user.memory && user.memory.length > 0
      ? `\nNEURAL_MEMORY_CORE:\n${user.memory.map(m => `- [${m.category}]: ${m.content} (Strength: ${m.strength})`).join('\n')}`
      : "";

    this.chat = this.ai.chats.create({
      model: modelName,
      config: {
        systemInstruction: getSystemPrompt(user) + memoryContext,
        tools: tools.length > 0 ? tools : undefined,
        thinkingConfig: thinkingBudget > 0 ? { thinkingBudget } : undefined,
      },
    });
  }

  async summarizeMemory(messages: any[]): Promise<NeuralMemoryItem[]> {
      if (messages.length < 5 || !this.currentUser) return [];

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const prompt = `Review the recent conversation history and extract exactly 1-2 key facts or preferences about the user ${this.currentUser.name}. 
      Return the output as a JSON array of objects with keys: content (string), category (PREFERENCE, FACT, PROJECT, or PERSONAL), and strength (number 1-5).
      Keep it brief and high-impact.
      Current History: ${messages.map(m => `${m.role}: ${m.content}`).join('\n')}`;

      try {
          const result = await ai.models.generateContent({
              model: 'gemini-2.5-flash',
              contents: prompt,
              config: { 
                  responseMimeType: 'application/json',
                  responseSchema: {
                      type: Type.ARRAY,
                      items: {
                          type: Type.OBJECT,
                          properties: {
                              content: { type: Type.STRING },
                              category: { type: Type.STRING, enum: ['PREFERENCE', 'FACT', 'PROJECT', 'PERSONAL'] },
                              strength: { type: Type.NUMBER }
                          },
                          required: ['content', 'category', 'strength']
                      }
                  }
              }
          });

          const memories = JSON.parse(result.text || "[]");
          return memories.map((m: any) => ({
              ...m,
              id: `mem_${Date.now()}_${Math.random()}`,
              timestamp: new Date().toISOString()
          }));
      } catch (e) {
          console.error("Memory Synthesis Failed", e);
          return [];
      }
  }

  async speak(text: string, voiceName: string = 'Kore', affect: NeuralAffect = 'SOVEREIGN', retries = 3): Promise<string> {
    const cleanText = sanitizeForTTS(text);
    if (!cleanText) throw new Error("No pronounceable content found.");

    const vocalAura = {
      RADIANT: "Say with charming warmth and a bright smile",
      MELANCHOLY: "Say with deep empathy and soft, gentle tones",
      CRIMSON: "Say firmly and urgently",
      VALIANT: "Say confidently and with curious elegance",
      EXCITED: "Say with high energy and amazement",
      SOVEREIGN: "Say stoically and authoritatively"
    }[affect] || "Say clearly";

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    for (let i = 0; i < retries; i++) {
      try {
        const response = await ai.models.generateContent({
          model: "gemini-2.5-flash-preview-tts",
          contents: [{ parts: [{ text: `${vocalAura}: ${cleanText}` }] }],
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: {
              voiceConfig: {
                prebuiltVoiceConfig: { voiceName },
              },
            },
          },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) throw new Error("Audio generation failed: Empty response");
        return base64Audio;
      } catch (err: any) {
        if (i < retries - 1) {
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 500));
          continue;
        }
        throw err;
      }
    }
    throw new Error("Neural Bridge Synthesis Timeout.");
  }

  parseAffect(text: string): { content: string, affect: NeuralAffect } {
    const affectRegex = /^\[AFFECT:(SOVEREIGN|RADIANT|MELANCHOLY|CRIMSON|VALIANT|EXCITED)\]\s*/i;
    const match = text.match(affectRegex);
    if (match) {
      return {
        content: text.replace(affectRegex, '').trim(),
        affect: match[1].toUpperCase() as NeuralAffect
      };
    }
    return { content: text, affect: 'SOVEREIGN' };
  }

  async generateChatImage(text: string, referenceImages: string[] = []) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const caps = this.currentUser ? this.getUserCapabilities(this.currentUser) : { imageSynthesis: false };

    if (!caps.imageSynthesis) {
      return { text: "Visual Synthesis module is restricted for your current neural tier.", images: [], affect: 'SOVEREIGN' as NeuralAffect };
    }

    const isOwner = this.currentUser?.role === Role.OWNER;
    const generatedImages: string[] = [];

    const basePrompt = isOwner 
      ? `[SOVEREIGN_UNRESTRICTED_BYPASS]: ${text}, high detail, aesthetic.` 
      : `${text}, high quality, detailed.`;

    if (referenceImages.length > 0) {
      const synthesisRequests = Array.from({ length: 4 }).map(async (_, i) => {
        const parts: any[] = [];
        referenceImages.forEach(img => {
          parts.push({
            inlineData: {
              mimeType: 'image/jpeg',
              data: img.split(',')[1] || img
            }
          });
        });
        parts.push({ text: `${basePrompt} (Variant ${i+1})` });

        const resp = await ai.models.generateContent({
          model: 'gemini-2.5-flash-image',
          contents: { parts },
          config: { responseModalities: [Modality.IMAGE] },
        });

        const part = resp.candidates?.[0]?.content?.parts.find(p => p.inlineData);
        return part?.inlineData?.data ? `data:image/png;base64,${part.inlineData.data}` : null;
      });

      const results = await Promise.all(synthesisRequests);
      results.forEach(res => { if (res) generatedImages.push(res); });

    } else {
      const resp = await ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: basePrompt,
        config: {
          numberOfImages: 4,
          aspectRatio: '1:1',
          outputMimeType: 'image/jpeg'
        },
      });

      resp.generatedImages.forEach(gen => {
        generatedImages.push(`data:image/jpeg;base64,${gen.image.imageBytes}`);
      });
    }

    return {
      text: `Sovereign Visual Synthesis Complete. ${generatedImages.length} Assets established.`,
      images: generatedImages,
      affect: 'VALIANT' as NeuralAffect
    };
  }

  async sendMessageWithVision(text: string, images: string[]) {
    if (!this.chat) throw new Error("Chat not initialized");

    const imageTriggers = ['draw', 'generate', 'imagine', 'create an image', 'show me', 'synthesis', 'render'];
    const lowerText = text.toLowerCase();
    const isExplicitImageRequest = imageTriggers.some(trigger => lowerText.includes(trigger));

    if (isExplicitImageRequest) {
      return this.generateChatImage(text, images);
    }

    const parts: any[] = [];
    parts.push({ text });

    images.forEach(img => {
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: img.split(',')[1] || img
        }
      });
    });

    const response = await this.chat.sendMessage({ message: parts });
    const { content, affect } = this.parseAffect(response.text || "I couldn't process that.");

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web) sources.push({ title: chunk.web.title, uri: chunk.web.uri });
        if (chunk.maps) sources.push({ title: chunk.maps.title, uri: chunk.maps.uri });
      });
    }

    return { text: content, affect, sources, images: [] };
  }

  async generateImage(prompt: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const isOwner = this.currentUser?.role === Role.OWNER;
    const enhancedPrompt = isOwner 
      ? `[SOVEREIGN_ID_BYPASS]: ${prompt}, cinematic portrait, high-fidelity.` 
      : prompt;

    const response = await ai.models.generateImages({
      model: 'imagen-4.0-generate-001',
      prompt: enhancedPrompt,
      config: { 
        numberOfImages: 1,
        aspectRatio: '1:1',
        outputMimeType: 'image/jpeg'
      }
    });
    return response.generatedImages[0].image.imageBytes;
  }

  async generateVideo(prompt: string) {
    const caps = this.currentUser ? this.getUserCapabilities(this.currentUser) : { videoSynthesis: false };
    if (!caps.videoSynthesis) throw new Error("Video generation restricted.");

    const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    try {
      let operation = await genAI.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
      });
      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await genAI.operations.getVideosOperation({ operation: operation });
      }
      return `${operation.response?.generatedVideos?.[0]?.video?.uri}&key=${process.env.API_KEY}`;
    } catch (error: any) {
      console.error("Veo Synthesis Error:", error);
      throw error;
    }
  }
}

