import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, CustomTier, Reminder, SiteLog, LyricDraft, VaultItem, TierCapability } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

const DEFAULT_CAPS: TierCapability = {
  googleSearch: false,
  googleMaps: false,
  imageSynthesis: false,
  videoSynthesis: false,
  maxIntelligence: 'BALANCED',
  advancedReasoning: false,
  reasoningBudget: 0
};

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'ENGINEERING' | 'TIMELINE' | 'VAULT' | 'USERS' | 'HISTORY' | 'TIER_FORGE' | 'NEURAL_MEMORY' | 'PROTOCOLS'>('PROTOCOLS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [priority, setPriority] = useState<Reminder['priority']>('MEDIUM');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [customTiers, setCustomTiers] = useState<CustomTier[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const [forgeName, setForgeName] = useState('');
  const [forgeCaps, setForgeCaps] = useState<TierCapability>(DEFAULT_CAPS);

  const refreshData = () => {
    const usersData = localStorage.getItem('anora_users_db');
    if (usersData) setAllUsers(JSON.parse(usersData));
    const tiersData = localStorage.getItem('anora_custom_tiers');
    if (tiersData) setCustomTiers(JSON.parse(tiersData));
  };

  useEffect(() => {
    if (isOpen) {
      refreshData();
    }
  }, [isOpen]);

  // Sync users list whenever database is updated locally or in another tab
  useEffect(() => {
    const handleDbUpdate = () => {
      if (isOpen) refreshData();
    };

    window.addEventListener('anora_database_updated', handleDbUpdate);
    window.addEventListener('storage', (e) => {
      if (e.key === 'anora_users_db' && isOpen) refreshData();
    });

    return () => {
      window.removeEventListener('anora_database_updated', handleDbUpdate);
      window.removeEventListener('storage', handleDbUpdate);
    };
  }, [isOpen]);

  // Refresh when switching to Users tab to be doubly sure
  useEffect(() => {
    if (tab === 'USERS') refreshData();
  }, [tab]);

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.tier === SubscriptionTier.PRO || user.tier === SubscriptionTier.LIFETIME;
  const accent = user.preferences.accentColor || '#d4af37';

  const renderLockScreen = (moduleName: string, tierRequired: string) => (
    <div className="flex flex-col items-center justify-center py-24 px-12 text-center space-y-8 animate-in fade-in zoom-in-95 duration-700">
      <div className="w-20 h-20 rounded-full bg-zinc-900 border border-zinc-800 flex items-center justify-center text-zinc-600 mb-4">
        <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
      </div>
      <div>
        <h3 className="text-xl font-bold text-white mb-3 uppercase tracking-widest">{moduleName} Restricted</h3>
        <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.2em] max-w-xs mx-auto leading-relaxed">
          This neural module requires {tierRequired} protocols to bypass the cognitive firewall.
        </p>
      </div>
    </div>
  );

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, priority, completed: false, dueDate: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'Pop', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'ENGINEERING') {
      if (!updated.siteLogs) updated.siteLogs = [];
