               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Asset Label..." className="w-full bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs text-white outline-none" />
                  <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Neural content/code..." className="w-full bg-black/30 border border-zinc-900 rounded-2xl p-6 text-[10px] text-zinc-400 h-24 resize-none outline-none" />
                  <button onClick={addItem} className="w-full py-4 bg-white text-black rounded-2xl font-bold uppercase text-[10px] tracking-widest">Store Asset</button>
               </div>
               <div className="grid grid-cols-1 gap-4">
                  {user.vault?.map(item => (
                    <div key={item.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group">
                       <div className="flex justify-between items-start mb-4">
                          <h4 className="text-xs font-bold text-white uppercase tracking-widest">{item.title}</h4>
                          <button onClick={() => removeItem(item.id, 'vault')} className="text-zinc-800 hover:text-red-500">×</button>
                       </div>
                       <pre className="text-[10px] bg-black/40 p-6 rounded-2xl text-zinc-500 overflow-x-auto no-scrollbar border border-white/5">{item.content}</pre>
                    </div>
                  ))}
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export enum Role {
  OWNER = 'OWNER',
  PREMIUM = 'PREMIUM',
  USER = 'USER'
}

export enum SubscriptionTier {
  LIFETIME = 'LIFETIME',
  PRO = 'PRO',
  FREE = 'FREE',
  CUSTOM = 'CUSTOM'
}

