import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, CustomTier, Reminder, SiteLog, LyricDraft, VaultItem, TierCapability, UpgradeRequest } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

const DEFAULT_CAPS: TierCapability = {
  googleSearch: false,
  googleMaps: false,
  imageSynthesis: false,
  videoSynthesis: false,
  maxIntelligence: 'BALANCED',
  advancedReasoning: false,
  reasoningBudget: 0
};

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'ENGINEERING' | 'TIMELINE' | 'VAULT' | 'USERS' | 'HISTORY' | 'TIER_FORGE' | 'NEURAL_MEMORY' | 'PROTOCOLS' | 'UPGRADE'>('PROTOCOLS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [priority, setPriority] = useState<Reminder['priority']>('MEDIUM');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [customTiers, setCustomTiers] = useState<CustomTier[]>([]);
  const [upgradeRequests, setUpgradeRequests] = useState<UpgradeRequest[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const [forgeName, setForgeName] = useState('');
  const [forgeCaps, setForgeCaps] = useState<TierCapability>(DEFAULT_CAPS);

  // Upgrade tab states for regular users
  const [requestedTier, setRequestedTier] = useState<SubscriptionTier>(SubscriptionTier.PRO);
  const [upgradeMessage, setUpgradeMessage] = useState('');
  const [isRequesting, setIsRequesting] = useState(false);

  const refreshData = () => {
    const usersData = localStorage.getItem('anora_users_db');
    if (usersData) setAllUsers(JSON.parse(usersData));
    const tiersData = localStorage.getItem('anora_custom_tiers');
    if (tiersData) setCustomTiers(JSON.parse(tiersData));
    const reqData = localStorage.getItem('anora_upgrade_requests');
    if (reqData) setUpgradeRequests(JSON.parse(reqData));
  };

  useEffect(() => {
    if (isOpen) {
      refreshData();
    }
  }, [isOpen]);

  useEffect(() => {
    const handleDbUpdate = () => {
      if (isOpen) refreshData();
    };

    window.addEventListener('anora_database_updated', handleDbUpdate);
    window.addEventListener('storage', (e) => {
      if (['anora_users_db', 'anora_upgrade_requests'].includes(e.key || '') && isOpen) refreshData();
    });

    return () => {
      window.removeEventListener('anora_database_updated', handleDbUpdate);
    };
  }, [isOpen]);

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.tier === SubscriptionTier.PRO || user.tier === SubscriptionTier.LIFETIME;
  const accent = user.preferences.accentColor || '#d4af37';

  const renderLockScreen = (moduleName: string, tierRequired: string) => (
    <div className="flex flex-col items-center justify-center py-24 px-12 text-center space-y-8 animate-in fade-in zoom-in-95 duration-700">
      <div className="w-20 h-20 rounded-full bg-zinc-900 border border-zinc-800 flex items-center justify-center text-zinc-600 mb-4">
        <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
      </div>
      <div>
        <h3 className="text-xl font-bold text-white mb-3 uppercase tracking-widest">{moduleName} Restricted</h3>
        <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.2em] max-w-xs mx-auto leading-relaxed">
          This neural module requires {tierRequired} protocols to bypass the cognitive firewall.
        </p>
      </div>
    </div>
  );

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, priority, completed: false, dueDate: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'Pop', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'ENGINEERING') {
      if (!updated.siteLogs) updated.siteLogs = [];
      updated.siteLogs.push({ id: Date.now().toString(), project: newItem, date: new Date().toLocaleDateString(), details: newDesc, status: 'PENDING' });
    } else if (tab === 'VAULT') {
      if (!updated.vault) updated.vault = [];
      updated.vault.push({ id: Date.now().toString(), title: newItem, content: newDesc, type: 'TEXT' });
    }

    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    if (list === 'memory') updated.memory = updated.memory.filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (list === 'vault') updated.vault = (updated.vault || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const updateUserTier = (targetUser: User, tier: SubscriptionTier, customId?: string) => {
    const usersData = localStorage.getItem('anora_users_db');
    const db: User[] = usersData ? JSON.parse(usersData) : [];

    const updatedUsers = db.map(u => {
      if (u.id === targetUser.id) {
        const updated = { ...u, tier, customTierId: customId };
        if (targetUser.id === user.id) {
          onUpdate(updated);
        }
        return updated;
      }
      return u;
    });
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
    setAllUsers(updatedUsers);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const handleRequestUpgrade = () => {
    setIsRequesting(true);
    const newReq: UpgradeRequest = {
      id: `req_${Date.now()}`,
      userId: user.id,
      userName: user.name,
      userEmail: user.email,
      requestedTier,
      message: upgradeMessage,
      timestamp: new Date().toISOString(),
      status: 'PENDING'
    };

    const updated = [...upgradeRequests, newReq];
    localStorage.setItem('anora_upgrade_requests', JSON.stringify(updated));
    setUpgradeRequests(updated);
    window.dispatchEvent(new Event('anora_database_updated'));

    setTimeout(() => {
      setIsRequesting(false);
      setUpgradeMessage('');
      alert("Elevation request submitted to Arjun's Terminal.");
    }, 1000);
  };

  const resolveUpgradeRequest = (requestId: string, approve: boolean) => {
    const req = upgradeRequests.find(r => r.id === requestId);
    if (!req) return;

    if (approve) {
      const target = allUsers.find(u => u.id === req.userId);
      if (target) {
        updateUserTier(target, req.requestedTier);
      }
    }

    const updated = upgradeRequests.filter(r => r.id !== requestId);
    localStorage.setItem('anora_upgrade_requests', JSON.stringify(updated));
    setUpgradeRequests(updated);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const handleCreateForgeTier = () => {
    if (!forgeName.trim()) return;
    const newTier: CustomTier = {
      id: `forge_${Date.now()}`,
      name: forgeName,
      capabilities: { ...forgeCaps }
    };
    const updatedTiers = [...customTiers, newTier];
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updatedTiers));
    setCustomTiers(updatedTiers);
    setForgeName('');
    setForgeCaps(DEFAULT_CAPS);
  };

  const deleteForgeTier = (id: string) => {
    const updated = customTiers.filter(t => t.id !== id);
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updated));
    setCustomTiers(updated);
  };

  const toggleReminder = (id: string) => {
    const updated = { ...user };
    updated.reminders = updated.reminders.map(r => r.id === id ? { ...r, completed: !r.completed } : r);
    onUpdate(updated);
  };

  const ProtocolsData = [
    { title: "Timeline Protocol", detail: "Sequential task management and temporal synchronization. Keep your objectives focused.", icon: "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" },
    { title: "Neural Memory", detail: "The core repository of your synthesized patterns, preferences, and long-term context.", icon: "M9 3v2m6-2v2M9 19v2m6-2v2M5 9H3m2 6H3m18-6h-2m2 6h-2M7 19h10a2 2 0 002-2V7a2 2 0 00-2-2H7a2 2 0 00-2-2v10a2 2 0 002 2zM9 9h6v6H9V9z" },
    { title: "Sovereign Vault", detail: "Encrypted storage for high-value text assets, sensitive code, and classified neural logs.", icon: "M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" },
    { title: "Blueprint Matrix", detail: "Specialized engineering module for AutoCAD project logs and site management synchronization.", icon: "M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m-1 4h1m5-10h1m-1 4h1m-1 4h1" },
    { title: "Harmony Lab", detail: "Creative synthesis lab for music lyrics, rhythmic structures, and artistic song drafts.", icon: "M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3" },
    { title: "Visual Synthesis", detail: "Unrestricted generation of cinematic imagery and temporal video assets from the void.", icon: "M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" },
    { title: "Authority Matrix", detail: "Administrative console for managing neural identities, roles, and global network status.", icon: "M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" },
    { title: "Tier Forge", detail: "Protocol fabrication tool for creating custom capability sets and neural permission tiers.", icon: "M11 4a2 2 0 114 0v1a1 1 0 001 1h3a1 1 0 011 1v3a1 1 0 01-1 1h-1a2 2 0 100 4h1a1 1 0 011 1v3a1 1 0 01-1 1h-3a1 1 0 01-1-1v-1a2 2 0 11-4 0v1a1 1 0 01-1 1H7a1 1 0 01-1-1v-3a1 1 0 00-1-1H4a2 2 0 110-4h1a1 1 0 001-1V7a1 1 0 011-1h3a1 1 0 001-1V4z" }
  ];

  const userTabs = ['PROTOCOLS', 'TIMELINE', 'PROJECTS', 'VAULT', 'CREATIVE', 'UPGRADE', 'NEURAL_MEMORY', 'HISTORY'] as const;
  const ownerTabs = ['PROTOCOLS', 'TIMELINE', 'PROJECTS', 'VAULT', 'CREATIVE', 'ENGINEERING', 'NEURAL_MEMORY', 'USERS', 'TIER_FORGE', 'HISTORY'] as const;
  const activeTabs = isOwner ? ownerTabs : userTabs;

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/95 backdrop-blur-3xl animate-in fade-in slide-in-from-right duration-500">
      <div className={`w-full max-w-2xl h-[94dvh] bg-[#050505] border-t sm:border-l flex flex-col shadow-2xl overflow-hidden rounded-t-[4rem] sm:rounded-none transition-all ${isOwner ? 'border-amber-500/10' : 'border-white/5'}`}>

        <div className="px-10 py-10 border-b border-white/5 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center border border-white/10">
               <svg className="w-6 h-6" style={{ color: accent }} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
               </svg>
             </div>
             <div>
                <h2 className={`text-2xl font-bold font-outfit ${isOwner ? 'text-amber-500' : 'text-white'}`}>Neural Hub</h2>
                <p className={`text-[10px] uppercase tracking-[0.4em] font-bold mt-1 ${isOwner ? 'text-amber-500/40' : 'text-zinc-600'}`}>
                  {isOwner ? 'Sovereign Core' : isPremium ? 'Premium Access' : 'Neural Link v1.0'}
                </p>
             </div>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-600 hover:text-white transition-all bg-white/5 rounded-3xl group">
            <svg className="w-6 h-6 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-black/40 p-1.5 mx-8 mt-6 rounded-2xl border border-white/5 overflow-x-auto no-scrollbar gap-1 shrink-0">
          {activeTabs.map(t => (
            <button key={t} onClick={() => setTab(t)} className={`flex-1 min-w-[100px] py-3 text-[9px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all relative ${tab === t ? 'bg-zinc-800 text-white shadow-xl' : 'text-zinc-700 hover:text-zinc-400'}`}>
              {t.replace('_', ' ')}
              {t === 'UPGRADE' && upgradeRequests.some(r => r.userId === user.id) && <div className="absolute top-1 right-1 w-1.5 h-1.5 bg-amber-500 rounded-full"></div>}
              {isOwner && t === 'USERS' && upgradeRequests.length > 0 && <div className="absolute -top-1 -right-1 px-1.5 py-0.5 bg-amber-500 text-black text-[7px] font-black rounded-full shadow-[0_0_10px_rgba(212,175,55,0.5)]">{upgradeRequests.length}</div>}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-10 no-scrollbar pb-24">

          {tab === 'CREATIVE' && !isPremium ? renderLockScreen("Lyric Harmony Lab", "Neural Pro") : null}
          {tab === 'ENGINEERING' && !isOwner ? renderLockScreen("Blueprint Matrix", "Sovereign") : null}
          {tab === 'VAULT' && !isPremium ? renderLockScreen("Sovereign Vault", "Neural Pro") : null}

          {tab === 'PROTOCOLS' && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
              <div className="px-4">
                <h3 className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em]">System Glossary</h3>
                <p className="text-[8px] text-zinc-800 font-bold uppercase tracking-widest mt-2">Core functional layers of the Anora environment</p>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {ProtocolsData.map((p, i) => (
                  <div key={i} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3rem] group hover:border-zinc-700 transition-all">
                    <div className="w-12 h-12 rounded-2xl bg-black/40 border border-white/5 flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                      <svg className="w-6 h-6" style={{ color: accent }} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={p.icon} />
                      </svg>
                    </div>
                    <div className="flex items-center gap-2 mb-3">
                       <div className="w-1 h-1 rounded-full bg-white/20"></div>
                       <h4 className="text-xs font-bold text-white uppercase tracking-widest">{p.title}</h4>
                    </div>
                    <p className="text-[10px] text-zinc-500 font-medium leading-relaxed uppercase tracking-wider">{p.detail}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {tab === 'UPGRADE' && !isOwner && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
               <div className="px-4 text-center py-6">
                  <h3 className="text-xl font-bold text-white mb-2">Protocol Elevation</h3>
                  <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.3em]">Request Arjun's Authorization for Tier Upgrade</p>
               </div>

               <div className="bg-zinc-900/20 border border-white/5 p-10 rounded-[4rem] space-y-10">
                  <div className="space-y-4">
                     <label className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em] ml-2">Target Neural Link</label>
                     <div className="grid grid-cols-2 gap-4">
                        {[SubscriptionTier.PRO, SubscriptionTier.LIFETIME].map(t => (
                          <button 
                            key={t}
                            onClick={() => setRequestedTier(t)}
                            className={`py-5 rounded-2xl border text-[10px] font-bold uppercase tracking-widest transition-all ${requestedTier === t ? 'bg-white text-black border-white' : 'bg-black/50 border-zinc-900 text-zinc-600 hover:border-zinc-700'}`}
                          >
                            {t}
                          </button>
                        ))}
                     </div>
