                            </div>
                         </div>
                      </div>
                    ))}
                 </div>
               </div>
            </div>
          )}

          {tab === 'TIER_FORGE' && isOwner && (
            <div className="space-y-8 animate-in fade-in duration-700">
               <div className="bg-zinc-900/20 border border-white/5 p-10 rounded-[4rem] space-y-10">
                  <div className="space-y-4">
                     <label className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em] ml-2">Protocol Designation</label>
                     <input 
                       value={forgeName} 
                       onChange={e => setForgeName(e.target.value)} 
                       placeholder="E.g. Engineering Authority" 
                       className="w-full bg-black/50 border border-zinc-900 rounded-2xl px-8 py-5 text-sm text-white outline-none focus:border-amber-500/30 transition-all"
                     />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                     {[
                       { id: 'googleSearch', label: 'Google Search' },
                       { id: 'googleMaps', label: 'Google Maps' },
                       { id: 'imageSynthesis', label: 'Image Synth' },
                       { id: 'videoSynthesis', label: 'Video Synth' },
                       { id: 'advancedReasoning', label: 'Adv. Reasoning' }
                     ].map(cap => (
                       <button 
                         key={cap.id}
