                         className={`p-6 rounded-3xl border text-[9px] font-bold uppercase tracking-widest transition-all flex items-center justify-between ${forgeCaps[cap.id as keyof TierCapability] ? 'bg-amber-500/10 border-amber-500/50 text-amber-500' : 'bg-black/50 border-zinc-900 text-zinc-800'}`}
                       >
