                  </div>

                  <div className="space-y-4">
                     <label className="text-[10px] font-bold text-zinc-700 uppercase tracking-[0.4em] ml-2">Intelligence Cap</label>
                     <div className="flex gap-2">
                        {(['LITE', 'BALANCED', 'DEEP'] as const).map(intel => (
                          <button 
                            key={intel}
