                    </div>
                  ))}
               </div>
            </div>
          )}

          {/* Fallback rendering for standard tabs */}
          {tab === 'PROTOCOLS' && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
               <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {[
                    { title: "Sovereign Architect", detail: "Arjun Bharti Mina: The master mind behind the Anora Core. Absolute authority granted.", icon: "M13 10V3L4 14h7v7l9-11h-7z" },
                    { title: "Tier Forge", detail: "Fabricate custom capability sets for neural identities across the link.", icon: "M11 4a2 2 0 114 0v1a1 1 0 001 1h3a1 1 0 011 1v3a1 1 0 01-1 1h-1a2 2 0 100 4h1a1 1 0 011 1v3a1 1 0 01-1 1h-3a1 1 0 01-1-1v-1a2 2 0 11-4 0v1a1 1 0 01-1 1H7a1 1 0 01-1-1v-3a1 1 0 00-1-1H4a2 2 0 110-4h1a1 1 0 001-1V7a1 1 0 011-1h3a1 1 0 001-1V4z" },
                    { title: "Protocol Evolution", detail: "Manage subscription tiers and elevation requests for all users.", icon: "M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" }
                  ].map((p, i) => (
                    <div key={i} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3.5rem] group hover:border-zinc-700 transition-all">
                      <div className="w-12 h-12 rounded-2xl bg-black/40 border border-white/5 flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                        <svg className="w-6 h-6" style={{ color: accent }} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={p.icon} /></svg>
                      </div>
                      <h4 className="text-xs font-black text-white uppercase tracking-widest mb-3">{p.title}</h4>
                      <p className="text-[10px] text-zinc-500 font-medium leading-relaxed uppercase tracking-wider">{p.detail}</p>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'TIMELINE' && (
            <div className="space-y-8">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                  <div className="flex gap-4">
                     <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Establish objective..." className="flex-1 bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs font-medium text-white outline-none" />
                     <button onClick={addItem} className={`px-8 rounded-2xl font-bold text-xl ${isOwner ? 'bg-amber-500 text-black' : 'bg-white text-black'}`}>+</button>
                  </div>
               </div>
               <div className="space-y-4">
                  {user.reminders.map(r => (
                    <div key={r.id} className={`group p-6 bg-zinc-900/10 border rounded-[2.5rem] flex items-center justify-between transition-all ${r.completed ? 'opacity-30 border-zinc-900' : 'border-white/5'}`}>
                       <div className="flex items-center gap-6">
                          <button onClick={() => toggleReminder(r.id)} className={`w-6 h-6 rounded-full border-2 transition-all ${r.completed ? 'bg-zinc-700 border-zinc-700' : 'border-zinc-800'}`}></button>
                          <div>
                             <p className={`text-sm font-medium ${r.completed ? 'line-through text-zinc-600' : 'text-white'}`}>{r.text}</p>
                          </div>
                       </div>
                       <button onClick={() => removeItem(r.id, 'reminders')} className="text-zinc-800 hover:text-red-500">×</button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'PROJECTS' && (
             <div className="space-y-8">
                <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                   <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="New Project Name..." className="w-full bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs font-medium text-white outline-none" />
                   <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Project details..." className="w-full bg-black/30 border border-zinc-900 rounded-2xl p-6 text-[10px] text-zinc-400 h-24 resize-none outline-none" />
                   <button onClick={addItem} className="w-full py-4 bg-white text-black rounded-2xl font-bold uppercase text-[10px] tracking-widest">Establish</button>
                </div>
                <div className="grid gap-4">
                   {user.projects.map(p => (
                     <div key={p.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3.5rem]">
                        <h4 className="text-sm font-bold text-white uppercase tracking-widest mb-3">{p.name}</h4>
                        <p className="text-[10px] text-zinc-500 leading-relaxed">{p.description}</p>
                        <button onClick={() => removeItem(p.id, 'projects')} className="mt-6 text-[9px] font-bold uppercase text-red-500/50 hover:text-red-500">Purge</button>
                     </div>
                   ))}
                </div>
             </div>
          )}

          {tab === 'VAULT' && isPremium && (
            <div className="space-y-8">
               <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Asset Label..." className="w-full bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs text-white outline-none" />
                  <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Content..." className="w-full bg-black/30 border border-zinc-900 rounded-2xl p-6 text-[10px] text-zinc-400 h-24 resize-none outline-none" />
                  <button onClick={addItem} className="w-full py-4 bg-white text-black rounded-2xl font-bold uppercase text-[10px] tracking-widest">Store</button>
               </div>
               <div className="grid grid-cols-1 gap-4">
                  {user.vault?.map(item => (
                    <div key={item.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3.5rem]">
                       <div className="flex justify-between items-start mb-4">
                          <h4 className="text-xs font-bold text-white uppercase tracking-widest">{item.title}</h4>
                          <button onClick={() => removeItem(item.id, 'vault')} className="text-zinc-800 hover:text-red-500">×</button>
                       </div>
                       <pre className="text-[10px] bg-black/40 p-6 rounded-2xl text-zinc-500 overflow-x-auto border border-white/5">{item.content}</pre>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'CREATIVE' && isPremium && (
             <div className="space-y-8">
                <div className="bg-zinc-900/20 border border-white/5 p-8 rounded-[3rem] space-y-6">
                   <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Song Title..." className="w-full bg-black/50 border border-zinc-900 rounded-2xl px-6 py-4 text-xs font-medium text-white outline-none" />
                   <button onClick={addItem} className="w-full py-4 bg-amber-500 text-black rounded-2xl font-bold uppercase text-[10px] tracking-widest">Begin Draft</button>
                </div>
                <div className="grid gap-4">
                   {user.lyrics?.map(l => (
                     <div key={l.id} className="p-8 bg-zinc-900/10 border border-white/5 rounded-[3.5rem]">
                        <h4 className="text-sm font-bold text-white uppercase tracking-widest mb-3">{l.title}</h4>
                        <button onClick={() => removeItem(l.id, 'lyrics')} className="mt-6 text-[9px] font-bold uppercase text-red-500/50 hover:text-red-500">Delete</button>
                     </div>
                   ))}
                </div>
             </div>
          )}

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, CustomTier, Reminder, SiteLog, LyricDraft, VaultItem, TierCapability, UpgradeRequest } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

const DEFAULT_CAPS: TierCapability = {
  googleSearch: false,
  googleMaps: false,
  imageSynthesis: false,
  videoSynthesis: false,
  maxIntelligence: 'BALANCED',
  advancedReasoning: false,
  reasoningBudget: 0
};

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'TIMELINE' | 'VAULT' | 'USERS' | 'HISTORY' | 'TIER_FORGE' | 'NEURAL_MEMORY' | 'PROTOCOLS' | 'UPGRADE'>('PROTOCOLS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [priority, setPriority] = useState<Reminder['priority']>('MEDIUM');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [customTiers, setCustomTiers] = useState<CustomTier[]>([]);
  const [upgradeRequests, setUpgradeRequests] = useState<UpgradeRequest[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const [forgeName, setForgeName] = useState('');
  const [forgeCaps, setForgeCaps] = useState<TierCapability>(DEFAULT_CAPS);

  const [requestedTier, setRequestedTier] = useState<SubscriptionTier>(SubscriptionTier.PRO);
  const [upgradeMessage, setUpgradeMessage] = useState('');
  const [isRequesting, setIsRequesting] = useState(false);

  const refreshData = () => {
    const usersData = localStorage.getItem('anora_users_db');
    if (usersData) setAllUsers(JSON.parse(usersData));
    const tiersData = localStorage.getItem('anora_custom_tiers');
    if (tiersData) setCustomTiers(JSON.parse(tiersData));
    const reqData = localStorage.getItem('anora_upgrade_requests');
    if (reqData) setUpgradeRequests(JSON.parse(reqData));
  };

  useEffect(() => {
    if (isOpen) {
      refreshData();
    }
  }, [isOpen]);

  useEffect(() => {
    const handleDbUpdate = () => {
      if (isOpen) refreshData();
    };

    window.addEventListener('anora_database_updated', handleDbUpdate);
    window.addEventListener('storage', (e) => {
      if (['anora_users_db', 'anora_upgrade_requests', 'anora_custom_tiers'].includes(e.key || '') && isOpen) refreshData();
    });

    return () => {
      window.removeEventListener('anora_database_updated', handleDbUpdate);
    };
  }, [isOpen]);

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.tier === SubscriptionTier.PRO || user.tier === SubscriptionTier.LIFETIME;
  const accent = user.preferences.accentColor || '#d4af37';

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, priority, completed: false, dueDate: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'Pop', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'VAULT') {
      if (!updated.vault) updated.vault = [];
      updated.vault.push({ id: Date.now().toString(), title: newItem, content: newDesc, type: 'TEXT' });
    }

    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (list === 'vault') updated.vault = (updated.vault || []).filter(i => i.id !== id);
    if (list === 'memory') updated.memory = (updated.memory || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const updateUserTier = (targetUser: User, tier: SubscriptionTier, customId?: string) => {
    const usersData = localStorage.getItem('anora_users_db');
    const db: User[] = usersData ? JSON.parse(usersData) : [];

    const updatedUsers = db.map(u => {
      if (u.id === targetUser.id) {
        const updated = { ...u, tier, customTierId: customId };
        if (targetUser.id === user.id) {
          onUpdate(updated);
        }
        return updated;
      }
      return u;
    });
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
    setAllUsers(updatedUsers);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const handleRequestUpgrade = () => {
    setIsRequesting(true);
    const newReq: UpgradeRequest = {
      id: `req_${Date.now()}`,
      userId: user.id,
      userName: user.name,
      userEmail: user.email,
      requestedTier,
      message: upgradeMessage,
      timestamp: new Date().toISOString(),
      status: 'PENDING'
    };

    const updated = [...upgradeRequests, newReq];
    localStorage.setItem('anora_upgrade_requests', JSON.stringify(updated));
    setUpgradeRequests(updated);
    window.dispatchEvent(new Event('anora_database_updated'));

    setTimeout(() => {
      setIsRequesting(false);
      setUpgradeMessage('');
      alert("Elevation request submitted to Sovereign Terminal.");
    }, 1000);
  };

  const resolveUpgradeRequest = (requestId: string, approve: boolean) => {
    const req = upgradeRequests.find(r => r.id === requestId);
    if (!req) return;

    if (approve) {
      const target = allUsers.find(u => u.id === req.userId);
      if (target) {
        updateUserTier(target, req.requestedTier);
      }
    }

    const updated = upgradeRequests.filter(r => r.id !== requestId);
    localStorage.setItem('anora_upgrade_requests', JSON.stringify(updated));
    setUpgradeRequests(updated);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const handleCreateForgeTier = () => {
    if (!forgeName.trim()) return;
    const newTier: CustomTier = {
      id: `forge_${Date.now()}`,
      name: forgeName,
      capabilities: { ...forgeCaps }
    };
    const updatedTiers = [...customTiers, newTier];
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updatedTiers));
    setCustomTiers(updatedTiers);
    setForgeName('');
    setForgeCaps(DEFAULT_CAPS);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const deleteForgeTier = (id: string) => {
    const updated = customTiers.filter(t => t.id !== id);
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updated));
    setCustomTiers(updated);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const toggleReminder = (id: string) => {
    const updated = { ...user };
    updated.reminders = updated.reminders.map(r => r.id === id ? { ...r, completed: !r.completed } : r);
    onUpdate(updated);
  };

  const userTabs = ['PROTOCOLS', 'TIMELINE', 'NEURAL_MEMORY', 'PROJECTS', 'VAULT', 'CREATIVE', 'UPGRADE', 'HISTORY'] as const;
  const ownerTabs = ['PROTOCOLS', 'TIMELINE', 'NEURAL_MEMORY', 'PROJECTS', 'VAULT', 'CREATIVE', 'ENGINEERING', 'USERS', 'TIER_FORGE', 'HISTORY'] as const;
  const activeTabs = isOwner ? ownerTabs : userTabs;

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/95 backdrop-blur-3xl animate-in fade-in slide-in-from-right duration-500">
      <div className={`w-full max-w-2xl h-[94dvh] bg-[#050505] border-t sm:border-l flex flex-col shadow-2xl overflow-hidden rounded-t-[4rem] sm:rounded-none transition-all ${isOwner ? 'border-amber-500/10' : 'border-white/5'}`}>

        <div className="px-10 py-10 border-b border-white/5 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center border border-white/10">
               <svg className="w-6 h-6" style={{ color: accent }} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
               </svg>
             </div>
             <div>
                <h2 className={`text-2xl font-bold font-outfit ${isOwner ? 'text-amber-500' : 'text-white'}`}>Neural Hub</h2>
                <p className={`text-[10px] uppercase tracking-[0.4em] font-bold mt-1 ${isOwner ? 'text-amber-500/40' : 'text-zinc-600'}`}>
                  {isOwner ? 'Sovereign Core' : isPremium ? 'Premium Access' : 'Neural Link v1.0'}
                </p>
             </div>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-600 hover:text-white transition-all bg-white/5 rounded-3xl group">
            <svg className="w-6 h-6 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-black/40 p-1.5 mx-8 mt-6 rounded-2xl border border-white/5 overflow-x-auto no-scrollbar gap-1 shrink-0">
          {activeTabs.map(t => (
