import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, AiMood, IntelligenceLevel, AppTheme, AppFont, Persona, CustomMood } from '../types';
import { ACCENT_COLORS, AI_MOODS, THEMES, LANGUAGES, PREBUILT_VOICES, PERSONA_INSTRUCTIONS } from '../constants';
import { anoraService } from '../services/geminiService';

interface ProfileModalProps {
  user: User;
  isOpen: boolean;
  onClose: () => void;
  onUpdate: (updatedUser: User) => void;
  onLogout: () => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ user, isOpen, onClose, onUpdate, onLogout }) => {
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || '');
  const [avatar, setAvatar] = useState(user.avatar || '');
  const [mood, setMood] = useState<AiMood>(user.preferences.aiMood);
  const [accent, setAccent] = useState(user.preferences.accentColor);
  const [intel, setIntel] = useState<IntelligenceLevel>(user.preferences.intelligenceLevel || 'BALANCED');
  const [lang, setLang] = useState(user.preferences.language || 'English');
  const [theme, setTheme] = useState<AppTheme>(user.preferences.theme || 'OBSIDIAN');
  const [font, setFont] = useState<AppFont>(user.preferences.font || 'INTER');
  const [sound, setSound] = useState(user.preferences.soundEnabled ?? true);
  const [autoRead, setAutoRead] = useState(user.preferences.autoRead ?? false);
  const [voiceName, setVoiceName] = useState(user.preferences.voiceName || 'Kore');
  const [persona, setPersona] = useState<Persona>(user.preferences.persona || 'DEFAULT');

  const [avatarPrompt, setAvatarPrompt] = useState('');
  const [generatingAvatar, setGeneratingAvatar] = useState(false);
  const [testingVoice, setTestingVoice] = useState<string | null>(null);
  const [showToast, setShowToast] = useState(false);

  useEffect(() => {
    setName(user.name);
    setBio(user.bio || '');
    setAvatar(user.avatar || '');
    setMood(user.preferences.aiMood);
    setAccent(user.preferences.accentColor);
    setIntel(user.preferences.intelligenceLevel || 'BALANCED');
    setLang(user.preferences.language || 'English');
    setTheme(user.preferences.theme || 'OBSIDIAN');
    setFont(user.preferences.font || 'INTER');
    setSound(user.preferences.soundEnabled ?? true);
    setAutoRead(user.preferences.autoRead ?? false);
    setVoiceName(user.preferences.voiceName || 'Kore');
    setPersona(user.preferences.persona || 'DEFAULT');
  }, [user, isOpen]);

  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(false), 2500);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPro = user.tier === SubscriptionTier.PRO || user.tier === SubscriptionTier.LIFETIME || isOwner;

  const handleSave = () => {
    onUpdate({
      ...user,
      name, bio, avatar,
      preferences: {
        ...user.preferences,
        aiMood: mood,
        accentColor: accent,
        intelligenceLevel: intel,
        language: lang,
        theme, font,
        soundEnabled: sound,
        autoRead, voiceName, persona
      }
    });
    setShowToast(true);
    setTimeout(onClose, 1200);
  };

  const handleGenerateAvatar = async () => {
    if (!avatarPrompt.trim()) return;
    setGeneratingAvatar(true);
    try {
      const bytes = await anoraService.generateImage(`Futuristic high-fidelity avatar profile, abstract digital art style: ${avatarPrompt}`);
      setAvatar(`data:image/png;base64,${bytes}`);
      setAvatarPrompt('');
    } catch (err: any) {
      alert(`Neural Synthesis Interrupted: ${err.message}`);
    } finally {
      setGeneratingAvatar(false);
    }
  };

  const testVoice = async (vName: string) => {
    if (testingVoice) return;
    setTestingVoice(vName);
    try {
      const base64 = await anoraService.speak(`Hi, I am Anora, how can I help you`, vName);
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const binaryString = atob(base64);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = audioCtx.createBuffer(1, dataInt16.length, 24000);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.destination);
      source.onended = () => setTestingVoice(null);
      source.start();
    } catch (err) {
      console.error(err);
      setTestingVoice(null);
    }
  };

  const getTierLabel = () => {
    if (user.role === Role.OWNER) return 'Sovereign Protocol';
    if (user.tier === SubscriptionTier.LIFETIME) return 'Infinite Access (Lifetime)';
