                  {!isLogin && (
                    <div className="animate-in fade-in slide-in-from-top-1 duration-900">
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Verify Encryption Key</label>
                      <input
                        type="password" required value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)}
                        className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none focus:ring-1 focus:ring-black/10 transition-all text-sm placeholder:text-zinc-300"
                        placeholder="••••••••"
                      />
                    </div>
                  )}
                </div>

                {isLogin && (
                  <div className="flex justify-end px-2">
                    <button type="button" onClick={() => setPhase(3)} className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest hover:text-zinc-600 transition-colors">
                      Forgot Access Key?
                    </button>
                  </div>
                )}

                <button
                  type="submit" disabled={loading}
