              </form>
            </>
          ) : (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
              <h3 className="text-zinc-900 text-center text-sm font-bold uppercase tracking-[0.3em] mb-8">Neural Key Recovery</h3>

              {recoverySuccess ? (
                <div className="text-center space-y-4 py-8 animate-in zoom-in duration-500">
                   <div className="w-16 h-16 bg-green-500/10 border border-green-500/20 rounded-full mx-auto flex items-center justify-center">
                     <svg className="w-8 h-8 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
