                        className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none focus:ring-1 focus:ring-black/10 transition-all text-sm"
                        placeholder="Verify email associated with link..."
                      />
                    </div>
                    <div>
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">New Access Key</label>
                      <input
                        type="password" required value={password} onChange={(e) => setPassword(e.target.value)}
                        className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none focus:ring-1 focus:ring-black/10 transition-all text-sm"
                        placeholder="Define new encryption sequence..."
                      />
