                  </div>
                  <div className="pt-4 flex flex-col gap-4">
                    <button type="submit" disabled={loading} className="w-full bg-zinc-900 text-white font-bold py-5 rounded-[2rem] uppercase text-[9px] tracking-widest hover:bg-black transition-all">
                      {loading ? "Validating Neural ID..." : "Reset Encryption Key"}
