                    <button type="button" onClick={() => setPhase(1)} className="w-full text-zinc-400 font-bold uppercase text-[9px] tracking-widest hover:text-zinc-600 transition-colors">
                      Return to Sync
                    </button>
                  </div>
                </form>
              )}
