          )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Message, Role, SubscriptionTier } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
  userTier: SubscriptionTier;
  onVocalize?: (id: string, content: string) => void;
  onEditMessage?: (id: string, newContent: string) => void;
  speakingId?: string | null;
}

export const MessageList: React.FC<MessageListProps> = ({ 
  messages, 
  isThinking, 
  ownerName, 
  isOwnerView,
  userTier,
  onVocalize,
  onEditMessage,
  speakingId
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  const handleStartEdit = (msg: Message) => {
    setEditingId(msg.id);
    setEditValue(msg.content);
  };

  const handleSaveEdit = () => {
    if (editingId && onEditMessage) {
      onEditMessage(editingId, editValue);
    }
    setEditingId(null);
  };

  const isPro = userTier === SubscriptionTier.PRO || isOwnerView;

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-8 pt-10 pb-20 space-y-10 max-w-5xl mx-auto w-full scroll-smooth no-scrollbar relative z-10">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isAnora = msg.role === 'anora';
        const isSynthesis = !isUser && msg.images && msg.images.length > 0;
        const isSpeaking = speakingId === msg.id;
        const isEditing = editingId === msg.id;

        let bubbleClass = "";
        if (isUser) {
          if (isOwnerView) {
            bubbleClass = "bg-zinc-900 border-amber-500/50 text-white shadow-xl rounded-tr-none";
          } else if (isPro) {
            bubbleClass = "bg-indigo-600 border-indigo-500 text-white rounded-tr-none";
          } else {
            bubbleClass = "bg-zinc-800 text-white border-zinc-700 rounded-tr-none";
          }
        } else {
          if (isOwnerView) {
            bubbleClass = "bg-zinc-50 border-amber-500/10 text-zinc-900 rounded-tl-none backdrop-blur-3xl shadow-sm";
          } else {
            bubbleClass = "bg-zinc-100/50 text-zinc-800 border-zinc-200/50 rounded-tl-none backdrop-blur-3xl";
          }
        }

        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-1000 fill-mode-both ease-out`}
            style={{ animationDelay: `${index * 30}ms` }}
          >
            <div className={`max-w-[92%] sm:max-w-[85%] group relative`}>
              <div className={`flex items-center gap-3 mb-2 px-2 transition-all duration-500 opacity-60 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[9px] font-bold uppercase tracking-[0.2em] ${isUser ? (isOwnerView ? 'text-amber-600' : isPro ? 'text-indigo-600' : 'text-zinc-600') : 'text-zinc-400'}`}>
                  {isUser ? (isOwnerView ? 'Sovereign' : isPro ? 'Neural Pro' : ownerName.split(' ')[0]) : (isSynthesis ? 'Synthesis' : 'Anora')}
                </span>
                <div className="w-0.5 h-0.5 rounded-full bg-zinc-200"></div>
                <span className="text-[8px] text-zinc-300 font-bold uppercase tracking-widest">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>

              {msg.images && msg.images.length > 0 && !isEditing && (
                <div className={`grid gap-2 mb-3 animate-in zoom-in-95 duration-700 ${msg.images.length === 4 ? 'grid-cols-2' : (msg.images.length > 1 ? 'flex flex-wrap' : 'flex')} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[1.8rem] sm:rounded-[2.5rem] border shadow-md transition-all hover:border-zinc-400
                      ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-200'} 
                      ${msg.images && msg.images.length === 1 ? 'w-64 h-64 sm:w-80 sm:h-80' : 'w-full aspect-square'}`}>
                      <img src={img} alt="V" className="w-full h-full object-cover transition-transform duration-[2s] group-hover/img:scale-110" />
                    </div>
                  ))}
                </div>
              )}

              <div className={`rounded-[2rem] sm:rounded-[3rem] px-6 sm:px-10 py-5 sm:py-8 text-sm sm:text-base leading-relaxed shadow-sm transition-all duration-700 relative ring-1 ring-black/5 ${bubbleClass}`}>
                {isUser && isOwnerView && <div className="absolute -top-1 -right-1 w-3 h-3 bg-amber-500 rounded-full border-2 border-white shadow-md"></div>}

                {isEditing ? (
                  <div className="space-y-4 py-2 animate-in fade-in duration-300">
                    <textarea 
                      value={editValue}
                      onChange={(e) => setEditValue(e.target.value)}
                      className="w-full bg-white/40 border border-zinc-200 rounded-2xl p-4 text-sm sm:text-base text-zinc-900 outline-none focus:border-zinc-400 transition-all resize-none min-h-[100px]"
                      autoFocus
                    />
                    <div className="flex gap-2 justify-end">
                      <button onClick={() => setEditingId(null)} className="px-4 py-2 text-[10px] font-bold uppercase tracking-widest text-zinc-400 hover:text-zinc-900 transition-colors">Abort</button>
                      <button onClick={handleSaveEdit} className={`px-6 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest active:scale-95 transition-all ${isOwnerView ? 'bg-amber-500 text-black' : 'bg-zinc-900 text-white'}`}>Synchronize</button>
                    </div>
                  </div>
                ) : (
                  <div className="prose prose-zinc max-w-none whitespace-pre-wrap font-medium tracking-tight">
                    {msg.content}
                  </div>
                )}

                {isAnora && onVocalize && !isEditing && (
                  <div className="absolute top-4 -right-12 flex flex-col gap-2 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-all duration-300 translate-x-4 sm:translate-x-4 sm:group-hover:translate-x-0">
                    <button 
                      onClick={() => onVocalize(msg.id, msg.content)}
                      className={`p-3 rounded-2xl border transition-all hover:scale-110 active:scale-90 shadow-md ${isSpeaking ? (isOwnerView ? 'text-amber-500 border-amber-500/50' : 'text-indigo-600 border-indigo-500/50') : 'text-zinc-400 border-zinc-100 bg-white hover:text-zinc-900'}`}
                    >
                      <svg className={`w-5 h-5 ${isSpeaking ? 'animate-pulse' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                      </svg>
                    </button>
                  </div>
                )}

                {msg.sources && msg.sources.length > 0 && !isEditing && (
                  <div className="mt-8 pt-8 border-t border-zinc-100 animate-in fade-in duration-1000">
                    <p className="text-[8px] font-bold text-zinc-300 uppercase tracking-[0.4em] mb-4">VERIFIED INTEL</p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((source, idx) => (
                        <a
                          key={idx}
                          href={source.uri}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center gap-3 px-4 py-3 bg-white border border-zinc-200 rounded-2xl text-[9px] text-zinc-400 hover:text-zinc-900 hover:border-zinc-300 transition-all group/source shadow-sm"
                        >
                          <span className="max-w-[150px] truncate font-bold tracking-wider">{source.title || 'Intel'}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}

      {isThinking && (
        <div className="flex justify-start animate-in fade-in slide-in-from-left-2 duration-700">
          <div className={`bg-white border rounded-[1.8rem] rounded-tl-none px-6 py-4 shadow-sm ring-1 ring-black/5 ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-100'}`}>
            <div className="flex gap-1.5">
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.3s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div>
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.15s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div>
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div>
            </div>
          </div>
        </div>
      )}
      <div ref={bottomRef} className="h-10" />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, CustomTier, Reminder, SiteLog, LyricDraft, VaultItem, TierCapability, UpgradeRequest } from '../types';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

const DEFAULT_CAPS: TierCapability = {
  googleSearch: false,
  googleMaps: false,
  imageSynthesis: false,
  videoSynthesis: false,
  maxIntelligence: 'BALANCED',
  advancedReasoning: false,
  reasoningBudget: 0
};

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROJECTS' | 'CREATIVE' | 'TIMELINE' | 'VAULT' | 'USERS' | 'HISTORY' | 'TIER_FORGE' | 'NEURAL_MEMORY' | 'PROTOCOLS' | 'UPGRADE'>('PROTOCOLS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [priority, setPriority] = useState<Reminder['priority']>('MEDIUM');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [customTiers, setCustomTiers] = useState<CustomTier[]>([]);
  const [upgradeRequests, setUpgradeRequests] = useState<UpgradeRequest[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const [forgeName, setForgeName] = useState('');
  const [forgeCaps, setForgeCaps] = useState<TierCapability>(DEFAULT_CAPS);

  const [requestedTier, setRequestedTier] = useState<SubscriptionTier>(SubscriptionTier.PRO);
  const [upgradeMessage, setUpgradeMessage] = useState('');
  const [isRequesting, setIsRequesting] = useState(false);

  const refreshData = () => {
    const usersData = localStorage.getItem('anora_users_db');
    if (usersData) setAllUsers(JSON.parse(usersData));
    const tiersData = localStorage.getItem('anora_custom_tiers');
    if (tiersData) setCustomTiers(JSON.parse(tiersData));
    const reqData = localStorage.getItem('anora_upgrade_requests');
    if (reqData) setUpgradeRequests(JSON.parse(reqData));
  };

  useEffect(() => {
    if (isOpen) {
      refreshData();
    }
  }, [isOpen]);

  useEffect(() => {
    const handleDbUpdate = () => {
      if (isOpen) refreshData();
    };

    window.addEventListener('anora_database_updated', handleDbUpdate);
    window.addEventListener('storage', (e) => {
      if (['anora_users_db', 'anora_upgrade_requests', 'anora_custom_tiers'].includes(e.key || '') && isOpen) refreshData();
    });

    return () => {
      window.removeEventListener('anora_database_updated', handleDbUpdate);
    };
  }, [isOpen]);

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const isPremium = isOwner || user.tier === SubscriptionTier.PRO || user.tier === SubscriptionTier.LIFETIME;
  const accent = user.preferences.accentColor || '#d4af37';

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, priority, completed: false, dueDate: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'CREATIVE') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: newDesc || 'Pop', content: '', timestamp: new Date().toISOString() });
    } else if (tab === 'VAULT') {
      if (!updated.vault) updated.vault = [];
      updated.vault.push({ id: Date.now().toString(), title: newItem, content: newDesc, type: 'TEXT' });
    }

    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (list === 'vault') updated.vault = (updated.vault || []).filter(i => i.id !== id);
    if (list === 'memory') updated.memory = (updated.memory || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const updateUserTier = (targetUser: User, tier: SubscriptionTier, customId?: string) => {
    const usersData = localStorage.getItem('anora_users_db');
    const db: User[] = usersData ? JSON.parse(usersData) : [];

    const updatedUsers = db.map(u => {
      if (u.id === targetUser.id) {
        const updated = { ...u, tier, customTierId: customId };
        if (targetUser.id === user.id) {
          onUpdate(updated);
        }
        return updated;
      }
      return u;
    });
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
    setAllUsers(updatedUsers);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const handleRequestUpgrade = () => {
    setIsRequesting(true);
    const newReq: UpgradeRequest = {
      id: `req_${Date.now()}`,
      userId: user.id,
      userName: user.name,
      userEmail: user.email,
      requestedTier,
      message: upgradeMessage,
      timestamp: new Date().toISOString(),
      status: 'PENDING'
    };

    const updated = [...upgradeRequests, newReq];
    localStorage.setItem('anora_upgrade_requests', JSON.stringify(updated));
    setUpgradeRequests(updated);
    window.dispatchEvent(new Event('anora_database_updated'));

    setTimeout(() => {
      setIsRequesting(false);
      setUpgradeMessage('');
      alert("Elevation request submitted to Sovereign Terminal.");
    }, 1000);
  };

  const resolveUpgradeRequest = (requestId: string, approve: boolean) => {
    const req = upgradeRequests.find(r => r.id === requestId);
    if (!req) return;

    if (approve) {
      const target = allUsers.find(u => u.id === req.userId);
      if (target) {
        updateUserTier(target, req.requestedTier);
      }
    }

    const updated = upgradeRequests.filter(r => r.id !== requestId);
    localStorage.setItem('anora_upgrade_requests', JSON.stringify(updated));
    setUpgradeRequests(updated);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const handleCreateForgeTier = () => {
    if (!forgeName.trim()) return;
    const newTier: CustomTier = {
      id: `forge_${Date.now()}`,
      name: forgeName,
      capabilities: { ...forgeCaps }
    };
    const updatedTiers = [...customTiers, newTier];
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updatedTiers));
    setCustomTiers(updatedTiers);
    setForgeName('');
    setForgeCaps(DEFAULT_CAPS);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const deleteForgeTier = (id: string) => {
    const updated = customTiers.filter(t => t.id !== id);
    localStorage.setItem('anora_custom_tiers', JSON.stringify(updated));
    setCustomTiers(updated);
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const toggleReminder = (id: string) => {
    const updated = { ...user };
    updated.reminders = updated.reminders.map(r => r.id === id ? { ...r, completed: !r.completed } : r);
    onUpdate(updated);
  };

  const userTabs = ['PROTOCOLS', 'TIMELINE', 'NEURAL_MEMORY', 'PROJECTS', 'VAULT', 'CREATIVE', 'UPGRADE', 'HISTORY'] as const;
  const ownerTabs = ['PROTOCOLS', 'TIMELINE', 'NEURAL_MEMORY', 'PROJECTS', 'VAULT', 'CREATIVE', 'ENGINEERING', 'USERS', 'TIER_FORGE', 'HISTORY'] as const;
  const activeTabs = isOwner ? ownerTabs : userTabs;

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/10 backdrop-blur-3xl animate-in fade-in slide-in-from-right duration-500">
      <div className={`w-full max-w-2xl h-[94dvh] bg-white border-t sm:border-l flex flex-col shadow-2xl overflow-hidden rounded-t-[4rem] sm:rounded-none transition-all ${isOwner ? 'border-amber-500/10' : 'border-zinc-100'}`}>

        <div className="px-10 py-10 border-b border-zinc-100 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 rounded-xl bg-zinc-50 flex items-center justify-center border border-zinc-100">
               <svg className="w-6 h-6" style={{ color: accent }} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
               </svg>
             </div>
             <div>
                <h2 className={`text-2xl font-bold font-outfit ${isOwner ? 'text-amber-600' : 'text-zinc-900'}`}>Neural Hub</h2>
                <p className={`text-[10px] uppercase tracking-[0.4em] font-bold mt-1 ${isOwner ? 'text-amber-600/40' : 'text-zinc-400'}`}>
                  {isOwner ? 'Sovereign Core' : isPremium ? 'Premium Access' : 'Neural Link v1.0'}
                </p>
             </div>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-400 hover:text-zinc-900 transition-all bg-zinc-100 rounded-3xl group">
            <svg className="w-6 h-6 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-zinc-50 p-1.5 mx-8 mt-6 rounded-2xl border border-zinc-100 overflow-x-auto no-scrollbar gap-1 shrink-0">
          {activeTabs.map(t => (
            <button key={t} onClick={() => setTab(t as any)} className={`flex-1 min-w-[100px] py-3 text-[9px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all relative ${tab === t ? 'bg-zinc-900 text-white shadow-xl' : 'text-zinc-400 hover:text-zinc-600'}`}>
              {t.replace('_', ' ')}
