import React, { useState, useEffect } from 'react';
import { Role, User, ImageAspectRatio } from '../types';
import { anoraService } from '../services/geminiService';

interface CommandCenterProps {
  user: User;
  isOpen: boolean;
  onClose: () => void;
}

const VIDEO_STATUS_MESSAGES = [
  "Initializing quantum render buffers...",
  "Seeding neural motion vectors...",
  "Synthesizing temporal frames...",
  "Compiling high-fidelity physics...",
  "Optimizing cinematic sovereign lighting...",
  "Finalizing high-bandwidth video asset...",
  "Stabilizing neural bridge for delivery...",
];

export const CommandCenter: React.FC<CommandCenterProps> = ({ user, isOpen, onClose }) => {
  const [prompt, setPrompt] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState<'IMAGE' | 'VIDEO'>('IMAGE');
  const [aspectRatio, setAspectRatio] = useState<ImageAspectRatio>('1:1');
  const [statusIdx, setStatusIdx] = useState(0);
  const [hasApiKey, setHasApiKey] = useState(false);

  useEffect(() => {
    if (isOpen) {
      checkApiKey();
    }
  }, [isOpen, mode]);

  useEffect(() => {
    let interval: any;
    if (loading && mode === 'VIDEO') {
      interval = setInterval(() => {
        setStatusIdx(prev => (prev + 1) % VIDEO_STATUS_MESSAGES.length);
      }, 12000);
    } else {
      setStatusIdx(0);
    }
    return () => clearInterval(interval);
  }, [loading, mode]);

  const checkApiKey = async () => {
    if (mode === 'VIDEO') {
      const selected = await (window as any).aistudio.hasSelectedApiKey();
      setHasApiKey(selected);
    } else {
      setHasApiKey(true);
    }
  };

  const handleOpenKeyDialog = async () => {
    await (window as any).aistudio.openSelectKey();
    checkApiKey();
  };

  if (!isOpen) return null;

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setLoading(true);
    setResult(null);

    try {
      if (mode === 'IMAGE') {
        const base64 = await anoraService.generateImage(prompt, aspectRatio);
        setResult(`data:image/png;base64,${base64}`);
      } else {
        const videoUrl = await anoraService.generateVideo(prompt, aspectRatio as '16:9' | '9:16');
        setResult(videoUrl);
      }
    } catch (err: any) {
      if (err.message?.includes("Requested entity was not found")) {
        setHasApiKey(false);
        alert("Neural Key mismatch. Please re-authenticate your API key.");
      } else {
        alert(err.message || "Synthesis disrupted by unknown anomaly.");
      }
    } finally {
      setLoading(false);
    }
  };

  const isOwner = user.role === Role.OWNER;

  return (
    <div className="fixed inset-0 z-[250] flex items-center justify-center p-0 sm:p-8 lg:p-12 xl:p-24 bg-white/95 backdrop-blur-3xl animate-in fade-in zoom-in-95 duration-500">
      <div className="w-full max-w-6xl bg-white border border-zinc-200 rounded-none sm:rounded-[4rem] lg:rounded-[5rem] shadow-2xl overflow-hidden flex flex-col h-full sm:h-auto sm:max-h-[92vh] transition-all">

        <div className="shrink-0 p-8 sm:p-12 border-b border-zinc-100 flex items-center justify-between">
          <div>
            <h2 className={`text-2xl sm:text-3xl font-bold font-outfit ${isOwner ? 'text-amber-600' : 'text-zinc-900'}`}>Visual Synthesis</h2>
            <p className="text-[10px] sm:text-xs text-zinc-400 uppercase tracking-[0.4em] font-bold mt-2">Unrestricted Sovereign Core</p>
          </div>
          <button onClick={onClose} className="p-5 text-zinc-400 hover:text-zinc-900 transition-all bg-zinc-50 rounded-3xl group active:scale-90 shadow-sm border border-zinc-100">
            <svg className="w-8 h-8 group-hover:rotate-90 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex bg-zinc-100/50 p-2 mx-8 sm:mx-12 mt-8 rounded-3xl border border-zinc-200">
          <button onClick={() => { setMode('IMAGE'); setAspectRatio('1:1'); setResult(null); }} className={`flex-1 py-4 sm:py-5 text-[10px] sm:text-xs font-bold uppercase tracking-[0.3em] rounded-2xl transition-all ${mode === 'IMAGE' ? 'bg-white text-zinc-900 shadow-sm' : 'text-zinc-400'}`}>Image Engine</button>
          {isOwner && <button onClick={() => { setMode('VIDEO'); setAspectRatio('16:9'); setResult(null); }} className={`flex-1 py-4 sm:py-5 text-[10px] sm:text-xs font-bold uppercase tracking-[0.3em] rounded-2xl transition-all ${mode === 'VIDEO' ? (loading ? 'bg-amber-50 text-amber-600' : 'bg-amber-500 text-white shadow-sm') : 'text-zinc-400'}`}>Sovereign Video</button>}
        </div>

        <div className="px-8 sm:mx-12 mt-6 flex flex-col gap-4">
           <label className="text-[10px] font-bold text-zinc-300 uppercase tracking-[0.4em] ml-2">Temporal Format (Aspect Ratio)</label>
           <div className="flex flex-wrap gap-2">
              {(mode === 'IMAGE' ? (['1:1', '4:3', '3:4', '16:9', '9:16'] as ImageAspectRatio[]) : (['16:9', '9:16'] as ImageAspectRatio[])).map(ratio => (
                <button 
                  key={ratio} 
                  onClick={() => setAspectRatio(ratio)}
                  className={`px-6 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all border ${aspectRatio === ratio ? (isOwner ? 'bg-amber-500 text-white border-amber-500 shadow-sm' : 'bg-zinc-900 text-white border-zinc-900') : 'bg-white text-zinc-400 border-zinc-100 hover:border-zinc-300'}`}
                >
                  {ratio}
                </button>
              ))}
           </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8 sm:p-12 space-y-12 no-scrollbar scroll-smooth">
           {mode === 'VIDEO' && !hasApiKey ? (
             <div className="py-20 flex flex-col items-center text-center space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="w-20 h-20 rounded-full bg-amber-50 border border-amber-100 flex items-center justify-center text-amber-500 shadow-sm">
