          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          userTier={currentUser.tier}
          onVocalize={(id, text) => {
            const msg = messages.find(m => m.id === id);
            handleVocalize(id, text, msg?.affect || 'SOVEREIGN');
          }}
          onEditMessage={(id, content) => {
             const index = messages.findIndex(m => m.id === id);
             if (index !== -1) {
                const truncated = [...messages.slice(0, index)];
                const editedMsg = { ...messages[index], content, timestamp: new Date() };
                const newHistory = [...truncated, editedMsg];
                setMessages(newHistory);
                generateAnoraResponse(newHistory, detectIntent(content));
             }
          }}
          speakingId={speakingId}
        />
        <NeuralOrb active={isThinking} intent={activeIntent} affect={activeAffect} speaking={speakingId !== null} listening={isWakeWordActive && !isVoiceMode} color={accent} />
      </main>

      <footer className="px-6 sm:px-12 pb-[calc(var(--sab)+1.5rem)] pt-4 bg-white/95 backdrop-blur-md border-t border-zinc-100 z-[100] shrink-0">
        <div className="max-w-4xl mx-auto flex items-center gap-4">
          {isPro && (
