import React, { useEffect, useRef, useState } from 'react';
import { Message, Role, SubscriptionTier } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
  userTier: SubscriptionTier;
  onVocalize?: (id: string, content: string) => void;
  onEditMessage?: (id: string, newContent: string) => void;
  onDeleteMessage?: (id: string) => void;
  onSaveToMemory?: (content: string) => void;
  onSaveToReminders?: (content: string) => void;
  speakingId?: string | null;
}

export const MessageList: React.FC<MessageListProps> = ({ 
  messages, 
  isThinking, 
  ownerName, 
  isOwnerView,
  userTier,
  onVocalize,
  onEditMessage,
  onDeleteMessage,
  onSaveToMemory,
  onSaveToReminders,
  speakingId
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');
  const [contextMenuId, setContextMenuId] = useState<string | null>(null);
  const longPressTimer = useRef<any>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  const handleStartEdit = (msg: Message) => {
    setEditingId(msg.id);
    setEditValue(msg.content);
    setContextMenuId(null);
  };

  const handleSaveEdit = () => {
    if (editingId && onEditMessage) {
      onEditMessage(editingId, editValue);
    }
    setEditingId(null);
  };

  const handleTouchStart = (msgId: string) => {
    longPressTimer.current = setTimeout(() => {
      setContextMenuId(msgId);
      if (window.navigator.vibrate) window.navigator.vibrate(50);
    }, 600);
  };

  const handleTouchEnd = () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
  };

  const isPro = userTier === SubscriptionTier.PRO || isOwnerView;

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-8 pt-10 pb-20 space-y-10 max-w-5xl mx-auto w-full scroll-smooth no-scrollbar relative z-10">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isAnora = msg.role === 'anora';
        const isSynthesis = !isUser && msg.images && msg.images.length > 0;
        const isSpeaking = speakingId === msg.id;
        const isEditing = editingId === msg.id;
        const isMenuOpen = contextMenuId === msg.id;

        let bubbleClass = "";
        if (isUser) {
          if (isOwnerView) {
            bubbleClass = "bg-zinc-900 border-amber-500/50 text-white shadow-xl rounded-tr-none";
          } else if (isPro) {
            bubbleClass = "bg-indigo-600 border-indigo-500 text-white rounded-tr-none";
          } else {
            bubbleClass = "bg-zinc-800 text-white border-zinc-700 rounded-tr-none";
          }
        } else {
          if (isOwnerView) {
            bubbleClass = "bg-zinc-50 border-amber-500/10 text-zinc-900 rounded-tl-none backdrop-blur-3xl shadow-sm";
          } else {
            bubbleClass = "bg-zinc-100/50 text-zinc-800 border-zinc-200/50 rounded-tl-none backdrop-blur-3xl";
          }
        }

        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-1000 fill-mode-both ease-out relative`}
            style={{ animationDelay: `${index * 30}ms` }}
          >
            <div className={`max-w-[92%] sm:max-w-[85%] group relative ${isMenuOpen ? 'z-[100] scale-[1.02]' : 'z-10'} transition-all duration-300`}>
              <div className={`flex items-center gap-3 mb-2 px-2 transition-all duration-500 opacity-60 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[9px] font-bold uppercase tracking-[0.2em] ${isUser ? (isOwnerView ? 'text-amber-600' : isPro ? 'text-indigo-600' : 'text-zinc-600') : 'text-zinc-400'}`}>
                  {isUser ? (isOwnerView ? 'Sovereign' : isPro ? 'Neural Pro' : ownerName.split(' ')[0]) : (isSynthesis ? 'Synthesis' : 'Anora')}
                </span>
                <div className="w-0.5 h-0.5 rounded-full bg-zinc-200"></div>
                <span className="text-[8px] text-zinc-300 font-bold uppercase tracking-widest">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>

              {msg.images && msg.images.length > 0 && !isEditing && (
                <div className={`grid gap-2 mb-3 animate-in zoom-in-95 duration-700 ${msg.images.length === 4 ? 'grid-cols-2' : (msg.images.length > 1 ? 'flex flex-wrap' : 'flex')} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[1.8rem] sm:rounded-[2.5rem] border shadow-md transition-all hover:border-zinc-400
                      ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-200'} 
