                onMouseUp={handleTouchEnd}
                onMouseLeave={handleTouchEnd}
                onTouchStart={() => handleTouchStart(msg.id)}
                onTouchEnd={handleTouchEnd}
                className={`rounded-[2rem] sm:rounded-[3rem] px-6 sm:px-10 py-5 sm:py-8 text-sm sm:text-base leading-relaxed shadow-sm transition-all duration-700 relative ring-1 ring-black/5 select-none touch-none ${bubbleClass} ${isMenuOpen ? 'ring-2 ring-zinc-900/10' : ''}`}
              >
                {isUser && isOwnerView && <div className="absolute -top-1 -right-1 w-3 h-3 bg-amber-500 rounded-full border-2 border-white shadow-md"></div>}

                {isEditing ? (
                  <div className="space-y-4 py-2 animate-in fade-in duration-300">
