                    </div>
                  </div>
                ) : (
                  <div className="prose prose-zinc max-w-none whitespace-pre-wrap font-medium tracking-tight">
                    {msg.content}
                  </div>
                )}

                {/* Standard Actions (Always Visible) */}
                {isAnora && onVocalize && !isEditing && (
