                          className="flex items-center gap-3 px-4 py-3 bg-white border border-zinc-200 rounded-2xl text-[9px] text-zinc-400 hover:text-zinc-900 hover:border-zinc-300 transition-all group/source shadow-sm"
                        >
                          <span className="max-w-[150px] truncate font-bold tracking-wider">{source.title || 'Intel'}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}

      {isThinking && (
        <div className="flex justify-start animate-in fade-in slide-in-from-left-2 duration-700">
          <div className={`bg-white border rounded-[1.8rem] rounded-tl-none px-6 py-4 shadow-sm ring-1 ring-black/5 ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-100'}`}>
            <div className="flex gap-1.5">
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.3s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div>
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.15s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div>
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div>
            </div>
          </div>
        </div>
      )}

      {/* Backdrop for Menu */}
      {contextMenuId && (
        <div 
          onClick={() => setContextMenuId(null)}
          className="fixed inset-0 z-50 bg-black/5 backdrop-blur-sm animate-in fade-in duration-300"
        ></div>
      )}

      <div ref={bottomRef} className="h-10" />
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob as GenAIBlob } from '@google/genai';
import { Message, Role, User, SubscriptionTier, Persona, NeuralAffect } from './types';
import { INITIAL_MESSAGE, OWNER_EMAIL } from './constants';
import { anoraService } from './services/geminiService';
import { MessageList } from './components/MessageList';
import { VoiceIndicator } from './components/VoiceIndicator';
import { AuthScreen } from './components/AuthScreen';
import { PremiumBadge } from './components/PremiumBadge';
import { CommandCenter } from './components/CommandCenter';
import { ProfileModal } from './components/ProfileModal';
import { AnoraLogo } from './components/AnoraLogo';
import { AssistantFeatures } from './components/AssistantFeatures';
import { NeuralOrb } from './components/NeuralOrb';

const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

const createBlob = (data: Float32Array): GenAIBlob => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
  return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [messages, setMessages] = useState<Message[]>([]);

  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [activeIntent, setActiveIntent] = useState<Message['intent']>('GENERAL');
  const [activeAffect, setActiveAffect] = useState<NeuralAffect>('SOVEREIGN');
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [inputFocused, setInputFocused] = useState(false);
  const [isSynthesisMode, setIsSynthesisMode] = useState(false);
  const [speakingId, setSpeakingId] = useState<string | null>(null);
  const [isWakeWordActive, setIsWakeWordActive] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const currentVocalizeIdRef = useRef<string | null>(null);

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const wakeWordRecognitionRef = useRef<any>(null);

  // Sync session and database
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      const savedDb = localStorage.getItem('anora_users_db');
      const users: User[] = savedDb ? JSON.parse(savedDb) : [];

      const exists = users.find(u => u.id === currentUser.id);
      let updatedUsers;
      if (exists) {
        updatedUsers = users.map((u: User) => u.id === currentUser.id ? currentUser : u);
      } else {
        updatedUsers = [...users, currentUser];
      }

      localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
      anoraService.initChat(currentUser);
      setIsWakeWordActive(currentUser.preferences.continuousListening || false);
    }
  }, [currentUser]);

  // Load history
  useEffect(() => {
    if (currentUser) {
      const historyKey = `anora_history_${currentUser.email}`;
      const savedHistory = localStorage.getItem(historyKey);
      if (savedHistory) {
        setMessages(JSON.parse(savedHistory));
      } else {
        handleNewThread();
      }
    }
  }, [currentUser?.email]);

  // Persistence and Memory Synchronization
  useEffect(() => {
    if (currentUser && messages.length > 0) {
      const historyKey = `anora_history_${currentUser.email}`;
      localStorage.setItem(historyKey, JSON.stringify(messages));

      const userMessageCount = messages.filter(m => m.role === 'user').length;
      if (userMessageCount > 0 && userMessageCount % 6 === 0) {
          const synthMemory = async () => {
              const newMemories = await anoraService.summarizeMemory(messages);
              if (newMemories.length > 0 && currentUser) {
                  const updatedUser = { 
                      ...currentUser, 
                      memory: [...(currentUser.memory || []), ...newMemories].slice(-20)
                  };
                  setCurrentUser(updatedUser);
              }
          };
          synthMemory();
      }

      const lastAnora = [...messages].reverse().find(m => m.role === 'anora');
      if (lastAnora?.affect) {
        setActiveAffect(lastAnora.affect);
      }
    }
  }, [messages, currentUser?.email]);

  const handleNewThread = () => {
    if (!currentUser) return;
    const initialRaw = INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT');
    const { content, affect } = anoraService.parseAffect(initialRaw);
    const initial: Message = {
      id: 'initial_' + Date.now(),
      role: 'anora',
      content,
      affect,
      timestamp: new Date()
    };
    setMessages([initial]);
    const historyKey = `anora_history_${currentUser.email}`;
    localStorage.setItem(historyKey, JSON.stringify([initial]));
    anoraService.initChat(currentUser); // Refresh Gemini session with potential new language
  };

  const handleLogout = useCallback(() => {
    setCurrentUser(null);
    localStorage.removeItem('anora_session');
    setMessages([]);
  }, []);

  const handleSaveToMemory = useCallback((content: string) => {
    if (!currentUser) return;
    const updated = { ...currentUser };
    updated.memory = [
      ...(updated.memory || []),
      { 
        id: `mem_${Date.now()}`, 
        content, 
        category: 'PERSONAL', 
        timestamp: new Date().toISOString(), 
        strength: 5 
      }
    ];
    setCurrentUser(updated);
  }, [currentUser]);

  const handleSaveToReminders = useCallback((content: string) => {
    if (!currentUser) return;
    const updated = { ...currentUser };
    updated.reminders = [
      ...(updated.reminders || []),
      { 
        id: `rem_${Date.now()}`, 
        text: content, 
        priority: 'MEDIUM', 
        completed: false, 
        dueDate: new Date().toISOString() 
      }
    ];
    setCurrentUser(updated);
  }, [currentUser]);

  const handleDeleteMessage = useCallback((id: string) => {
    setMessages(prev => prev.filter(m => m.id !== id));
  }, []);

  const toggleVoiceMode = useCallback(async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(t => t.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }
    try {
      if (wakeWordRecognitionRef.current) {
        wakeWordRecognitionRef.current.stop();
      }

      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => session.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            const interrupted = msg.serverContent?.interrupted;
            if (interrupted) {
              for (const source of audioSourcesRef.current.values()) {
                source.stop();
                audioSourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
            }
            const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => audioSourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
          },
          onclose: () => setIsVoiceMode(false),
          onerror: () => setIsVoiceMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `Anora Voice v8.5. Language: ${currentUser?.preferences.language}. Persona: ${currentUser?.preferences.persona}. Master: ${currentUser?.name}. Environment: White Light Theme. Respond with elegant clarity.`
        }
      });
    } catch (err) {
      console.error(err);
      setIsVoiceMode(false);
    }
  }, [isVoiceMode, currentUser]);

  const handleVocalize = async (id: string, text: string, affect: NeuralAffect = 'SOVEREIGN') => {
    if (activeSourceRef.current) {
      try { activeSourceRef.current.stop(); } catch (e) {}
      activeSourceRef.current = null;
    }
    if (speakingId === id) {
      setSpeakingId(null);
      currentVocalizeIdRef.current = null;
      return;
    }
    setSpeakingId(id);
    currentVocalizeIdRef.current = id;

    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      }
      if (audioCtxRef.current.state === 'suspended') await audioCtxRef.current.resume();
      const voiceName = currentUser?.preferences.voiceName || 'Kore';
      const base64 = await anoraService.speak(text, voiceName, affect);
      if (currentVocalizeIdRef.current !== id) return;
      const buffer = await decodeAudioData(decode(base64), audioCtxRef.current, 24000, 1);
      if (currentVocalizeIdRef.current !== id) return;
      const source = audioCtxRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtxRef.current.destination);
      source.onended = () => {
        if (currentVocalizeIdRef.current === id) {
          setSpeakingId(null);
          currentVocalizeIdRef.current = null;
        }
      };
      activeSourceRef.current = source;
      source.start();
    } catch (err) {
      console.error("Vocalization failed:", err);
      setSpeakingId(null);
    }
  };

  const detectIntent = (text: string): Message['intent'] => {
    const t = text.toLowerCase();
    if (t.includes('autocad') || t.includes('rhb') || t.includes('site') || t.includes('engineering') || t.includes('cad')) return 'ENGINEERING';
    if (t.includes('lyrics') || t.includes('song') || t.includes('rhyme') || t.includes('music')) return 'CREATIVE';
    if (t.includes('sovereign') || t.includes('command')) return 'SOVEREIGN';
    return 'GENERAL';
  };

  const handleSend = async (text: string) => {
    const val = text.trim();
    if ((!val && pendingImages.length === 0) || !currentUser) return;
    if (activeSourceRef.current) {
      try { activeSourceRef.current.stop(); } catch(e) {}
      setSpeakingId(null);
      currentVocalizeIdRef.current = null;
    }

    const intent = detectIntent(val);
    setActiveIntent(intent);

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: val || "Sharing visual asset...",
      timestamp: new Date(),
      images: pendingImages.length > 0 ? [...pendingImages] : undefined,
      intent
    };
    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setPendingImages([]);
    await generateAnoraResponse([...messages, userMsg], intent);
  };

  const generateAnoraResponse = async (currentHistory: Message[], intent: Message['intent']) => {
    setIsThinking(true);
    try {
      const lastUserMsg = currentHistory[currentHistory.length - 1];
      const response = await anoraService.sendMessageWithVision(lastUserMsg.content, lastUserMsg.images || []);
      const anoraMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'anora',
        content: response.text,
        sources: (response as any).sources,
        images: response.images,
        affect: response.affect as NeuralAffect,
        timestamp: new Date(),
        intent
      };
      setMessages(prev => [...prev, anoraMsg]);
      if (currentUser?.preferences.autoRead && anoraMsg.content) {
        handleVocalize(anoraMsg.id, anoraMsg.content, anoraMsg.affect);
      }
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { id: 'err', role: 'system', content: "Neural bridge unstable. Synchronizing...", timestamp: new Date() }]);
    } finally {
      setIsThinking(false);
      setActiveIntent('GENERAL');
    }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const isOwner = currentUser.role === Role.OWNER;
  const isPro = currentUser.tier === SubscriptionTier.PRO || currentUser.tier === SubscriptionTier.LIFETIME || isOwner;
  const font = currentUser.preferences.font || 'INTER';
  const accent = isOwner ? '#d4af37' : isPro ? '#8b5cf6' : '#3f3f46';

  return (
    <div className={`flex flex-col h-[100dvh] bg-white text-zinc-800 overflow-hidden transition-all duration-700 ${font === 'OUTFIT' ? 'font-outfit' : 'font-inter'}`}>
      <style>{`
        .accent-text { color: ${accent}; }
        .accent-border { border-color: ${accent}20; }
        .input-glow-focus {
          box-shadow: 0 4px 20px -5px ${accent}20;
          border-color: ${accent}40;
        }
      `}</style>

      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} onLogout={handleLogout} />
      <AssistantFeatures 
        user={currentUser} 
        onUpdate={setCurrentUser} 
        onClearHistory={handleNewThread}
        messagesCount={messages.length}
        isOpen={isHubOpen} 
        onClose={() => setIsHubOpen(false)} 
      />

      <header className="flex items-center justify-between px-6 sm:px-12 pt-[calc(var(--sat)+1rem)] pb-4 border-b border-zinc-100 bg-white/95 backdrop-blur-md z-[100] shrink-0">
        <div className="flex items-center gap-6">
          <AnoraLogo size={40} color={accent} />
          <div className="hidden sm:block">
            <PremiumBadge role={currentUser.role} tier={currentUser.tier} />
          </div>
        </div>

        <div className="flex items-center gap-4 sm:gap-6">
          <VoiceIndicator active={isVoiceMode} />
          <div className="flex items-center gap-2 p-1 bg-zinc-50 rounded-full border border-zinc-100 shadow-sm">
            <button onClick={() => setIsHubOpen(true)} className="p-2.5 text-zinc-400 hover:text-zinc-900 transition-colors"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg></button>
            <button onClick={() => isPro ? setIsCommandCenterOpen(true) : alert("Upgrade to Neural Pro for Visual Synthesis.")} className={`p-2.5 transition-colors ${isPro ? 'text-zinc-400 hover:text-zinc-900' : 'text-zinc-200 cursor-not-allowed'}`}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></button>
            <button onClick={() => setIsProfileOpen(true)} className={`w-9 h-9 rounded-full border border-zinc-200 bg-white overflow-hidden flex items-center justify-center text-[10px] font-black ${isOwner ? 'ring-2 ring-amber-500/30' : ''}`}>
              {currentUser.avatar ? <img src={currentUser.avatar} alt="AV" className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden bg-white">
        <MessageList 
          messages={messages} 
          isThinking={isThinking} 
          ownerName={currentUser.name} 
          isOwnerView={isOwner} 
          userTier={currentUser.tier}
          onVocalize={(id, text) => {
            const msg = messages.find(m => m.id === id);
            handleVocalize(id, text, msg?.affect || 'SOVEREIGN');
          }}
          onEditMessage={(id, content) => {
             const index = messages.findIndex(m => m.id === id);
             if (index !== -1) {
                const truncated = [...messages.slice(0, index)];
                const editedMsg = { ...messages[index], content, timestamp: new Date() };
                const newHistory = [...truncated, editedMsg];
                setMessages(newHistory);
                generateAnoraResponse(newHistory, detectIntent(content));
             }
          }}
          onDeleteMessage={handleDeleteMessage}
          onSaveToMemory={handleSaveToMemory}
          onSaveToReminders={handleSaveToReminders}
          speakingId={speakingId}
        />
        <NeuralOrb active={isThinking} intent={activeIntent} affect={activeAffect} speaking={speakingId !== null} listening={isWakeWordActive && !isVoiceMode} color={accent} />
      </main>

      <footer className="px-6 sm:px-12 pb-[calc(var(--sab)+1.5rem)] pt-4 bg-white/95 backdrop-blur-md border-t border-zinc-100 z-[100] shrink-0">
        <div className="max-w-4xl mx-auto flex items-center gap-4">
          {isPro && (
            <button onClick={() => fileInputRef.current?.click()} className="p-4 rounded-2xl bg-zinc-50 text-zinc-400 border border-zinc-100 hover:border-zinc-300 transition-all active:scale-95">
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
              <input type="file" ref={fileInputRef} hidden multiple onChange={e => {
                  const files = e.currentTarget.files;
                  if (files) Array.from(files).forEach((f: File) => {
                    const reader = new FileReader();
                    reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]);
                    reader.readAsDataURL(f);
                  });
                }} />
            </button>
          )}

          <div className="flex-1 relative flex items-center group">
            <input
              type="text"
              value={inputValue}
              onFocus={() => setInputFocused(true)}
              onBlur={() => setInputFocused(false)}
              onChange={e => setInputValue(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)}
              placeholder={isOwner ? "Sovereign Command..." : "Neural Input..."}
              className={`w-full bg-zinc-50 border border-zinc-100 text-zinc-900 rounded-[2rem] pl-6 pr-16 py-4.5 outline-none transition-all duration-300 ${inputFocused ? 'input-glow-focus' : ''}`}
            />
            <button 
              onClick={() => handleSend(inputValue)}
              disabled={!inputValue.trim() && pendingImages.length === 0}
              className={`absolute right-1.5 p-3.5 rounded-full transition-all active:scale-90 ${isOwner ? 'bg-amber-500 text-white' : 'bg-zinc-900 text-white'} disabled:opacity-20 shadow-sm`}
            >
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg>
            </button>
          </div>
        </div>
      </footer>
    </div>
  );
};

