               <svg className="w-5 h-5 text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
             </div>
             <div>
                <h2 className="text-xl font-black font-outfit text-zinc-900">Neural Hub</h2>
                <p className="text-[9px] uppercase tracking-[0.3em] font-bold text-zinc-400 mt-1">Sovereign Intel v3.5</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 text-zinc-300 hover:text-zinc-900 transition-colors bg-zinc-50 rounded-2xl shadow-sm border border-zinc-100">
