                        <span className="text-[10px] font-black uppercase tracking-widest text-red-500">Purge Synapse</span>
                      </button>
                    </div>
                  </div>
                )}

                {msg.sources && msg.sources.length > 0 && !isEditing && (
                  <div className="mt-8 pt-8 border-t border-zinc-100 animate-in fade-in duration-1000">
                    <p className="text-[8px] font-bold text-zinc-300 uppercase tracking-[0.4em] mb-4">VERIFIED INTEL</p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((source, idx) => (
                        <a
