                        className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item"
                      >
                        <svg className="w-4 h-4 text-zinc-400 group-hover/item:text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                        <span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Copy Intel</span>
                      </button>

