                          <span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Sync to Memory</span>
                        </button>
                      )}

                      {onSaveToReminders && (
                        <button 
                          onClick={() => {
                            onSaveToReminders(msg.content);
                            setContextMenuId(null);
