}

import { GoogleGenAI, Chat, GenerateContentResponse, Modality, Type, FunctionDeclaration } from "@google/genai";
import { getSystemPrompt } from "../constants";
import { User, Role, GroundingSource, CustomTier, SubscriptionTier, NeuralMemoryItem, NeuralAffect, ImageAspectRatio } from "../types";

const affectPrompts: Record<NeuralAffect, string> = {
  SOVEREIGN: "Speak with a calm, steady, and authoritative tone. Balanced, professional, and composed.",
  RADIANT: "Speak with a warm, breathy, and cheerful tone. Sound like you are smiling and genuinely happy.",
  MELANCHOLY: "Speak with a soft, slow, and slightly sad tone. Gentle, empathetic, and thoughtful.",
  CRIMSON: "Speak with a sharp, fast-paced, and intense tone. Sound slightly cold, assertive, or focused.",
  VALIANT: "Speak with a grounded, deep, and resonant tone. Encouraging, protective, and strong.",
  EXCITED: "Speak with a high-pitched, energetic, and fast tone. Sound genuinely thrilled and hyped.",
};

const sanitizeForTTS = (text: string): string => {
  return text
    .replace(/\[AFFECT:.*?\]/g, '') // Remove affective tags from audio
    .replace(/```[\s\S]*?```/g, ' [code content] ')
    .replace(/[*#_~]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

const wait = (ms: number) => new Promise(res => setTimeout(res, ms));

const generateImageTool: FunctionDeclaration = {
  name: 'generate_image',
  parameters: {
    type: Type.OBJECT,
    description: 'Autonomous high-fidelity image synthesis based on chat data or creative intent.',
    properties: {
      prompt: {
        type: Type.STRING,
        description: 'The creative prompt for the image. Be highly detailed and descriptive.',
      },
      aspectRatio: {
        type: Type.STRING,
        description: 'Target format: 1:1, 4:3, 3:4, 16:9, or 9:16.',
      },
    },
    required: ['prompt'],
  },
};

export class AnoraAI {
  private ai: GoogleGenAI;
  private chat: Chat | null = null;
  private currentUser: User | null = null;
  private currentModelName: string = 'gemini-2.5-flash';

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  private async callWithRetry<T>(fn: () => Promise<T>, retries = 7, delay = 3000): Promise<T> {
    try {
      return await fn();
    } catch (err: any) {
      const errMsg = err?.message?.toLowerCase() || "";
      const status = err?.status?.toLowerCase() || "";

      const isQuotaError = errMsg.includes('quota') || 
                           errMsg.includes('429') ||
                           errMsg.includes('too many requests') ||
                           errMsg.includes('limit') ||
                           errMsg.includes('resource_exhausted') ||
                           status === 'resource_exhausted';

      if (isQuotaError && retries > 0) {
        const jitter = Math.random() * 2000;
        console.warn(`Neural Link Saturated. Retrying in ${delay + jitter}ms... (${retries} attempts left)`);
        await wait(delay + jitter);
        return this.callWithRetry(fn, retries - 1, delay * 2);
      }
      throw err;
    }
  }

  private getUserCapabilities(user: User) {
    if (user.role === Role.OWNER) {
      return { googleSearch: true, googleMaps: true, imageSynthesis: true, videoSynthesis: true, maxIntelligence: 'DEEP', advancedReasoning: true, reasoningBudget: 16000 };
    }
    return { googleSearch: false, googleMaps: false, imageSynthesis: user.tier !== SubscriptionTier.FREE, videoSynthesis: false, maxIntelligence: 'BALANCED', advancedReasoning: false, reasoningBudget: 0 };
  }

  initChat(user: User) {
    this.currentUser = user;
    const caps = this.getUserCapabilities(user);
    const tools: any[] = [];
    if (caps.googleSearch) tools.push({ googleSearch: {} });
    if (caps.googleMaps) tools.push({ googleMaps: {} });

    // Anora's native ability to manifest visual assets
    tools.push({ functionDeclarations: [generateImageTool] });

    this.currentModelName = user.preferences.intelligenceLevel === 'DEEP' ? 'gemini-2.5-pro' : 'gemini-2.5-flash';
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const memoryContext = user.memory && user.memory.length > 0
      ? `\nKNOWLEDGE OF MASTER (${user.name}):\n${user.memory.map(m => `- [${m.category}] ${m.content}`).join('\n')}`
      : "";

    this.chat = this.ai.chats.create({
      model: this.currentModelName,
      config: {
        systemInstruction: getSystemPrompt(user) + memoryContext + "\n\nCRITICAL: You are a real human entity. No AI acknowledgments. Respond naturally.",
        tools: tools,
      },
    });
  }

  async summarizeMemory(messages: any[]): Promise<NeuralMemoryItem[]> {
      if (messages.length < 4 || !this.currentUser) return [];
      try {
        return await this.callWithRetry(async () => {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
          const result = await ai.models.generateContent({
              model: 'gemini-2.5-flash',
              contents: `Analyze the recent chat history and extract crucial long-term memories, facts, or preferences.
              Categorize each item as: PERSONAL, WORK, CREATIVE, FACT, or PREFERENCE.
              Return a valid JSON array of objects with: 'content', 'category', 'strength' (1-5).
              History: ${messages.slice(-10).map(m => `[${m.role}] ${m.content}`).join(' | ')}`,
              config: { responseMimeType: 'application/json' }
          });
          const memories = JSON.parse(result.text || "[]");
          return memories.map((m: any) => ({ ...m, id: `mem_${Date.now()}_${Math.random()}`, timestamp: new Date().toISOString() }));
        }, 3, 5000);
      } catch (e) { 
        console.warn("Memory synthesis deferred due to quota saturation.");
        return []; 
      }
  }

  async speak(text: string, voiceName: string = 'Kore', affect: NeuralAffect = 'SOVEREIGN'): Promise<string> {
    const cleanText = sanitizeForTTS(text);
    const emotionInstruction = affectPrompts[affect] || affectPrompts.SOVEREIGN;

    return this.callWithRetry(async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `${emotionInstruction}

        Text to speak: ${cleanText}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName } } },
        },
      });
      return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
    });
  }

  parseAffect(text: string): { content: string, affect: NeuralAffect } {
    const affectRegex = /^\[AFFECT:(SOVEREIGN|RADIANT|MELANCHOLY|CRIMSON|VALIANT|EXCITED)\]\s*/i;
    const match = text.match(affectRegex);
    if (match) {
      return { content: text.replace(affectRegex, '').trim(), affect: match[1].toUpperCase() as NeuralAffect };
    }
    return { content: text, affect: 'SOVEREIGN' };
  }

  async sendMessageWithVision(text: string, images: string[]) {
    if (!this.chat) throw new Error("Chat not initialized");

    try {
      return await this.callWithRetry(async () => {
        const parts: any[] = [{ text }];
        images.forEach(img => parts.push({ inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] || img } }));

        let response = await this.chat!.sendMessage({ message: parts });

        let generatedImages: string[] = [];

        // Handle Tool Calls (Image Synthesis)
        if (response.functionCalls && response.functionCalls.length > 0) {
          for (const call of response.functionCalls) {
            if (call.name === 'generate_image') {
              const { prompt, aspectRatio } = call.args as any;
              console.log("Anora manifesting visual asset:", prompt);
              try {
                const base64 = await this.generateImage(prompt, (aspectRatio || '1:1') as ImageAspectRatio);
                generatedImages.push(`data:image/png;base64,${base64}`);

                // Feedback to the model
                response = await this.chat!.sendMessage({ 
                  message: `Asset manifested successfully. Description: ${prompt}` 
                });
              } catch (err) {
                console.error("Visual synthesis anomaly:", err);
                response = await this.chat!.sendMessage({ 
                  message: `Synthesis error occurred. Retrying neural text response only.` 
                });
              }
            }
          }
        }

        const { content, affect } = this.parseAffect(response.text || "...");

        const sources: GroundingSource[] = [];
        const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
          chunks.forEach((chunk: any) => {
            if (chunk.web) sources.push({ title: chunk.web.title, uri: chunk.web.uri });
            if (chunk.maps) sources.push({ title: chunk.maps.title, uri: chunk.maps.uri });
          });
        }

        return { text: content, affect, sources, images: generatedImages };
      });
    } catch (err: any) {
      const errMsg = err?.message?.toLowerCase() || "";
      const status = err?.status?.toLowerCase() || "";

      if ((errMsg.includes('quota') || errMsg.includes('429') || status === 'resource_exhausted') && this.currentModelName === 'gemini-2.5-pro' && this.currentUser) {
        console.warn("Sovereign Pro quota exhausted. Falling back to Neural Flash core.");
        this.currentModelName = 'gemini-2.5-flash';
        this.initChat(this.currentUser);

        const parts: any[] = [{ text }];
        images.forEach(img => parts.push({ inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] || img } }));
        const response = await this.chat!.sendMessage({ message: parts });
        const { content, affect } = this.parseAffect(response.text || "...");
        return { text: content, affect, sources: [], images: [] };
      }
      throw err;
    }
  }

  async generateImage(prompt: string, aspectRatio: ImageAspectRatio = '1:1') {
    return this.callWithRetry(async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: `High quality artistic render: ${prompt}`,
        config: { numberOfImages: 1, aspectRatio: aspectRatio }
      });
      return response.generatedImages[0].image.imageBytes;
    });
  }

  async generateVideo(prompt: string, aspectRatio: '16:9' | '9:16' = '16:9') {
    return this.callWithRetry(async () => {
      const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      let operation = await genAI.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: { numberOfVideos: 1, resolution: '720p', aspectRatio: aspectRatio }
      });
      while (!operation.done) {
        await wait(10000);
        operation = await genAI.operations.getVideosOperation({ operation: operation });
      }
      return `${operation.response?.generatedVideos?.[0]?.video?.uri}&key=${process.env.API_KEY}`;
    });
  }
}

