const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

const createBlob = (data: Float32Array): GenAIBlob => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
  return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
};

const TOKEN_LIMITS = {
  OWNER: { chat: Infinity, image: Infinity, video: Infinity },
  PRO: { chat: 100000, image: 100, video: 20 },
  LIFETIME: { chat: 100000, image: 100, video: 20 },
  FREE: { chat: 20000, image: 10, video: 0 },
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [activeIntent, setActiveIntent] = useState<Message['intent']>('GENERAL');
  const [activeAffect, setActiveAffect] = useState<NeuralAffect>('SOVEREIGN');
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [inputFocused, setInputFocused] = useState(false);
  const [speakingId, setSpeakingId] = useState<string | null>(null);
  const [isWakeWordActive, setIsWakeWordActive] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const currentVocalizeIdRef = useRef<string | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const wakeWordRecognitionRef = useRef<any>(null);

  useEffect(() => {
    const handleDbUpdate = () => {
      if (!currentUser) return;
      const users: User[] = JSON.parse(localStorage.getItem('anora_users_db') || '[]');
      const updated = users.find(u => u.id === currentUser.id);
      if (updated && (updated.tier !== currentUser.tier || updated.role !== currentUser.role)) {
        setCurrentUser(updated);
      }
    };
    window.addEventListener('anora_database_updated', handleDbUpdate);
    return () => window.removeEventListener('anora_database_updated', handleDbUpdate);
  }, [currentUser]);

  useEffect(() => {
    if (currentUser) {
      // Token Reset Logic
      const today = new Date().toDateString();
      if (!currentUser.tokens || currentUser.tokens.lastReset !== today) {
        const limits = currentUser.role === Role.OWNER ? TOKEN_LIMITS.OWNER : (TOKEN_LIMITS[currentUser.tier] || TOKEN_LIMITS.FREE);
        const resetUser = {
          ...currentUser,
          tokens: {
            ...limits,
            lastReset: today
          }
        };
        setCurrentUser(resetUser);
        return; // Next effect will handle saving
      }

      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      const savedDb = localStorage.getItem('anora_users_db');
      const users: User[] = savedDb ? JSON.parse(savedDb) : [];
      const exists = users.find(u => u.id === currentUser.id);
      const updatedUsers = exists ? users.map((u: User) => u.id === currentUser.id ? currentUser : u) : [...users, currentUser];
      localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
      anoraService.initChat(currentUser);
      setIsWakeWordActive(currentUser.preferences.continuousListening || false);
    }
  }, [currentUser]);

  useEffect(() => {
    if (currentUser) {
      const historyKey = `anora_history_${currentUser.email}`;
      const savedHistory = localStorage.getItem(historyKey);
      if (savedHistory) {
        setMessages(JSON.parse(savedHistory));
      } else {
        handleNewThread();
      }
    }
  }, [currentUser?.email]);

  useEffect(() => {
    if (currentUser && messages.length > 0) {
      const historyKey = `anora_history_${currentUser.email}`;
      localStorage.setItem(historyKey, JSON.stringify(messages));
      if (messages.filter(m => m.role === 'user').length % 6 === 0) {
          const synthMemory = async () => {
              const newMemories = await anoraService.summarizeMemory(messages);
              if (newMemories.length > 0 && currentUser) {
                  setCurrentUser({ ...currentUser, memory: [...(currentUser.memory || []), ...newMemories].slice(-20) });
              }
          };
          synthMemory();
      }
      const lastAnora = [...messages].reverse().find(m => m.role === 'anora');
      if (lastAnora?.affect) setActiveAffect(lastAnora.affect);
    }
  }, [messages, currentUser?.email]);

  const deductTokens = useCallback((type: keyof Omit<TokenUsage, 'lastReset'>, amount: number) => {
    if (!currentUser) return false;
    if (currentUser.role === Role.OWNER) return true;

    const tokens = currentUser.tokens || { chat: 0, image: 0, video: 0, lastReset: '' };
    if (tokens[type] < amount) {
      alert(`Insufficient Neural Resources: ${type.toUpperCase()} pool depleted for today.`);
      return false;
    }

    const updatedUser = {
      ...currentUser,
      tokens: {
        ...tokens,
        [type]: tokens[type] - amount
      }
    };
    setCurrentUser(updatedUser);
    return true;
  }, [currentUser]);

  const handleNewThread = () => {
    if (!currentUser) return;
    const initialRaw = INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT');
    const { content, affect } = anoraService.parseAffect(initialRaw);
    const initial: Message = { id: 'init_' + Date.now(), role: 'anora', content, affect, timestamp: new Date() };
    setMessages([initial]);
    localStorage.setItem(`anora_history_${currentUser.email}`, JSON.stringify([initial]));
    anoraService.initChat(currentUser);
  };

  const handleLogout = useCallback(() => {
    setCurrentUser(null);
    localStorage.removeItem('anora_session');
    setMessages([]);
  }, []);

  const handleSaveToMemory = useCallback((content: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, memory: [...(currentUser.memory || []), { id: `mem_${Date.now()}`, content, category: 'PERSONAL', timestamp: new Date().toISOString(), strength: 5 }] });
  }, [currentUser]);

  const handleSaveToReminders = useCallback((content: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, reminders: [...(currentUser.reminders || []), { id: `rem_${Date.now()}`, text: content, priority: 'MEDIUM', completed: false, dueDate: new Date().toISOString() }] });
  }, [currentUser]);

  const handleDeleteMessage = useCallback((id: string) => { setMessages(prev => prev.filter(m => m.id !== id)); }, []);

  const toggleVoiceMode = useCallback(async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(t => t.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }
    try {
      if (wakeWordRecognitionRef.current) wakeWordRecognitionRef.current.stop();
      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => session.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
          },
          onclose: () => setIsVoiceMode(false),
          onerror: () => setIsVoiceMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `Anora Voice. User: ${currentUser?.name}. Persona: ${currentUser?.preferences.persona}.`
        }
      });
    } catch (err) { setIsVoiceMode(false); }
  }, [isVoiceMode, currentUser]);

  const handleVocalize = async (id: string, text: string, affect: NeuralAffect = 'SOVEREIGN') => {
    if (activeSourceRef.current) { try { activeSourceRef.current.stop(); } catch (e) {} activeSourceRef.current = null; }
    if (speakingId === id) { setSpeakingId(null); currentVocalizeIdRef.current = null; return; }
    setSpeakingId(id); currentVocalizeIdRef.current = id;
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const base64 = await anoraService.speak(text, currentUser?.preferences.voiceName || 'Kore', affect);
      if (currentVocalizeIdRef.current !== id) return;
      const buffer = await decodeAudioData(decode(base64), audioCtxRef.current, 24000, 1);
      const source = audioCtxRef.current.createBufferSource();
      source.buffer = buffer; source.connect(audioCtxRef.current.destination);
      source.onended = () => { if (currentVocalizeIdRef.current === id) setSpeakingId(null); };
      activeSourceRef.current = source; source.start();
    } catch (err) { setSpeakingId(null); }
  };

  const handleSend = async (text: string) => {
    const val = text.trim();
    if (!val && pendingImages.length === 0) return;

    // Deduct Chat Tokens (Estimate: 1 token per 3 chars)
    const chatTokenCost = Math.max(1, Math.ceil((val.length || 10) / 3));
    if (!deductTokens('chat', chatTokenCost)) return;

    const intent = (t: string) => {
      const lower = t.toLowerCase();
      if (lower.includes('cad') || lower.includes('engineering')) return 'ENGINEERING';
      if (lower.includes('music') || lower.includes('lyrics')) return 'CREATIVE';
      return 'GENERAL';
    };
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: val || "Asset shared.", timestamp: new Date(), images: pendingImages.length > 0 ? [...pendingImages] : undefined, intent: intent(val) as any };
    setMessages(prev => [...prev, userMsg]);
    setInputValue(''); setPendingImages([]);
    setIsThinking(true);
    try {
      const response = await anoraService.sendMessageWithVision(userMsg.content, userMsg.images || []);
      const anoraMsg: Message = { id: (Date.now()+1).toString(), role: 'anora', content: response.text, sources: (response as any).sources, images: response.images, affect: response.affect as any, timestamp: new Date() };
      setMessages(prev => [...prev, anoraMsg]);
      if (currentUser?.preferences.autoRead) handleVocalize(anoraMsg.id, anoraMsg.content, anoraMsg.affect);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'system', content: "Neural bridge unstable.", timestamp: new Date() }]);
    } finally { setIsThinking(false); }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const isOwner = currentUser.role === Role.OWNER;
  const isPro = currentUser.tier !== SubscriptionTier.FREE || isOwner;
  const accent = isOwner ? '#d4af37' : (isPro ? '#8b5cf6' : '#3f3f46');

  return (
    <div className={`flex flex-col h-[100dvh] bg-white text-zinc-800 overflow-hidden ${currentUser.preferences.font === 'OUTFIT' ? 'font-outfit' : 'font-inter'}`}>
      <style>{`.accent-text { color: ${accent}; } .accent-border { border-color: ${accent}20; }`}</style>
      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onDeductToken={deductTokens} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} onLogout={handleLogout} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} onClearHistory={handleNewThread} messagesCount={messages.length} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <header className="flex items-center justify-between px-6 sm:px-12 pt-[calc(var(--sat)+1rem)] pb-4 border-b border-zinc-100 shrink-0">
        <AnoraLogo size={40} color={accent} />
        <div className="flex items-center gap-4">
          <VoiceIndicator active={isVoiceMode} />
          <div className="flex items-center gap-2 p-1 bg-zinc-50 rounded-full border border-zinc-100">
            <button onClick={() => setIsHubOpen(true)} className="p-2.5 text-zinc-400 hover:text-zinc-900"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg></button>
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-2.5 text-zinc-400 hover:text-zinc-900"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></button>
            <button onClick={() => setIsProfileOpen(true)} className={`w-9 h-9 rounded-full bg-white overflow-hidden flex items-center justify-center text-[10px] font-black ${isOwner ? 'ring-2 ring-amber-500' : 'border border-zinc-200'}`}>
              {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <MessageList messages={messages} isThinking={isThinking} ownerName={currentUser.name} isOwnerView={isOwner} userTier={currentUser.tier} onVocalize={handleVocalize} onDeleteMessage={handleDeleteMessage} onSaveToMemory={handleSaveToMemory} onSaveToReminders={handleSaveToReminders} speakingId={speakingId} />
        <NeuralOrb active={isThinking} affect={activeAffect} speaking={speakingId !== null} color={accent} />
      </main>

      <footer className="px-6 sm:px-12 pb-[calc(var(--sab)+1.5rem)] pt-4 border-t border-zinc-100 shrink-0">
        <div className="max-w-4xl mx-auto flex items-center gap-4">
          <button onClick={() => fileInputRef.current?.click()} className="p-4 rounded-2xl bg-zinc-50 text-zinc-400 border border-zinc-100"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg><input type="file" ref={fileInputRef} hidden multiple onChange={e => { const files = e.currentTarget.files; if (files) (Array.from(files) as File[]).forEach(f => { const reader = new FileReader(); reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]); reader.readAsDataURL(f); }); }} /></button>
          <div className="flex-1 relative flex items-center">
            <input type="text" value={inputValue} onChange={e => setInputValue(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)} placeholder={isOwner ? "Sovereign Command..." : "Neural Input..."} className="w-full bg-zinc-50 border border-zinc-100 rounded-[2rem] pl-6 pr-16 py-4.5 outline-none" />
            <button onClick={() => handleSend(inputValue)} className={`absolute right-1.5 p-3.5 rounded-full ${isOwner ? 'bg-amber-500' : 'bg-zinc-900'} text-white`}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, AiMood, IntelligenceLevel, Persona } from '../types';
import { ACCENT_COLORS, PREBUILT_VOICES, PERSONA_INSTRUCTIONS } from '../constants';
import { anoraService } from '../services/geminiService';

interface ProfileModalProps {
  user: User;
  isOpen: boolean;
  onClose: () => void;
  onUpdate: (updatedUser: User) => void;
  onLogout: () => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ user, isOpen, onClose, onUpdate, onLogout }) => {
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || '');
  const [avatar, setAvatar] = useState(user.avatar || '');
  const [mood, setMood] = useState<AiMood>(user.preferences.aiMood);
  const [accent, setAccent] = useState(user.preferences.accentColor);
  const [intel, setIntel] = useState<IntelligenceLevel>(user.preferences.intelligenceLevel || 'BALANCED');
  const [voiceName, setVoiceName] = useState(user.preferences.voiceName || 'Kore');
  const [persona, setPersona] = useState<Persona>(user.preferences.persona || 'DEFAULT');

  const [avatarPrompt, setAvatarPrompt] = useState('');
  const [generatingAvatar, setGeneratingAvatar] = useState(false);
  const [showToast, setShowToast] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setName(user.name);
      setBio(user.bio || '');
      setAvatar(user.avatar || '');
      setMood(user.preferences.aiMood);
      setAccent(user.preferences.accentColor);
      setIntel(user.preferences.intelligenceLevel || 'BALANCED');
      setVoiceName(user.preferences.voiceName || 'Kore');
      setPersona(user.preferences.persona || 'DEFAULT');
    }
  }, [user, isOpen]);

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const remainingChat = user.tokens?.chat ?? 0;
  const remainingImages = user.tokens?.image ?? 0;
  const remainingVideos = user.tokens?.video ?? 0;

  const handleSave = () => {
    onUpdate({
      ...user,
      name, bio, avatar,
      preferences: {
        ...user.preferences,
        aiMood: mood,
        accentColor: accent,
        intelligenceLevel: intel,
        voiceName,
        persona
      }
    });
    setShowToast(true);
    setTimeout(() => {
        setShowToast(false);
        onClose();
    }, 1500);
  };

  const handleGenerateAvatar = async () => {
    if (!avatarPrompt.trim()) return;
    setGeneratingAvatar(true);
    try {
      const bytes = await anoraService.generateImage(`Futuristic high-fidelity digital avatar profile: ${avatarPrompt}`);
      setAvatar(`data:image/png;base64,${bytes}`);
      setAvatarPrompt('');
    } catch (err: any) {
      alert(`Synthesis Error: ${err.message}`);
    } finally {
      setGeneratingAvatar(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-0 sm:p-6 bg-black/5 backdrop-blur-2xl animate-in fade-in duration-300">
      {showToast && (
        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[220] animate-in slide-in-from-top-6 duration-500 shadow-2xl">
          <div className="px-10 py-4 bg-zinc-900 text-white rounded-full font-black text-[9px] uppercase tracking-[0.5em]">Neural Link Synced</div>
        </div>
      )}

      <div className="w-full max-w-5xl bg-white border border-zinc-100 rounded-none sm:rounded-[4rem] shadow-2xl flex flex-col h-[100dvh] sm:h-auto sm:max-h-[92vh] overflow-hidden transition-all duration-500">

        <div className="shrink-0 px-8 py-8 border-b border-zinc-50 flex items-center justify-between bg-white/90 backdrop-blur-md z-20">
          <div>
            <h2 className="text-2xl font-black font-outfit text-zinc-900 tracking-tight">Identity Protocol</h2>
            <p className="text-[9px] text-zinc-400 font-black uppercase tracking-[0.4em] mt-1">Authorized Neural Presence</p>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-300 hover:text-zinc-900 transition-all bg-zinc-50 rounded-3xl shadow-sm border border-zinc-100">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

