                    <p className="text-[8px] text-zinc-400 font-bold uppercase tracking-widest mt-1">Songwriting & Musical Composition Hub</p>
                  </div>
                  <div className="space-y-4">
                    <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Composition Title" className="w-full bg-white border border-zinc-100 rounded-2xl px-5 py-3.5 text-xs font-bold text-zinc-900 outline-none shadow-sm" />
                    <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Draft lyrics or musical motifs..." className="w-full bg-white border border-zinc-100 rounded-2xl px-5 py-3.5 text-xs font-bold text-zinc-900 outline-none shadow-sm h-40 resize-none font-serif" />
                  </div>
                  <button onClick={addItem} className="w-full py-4 rounded-2xl bg-zinc-900 text-white font-black uppercase text-[10px] tracking-widest active:scale-95 shadow-lg">Synth Lyric Draft</button>
               </div>
               <div className="grid gap-4">
                  {(user.lyrics || []).map(lyric => (
                    <div key={lyric.id} className="p-6 bg-white border border-zinc-100 rounded-[2.5rem] shadow-sm group">
                       <h4 className="text-[11px] font-black text-zinc-900 uppercase tracking-widest mb-2">{lyric.title}</h4>
                       <p className="text-[10px] text-zinc-500 font-serif leading-relaxed line-clamp-3 italic">"{lyric.content}"</p>
                       <button onClick={() => removeItem(lyric.id, 'lyrics')} className="mt-4 text-[8px] font-black text-red-400 uppercase tracking-widest">Delete Draft</button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'VAULT' && isPremium && (
            <div className="space-y-8 animate-in fade-in duration-500">
               <div className="bg-zinc-50 border border-zinc-100 p-8 rounded-[3rem] shadow-sm space-y-6">
                  <div className="px-2">
                    <h3 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest">Neural Vault</h3>
                    <p className="text-[8px] text-zinc-400 font-bold uppercase tracking-widest mt-1">Encrypted records & secure intellectual property</p>
                  </div>
                  <div className="space-y-4">
                    <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Entry Header" className="w-full bg-white border border-zinc-100 rounded-2xl px-5 py-3.5 text-xs font-bold text-zinc-900 outline-none shadow-sm" />
                    <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Encrypted content..." className="w-full bg-white border border-zinc-100 rounded-2xl px-5 py-3.5 text-xs font-bold text-zinc-900 outline-none shadow-sm h-24 resize-none" />
                  </div>
                  <button onClick={addItem} className="w-full py-4 rounded-2xl bg-zinc-900 text-white font-black uppercase text-[10px] tracking-widest active:scale-95 shadow-lg">Seal into Vault</button>
               </div>
               <div className="grid gap-4">
                  {(user.vault || []).map(item => (
                    <div key={item.id} className="p-6 bg-white border border-zinc-100 rounded-[2.5rem] shadow-sm group flex items-center justify-between">
                       <div className="flex items-center gap-4">
                          <div className="w-8 h-8 rounded-full bg-zinc-50 border border-zinc-100 flex items-center justify-center">
                            <svg className="w-4 h-4 text-zinc-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
                          </div>
                          <div>
                            <h4 className="text-[11px] font-black text-zinc-900 uppercase tracking-widest">{item.title}</h4>
                            <p className="text-[9px] text-zinc-400 font-bold uppercase">Stored Encrypted</p>
                          </div>
                       </div>
                       <button onClick={() => removeItem(item.id, 'vault')} className="text-[8px] font-black text-red-300 hover:text-red-500 uppercase tracking-widest">Purge</button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'REQUESTS' && isOwner && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <div className="px-2">
                  <h3 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest">Neural Elevation Queue</h3>
                  <p className="text-[8px] text-zinc-400 font-bold uppercase tracking-widest mt-1">Pending user upgrade requests</p>
               </div>
               <div className="grid gap-4">
                  {upgradeRequests.length > 0 ? upgradeRequests.filter(r => r.status === 'PENDING').map(req => (
                    <div key={req.id} className="p-6 bg-white border border-zinc-100 rounded-[2.5rem] shadow-sm space-y-4">
                       <div className="flex justify-between items-start">
                          <div>
                            <p className="text-[11px] font-black text-zinc-900 uppercase">{req.userName}</p>
                            <p className="text-[9px] text-zinc-400 font-bold uppercase">{req.userEmail}</p>
                          </div>
                          <span className="text-[8px] px-2 py-0.5 bg-amber-50 text-amber-600 rounded-full font-black uppercase tracking-widest">REQ: {req.requestedTier}</span>
                       </div>
                       <div className="p-4 bg-zinc-50 rounded-2xl text-[10px] text-zinc-600 italic leading-relaxed border border-zinc-100">
                          "{req.message}"
                       </div>
                       <div className="flex gap-2">
                          <button onClick={() => handleActionRequest(req.id, true)} className="flex-1 py-3 bg-zinc-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-md">Approve</button>
                          <button onClick={() => handleActionRequest(req.id, false)} className="flex-1 py-3 border border-red-100 text-red-500 rounded-xl text-[9px] font-black uppercase tracking-widest">Deny</button>
                       </div>
                    </div>
                  )) : (
                    <div className="py-20 text-center border-2 border-dashed border-zinc-100 rounded-[3rem] text-[9px] font-black text-zinc-200 uppercase tracking-[0.5em]">No Pending Requests</div>
                  )}
               </div>
            </div>
          )}

          {tab === 'TIMELINE' && (
            <div className="space-y-8 animate-in fade-in duration-500">
               <div className="bg-zinc-50 border border-zinc-100 p-8 rounded-[3rem] shadow-sm flex gap-2">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Establish Directive..." className="flex-1 bg-white border border-zinc-100 rounded-2xl px-5 py-3.5 text-xs font-bold text-zinc-900 outline-none shadow-sm" />
                  <button onClick={addItem} className="p-4 rounded-2xl bg-zinc-900 text-white shadow-lg active:scale-95 transition-all">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                  </button>
               </div>
               <div className="grid gap-4">
                  {user.reminders.map(r => (
                    <div key={r.id} className="p-6 bg-white border border-zinc-100 rounded-[2rem] shadow-sm flex items-center justify-between group">
                       <div className="flex items-center gap-4">
                          <div className={`w-2 h-2 rounded-full ${r.completed ? 'bg-zinc-200' : 'bg-zinc-900'}`} />
                          <p className={`text-xs font-bold uppercase tracking-widest ${r.completed ? 'text-zinc-300 line-through' : 'text-zinc-800'}`}>{r.text}</p>
                       </div>
                       <button onClick={() => removeItem(r.id, 'reminders')} className="p-2 text-zinc-200 hover:text-red-500 transition-colors">
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                       </button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'PROJECTS' && (
            <div className="space-y-8 animate-in fade-in duration-500">
               <div className="bg-zinc-50 border border-zinc-100 p-8 rounded-[3rem] shadow-sm space-y-6">
                  <div className="space-y-4">
                    <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Project Name" className="w-full bg-white border border-zinc-100 rounded-2xl px-5 py-3.5 text-xs font-bold text-zinc-900 outline-none shadow-sm" />
                    <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Project Description..." className="w-full bg-white border border-zinc-100 rounded-2xl px-5 py-3.5 text-xs font-bold text-zinc-900 outline-none shadow-sm h-24 resize-none" />
                  </div>
                  <button onClick={addItem} className="w-full py-4 rounded-2xl bg-zinc-900 text-white font-black uppercase text-[10px] tracking-widest active:scale-95 shadow-lg">Create Project</button>
               </div>
               <div className="grid gap-4">
                  {user.projects.map(p => (
                    <div key={p.id} className="p-6 bg-white border border-zinc-100 rounded-[2.5rem] shadow-sm group">
                       <h4 className="text-[11px] font-black text-zinc-900 uppercase tracking-widest">{p.name}</h4>
                       <p className="text-[10px] text-zinc-400 font-bold leading-relaxed">{p.description}</p>
                       <button onClick={() => removeItem(p.id, 'projects')} className="mt-4 text-[8px] font-black text-red-400 uppercase tracking-widest">Archive</button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'USERS' && isOwner && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <input 
                  value={searchTerm} 
                  onChange={e => setSearchTerm(e.target.value)}
                  placeholder="Search user database..." 
                  className="w-full bg-zinc-50 border border-zinc-100 rounded-2xl px-6 py-4 text-xs text-zinc-900 outline-none shadow-sm"
                />
                <div className="grid gap-4">
                   {allUsers.filter(u => u.name.toLowerCase().includes(searchTerm.toLowerCase())).map(u => (
                     <div key={u.id} className="p-6 bg-white border border-zinc-100 rounded-[2rem] shadow-sm flex items-center justify-between">
                        <div className="flex items-center gap-4">
                           <div className="w-10 h-10 rounded-full bg-zinc-900 text-white flex items-center justify-center font-black text-xs">{u.name.charAt(0)}</div>
                           <div>
                              <p className="text-xs font-black text-zinc-900 uppercase">{u.name}</p>
                              <p className="text-[9px] text-zinc-400 font-bold uppercase">{u.tier}</p>
                           </div>
                        </div>
                     </div>
                   ))}
                </div>
            </div>
          )}
        </div>

        <div className="shrink-0 p-8 border-t border-zinc-50 bg-white z-20">
          <button 
            onClick={() => {
               if(window.confirm("Purge thread context and establish new synapse?")) {
                 onClearHistory();
                 onClose();
               }
            }}
            className="w-full py-5 rounded-[2rem] bg-zinc-900 text-white font-black uppercase text-[10px] tracking-[0.4em] active:scale-[0.98] transition-all shadow-xl flex items-center justify-center gap-3"
          >
            Establish New Thread
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Message, Role, SubscriptionTier } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
  userTier: SubscriptionTier;
  onVocalize?: (id: string, content: string) => void;
  onEditMessage?: (id: string, newContent: string) => void;
  onDeleteMessage?: (id: string) => void;
  onSaveToMemory?: (content: string) => void;
  onSaveToReminders?: (content: string) => void;
  speakingId?: string | null;
}

export const MessageList: React.FC<MessageListProps> = ({ 
  messages, 
  isThinking, 
  ownerName, 
  isOwnerView,
  userTier,
  onVocalize,
  onEditMessage,
  onDeleteMessage,
  onSaveToMemory,
  onSaveToReminders,
  speakingId
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');
  const [contextMenuId, setContextMenuId] = useState<string | null>(null);
  const longPressTimer = useRef<any>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  const handleStartEdit = (msg: Message) => {
    setEditingId(msg.id);
    setEditValue(msg.content);
    setContextMenuId(null);
  };

  const handleSaveEdit = () => {
    if (editingId && onEditMessage) {
      onEditMessage(editingId, editValue);
    }
    setEditingId(null);
  };

  const handleTouchStart = (msgId: string) => {
    longPressTimer.current = setTimeout(() => {
      setContextMenuId(msgId);
      if (window.navigator.vibrate) window.navigator.vibrate(50);
    }, 600);
  };

  const handleTouchEnd = () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
  };

  const handleTouchMove = () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
  };

  const isPro = userTier === SubscriptionTier.PRO || isOwnerView;

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-8 pt-10 pb-20 space-y-10 max-w-5xl mx-auto w-full scroll-smooth no-scrollbar relative z-10 touch-pan-y">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isAnora = msg.role === 'anora';
        const isSynthesis = !isUser && msg.images && msg.images.length > 0;
        const isSpeaking = speakingId === msg.id;
        const isEditing = editingId === msg.id;
        const isMenuOpen = contextMenuId === msg.id;

        let bubbleClass = "";
        if (isUser) {
          if (isOwnerView) {
            bubbleClass = "bg-zinc-900 border-amber-500/50 text-white shadow-xl rounded-tr-none";
          } else if (isPro) {
            bubbleClass = "bg-indigo-600 border-indigo-500 text-white rounded-tr-none";
          } else {
            bubbleClass = "bg-zinc-800 text-white border-zinc-700 rounded-tr-none";
          }
        } else {
          if (isOwnerView) {
            bubbleClass = "bg-zinc-50 border-amber-500/10 text-zinc-900 rounded-tl-none backdrop-blur-3xl shadow-sm";
          } else {
            bubbleClass = "bg-zinc-100/50 text-zinc-800 border-zinc-200/50 rounded-tl-none backdrop-blur-3xl";
          }
        }

        return (
          <div
            key={msg.id}
            className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-1000 fill-mode-both ease-out relative`}
            style={{ animationDelay: `${index * 30}ms` }}
          >
            <div className={`max-w-[92%] sm:max-w-[85%] group relative ${isMenuOpen ? 'z-[100] scale-[1.02]' : 'z-10'} transition-all duration-300`}>
              <div className={`flex items-center gap-3 mb-2 px-2 transition-all duration-500 opacity-60 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[9px] font-bold uppercase tracking-[0.2em] ${isUser ? (isOwnerView ? 'text-amber-600' : isPro ? 'text-indigo-600' : 'text-zinc-600') : 'text-zinc-400'}`}>
                  {isUser ? (isOwnerView ? 'Sovereign' : isPro ? 'Neural Pro' : ownerName.split(' ')[0]) : (isSynthesis ? 'Synthesis' : 'Anora')}
                </span>
                <div className="w-0.5 h-0.5 rounded-full bg-zinc-200"></div>
                <span className="text-[8px] text-zinc-300 font-bold uppercase tracking-widest">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>

              {msg.images && msg.images.length > 0 && !isEditing && (
                <div className={`grid gap-2 mb-3 animate-in zoom-in-95 duration-700 ${msg.images.length === 4 ? 'grid-cols-2' : (msg.images.length > 1 ? 'flex flex-wrap' : 'flex')} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[1.8rem] sm:rounded-[2.5rem] border shadow-md transition-all hover:border-zinc-400
                      ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-200'} 
                      ${msg.images && msg.images.length === 1 ? 'w-64 h-64 sm:w-80 sm:h-80' : 'w-full aspect-square'}`}>
                      <img src={img} alt="V" className="w-full h-full object-cover transition-transform duration-[2s] group-hover/img:scale-110" />

                      {/* Download Button Overlay */}
                      <a 
                        href={img} 
                        download={`anora_asset_${Date.now()}.png`} 
                        className="absolute bottom-4 right-4 p-3 bg-white/90 backdrop-blur-md rounded-2xl text-zinc-900 opacity-0 group-hover/img:opacity-100 transition-all shadow-xl hover:bg-white active:scale-90"
                        title="Download Asset"
                      >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                        </svg>
                      </a>
                    </div>
                  ))}
                </div>
              )}

              <div 
                onMouseDown={() => handleTouchStart(msg.id)}
                onMouseUp={handleTouchEnd}
                onMouseLeave={handleTouchEnd}
                onTouchStart={() => handleTouchStart(msg.id)}
                onTouchEnd={handleTouchEnd}
                onTouchEnd={handleTouchEnd}
                className={`rounded-[2rem] sm:rounded-[3rem] px-6 sm:px-10 py-5 sm:py-8 text-sm sm:text-base leading-relaxed shadow-sm transition-all duration-700 relative ring-1 ring-black/5 select-none touch-pan-y ${bubbleClass} ${isMenuOpen ? 'ring-2 ring-zinc-900/10' : ''}`}
              >
                {isUser && isOwnerView && <div className="absolute -top-1 -right-1 w-3 h-3 bg-amber-500 rounded-full border-2 border-white shadow-md"></div>}

                {isEditing ? (
                  <div className="space-y-4 py-2 animate-in fade-in duration-300">
                    <textarea 
                      value={editValue}
                      onChange={(e) => setEditValue(e.target.value)}
                      className="w-full bg-white/40 border border-zinc-200 rounded-2xl p-4 text-sm sm:text-base text-zinc-900 outline-none focus:border-zinc-400 transition-all resize-none min-h-[100px]"
                      autoFocus
                    />
                    <div className="flex gap-2 justify-end">
                      <button onClick={() => setEditingId(null)} className="px-4 py-2 text-[10px] font-bold uppercase tracking-widest text-zinc-400 hover:text-zinc-900 transition-colors">Abort</button>
                      <button onClick={handleSaveEdit} className={`px-6 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest active:scale-95 transition-all ${isOwnerView ? 'bg-amber-500 text-black' : 'bg-zinc-900 text-white'}`}>Synchronize</button>
                    </div>
                  </div>
                ) : (
                  <div className="prose prose-zinc max-w-none whitespace-pre-wrap font-medium tracking-tight">
                    {msg.content}
                  </div>
                )}

                {/* Standard Actions (Always Visible) */}
                {isAnora && onVocalize && !isEditing && (
                  <div className="absolute top-4 -right-12 flex flex-col gap-2 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-all duration-300 translate-x-4 sm:translate-x-4 sm:group-hover:translate-x-0">
                    <button 
                      onClick={() => onVocalize(msg.id, msg.content)}
                      className={`p-3 rounded-2xl border transition-all hover:scale-110 active:scale-90 shadow-md ${isSpeaking ? (isOwnerView ? 'text-amber-500 border-amber-500/50' : 'text-indigo-600 border-indigo-500/50') : 'text-zinc-400 border-zinc-100 bg-white hover:text-zinc-900'}`}
                    >
                      <svg className={`w-5 h-5 ${isSpeaking ? 'animate-pulse' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                      </svg>
                    </button>
                  </div>
                )}

                {/* Long-Press Neural Menu */}
                {isMenuOpen && (
                  <div className="absolute z-[150] top-0 left-0 w-full h-full flex items-center justify-center pointer-events-none">
                    <div className="bg-white/95 backdrop-blur-xl border border-zinc-100 rounded-[2.5rem] shadow-[0_20px_60px_-15px_rgba(0,0,0,0.15)] flex flex-col p-2 min-w-[200px] animate-in zoom-in duration-300 pointer-events-auto">
                      <button 
                        onClick={() => {
                          navigator.clipboard.writeText(msg.content);
                          setContextMenuId(null);
                        }}
                        className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item"
                      >
                        <svg className="w-4 h-4 text-zinc-400 group-hover/item:text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                        <span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Copy Intel</span>
                      </button>

                      {onSaveToMemory && (
                        <button 
                          onClick={() => {
                            onSaveToMemory(msg.content);
                            setContextMenuId(null);
                          }}
                          className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item"
                        >
                          <svg className="w-4 h-4 text-zinc-400 group-hover/item:text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" /></svg>
                          <span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Sync to Memory</span>
                        </button>
                      )}

                      {onSaveToReminders && (
                        <button 
                          onClick={() => {
                            onSaveToReminders(msg.content);
                            setContextMenuId(null);
                          }}
                          className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item"
                        >
                          <svg className="w-4 h-4 text-zinc-400 group-hover/item:text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                          <span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Establish Directive</span>
                        </button>
                      )}

                      {isUser && onEditMessage && (
                        <button 
                          onClick={() => handleStartEdit(msg)}
                          className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item"
                        >
                          <svg className="w-4 h-4 text-zinc-400 group-hover/item:text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.636l-3.536 3.536m0 0l-3.536 3.536m3.536-3.536L21.899 2.1c.391-.391.391-1.023 0-1.414-.391-.391-1.023-.391-1.414 0l-3.536 3.536z" /></svg>
                          <span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Refine Intent</span>
                        </button>
                      )}

                      <div className="h-[1px] bg-zinc-100 mx-4 my-2"></div>

                      <button 
                        onClick={() => {
                          if (onDeleteMessage) onDeleteMessage(msg.id);
                          setContextMenuId(null);
                        }}
                        className="flex items-center gap-4 px-6 py-4 hover:bg-red-50 rounded-[1.8rem] transition-colors group/item"
                      >
                        <svg className="w-4 h-4 text-zinc-400 group-hover/item:text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        <span className="text-[10px] font-black uppercase tracking-widest text-red-500">Purge Synapse</span>
                      </button>
                    </div>
                  </div>
                )}

                {msg.sources && msg.sources.length > 0 && !isEditing && (
                  <div className="mt-8 pt-8 border-t border-zinc-100 animate-in fade-in duration-1000">
                    <p className="text-[8px] font-bold text-zinc-300 uppercase tracking-[0.4em] mb-4">VERIFIED INTEL</p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((source, idx) => (
                        <a
                          key={idx}
                          href={source.uri}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center gap-3 px-4 py-3 bg-white border border-zinc-200 rounded-2xl text-[9px] text-zinc-400 hover:text-zinc-900 hover:border-zinc-300 transition-all group/source shadow-sm"
                        >
                          <span className="max-w-[150px] truncate font-bold tracking-wider">{source.title || 'Intel'}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}

      {isThinking && (
        <div className="flex justify-start animate-in fade-in slide-in-from-left-2 duration-700">
          <div className={`bg-white border rounded-[1.8rem] rounded-tl-none px-6 py-4 shadow-sm ring-1 ring-black/5 ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-100'}`}>
            <div className="flex gap-1.5">
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.3s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div>
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.15s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div>
              <div className={`w-1.5 h-1.5 rounded-full animate-bounce ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div>
            </div>
          </div>
        </div>
      )}

      {/* Backdrop for Menu */}
      {contextMenuId && (
        <div 
          onClick={() => setContextMenuId(null)}
          className="fixed inset-0 z-50 bg-black/5 backdrop-blur-sm animate-in fade-in duration-300"
        ></div>
      )}

      <div ref={bottomRef} className="h-10" />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Role, SubscriptionTier, CustomTier, Reminder, TierCapability, UpgradeRequest, NeuralMemoryItem, SiteLog, LyricDraft, VaultItem } from '../types';
import { LANGUAGES } from '../constants';
import { anoraService } from '../services/geminiService';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

const PLAN_FEATURES = {
  FREE: [
    "20,000 Daily Synapse Tokens",
    "Balanced Intelligence Core",
    "Standard Personas",
    "Watermarked Image Synthesis",
    "Basic Timeline & Projects"
  ],
  PRO: [
    "100,000 Daily Synapse Tokens",
    "Deep Reasoning Core (Gemini Pro)",
    "Google Search & Maps Grounding",
    "100 High-Res Images (No Watermark)",
    "20 Cinematic Videos (Veo 3.1)",
    "RHB Engineering Site Logs",
    "Creative Lyric Studio",
    "Encrypted Neural Vault",
    "Advanced Neural Analytics"
  ],
  LIFETIME: [
    "Infinite Synapse Tokens",
    "Priority Sovereign Compute",
    "All Pro Protocols Included",
    "Permanent Neural Bond",
    "Custom AI Mood Synthesizer",
    "Early Access to Neural v9.0"
  ]
};

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROTOCOLS' | 'NEURAL_MEMORY' | 'TIMELINE' | 'PROJECTS' | 'USERS' | 'UPGRADE' | 'REQUESTS' | 'SITE_LOGS' | 'LYRIC_STUDIO' | 'VAULT' | 'ANALYTICS'>('PROTOCOLS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [upgradeRequests, setUpgradeRequests] = useState<UpgradeRequest[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const [requestedTier, setRequestedTier] = useState<SubscriptionTier>(SubscriptionTier.PRO);
  const [upgradeMessage, setUpgradeMessage] = useState('');
  const [isRequesting, setIsRequesting] = useState(false);

  // Payment states
  const [paymentMode, setPaymentMode] = useState<'REQUEST' | 'PAY'>('PAY');
  const [paymentPhase, setPaymentPhase] = useState<'SELECT' | 'PAY_PORTAL' | 'VERIFY'>('SELECT');
  const [selectedPlanPrice, setSelectedPlanPrice] = useState<number>(0);
  const [isVerifyingPayment, setIsVerifyingPayment] = useState(false);
  const [paymentConfirmed, setPaymentConfirmed] = useState(false);
  const [screenshot, setScreenshot] = useState<string | null>(null);
  const [verificationError, setVerificationError] = useState<string | null>(null);
  const [showPlanDetails, setShowPlanDetails] = useState<SubscriptionTier | null>(null);

  const screenshotInputRef = useRef<HTMLInputElement>(null);

  const refreshData = () => {
    const usersData = localStorage.getItem('anora_users_db');
    if (usersData) setAllUsers(JSON.parse(usersData));
    const reqData = localStorage.getItem('anora_upgrade_requests');
    if (reqData) setUpgradeRequests(JSON.parse(reqData));
  };

  useEffect(() => {
    if (isOpen) {
      refreshData();
      setScreenshot(null);
      setVerificationError(null);
    }
  }, [isOpen]);

  const handleScreenshotUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setScreenshot(ev.target?.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleRequestUpgrade = () => {
    if (!upgradeMessage.trim()) {
      alert("Please provide a justification for elevation.");
      return;
    }
    setIsRequesting(true);

    const request: UpgradeRequest = {
      id: `req_${Date.now()}`,
      userId: user.id,
      userName: user.name,
      userEmail: user.email,
      requestedTier: requestedTier,
      message: upgradeMessage,
      timestamp: new Date().toISOString(),
      status: 'PENDING'
    };

    const existing = JSON.parse(localStorage.getItem('anora_upgrade_requests') || '[]');
    localStorage.setItem('anora_upgrade_requests', JSON.stringify([...existing, request]));

    setTimeout(() => {
      setIsRequesting(false);
      setUpgradeMessage('');
      alert("Neural elevation request transmitted to the Sovereign.");
      refreshData();
      setPaymentMode('PAY'); 
    }, 1500);
  };

  const initiatePayment = (tier: SubscriptionTier, price: number) => {
    setRequestedTier(tier);
    setSelectedPlanPrice(price);
    setPaymentPhase('PAY_PORTAL');

    const upiId = "8233538355@ybl";
    const name = "Anora Sovereign";
    const upiLink = `upi://pay?pa=${upiId}&pn=${encodeURIComponent(name)}&am=${price}&cu=INR&tn=Anora%20Neural%20Upgrade`;

    window.location.href = upiLink;
  };

  const handleConfirmActivation = async () => {
    if (!screenshot) {
      alert("Payment receipt screenshot is required for activation.");
      return;
    }

    setPaymentPhase('VERIFY');
    setIsVerifyingPayment(true);
    setVerificationError(null);

    try {
      const result = await anoraService.verifyPaymentScreenshot(screenshot, selectedPlanPrice);

      if (result.verified) {
        const users: User[] = JSON.parse(localStorage.getItem('anora_users_db') || '[]');
        const uIdx = users.findIndex(u => u.id === user.id);

        const updatedUser = { 
          ...user, 
          tier: requestedTier, 
          role: requestedTier === SubscriptionTier.PRO || requestedTier === SubscriptionTier.LIFETIME ? Role.PREMIUM : user.role 
        };

        if (uIdx !== -1) {
          users[uIdx] = updatedUser;
          localStorage.setItem('anora_users_db', JSON.stringify(users));
        }

        onUpdate(updatedUser);
        setIsVerifyingPayment(false);
        setPaymentConfirmed(true);

        setTimeout(() => {
          setPaymentConfirmed(false);
          setPaymentPhase('SELECT');
          setScreenshot(null);
          alert(`Neural Link Ascended to ${requestedTier}. Welcome to the Sovereign Core.`);
        }, 1500);
      } else {
        setIsVerifyingPayment(false);
        setVerificationError(result.reason || "Payment criteria not fulfilled. Verification declined.");
      }
    } catch (err) {
      console.error("Verification error:", err);
      setIsVerifyingPayment(false);
      setVerificationError("Neural bridge failed to analyze the asset. Please try again with a clear screenshot.");
    }
  };

  const handleActionRequest = (requestId: string, approve: boolean) => {
    const requests: UpgradeRequest[] = JSON.parse(localStorage.getItem('anora_upgrade_requests') || '[]');
    const reqIndex = requests.findIndex(r => r.id === requestId);
    if (reqIndex === -1) return;

    const request = requests[reqIndex];
    if (approve) {
      const users: User[] = JSON.parse(localStorage.getItem('anora_users_db') || '[]');
      const uIndex = users.findIndex(u => u.id === request.userId);
      if (uIndex !== -1) {
        users[uIndex].tier = request.requestedTier;
        if (users[uIndex].role === Role.USER) users[uIndex].role = Role.PREMIUM;
        localStorage.setItem('anora_users_db', JSON.stringify(users));
        setAllUsers(users);
        window.dispatchEvent(new Event('anora_database_updated'));
      }
    }

    requests[reqIndex].status = approve ? 'APPROVED' : 'DENIED';
    localStorage.setItem('anora_upgrade_requests', JSON.stringify(requests));
    refreshData();
  };

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, priority: 'MEDIUM', completed: false, dueDate: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'SITE_LOGS') {
      if (!updated.siteLogs) updated.siteLogs = [];
      updated.siteLogs.push({ id: Date.now().toString(), project: newItem, date: new Date().toISOString(), details: newDesc, status: 'PENDING' });
    } else if (tab === 'LYRIC_STUDIO') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: 'GENERAL', content: newDesc, timestamp: new Date().toISOString() });
    } else if (tab === 'VAULT') {
      if (!updated.vault) updated.vault = [];
      updated.vault.push({ id: Date.now().toString(), title: newItem, content: newDesc, type: 'NOTE' });
    }

    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (list === 'memory') updated.memory = (updated.memory || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'vault') updated.vault = (updated.vault || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const updateMemoryCategory = (id: string, category: NeuralMemoryItem['category']) => {
    const updated = { ...user };
    updated.memory = (updated.memory || []).map(m => m.id === id ? { ...m, category } : m);
    onUpdate(updated);
  };

  const setLanguage = (lang: string) => {
    onUpdate({
      ...user,
      preferences: { ...user.preferences, language: lang }
    });
  };

  const isOwner = user.role === Role.OWNER;
  const isPremium = user.tier !== SubscriptionTier.FREE || isOwner;
  const isLifetime = user.tier === SubscriptionTier.LIFETIME;

  const activeTabs = isOwner 
    ? (['PROTOCOLS', 'NEURAL_MEMORY', 'TIMELINE', 'PROJECTS', 'SITE_LOGS', 'LYRIC_STUDIO', 'VAULT', 'ANALYTICS', 'USERS', 'REQUESTS'] as const)
    : isPremium
      ? (['PROTOCOLS', 'NEURAL_MEMORY', 'TIMELINE', 'PROJECTS', 'SITE_LOGS', 'LYRIC_STUDIO', 'VAULT', 'ANALYTICS', 'UPGRADE'] as const)
      : (['PROTOCOLS', 'NEURAL_MEMORY', 'TIMELINE', 'PROJECTS', 'UPGRADE'] as const);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/10 backdrop-blur-xl animate-in fade-in slide-in-from-right duration-300">
      <div className="w-full max-w-xl h-[95dvh] sm:h-full bg-white border-l border-zinc-100 flex flex-col shadow-2xl overflow-hidden rounded-t-[3rem] sm:rounded-none">

        <div className="px-8 py-8 border-b border-zinc-50 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 rounded-2xl bg-zinc-50 flex items-center justify-center border border-zinc-100 shadow-sm">
               <svg className="w-5 h-5 text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
             </div>
             <div>
                <h2 className="text-xl font-black font-outfit text-zinc-900">Neural Hub</h2>
                <p className="text-[9px] uppercase tracking-[0.3em] font-bold text-zinc-400 mt-1">Sovereign Intel v3.5</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 text-zinc-300 hover:text-zinc-900 transition-colors bg-zinc-50 rounded-2xl shadow-sm border border-zinc-100">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="px-8 py-4 border-b border-zinc-50 flex items-center gap-4 overflow-hidden shrink-0">
          <span className="text-[8px] font-black uppercase tracking-widest text-zinc-300 whitespace-nowrap">Language:</span>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
