                    { title: "Synapse Core", detail: "Active long-term memory patterns and synapse persistence.", icon: "M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" },
                    { title: "Responsive Interface", detail: "Interface adapts dynamically to device models and viewport states.", icon: "M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z" }
                  ].map((p, i) => (
                    <div key={i} className="p-6 bg-zinc-50 border border-zinc-100 rounded-[2.5rem] group hover:border-zinc-300 transition-all shadow-sm">
