import { LANGUAGES } from '../constants';
import { anoraService } from '../services/geminiService';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

const PLAN_FEATURES = {
  FREE: [
    "20,000 Daily Synapse Tokens",
    "Balanced Intelligence Core",
    "Standard Personas",
    "Watermarked Image Synthesis",
    "Basic Timeline & Projects"
  ],
  PRO: [
    "100,000 Daily Synapse Tokens",
    "Deep Reasoning Core (Gemini Pro)",
    "Google Search & Maps Grounding",
    "100 High-Res Images (No Watermark)",
    "20 Cinematic Videos (Veo 3.1)",
    "Direct Audio Manifestation (Voice Replies)",
    "RHB Engineering Site Logs",
    "Creative Lyric Studio",
    "Encrypted Neural Vault",
    "Advanced Neural Analytics"
  ],
  LIFETIME: [
    "Infinite Synapse Tokens",
    "Priority Sovereign Compute",
    "All Pro Protocols Included",
    "Direct Audio Manifestation (Voice Replies)",
    "Permanent Neural Bond",
    "Custom AI Mood Synthesizer",
    "Early Access to Neural v9.0"
  ]
};

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'PROTOCOLS' | 'NEURAL_MEMORY' | 'TIMELINE' | 'PROJECTS' | 'USERS' | 'UPGRADE' | 'REQUESTS' | 'SITE_LOGS' | 'LYRIC_STUDIO' | 'VAULT' | 'ANALYTICS'>('PROTOCOLS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [upgradeRequests, setUpgradeRequests] = useState<UpgradeRequest[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const [requestedTier, setRequestedTier] = useState<SubscriptionTier>(SubscriptionTier.PRO);
  const [upgradeMessage, setUpgradeMessage] = useState('');
  const [isRequesting, setIsRequesting] = useState(false);

  // Payment states
  const [paymentMode, setPaymentMode] = useState<'REQUEST' | 'PAY'>('PAY');
  const [paymentPhase, setPaymentPhase] = useState<'SELECT' | 'PAY_PORTAL' | 'VERIFY'>('SELECT');
  const [selectedPlanPrice, setSelectedPlanPrice] = useState<number>(0);
  const [isVerifyingPayment, setIsVerifyingPayment] = useState(false);
  const [paymentConfirmed, setPaymentConfirmed] = useState(false);
  const [screenshot, setScreenshot] = useState<string | null>(null);
  const [verificationError, setVerificationError] = useState<string | null>(null);
  const [showPlanDetails, setShowPlanDetails] = useState<SubscriptionTier | null>(null);

  const screenshotInputRef = useRef<HTMLInputElement>(null);

  const refreshData = () => {
    const usersData = localStorage.getItem('anora_users_db');
    if (usersData) setAllUsers(JSON.parse(usersData));
    const reqData = localStorage.getItem('anora_upgrade_requests');
    if (reqData) setUpgradeRequests(JSON.parse(reqData));
  };

  useEffect(() => {
    if (isOpen) {
      refreshData();
      setScreenshot(null);
      setVerificationError(null);
    }
  }, [isOpen]);

  const handleScreenshotUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setScreenshot(ev.target?.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleRequestUpgrade = () => {
    if (!upgradeMessage.trim()) {
      alert("Please provide a justification for elevation.");
      return;
    }
    setIsRequesting(true);

    const request: UpgradeRequest = {
      id: `req_${Date.now()}`,
      userId: user.id,
      userName: user.name,
      userEmail: user.email,
      requestedTier: requestedTier,
      message: upgradeMessage,
      timestamp: new Date().toISOString(),
      status: 'PENDING'
    };

    const existing = JSON.parse(localStorage.getItem('anora_upgrade_requests') || '[]');
    localStorage.setItem('anora_upgrade_requests', JSON.stringify([...existing, request]));

    setTimeout(() => {
      setIsRequesting(false);
      setUpgradeMessage('');
      alert("Neural elevation request transmitted to the Sovereign.");
      refreshData();
      setPaymentMode('PAY'); 
    }, 1500);
  };

  const initiatePayment = (tier: SubscriptionTier, price: number) => {
    setRequestedTier(tier);
    setSelectedPlanPrice(price);
    setPaymentPhase('PAY_PORTAL');

    const upiId = "8233538355@ybl";
    const name = "Anora Sovereign";
    const upiLink = `upi://pay?pa=${upiId}&pn=${encodeURIComponent(name)}&am=${price}&cu=INR&tn=Anora%20Neural%20Upgrade`;

    window.location.href = upiLink;
  };

  const handleConfirmActivation = async () => {
    if (!screenshot) {
      alert("Payment receipt screenshot is required for activation.");
      return;
    }

    setPaymentPhase('VERIFY');
    setIsVerifyingPayment(true);
    setVerificationError(null);

    try {
      const result = await anoraService.verifyPaymentScreenshot(screenshot, selectedPlanPrice);

      if (result.verified) {
        const users: User[] = JSON.parse(localStorage.getItem('anora_users_db') || '[]');
        const uIdx = users.findIndex(u => u.id === user.id);

        const updatedUser = { 
          ...user, 
          tier: requestedTier, 
          role: requestedTier === SubscriptionTier.PRO || requestedTier === SubscriptionTier.LIFETIME ? Role.PREMIUM : user.role 
        };

        if (uIdx !== -1) {
          users[uIdx] = updatedUser;
          localStorage.setItem('anora_users_db', JSON.stringify(users));
        }

        onUpdate(updatedUser);
        setIsVerifyingPayment(false);
        setPaymentConfirmed(true);

        setTimeout(() => {
          setPaymentConfirmed(false);
          setPaymentPhase('SELECT');
          setScreenshot(null);
          alert(`Neural Link Ascended to ${requestedTier}. Welcome to the Sovereign Core.`);
        }, 1500);
      } else {
        setIsVerifyingPayment(false);
        setVerificationError(result.reason || "Payment criteria not fulfilled. Verification declined.");
      }
    } catch (err) {
      console.error("Verification error:", err);
      setIsVerifyingPayment(false);
      setVerificationError("Neural bridge failed to analyze the asset. Please try again with a clear screenshot.");
    }
  };

  const handleActionRequest = (requestId: string, approve: boolean) => {
    const requests: UpgradeRequest[] = JSON.parse(localStorage.getItem('anora_upgrade_requests') || '[]');
    const reqIndex = requests.findIndex(r => r.id === requestId);
    if (reqIndex === -1) return;

    const request = requests[reqIndex];
    if (approve) {
      const users: User[] = JSON.parse(localStorage.getItem('anora_users_db') || '[]');
      const uIndex = users.findIndex(u => u.id === request.userId);
      if (uIndex !== -1) {
        users[uIndex].tier = request.requestedTier;
        if (users[uIndex].role === Role.USER) users[uIndex].role = Role.PREMIUM;
        localStorage.setItem('anora_users_db', JSON.stringify(users));
        setAllUsers(users);
        window.dispatchEvent(new Event('anora_database_updated'));
      }
    }

    requests[reqIndex].status = approve ? 'APPROVED' : 'DENIED';
    localStorage.setItem('anora_upgrade_requests', JSON.stringify(requests));
    refreshData();
  };

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, priority: 'MEDIUM', completed: false, dueDate: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'SITE_LOGS') {
      if (!updated.siteLogs) updated.siteLogs = [];
      updated.siteLogs.push({ id: Date.now().toString(), project: newItem, date: new Date().toISOString(), details: newDesc, status: 'PENDING' });
    } else if (tab === 'LYRIC_STUDIO') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: 'GENERAL', content: newDesc, timestamp: new Date().toISOString() });
    } else if (tab === 'VAULT') {
      if (!updated.vault) updated.vault = [];
      updated.vault.push({ id: Date.now().toString(), title: newItem, content: newDesc, type: 'NOTE' });
    }

    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (list === 'memory') updated.memory = (updated.memory || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'vault') updated.vault = (updated.vault || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const updateMemoryCategory = (id: string, category: NeuralMemoryItem['category']) => {
    const updated = { ...user };
    updated.memory = (updated.memory || []).map(m => m.id === id ? { ...m, category } : m);
    onUpdate(updated);
  };

  const setLanguage = (lang: string) => {
    onUpdate({
      ...user,
      preferences: { ...user.preferences, language: lang }
    });
  };

  const isOwner = user.role === Role.OWNER;
  const isPremium = user.tier !== SubscriptionTier.FREE || isOwner;
  const isLifetime = user.tier === SubscriptionTier.LIFETIME;

  const activeTabs = isOwner 
    ? (['PROTOCOLS', 'NEURAL_MEMORY', 'TIMELINE', 'PROJECTS', 'SITE_LOGS', 'LYRIC_STUDIO', 'VAULT', 'ANALYTICS', 'USERS', 'REQUESTS'] as const)
    : isPremium
      ? (['PROTOCOLS', 'NEURAL_MEMORY', 'TIMELINE', 'PROJECTS', 'SITE_LOGS', 'LYRIC_STUDIO', 'VAULT', 'ANALYTICS', 'UPGRADE'] as const)
      : (['PROTOCOLS', 'NEURAL_MEMORY', 'TIMELINE', 'PROJECTS', 'UPGRADE'] as const);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/10 backdrop-blur-xl animate-in fade-in slide-in-from-right duration-300">
      <div className="w-full max-w-xl h-[95dvh] sm:h-full bg-white border-l border-zinc-100 flex flex-col shadow-2xl overflow-hidden rounded-t-[3rem] sm:rounded-none">

        <div className="px-8 py-8 border-b border-zinc-50 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 rounded-2xl bg-zinc-50 flex items-center justify-center border border-zinc-100 shadow-sm">
               <svg className="w-5 h-5 text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
             </div>
             <div>
                <h2 className="text-xl font-black font-outfit text-zinc-900">Neural Hub</h2>
                <p className="text-[9px] uppercase tracking-[0.3em] font-bold text-zinc-400 mt-1">Sovereign Intel v3.5</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 text-zinc-300 hover:text-zinc-900 transition-colors bg-zinc-50 rounded-2xl shadow-sm border border-zinc-100">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="px-8 py-4 border-b border-zinc-50 flex items-center gap-4 overflow-hidden shrink-0">
          <span className="text-[8px] font-black uppercase tracking-widest text-zinc-300 whitespace-nowrap">Language:</span>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            {LANGUAGES.slice(0, 10).map(lang => (
              <button 
                key={lang}
                onClick={() => setLanguage(lang)}
                className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest transition-all whitespace-nowrap border ${user.preferences.language === lang ? 'bg-zinc-900 text-white border-zinc-900 shadow-md' : 'bg-zinc-50 text-zinc-400 border-zinc-100 hover:border-zinc-300'}`}
              >
                {lang}
              </button>
            ))}
          </div>
        </div>

        <div className="flex bg-zinc-50 p-1.5 mx-6 mt-6 rounded-2xl border border-zinc-100 overflow-x-auto no-scrollbar gap-1 shrink-0 shadow-sm">
          {activeTabs.map(t => (
            <button key={t} onClick={() => setTab(t as any)} className={`flex-1 min-w-[90px] py-2.5 text-[8px] font-black uppercase tracking-widest rounded-xl transition-all ${tab === t ? 'bg-zinc-900 text-white shadow-md' : 'text-zinc-400 hover:text-zinc-600'}`}>
              {t.replace('_', ' ')}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-10 no-scrollbar pb-32">
          {tab === 'PROTOCOLS' && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {[
                    { title: "Sovereign Architect", detail: "Arjun Bharti Mina: The master mind. Absolute authority.", icon: "M13 10V3L4 14h7v7l9-11h-7z" },
                    { title: "Synapse Core", detail: "Active long-term memory patterns and synapse persistence.", icon: "M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" },
                    { title: "Responsive Interface", detail: "Interface adapts dynamically to device models and viewport states.", icon: "M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z" }
                  ].map((p, i) => (
                    <div key={i} className="p-6 bg-zinc-50 border border-zinc-100 rounded-[2.5rem] group hover:border-zinc-300 transition-all shadow-sm">
                      <div className="w-10 h-10 rounded-xl bg-white border border-zinc-100 flex items-center justify-center mb-4 group-hover:scale-110 transition-transform shadow-sm">
                        <svg className="w-5 h-5 text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={p.icon} /></svg>
                      </div>
                      <h4 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest mb-2">{p.title}</h4>
                      <p className="text-[9px] text-zinc-400 font-bold leading-relaxed uppercase tracking-wider">{p.detail}</p>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'ANALYTICS' && isPremium && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <div className="p-8 bg-zinc-900 rounded-[3rem] text-white space-y-4 shadow-xl">
                  <h3 className="text-xl font-black uppercase tracking-widest font-outfit">Neural Analytics</h3>
                  <div className="grid grid-cols-2 gap-4 pt-4">
                     <div className="p-4 bg-white/5 rounded-2xl border border-white/10">
                        <p className="text-[8px] font-black uppercase text-zinc-500 mb-1">Total Synapses</p>
                        <p className="text-2xl font-black">{messagesCount}</p>
                     </div>
                     <div className={`p-4 bg-white/5 rounded-2xl border border-white/10 ${isOwner ? 'border-amber-500/20' : ''}`}>
                        <p className="text-[8px] font-black uppercase text-zinc-500 mb-1">Neural Rank</p>
                        <p className="text-sm font-black text-amber-500 uppercase">{user.tier}</p>
                     </div>
                  </div>
               </div>
               <div className="p-6 bg-zinc-50 border border-zinc-100 rounded-[2.5rem] shadow-sm">
                  <h4 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest mb-4">Compute Efficiency</h4>
                  <div className="space-y-3">
                     {[
                       { label: "Reasoning Core", val: isOwner ? 100 : 85 },
                       { label: "Image Manifest", val: isOwner ? 100 : 70 },
                       { label: "Temporal Motion", val: isOwner ? 100 : 40 }
                     ].map((s, i) => (
                       <div key={i} className="space-y-1">
                          <div className="flex justify-between text-[8px] font-black uppercase">
                             <span className="text-zinc-400">{s.label}</span>
                             <span className="text-zinc-900">{s.val}%</span>
                          </div>
                          <div className="h-1 bg-zinc-200 rounded-full overflow-hidden">
                             <div className="h-full bg-zinc-900" style={{ width: `${s.val}%` }}></div>
                          </div>
                       </div>
                     ))}
                  </div>
               </div>
            </div>
          )}

          {tab === 'NEURAL_MEMORY' && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <div className="px-2">
                  <h3 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest">Active Synapse Records</h3>
                  <p className="text-[8px] text-zinc-400 font-bold uppercase tracking-widest mt-1">Stored knowledge and preference patterns</p>
               </div>
               <div className="grid gap-4">
                  {(user.memory || []).length > 0 ? (user.memory || []).map(m => (
                    <div key={m.id} className="p-6 bg-white border border-zinc-100 rounded-[2rem] shadow-sm space-y-4 group">
                       <div className="flex justify-between items-start">
                          <div className="flex gap-2">
                            {(['PERSONAL', 'WORK', 'CREATIVE', 'FACT'] as const).map(cat => (
                              <button 
                                key={cat} 
                                onClick={() => updateMemoryCategory(m.id, cat)}
                                className={`px-2 py-0.5 rounded text-[7px] font-black uppercase tracking-widest transition-all ${m.category === cat ? 'bg-zinc-900 text-white' : 'bg-zinc-100 text-zinc-400 hover:text-zinc-600'}`}
                              >
                                {cat}
                              </button>
                            ))}
                          </div>
                          <button onClick={() => removeItem(m.id, 'memory')} className="p-1 text-zinc-200 hover:text-red-500 transition-colors">
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                          </button>
                       </div>
                       <p className="text-xs text-zinc-800 font-medium leading-relaxed">
                          {m.content}
                       </p>
                       <div className="flex justify-between items-center pt-2">
                          <span className="text-[7px] font-black text-zinc-300 uppercase tracking-widest">STRENGTH: {m.strength}/5</span>
                          <span className="text-[7px] font-black text-zinc-300 uppercase tracking-widest">{new Date(m.timestamp).toLocaleDateString()}</span>
                       </div>
                    </div>
                  )) : (
                    <div className="py-20 text-center border-2 border-dashed border-zinc-100 rounded-[3rem] text-[9px] font-black text-zinc-200 uppercase tracking-[0.5em]">Neural Database Empty</div>
                  )}
               </div>
            </div>
          )}

          {tab === 'UPGRADE' && !isOwner && !isLifetime && (
            <div className="space-y-8 animate-in fade-in duration-500 pb-10">
               <div className="p-8 bg-zinc-900 rounded-[3rem] text-white space-y-4 shadow-xl relative overflow-hidden">
                  <div className="absolute top-4 right-8 opacity-20 rotate-12 scale-150">
                    <svg className="w-24 h-24" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M2.166 4.999A11.954 11.954 0 0010 1.944 11.954 11.954 0 0017.834 5c.11.65.166 1.32.166 2.001 0 5.225-3.34 9.67-8 11.317C5.34 16.67 2 12.225 2 7c0-.682.057-1.35.166-2.001zm11.541 3.708a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                  </div>
                  <h3 className="text-xl font-black font-outfit uppercase tracking-tighter relative z-10">Ascend to Neural Pro</h3>
                  <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest leading-relaxed relative z-10">
                    Unlock visual synthesis, temporal video rendering, and unlimited deep intelligence cores. 
                    Your current status: <span className="text-white font-black">{user.tier}</span>
                  </p>
               </div>

               <div className="flex bg-zinc-100/50 p-1.5 rounded-2xl border border-zinc-200">
                  <button onClick={() => { setPaymentMode('PAY'); setPaymentPhase('SELECT'); }} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest rounded-xl transition-all ${paymentMode === 'PAY' ? 'bg-white text-zinc-900 shadow-sm' : 'text-zinc-400'}`}>Direct Activation</button>
                  <button onClick={() => setPaymentMode('REQUEST')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest rounded-xl transition-all ${paymentMode === 'REQUEST' ? 'bg-white text-zinc-900 shadow-sm' : 'text-zinc-400'}`}>Request to Owner</button>
               </div>

               {paymentMode === 'PAY' ? (
                 <div className="space-y-6 animate-in slide-in-from-bottom-2 duration-500">
                    {paymentPhase === 'SELECT' && (
                      <div className="grid gap-4">
                        {user.tier === SubscriptionTier.FREE && (
                          <div className="space-y-2">
                            <button 
                              onClick={() => setShowPlanDetails(showPlanDetails === SubscriptionTier.PRO ? null : SubscriptionTier.PRO)}
                              className={`w-full group p-6 bg-white border rounded-[2.5rem] transition-all flex items-center justify-between active:scale-95 shadow-sm ${showPlanDetails === SubscriptionTier.PRO ? 'border-zinc-900' : 'border-zinc-100 hover:border-zinc-300'}`}
                            >
                               <div className="text-left">
                                  <p className="text-[11px] font-black text-zinc-900 uppercase">Neural Pro Monthly</p>
                                  <p className="text-[9px] text-zinc-400 font-bold uppercase">Click for feature breakdown</p>
                               </div>
                               <p className="text-lg font-black text-zinc-900">₹499<span className="text-[10px] text-zinc-400 font-bold ml-1">/MO</span></p>
                            </button>
                            {showPlanDetails === SubscriptionTier.PRO && (
                              <div className="p-6 bg-zinc-50 rounded-[2rem] border border-zinc-100 animate-in slide-in-from-top-4 duration-300 space-y-4">
                                <ul className="space-y-2">
                                  {PLAN_FEATURES.PRO.map((f, i) => (
                                    <li key={i} className="flex items-center gap-2 text-[9px] font-bold text-zinc-600 uppercase tracking-widest">
                                      <div className="w-1.5 h-1.5 rounded-full bg-zinc-900"></div>
                                      {f}
                                    </li>
                                  ))}
                                </ul>
                                <button onClick={() => initiatePayment(SubscriptionTier.PRO, 499)} className="w-full py-3 bg-zinc-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">Activate Pro Neural Link</button>
                              </div>
                            )}
                          </div>
                        )}

                        <div className="space-y-2">
                          <button 
                            onClick={() => setShowPlanDetails(showPlanDetails === SubscriptionTier.LIFETIME ? null : SubscriptionTier.LIFETIME)}
                            className={`w-full group p-6 rounded-[2.5rem] transition-all flex items-center justify-between active:scale-95 shadow-xl ${user.tier === SubscriptionTier.FREE ? 'bg-zinc-900 text-white' : 'bg-amber-500 text-black'} ${showPlanDetails === SubscriptionTier.LIFETIME ? 'ring-2 ring-offset-2 ring-zinc-400' : ''}`}
                          >
                             <div className="text-left">
                                <p className={`text-[11px] font-black uppercase ${user.tier === SubscriptionTier.FREE ? 'text-white' : 'text-black'}`}>Neural Sovereign Lifetime</p>
