    if (!currentUser) return false;
    if (currentUser.role === Role.OWNER) return true;

    const tokens = currentUser.tokens || { chat: 0, image: 0, video: 0, audio: 0, lastReset: '' };
    if (tokens[type] < amount) {
      alert(`Neural Resources Exhausted: ${type.toUpperCase()} pool empty for today. Upgrade for higher throughput.`);
      return false;
    }

    const updatedUser = {
      ...currentUser,
      tokens: { ...tokens, [type]: tokens[type] - amount }
    };
    setCurrentUser(updatedUser);
    return true;
  }, [currentUser]);

  const handleNewThread = () => {
    if (!currentUser) return;
    const initialRaw = INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT');
    const { content, affect } = anoraService.parseAffect(initialRaw);
    const initial: Message = { id: 'init_' + Date.now(), role: 'anora', content, affect, timestamp: new Date() };
    setMessages([initial]);
    localStorage.setItem(`anora_history_${currentUser.email}`, JSON.stringify([initial]));
    anoraService.initChat(currentUser);
  };

  const handleLogout = useCallback(() => {
    setCurrentUser(null);
    localStorage.removeItem('anora_session');
    setMessages([]);
  }, []);

  const handleSaveToMemory = useCallback((content: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, memory: [...(currentUser.memory || []), { id: `mem_${Date.now()}`, content, category: 'PERSONAL', timestamp: new Date().toISOString(), strength: 5 }] });
  }, [currentUser]);

  const handleSaveToReminders = useCallback((content: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, reminders: [...(currentUser.reminders || []), { id: `rem_${Date.now()}`, text: content, priority: 'MEDIUM', completed: false, dueDate: new Date().toISOString() }] });
  }, [currentUser]);

  const handleDeleteMessage = useCallback((id: string) => { setMessages(prev => prev.filter(m => m.id !== id)); }, []);

  const toggleVoiceMode = useCallback(async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(t => t.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }
    try {
      if (wakeWordRecognitionRef.current) wakeWordRecognitionRef.current.stop();
      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => session.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
          },
          onclose: () => setIsVoiceMode(false),
          onerror: () => setIsVoiceMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `Anora Voice. User: ${currentUser?.name}. Persona: ${currentUser?.preferences.persona}.`
        }
      });
    } catch (err) { setIsVoiceMode(false); }
  }, [isVoiceMode, currentUser]);

  const handleVocalize = async (id: string, text: string, affect: NeuralAffect = 'SOVEREIGN') => {
    if (activeSourceRef.current) { try { activeSourceRef.current.stop(); } catch (e) {} activeSourceRef.current = null; }
    if (speakingId === id) { setSpeakingId(null); currentVocalizeIdRef.current = null; return; }
    setSpeakingId(id); currentVocalizeIdRef.current = id;
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const base64 = await anoraService.speak(text, currentUser?.preferences.voiceName || 'Kore', affect);
      if (currentVocalizeIdRef.current !== id) return;
      if (!base64) throw new Error("No audio generated");
      const buffer = await decodeAudioData(decode(base64), audioCtxRef.current, 24000, 1);
      const source = audioCtxRef.current.createBufferSource();
      source.buffer = buffer; source.connect(audioCtxRef.current.destination);
      source.onended = () => { if (currentVocalizeIdRef.current === id) setSpeakingId(null); };
      activeSourceRef.current = source; source.start();
    } catch (err) { setSpeakingId(null); }
  };

  const handleSend = async (text: string) => {
    const val = text.trim();
    if (!val && pendingImages.length === 0) return;

    const chatTokenCost = Math.max(1, Math.ceil((val.length || 10) / 3));
    if (!deductTokens('chat', chatTokenCost)) return;

    if (pendingImages.length > 0) {
      if (!deductTokens('image', pendingImages.length)) return;
    }

    const intent = (t: string) => {
      const lower = t.toLowerCase();
      if (lower.includes('cad') || lower.includes('engineering')) return 'ENGINEERING';
      if (lower.includes('music') || lower.includes('lyrics')) return 'CREATIVE';
      return 'GENERAL';
    };

    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: val || "Asset manifest shared.", 
      timestamp: new Date(), 
      images: pendingImages.length > 0 ? [...pendingImages] : undefined, 
      intent: intent(val) as any 
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue(''); 
    setPendingImages([]); 
    setIsThinking(true);

    try {
      const response = await anoraService.sendMessageWithVision(userMsg.content, userMsg.images || []);

      if (response.audioUrl) {
        if (!deductTokens('audio', 1)) {
          response.audioUrl = undefined;
        }
      }

      const anoraMsg: Message = { 
        id: (Date.now()+1).toString(), 
        role: 'anora', 
        content: response.text, 
        sources: (response as any).sources, 
        images: response.images, 
        audioUrl: response.audioUrl,
        affect: response.affect as any, 
        timestamp: new Date() 
      };
      setMessages(prev => [...prev, anoraMsg]);
      if (currentUser?.preferences.autoRead) handleVocalize(anoraMsg.id, anoraMsg.content, anoraMsg.affect);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'system', content: "Neural bridge unstable. Sync deferred.", timestamp: new Date() }]);
    } finally { setIsThinking(false); }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const isOwner = currentUser.role === Role.OWNER;
  const isPremium = currentUser.tier !== SubscriptionTier.FREE || isOwner;
  const accent = isOwner ? '#d4af37' : (isPremium ? '#8b5cf6' : '#3f3f46');

  const handleFileSelect = () => {
    if (!isPremium) {
      alert("Multimodal Integration reserved for Premium/Sovereign tiers.");
      return;
    }
    fileInputRef.current?.click();
  };

  return (
    <div className={`flex flex-col h-[100dvh] bg-white text-zinc-800 overflow-hidden ${currentUser.preferences.font === 'OUTFIT' ? 'font-outfit' : 'font-inter'}`}>
      <style>{`.accent-text { color: ${accent}; } .accent-border { border-color: ${accent}20; }`}</style>
      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onDeductToken={deductTokens} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} onLogout={handleLogout} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} onClearHistory={handleNewThread} messagesCount={messages.length} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <header className="flex items-center justify-between px-6 sm:px-12 pt-[calc(var(--sat)+1rem)] pb-4 border-b border-zinc-100 shrink-0">
        <AnoraLogo size={40} color={accent} />
        <div className="flex items-center gap-4">
          <VoiceIndicator active={isVoiceMode} />
          <div className="flex items-center gap-2 p-1 bg-zinc-50 rounded-full border border-zinc-100">
            <button onClick={() => setIsHubOpen(true)} className="p-2.5 text-zinc-400 hover:text-zinc-900"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg></button>
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-2.5 text-zinc-400 hover:text-zinc-900"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></button>
            <button onClick={() => setIsProfileOpen(true)} className={`w-9 h-9 rounded-full bg-white overflow-hidden flex items-center justify-center text-[10px] font-black ${isOwner ? 'ring-2 ring-amber-500' : 'border border-zinc-200'}`}>
              {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <MessageList messages={messages} isThinking={isThinking} ownerName={currentUser.name} isOwnerView={isOwner} userTier={currentUser.tier} onVocalize={handleVocalize} onDeleteMessage={handleDeleteMessage} onSaveToMemory={handleSaveToMemory} onSaveToReminders={handleSaveToReminders} speakingId={speakingId} />
        <NeuralOrb active={isThinking} affect={activeAffect} speaking={speakingId !== null} color={accent} />
      </main>

      <footer className="px-6 sm:px-12 pb-[calc(var(--sab)+1.5rem)] pt-4 border-t border-zinc-100 shrink-0 bg-white/80 backdrop-blur-xl">
        <div className="max-w-4xl mx-auto space-y-4">
          {pendingImages.length > 0 && (
            <div className="flex gap-3 overflow-x-auto no-scrollbar py-2 px-1 animate-in slide-in-from-bottom-2 duration-300">
               {pendingImages.map((img, idx) => (
                 <div key={idx} className="relative w-16 h-16 rounded-2xl overflow-hidden border border-zinc-100 shadow-md shrink-0 group">
                    <img src={img} className="w-full h-full object-cover" />
                    <button onClick={() => setPendingImages(prev => prev.filter((_, i) => i !== idx))} className="absolute top-1 right-1 p-1 bg-black/60 text-white rounded-full backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity">
                      <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                 </div>
               ))}
            </div>
          )}
          <div className="flex items-center gap-4">
            <button onClick={handleFileSelect} className={`p-4 rounded-2xl bg-zinc-50 border border-zinc-100 transition-all active:scale-95 ${isPremium ? 'text-zinc-400 hover:text-zinc-900' : 'text-zinc-200 opacity-50'}`}>
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
              <input type="file" ref={fileInputRef} hidden multiple accept="image/*" onChange={e => { 
                  const files = e.currentTarget.files; 
                  if (files) (Array.from(files) as File[]).forEach(f => { 
                    const reader = new FileReader(); 
                    reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]); 
                    reader.readAsDataURL(f); 
                  }); 
                  e.target.value = '';
                }} />
            </button>
            <div className="flex-1 relative flex items-center">
              <input type="text" value={inputValue} onChange={e => setInputValue(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)} placeholder={isOwner ? "Sovereign Command..." : "Neural Input..."} className="w-full bg-zinc-50 border border-zinc-100 rounded-[2rem] pl-6 pr-16 py-4.5 outline-none transition-all focus:bg-white focus:ring-1 focus:ring-black/5" />
              <button onClick={() => handleSend(inputValue)} className={`absolute right-1.5 p-3.5 rounded-full transition-all active:scale-90 ${isOwner ? 'bg-amber-500' : 'bg-zinc-900'} text-white shadow-lg`}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { Message, Role, SubscriptionTier } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  ownerName: string;
  isOwnerView: boolean;
  userTier: SubscriptionTier;
  onVocalize?: (id: string, content: string) => void;
  onEditMessage?: (id: string, newContent: string) => void;
  onDeleteMessage?: (id: string) => void;
  onSaveToMemory?: (content: string) => void;
  onSaveToReminders?: (content: string) => void;
  speakingId?: string | null;
}

const decode = (base64: string) => {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  } catch (e) {
    return new Uint8Array(0);
  }
};

const createWavUrl = (base64Pcm: string): string => {
  const pcmData = decode(base64Pcm);
  if (pcmData.length === 0) return "";
  const sampleRate = 24000;
  const numChannels = 1;
  const bitsPerSample = 16;
  const byteRate = (sampleRate * numChannels * bitsPerSample) / 8;
  const blockAlign = (numChannels * bitsPerSample) / 8;

  const wavHeader = new ArrayBuffer(44);
  const view = new DataView(wavHeader);
  const writeString = (view: DataView, offset: number, string: string) => {
    for (let i = 0; i < string.length; i++) view.setUint8(offset + i, string.charCodeAt(i));
  };

  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + pcmData.length, true);
  writeString(view, 8, 'WAVE');
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, byteRate, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitsPerSample, true);
  writeString(view, 36, 'data');
  view.setUint32(40, pcmData.length, true);

  const blob = new Blob([wavHeader, pcmData], { type: 'audio/wav' });
  return URL.createObjectURL(blob);
};

const VocalPlayer: React.FC<{ audioUrl: string, msgId: string }> = ({ audioUrl, msgId }) => {
  const wavUrl = useMemo(() => createWavUrl(audioUrl), [audioUrl]);

  useEffect(() => {
    return () => { if (wavUrl) URL.revokeObjectURL(wavUrl); };
  }, [wavUrl]);

  if (!wavUrl) return null;

  return (
    <div className="pt-2 animate-in slide-in-from-top-2 duration-500">
      <div className="flex items-center gap-3 p-3 bg-black/5 rounded-2xl border border-black/5">
        <audio src={wavUrl} controls className="h-8 flex-1" />
        <a 
          href={wavUrl} 
          download={`anora_vocal_${msgId}.wav`}
          className="p-2 text-zinc-400 hover:text-zinc-900 transition-colors"
          title="Download Manifest"
        >
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
          </svg>
        </a>
      </div>
    </div>
  );
};

export const MessageList: React.FC<MessageListProps> = ({ 
  messages, isThinking, ownerName, isOwnerView, userTier, onVocalize, onEditMessage, onDeleteMessage, onSaveToMemory, onSaveToReminders, speakingId
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');
  const [contextMenuId, setContextMenuId] = useState<string | null>(null);
  const longPressTimer = useRef<any>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isThinking]);

  const handleStartEdit = (msg: Message) => {
    setEditingId(msg.id);
    setEditValue(msg.content);
    setContextMenuId(null);
  };

  const handleSaveEdit = () => {
    if (editingId && onEditMessage) onEditMessage(editingId, editValue);
    setEditingId(null);
  };

  const handleTouchStart = (msgId: string) => {
    longPressTimer.current = setTimeout(() => {
      setContextMenuId(msgId);
      if (window.navigator.vibrate) window.navigator.vibrate(50);
    }, 600);
  };

  const handleTouchEnd = () => { if (longPressTimer.current) clearTimeout(longPressTimer.current); };

  const isPro = userTier === SubscriptionTier.PRO || isOwnerView;

  return (
    <div className="flex-1 overflow-y-auto px-4 sm:px-8 pt-10 pb-20 space-y-10 max-w-5xl mx-auto w-full scroll-smooth no-scrollbar relative z-10 touch-pan-y">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isAnora = msg.role === 'anora';
        const isSpeaking = speakingId === msg.id;
        const isEditing = editingId === msg.id;
        const isMenuOpen = contextMenuId === msg.id;

        let bubbleClass = isUser 
          ? (isOwnerView ? "bg-zinc-900 border-amber-500/50 text-white shadow-xl rounded-tr-none" : isPro ? "bg-indigo-600 border-indigo-500 text-white rounded-tr-none" : "bg-zinc-800 text-white border-zinc-700 rounded-tr-none")
          : (isOwnerView ? "bg-zinc-50 border-amber-500/10 text-zinc-900 rounded-tl-none backdrop-blur-3xl shadow-sm" : "bg-zinc-100/50 text-zinc-800 border-zinc-200/50 rounded-tl-none backdrop-blur-3xl");

        return (
          <div key={msg.id} className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-1000 relative`} style={{ animationDelay: `${index * 30}ms` }}>
            <div className={`max-w-[92%] sm:max-w-[85%] group relative ${isMenuOpen ? 'z-[100] scale-[1.02]' : 'z-10'} transition-all duration-300`}>
              <div className={`flex items-center gap-3 mb-2 px-2 transition-all opacity-60 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[9px] font-bold uppercase tracking-[0.2em] ${isUser ? (isOwnerView ? 'text-amber-600' : isPro ? 'text-indigo-600' : 'text-zinc-600') : 'text-zinc-400'}`}>
                  {isUser ? (isOwnerView ? 'Sovereign' : isPro ? 'Neural Pro' : ownerName.split(' ')[0]) : (msg.images && msg.images.length > 0 ? 'Synthesis' : 'Anora')}
                </span>
                <span className="text-[8px] text-zinc-300 font-bold uppercase tracking-widest">{new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>

              {msg.images && msg.images.length > 0 && !isEditing && (
                <div className={`grid gap-2 mb-3 animate-in zoom-in-95 duration-700 ${msg.images.length === 4 ? 'grid-cols-2' : 'flex flex-wrap'} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[1.8rem] sm:rounded-[2.5rem] border shadow-md transition-all hover:border-zinc-400 ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-200'} ${msg.images && msg.images.length === 1 ? 'w-64 h-64 sm:w-80 sm:h-80' : 'w-full aspect-square'}`}>
                      <img src={img} alt="V" className="w-full h-full object-cover transition-transform duration-[2s] group-hover/img:scale-110" />
                      <a href={img} download={`anora_full_res_${Date.now()}.png`} className="absolute bottom-4 right-4 flex items-center gap-2 px-4 py-3 bg-white/90 backdrop-blur-md rounded-2xl text-zinc-900 opacity-0 group-hover/img:opacity-100 transition-all shadow-2xl active:scale-90"><span className="text-[8px] font-black uppercase tracking-widest">Full Quality</span></a>
                    </div>
                  ))}
                </div>
              )}

              <div onMouseDown={() => handleTouchStart(msg.id)} onMouseUp={handleTouchEnd} onMouseLeave={handleTouchEnd} onTouchStart={() => handleTouchStart(msg.id)} onTouchEnd={handleTouchEnd} className={`rounded-[2rem] sm:rounded-[3rem] px-6 sm:px-10 py-5 sm:py-8 text-sm sm:text-base leading-relaxed shadow-sm transition-all duration-700 relative ring-1 ring-black/5 select-none touch-pan-y ${bubbleClass} ${isMenuOpen ? 'ring-2 ring-zinc-900/10' : ''}`}>
                {isEditing ? (
                  <div className="space-y-4 py-2 animate-in fade-in duration-300">
                    <textarea value={editValue} onChange={(e) => setEditValue(e.target.value)} className="w-full bg-white/40 border border-zinc-200 rounded-2xl p-4 text-zinc-900 outline-none focus:border-zinc-400 transition-all resize-none min-h-[100px]" autoFocus />
                    <div className="flex gap-2 justify-end">
                      <button onClick={() => setEditingId(null)} className="px-4 py-2 text-[10px] font-bold uppercase tracking-widest text-zinc-400 hover:text-zinc-900 transition-colors">Abort</button>
                      <button onClick={handleSaveEdit} className={`px-6 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest active:scale-95 transition-all ${isOwnerView ? 'bg-amber-500 text-black' : 'bg-zinc-900 text-white'}`}>Sync</button>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <div className="prose prose-zinc max-w-none whitespace-pre-wrap font-medium tracking-tight">{msg.content}</div>
                    {msg.audioUrl && <VocalPlayer audioUrl={msg.audioUrl} msgId={msg.id} />}
                  </div>
                )}

                {isAnora && onVocalize && !isEditing && (
                  <div className="absolute top-4 -right-12 flex flex-col gap-2 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-all duration-300 translate-x-4 sm:group-hover:translate-x-0">
                    <button onClick={() => onVocalize(msg.id, msg.content, msg.affect)} className={`p-3 rounded-2xl border transition-all hover:scale-110 active:scale-90 shadow-md ${isSpeaking ? (isOwnerView ? 'text-amber-500 border-amber-500/50' : 'text-indigo-600 border-indigo-500/50') : 'text-zinc-400 border-zinc-100 bg-white hover:text-zinc-900'}`}><svg className={`w-5 h-5 ${isSpeaking ? 'animate-pulse' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg></button>
                  </div>
                )}

                {isMenuOpen && (
                  <div className="absolute z-[150] top-0 left-0 w-full h-full flex items-center justify-center pointer-events-none">
                    <div className="bg-white/95 backdrop-blur-xl border border-zinc-100 rounded-[2.5rem] shadow-2xl flex flex-col p-2 min-w-[200px] animate-in zoom-in duration-300 pointer-events-auto">
                      <button onClick={() => { navigator.clipboard.writeText(msg.content); setContextMenuId(null); }} className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item"><span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Copy Intel</span></button>
                      {onSaveToMemory && <button onClick={() => { onSaveToMemory(msg.content); setContextMenuId(null); }} className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item"><span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Sync to Memory</span></button>}
                      {isUser && onEditMessage && <button onClick={() => handleStartEdit(msg)} className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item"><span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Refine Intent</span></button>}
                      <button onClick={() => { if (onDeleteMessage) onDeleteMessage(msg.id); setContextMenuId(null); }} className="flex items-center gap-4 px-6 py-4 hover:bg-red-50 rounded-[1.8rem] transition-colors group/item"><span className="text-[10px] font-black uppercase tracking-widest text-red-500">Purge Synapse</span></button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}
      {isThinking && <div className="flex justify-start animate-in fade-in slide-in-from-left-2 duration-700"><div className={`bg-white border rounded-[1.8rem] rounded-tl-none px-6 py-4 shadow-sm ring-1 ring-black/5 ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-100'}`}><div className="flex gap-1.5"><div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.3s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div><div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.15s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div><div className={`w-1.5 h-1.5 rounded-full animate-bounce ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div></div></div></div>}
      {contextMenuId && <div onClick={() => setContextMenuId(null)} className="fixed inset-0 z-50 bg-black/5 backdrop-blur-sm animate-in fade-in duration-300"></div>}
      <div ref={bottomRef} className="h-10" />
    </div>
  );
};

export enum Role {
  OWNER = 'OWNER',
  PREMIUM = 'PREMIUM',
  USER = 'USER'
}

export enum SubscriptionTier {
  LIFETIME = 'LIFETIME',
  PRO = 'PRO',
  FREE = 'FREE',
  CUSTOM = 'CUSTOM'
}

export type AiMood = 'CALM' | 'ENERGIZED' | 'STRICT' | 'CREATIVE' | 'SOVEREIGN' | 'ENGINEERING' | string;
export type IntelligenceLevel = 'LITE' | 'BALANCED' | 'DEEP';
export type AppTheme = 'OBSIDIAN' | 'NEURAL_NOISE' | 'MESH_GRADIENT' | 'MINIMAL' | 'SINGULARITY';
export type AppFont = 'INTER' | 'OUTFIT';
export type Persona = 'DEFAULT' | 'FRIEND' | 'TEACHER' | 'MENTOR' | 'GIRLFRIEND' | 'BOYFRIEND' | 'BROTHER' | 'SISTER' | 'SOVEREIGN_AI';
export type AppColorMode = 'WHITE' | 'DARK' | 'MIDNIGHT' | 'SOLAR';

export type NeuralAffect = 'SOVEREIGN' | 'RADIANT' | 'MELANCHOLY' | 'CRIMSON' | 'VALIANT' | 'EXCITED';
export type ImageAspectRatio = '1:1' | '4:3' | '3:4' | '16:9' | '9:16';

export interface TokenUsage {
  chat: number;
  image: number;
  video: number;
