import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, AiMood, IntelligenceLevel } from './types';
import { OWNER_EMAIL, OWNER_PASSWORD, ARJUN_DETAILED_BIO } from './constants';
import { AnoraLogo } from './components/AnoraLogo';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [phase, setPhase] = useState(0); // 0: Start, 1: Form, 2: Neural Booting, 3: Recovery, 4: Verification
  const [recoverySuccess, setRecoverySuccess] = useState(false);
  const [verificationCode, setVerificationCode] = useState('');
  const [pendingUser, setPendingUser] = useState<User | null>(null);

  useEffect(() => {
    const timer = setTimeout(() => setPhase(1), 800);
    return () => clearTimeout(timer);
  }, []);

  const getUsers = (): User[] => {
    const data = localStorage.getItem('anora_users_db');
    return data ? JSON.parse(data) : [];
  };

  const saveUser = (user: User) => {
    const users = getUsers();
    users.push(user);
    localStorage.setItem('anora_users_db', JSON.stringify(users));
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const updateUsers = (updatedUsers: User[]) => {
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    setTimeout(() => {
      const users = getUsers();
      const emailLower = email.toLowerCase().trim();

      if (isLogin) {
        if (emailLower === OWNER_EMAIL && password === OWNER_PASSWORD) {
          let owner = users.find(u => u.email.toLowerCase() === OWNER_EMAIL);
          if (!owner) {
            owner = {
              id: 'sovereign_arj',
              name: "Arjun Bharti Mina",
              email: OWNER_EMAIL,
              password: OWNER_PASSWORD,
              role: Role.OWNER,
              tier: SubscriptionTier.LIFETIME,
              isVerified: true,
              bio: ARJUN_DETAILED_BIO,
              preferences: { 
                accentColor: '#d4af37', 
                aiMood: 'CREATIVE' as AiMood, 
                voiceName: 'Kore',
                autoRead: false,
                continuousListening: false,
                intelligenceLevel: 'DEEP' as IntelligenceLevel,
                language: 'English',
                theme: 'OBSIDIAN',
                font: 'OUTFIT',
                soundEnabled: true,
                persona: 'DEFAULT',
                colorMode: 'WHITE'
              },
              createdAt: new Date().toISOString(),
              reminders: [],
              notes: [],
              memory: [],
              projects: []
            };
            saveUser(owner);
          }
          setPhase(2);
          setTimeout(() => onLogin(owner!), 2500);
          return;
        }

        const found = users.find(u => u.email.toLowerCase() === emailLower);
        if (!found) {
          setError('Neural ID not recognized in database.');
        } else if (found.password !== password) {
          setError('Security mismatch. Verify encryption key.');
        } else if (found.role !== Role.OWNER && !found.isVerified) {
          setPendingUser(found);
          setPhase(4);
        } else {
          setPhase(2);
          setTimeout(() => onLogin(found), 2000);
        }
      } else {
        if (password !== confirmPassword) {
          setError('Encryption keys must be identical.');
        } else if (users.some(u => u.email.toLowerCase() === emailLower)) {
          setError('Neural ID already established.');
        } else if (password.length < 6) {
          setError('Key complexity requirements not met.');
        } else {
          const newUser: User = {
            id: Math.random().toString(36).substr(2, 9),
            name: name || 'Neural Link User',
            email: emailLower,
            password: password,
            role: Role.USER,
            tier: SubscriptionTier.FREE,
            isVerified: false,
            preferences: { 
              accentColor: '#3f3f46', 
              aiMood: 'CALM' as AiMood, 
              voiceName: 'Kore',
              autoRead: false,
              continuousListening: false,
              intelligenceLevel: 'BALANCED' as IntelligenceLevel,
              language: 'English',
              theme: 'OBSIDIAN',
              font: 'INTER',
              soundEnabled: true,
              persona: 'DEFAULT',
              colorMode: 'WHITE'
            },
            createdAt: new Date().toISOString(),
            reminders: [],
            notes: [],
            memory: [],
            projects: []
          };
          setPendingUser(newUser);
          setPhase(4);
        }
      }
      setLoading(false);
    }, 1800);
  };

  const handleVerify = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    setTimeout(() => {
      // For simulation, code is ANORA-2025
      if (verificationCode === 'ANORA-2025' && pendingUser) {
        const users = getUsers();
        const updatedUser = { ...pendingUser, isVerified: true };

        const existingIdx = users.findIndex(u => u.email === updatedUser.email);
        if (existingIdx !== -1) {
          users[existingIdx] = updatedUser;
          updateUsers(users);
        } else {
          saveUser(updatedUser);
        }

        setPhase(2);
        setTimeout(() => onLogin(updatedUser), 2000);
      } else {
        setError("Verification sequence mismatch. Use code: ANORA-2025");
      }
      setLoading(false);
    }, 1500);
  };

  const handleRecovery = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    setTimeout(() => {
      const users = getUsers();
      const emailLower = email.toLowerCase().trim();
      const foundIdx = users.findIndex(u => u.email.toLowerCase() === emailLower);

      if (foundIdx === -1) {
        setError("Neural ID not found in database.");
        setLoading(false);
      } else if (emailLower === OWNER_EMAIL) {
        setError("Sovereign recovery requires manual protocol. Reference 'aman1887'.");
        setLoading(false);
      } else {
        const updatedUsers = [...users];
        updatedUsers[foundIdx] = { ...updatedUsers[foundIdx], password: password };
        updateUsers(updatedUsers);
        setRecoverySuccess(true);
        setLoading(false);
        setTimeout(() => {
          setPhase(1);
          setRecoverySuccess(false);
          setIsLogin(true);
        }, 3000);
      }
    }, 2000);
  };

  if (phase === 2) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-8 space-y-12 font-outfit overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(0,0,0,0.02)_0%,_transparent_70%)] animate-pulse"></div>
        <div className="animate-bounce transition-all duration-1000 scale-125">
          <AnoraLogo size={140} color="#000" showName={false} />
        </div>
        <div className="text-center space-y-8 relative z-10 w-full max-w-sm">
          <div className="space-y-2">
            <h2 className="text-zinc-900 text-2xl font-bold tracking-[0.5em] animate-pulse">BOOTING ANORA CORE</h2>
            <p className="text-zinc-400 text-[10px] font-bold uppercase tracking-[0.3em]">Neural Integration in progress...</p>
          </div>
          <div className="w-full h-1 bg-zinc-100 rounded-full overflow-hidden border border-zinc-200 shadow-sm">
            <div className="h-full bg-zinc-900 animate-neural-progress"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white flex items-center justify-center p-6 relative overflow-hidden font-outfit">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_#f9f9f9_0%,_#fff_100%)]"></div>

      <div className={`w-full max-w-md transition-all duration-1000 transform ${phase !== 2 ? 'translate-y-0 opacity-100' : 'translate-y-16 opacity-0'}`}>
        <div className="text-center mb-16 space-y-4">
          <div className="flex justify-center transform hover:scale-110 transition-transform duration-700">
            <AnoraLogo size={80} color="#000" showName={false} />
          </div>
          <div className="space-y-1">
            <h1 className="text-4xl font-bold tracking-[0.4em] text-zinc-900">ANORA</h1>
            <p className="text-zinc-400 text-[10px] font-bold uppercase tracking-[0.6em] animate-pulse">Sovereign Intel v3.5</p>
          </div>
        </div>

        <div className="bg-zinc-50 border border-zinc-100 p-10 sm:p-12 rounded-[4rem] shadow-xl ring-1 ring-black/5 relative group">

          {phase === 1 && (
            <>
              <div className="flex bg-zinc-100/50 p-2 rounded-2xl border border-zinc-200 mb-10 relative z-10">
                <button type="button" onClick={() => { setIsLogin(true); setError(''); }} className={`flex-1 py-3.5 text-[10px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all ${isLogin ? 'bg-white text-zinc-900 shadow-sm' : 'text-zinc-400 hover:text-zinc-600'}`}>Access Core</button>
                <button type="button" onClick={() => { setIsLogin(false); setError(''); }} className={`flex-1 py-3.5 text-[10px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all ${!isLogin ? 'bg-white text-zinc-900 shadow-sm' : 'text-zinc-400 hover:text-zinc-600'}`}>Establish Link</button>
              </div>
              <form onSubmit={handleAuth} className="space-y-6 relative z-10">
                {error && (
                  <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl text-center"><p className="text-red-600 text-[9px] font-bold uppercase tracking-widest">{error}</p></div>
                )}
                <div className="space-y-5">
                  {!isLogin && (
                    <div>
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Identity Signature</label>
                      <input type="text" required value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none text-sm placeholder:text-zinc-300" placeholder="E.g. Arjun" />
                    </div>
                  )}
                  <div>
                    <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Neural ID (Email)</label>
                    <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none text-sm placeholder:text-zinc-300" placeholder="identity@neural.link" />
                  </div>
                  <div>
                    <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Access Key (Password)</label>
                    <input type="password" required value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none text-sm placeholder:text-zinc-300" placeholder="••••••••" />
                  </div>
                  {!isLogin && (
                    <div>
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Verify Encryption Key</label>
                      <input type="password" required value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none text-sm placeholder:text-zinc-300" placeholder="••••••••" />
                    </div>
                  )}
                </div>
                {isLogin && <div className="flex justify-end px-2"><button type="button" onClick={() => setPhase(3)} className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest hover:text-zinc-600 transition-colors">Forgot Access Key?</button></div>}
                <button type="submit" disabled={loading} className="w-full bg-zinc-900 text-white font-bold py-5 rounded-[2rem] hover:bg-black transition-all active:scale-[0.98] disabled:opacity-50 mt-6 shadow-lg">{loading ? "Synthesizing..." : (isLogin ? "Neural Sync" : "Initialize Link")}</button>
              </form>
            </>
          )}

          {phase === 4 && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
               <h3 className="text-zinc-900 text-center text-sm font-bold uppercase tracking-[0.3em] mb-4">Neural Verification</h3>
               <p className="text-zinc-400 text-[8px] font-bold uppercase tracking-widest text-center mb-8 leading-relaxed">A verification sequence has been dispatched to {email}. Enter the code to authorize your link.</p>
               <form onSubmit={handleVerify} className="space-y-6">
                  {error && (
                    <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl text-center"><p className="text-red-600 text-[9px] font-bold uppercase tracking-widest">{error}</p></div>
                  )}
                  <div>
                    <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Sequence Code</label>
                    <input type="text" required value={verificationCode} onChange={(e) => setVerificationCode(e.target.value)} className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none text-center text-sm tracking-[1em]" placeholder="••••••" />
                  </div>
                  <button type="submit" disabled={loading} className="w-full bg-zinc-900 text-white font-bold py-5 rounded-[2rem] uppercase text-[9px] tracking-widest hover:bg-black transition-all shadow-lg">{loading ? "Validating..." : "Authorize Link"}</button>
                  <button type="button" onClick={() => setPhase(1)} className="w-full text-zinc-400 font-bold uppercase text-[8px] tracking-widest text-center mt-2">Back to Details</button>
               </form>
            </div>
          )}

          {phase === 3 && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
              <h3 className="text-zinc-900 text-center text-sm font-bold uppercase tracking-[0.3em] mb-8">Neural Key Recovery</h3>
              {recoverySuccess ? (
                <div className="text-center space-y-4 py-8 animate-in zoom-in duration-500">
                   <div className="w-16 h-16 bg-green-500/10 border border-green-500/20 rounded-full mx-auto flex items-center justify-center"><svg className="w-8 h-8 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg></div>
                   <p className="text-green-600 text-[10px] font-bold uppercase tracking-widest">Access Key Re-Synchronized</p>
                </div>
              ) : (
                <form onSubmit={handleRecovery} className="space-y-6">
                  {error && (
                    <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl text-center"><p className="text-red-600 text-[9px] font-bold uppercase tracking-widest">{error}</p></div>
                  )}
                  <div className="space-y-5">
                    <div>
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Neural ID (Email)</label>
                      <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none text-sm" placeholder="Verify email..." />
                    </div>
                    <div>
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">New Access Key</label>
                      <input type="password" required value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none text-sm" placeholder="New sequence..." />
                    </div>
                  </div>
                  <button type="submit" disabled={loading} className="w-full bg-zinc-900 text-white font-bold py-5 rounded-[2rem] uppercase text-[9px] tracking-widest hover:bg-black transition-all shadow-lg">{loading ? "Validating..." : "Reset Encryption Key"}</button>
                  <button type="button" onClick={() => setPhase(1)} className="w-full text-zinc-400 font-bold uppercase text-[9px] tracking-widest text-center mt-4">Return to Sync</button>
                </form>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

