                    <textarea value={editValue} onChange={(e) => setEditValue(e.target.value)} className="w-full bg-white/40 border border-zinc-200 rounded-2xl p-4 text-zinc-900 outline-none focus:border-zinc-400 transition-all resize-none min-h-[100px]" autoFocus />
                    <div className="flex gap-2 justify-end">
                      <button onClick={() => setEditingId(null)} className="px-4 py-2 text-[10px] font-bold uppercase tracking-widest text-zinc-400 hover:text-zinc-900 transition-colors">Abort</button>
                      <button onClick={handleSaveEdit} className={`px-6 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest active:scale-95 transition-all ${isOwnerView ? 'bg-amber-500 text-black' : 'bg-zinc-900 text-white'}`}>Sync</button>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <div className="prose prose-zinc max-w-none whitespace-pre-wrap font-medium tracking-tight">{msg.content}</div>
                    {msg.audioUrl && <VocalPlayer audioUrl={msg.audioUrl} msgId={msg.id} />}
                    {isAnora && msg.sources && <GroundingSources sources={msg.sources} />}
                  </div>
                )}

                {isAnora && onVocalize && !isEditing && (
                  <div className="absolute top-4 -right-12 flex flex-col gap-2 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-all duration-300 translate-x-4 sm:group-hover:translate-x-0">
                    <button onClick={() => onVocalize(msg.id, msg.content, msg.affect)} className={`p-3 rounded-2xl border transition-all hover:scale-110 active:scale-90 shadow-md ${isSpeaking ? (isOwnerView ? 'text-amber-500 border-amber-500/50' : 'text-indigo-600 border-indigo-500/50') : 'text-zinc-400 border-zinc-100 bg-white hover:text-zinc-900'}`}><svg className={`w-5 h-5 ${isSpeaking ? 'animate-pulse' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg></button>
                  </div>
                )}

                {isMenuOpen && (
                  <div className="absolute z-[150] top-0 left-0 w-full h-full flex items-center justify-center pointer-events-none">
                    <div className="bg-white/95 backdrop-blur-xl border border-zinc-100 rounded-[2.5rem] shadow-2xl flex flex-col p-2 min-w-[200px] animate-in zoom-in duration-300 pointer-events-auto">
                      <button onClick={() => { navigator.clipboard.writeText(msg.content); setContextMenuId(null); }} className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item text-left w-full"><span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Copy Intel</span></button>
                      {onSaveToMemory && <button onClick={() => { onSaveToMemory(msg.content); setContextMenuId(null); }} className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item text-left w-full"><span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Sync to Memory</span></button>}
                      {isUser && onEditMessage && <button onClick={() => handleStartEdit(msg)} className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item text-left w-full"><span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Refine Intent</span></button>}
                      <button onClick={() => { if (onDeleteMessage) onDeleteMessage(msg.id); setContextMenuId(null); }} className="flex items-center gap-4 px-6 py-4 hover:bg-red-50 rounded-[1.8rem] transition-colors group/item text-left w-full"><span className="text-[10px] font-black uppercase tracking-widest text-red-500">Purge Synapse</span></button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}
      {isThinking && <div className="flex justify-start animate-in fade-in slide-in-from-left-2 duration-700"><div className={`bg-white border rounded-[1.8rem] rounded-tl-none px-6 py-4 shadow-sm ring-1 ring-black/5 ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-100'}`}><div className="flex gap-1.5"><div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.3s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div><div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.15s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div><div className={`w-1.5 h-1.5 rounded-full animate-bounce ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div></div></div></div>}
      {contextMenuId && <div onClick={() => setContextMenuId(null)} className="fixed inset-0 z-50 bg-black/5 backdrop-blur-sm animate-in fade-in duration-300"></div>}
      <div ref={bottomRef} className="h-10" />
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob as GenAIBlob } from '@google/genai';
import { Message, Role, User, SubscriptionTier, Persona, NeuralAffect, TokenUsage, AppColorMode } from './types';
import { INITIAL_MESSAGE, OWNER_EMAIL } from './constants';
import { anoraService } from './services/geminiService';
import { MessageList } from './components/MessageList';
import { VoiceIndicator } from './components/VoiceIndicator';
import { AuthScreen } from './components/AuthScreen';
import { PremiumBadge } from './components/PremiumBadge';
import { CommandCenter } from './components/CommandCenter';
import { ProfileModal } from './components/ProfileModal';
import { AnoraLogo } from './components/AnoraLogo';
import { AssistantFeatures } from './components/AssistantFeatures';
import { NeuralOrb } from './components/NeuralOrb';

const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
};

const decode = (base64: string) => {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  } catch (e) {
    console.error("Neural decoding error", e);
    return new Uint8Array(0);
  }
};

const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
  if (data.length === 0) return ctx.createBuffer(numChannels, 1, sampleRate);
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

const createBlob = (data: Float32Array): GenAIBlob => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
  return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
};

const TOKEN_LIMITS = {
  OWNER: { chat: Infinity, image: Infinity, video: Infinity, audio: Infinity },
  LIFETIME: { chat: 100000, image: 100, video: 20, audio: 100 },
  PRO: { chat: 100000, image: 100, video: 20, audio: 50 },
  FREE: { chat: 20000, image: 10, video: 0, audio: 0 },
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [activeAffect, setActiveAffect] = useState<NeuralAffect>('SOVEREIGN');
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [speakingId, setSpeakingId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const currentVocalizeIdRef = useRef<string | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const handleDbUpdate = () => {
      if (!currentUser) return;
      const users: User[] = JSON.parse(localStorage.getItem('anora_users_db') || '[]');
      const updated = users.find(u => u.id === currentUser.id);
      if (updated && (updated.tier !== currentUser.tier || updated.role !== currentUser.role)) {
        setCurrentUser(updated);
      }
    };
    window.addEventListener('anora_database_updated', handleDbUpdate);
    return () => window.removeEventListener('anora_database_updated', handleDbUpdate);
  }, [currentUser]);

  useEffect(() => {
    if (currentUser) {
      const today = new Date().toDateString();
      if (!currentUser.tokens || currentUser.tokens.lastReset !== today) {
        const limits = currentUser.role === Role.OWNER ? TOKEN_LIMITS.OWNER : (TOKEN_LIMITS[currentUser.tier] || TOKEN_LIMITS.FREE);
        const resetUser = {
          ...currentUser,
          tokens: { ...limits, lastReset: today }
        };
        setCurrentUser(resetUser);
        return; 
      }

      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      const savedDb = localStorage.getItem('anora_users_db');
      const users: User[] = savedDb ? JSON.parse(savedDb) : [];
      const exists = users.find(u => u.id === currentUser.id);
      const updatedUsers = exists ? users.map((u: User) => u.id === currentUser.id ? currentUser : u) : [...users, currentUser];
      localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
      anoraService.initChat(currentUser);
    }
  }, [currentUser]);

  useEffect(() => {
    if (currentUser) {
      const historyKey = `anora_history_${currentUser.email}`;
      const savedHistory = localStorage.getItem(historyKey);
      if (savedHistory) {
        try { setMessages(JSON.parse(savedHistory)); } catch (e) { handleNewThread(); }
      } else {
        handleNewThread();
      }
    }
  }, [currentUser?.email]);

  useEffect(() => {
    if (currentUser && messages.length > 0) {
      const historyKey = `anora_history_${currentUser.email}`;
      try {
        localStorage.setItem(historyKey, JSON.stringify(messages));
      } catch (e) {
        try { localStorage.setItem(historyKey, JSON.stringify(messages.slice(-20))); } catch (e2) {}
      }

      const lastAnora = [...messages].reverse().find(m => m.role === 'anora');
      if (lastAnora?.affect) setActiveAffect(lastAnora.affect);
    }
  }, [messages, currentUser?.email]);

  const deductTokens = useCallback((type: keyof Omit<TokenUsage, 'lastReset'>, amount: number) => {
    if (!currentUser) return false;
    if (currentUser.role === Role.OWNER) return true;

    const tokens = currentUser.tokens || { chat: 0, image: 0, video: 0, audio: 0, lastReset: '' };
    if (tokens[type] < amount) {
      alert(`Neural Resources Exhausted: ${type.toUpperCase()} pool empty for today.`);
      return false;
    }

    const updatedUser = {
      ...currentUser,
      tokens: { ...tokens, [type]: tokens[type] - amount }
    };
    setCurrentUser(updatedUser);
    return true;
  }, [currentUser]);

  const handleNewThread = () => {
    if (!currentUser) return;
    const initialRaw = INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT');
    const { content, affect } = anoraService.parseAffect(initialRaw);
    const initial: Message = { id: 'init_' + Date.now(), role: 'anora', content, affect, timestamp: new Date() };
    setMessages([initial]);
    localStorage.setItem(`anora_history_${currentUser.email}`, JSON.stringify([initial]));
    anoraService.initChat(currentUser);
  };

  const handleLogout = useCallback(() => {
    setCurrentUser(null);
    localStorage.removeItem('anora_session');
    setMessages([]);
  }, []);

  const handleSaveToMemory = useCallback((content: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, memory: [...(currentUser.memory || []), { id: `mem_${Date.now()}`, content, category: 'PERSONAL', timestamp: new Date().toISOString(), strength: 5 }] });
  }, [currentUser]);

  const handleSaveToReminders = useCallback((content: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, reminders: [...(currentUser.reminders || []), { id: `rem_${Date.now()}`, text: content, priority: 'MEDIUM', completed: false, dueDate: new Date().toISOString() }] });
  }, [currentUser]);

  const handleDeleteMessage = useCallback((id: string) => { setMessages(prev => prev.filter(m => m.id !== id)); }, []);

  const stopCurrentVocalize = useCallback(() => {
    if (activeSourceRef.current) {
      try { activeSourceRef.current.stop(); } catch (e) {}
      activeSourceRef.current = null;
    }
    setSpeakingId(null);
    currentVocalizeIdRef.current = null;
  }, []);

  const toggleVoiceMode = useCallback(async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(t => t.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }
    try {
      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => session.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
            if (msg.serverContent?.interrupted) {
               audioSourcesRef.current.forEach(s => { try { s.stop(); } catch(e){} });
               audioSourcesRef.current.clear();
               nextStartTimeRef.current = 0;
            }
          },
          onclose: () => setIsVoiceMode(false),
          onerror: () => setIsVoiceMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `Anora Voice active. Real-time neural sync enabled for Master ${currentUser?.name}. Protocol: ${currentUser?.preferences.persona}.`
        }
      });
    } catch (err) { setIsVoiceMode(false); }
  }, [isVoiceMode, currentUser]);

  const handleVocalize = async (id: string, text: string, affect: NeuralAffect = 'SOVEREIGN') => {
    if (speakingId === id) { stopCurrentVocalize(); return; }
    stopCurrentVocalize();
    setSpeakingId(id); currentVocalizeIdRef.current = id;
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const base64 = await anoraService.speak(text, currentUser?.preferences.voiceName || 'Kore', affect);
      if (currentVocalizeIdRef.current !== id) return;
      if (!base64) throw new Error("No audio generated");
      const buffer = await decodeAudioData(decode(base64), audioCtxRef.current, 24000, 1);
      const source = audioCtxRef.current.createBufferSource();
      source.buffer = buffer; source.connect(audioCtxRef.current.destination);
      source.onended = () => { if (currentVocalizeIdRef.current === id) setSpeakingId(null); };
      activeSourceRef.current = source; source.start();
    } catch (err) { setSpeakingId(null); }
  };

  const handleSend = async (text: string) => {
    const val = text.trim();
    if (!val && pendingImages.length === 0) return;

    // Interrupt current speaking if user sends new message
    stopCurrentVocalize();

    const chatTokenCost = Math.max(1, Math.ceil((val.length || 10) / 3));
    if (!deductTokens('chat', chatTokenCost)) return;

    if (pendingImages.length > 0) {
      if (!deductTokens('image', pendingImages.length)) return;
    }

    const intent = (t: string) => {
      const lower = t.toLowerCase();
      if (lower.includes('cad') || lower.includes('engineering') || lower.includes('site')) return 'ENGINEERING';
      if (lower.includes('music') || lower.includes('lyrics') || lower.includes('song')) return 'CREATIVE';
      return 'GENERAL';
    };

    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: val || "Asset manifest shared for analysis.", 
      timestamp: new Date(), 
      images: pendingImages.length > 0 ? [...pendingImages] : undefined, 
      intent: intent(val) as any 
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue(''); 
    setPendingImages([]); 
    setIsThinking(true);

    try {
      const response = await anoraService.sendMessageWithVision(userMsg.content, userMsg.images || []);

      if (response.audioUrl) {
        if (!deductTokens('audio', 1)) {
          response.audioUrl = undefined;
        }
      }

      const anoraMsg: Message = { 
        id: (Date.now()+1).toString(), 
        role: 'anora', 
        content: response.text, 
        sources: response.sources, 
        images: response.images, 
        audioUrl: response.audioUrl,
        affect: response.affect as any, 
        timestamp: new Date() 
      };
      setMessages(prev => [...prev, anoraMsg]);
      if (currentUser?.preferences.autoRead) handleVocalize(anoraMsg.id, anoraMsg.content, anoraMsg.affect);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'system', content: "Neural bridge unstable. Sync deferred by Sovereign decree.", timestamp: new Date() }]);
    } finally { setIsThinking(false); }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const isOwner = currentUser.role === Role.OWNER;
  const isPremium = currentUser.tier !== SubscriptionTier.FREE || isOwner;
  const accent = isOwner ? '#d4af37' : (isPremium ? '#8b5cf6' : '#3f3f46');
  const colorMode = currentUser.preferences.colorMode || 'WHITE';

  const getColorStyles = () => {
    switch(colorMode) {
      case 'DARK': return 'bg-zinc-900 text-white';
      case 'MIDNIGHT': return 'bg-black text-white';
      case 'SOLAR': return 'bg-orange-50 text-orange-950';
      default: return 'bg-white text-zinc-800';
    }
  };

  const handleFileSelect = () => {
    if (!isPremium) {
      alert("Multimodal neural integration is reserved for Premium/Sovereign tiers.");
      return;
    }
    fileInputRef.current?.click();
  };

  return (
    <div className={`flex flex-col h-[100dvh] transition-colors duration-700 overflow-hidden ${getColorStyles()} ${currentUser.preferences.font === 'OUTFIT' ? 'font-outfit' : 'font-inter'}`}>
      <style>{`.accent-text { color: ${accent}; } .accent-border { border-color: ${accent}20; }`}</style>
      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onDeductToken={deductTokens} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} onLogout={handleLogout} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} onClearHistory={handleNewThread} messagesCount={messages.length} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <header className={`flex items-center justify-between px-6 sm:px-12 pt-[calc(var(--sat)+1rem)] pb-4 border-b shrink-0 transition-all duration-700 ${colorMode === 'WHITE' ? 'border-zinc-100' : colorMode === 'DARK' ? 'border-zinc-800' : colorMode === 'MIDNIGHT' ? 'border-zinc-900' : 'border-orange-100'}`}>
        <div className="transform hover:scale-105 transition-transform cursor-pointer" onClick={() => setIsHubOpen(true)}>
          <AnoraLogo size={40} color={accent} />
        </div>
        <div className="flex items-center gap-4">
          <VoiceIndicator active={isVoiceMode} />
          <div className={`flex items-center gap-2 p-1 rounded-full border transition-all duration-700 ${colorMode === 'WHITE' ? 'bg-zinc-50 border-zinc-100 shadow-sm' : 'bg-white/5 border-white/10'}`}>
            <button onClick={toggleVoiceMode} className={`p-2.5 rounded-full transition-all active:scale-95 ${isVoiceMode ? 'bg-blue-500 text-white shadow-lg shadow-blue-500/30' : 'text-zinc-400 hover:text-zinc-900'}`}>
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            </button>
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-2.5 text-zinc-400 hover:text-zinc-900 transition-all active:scale-90"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></button>
            <button onClick={() => setIsProfileOpen(true)} className={`w-9 h-9 rounded-full overflow-hidden flex items-center justify-center text-[10px] font-black transition-all active:scale-90 ${isOwner ? 'ring-2 ring-amber-500 shadow-lg' : (colorMode === 'WHITE' ? 'bg-white border border-zinc-200' : 'bg-white/10 border border-white/20')}`}>
              {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" alt="Me" /> : currentUser.name.charAt(0)}
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <MessageList messages={messages} isThinking={isThinking} ownerName={currentUser.name} isOwnerView={isOwner} userTier={currentUser.tier} onVocalize={handleVocalize} onDeleteMessage={handleDeleteMessage} onSaveToMemory={handleSaveToMemory} onSaveToReminders={handleSaveToReminders} speakingId={speakingId} />
        <NeuralOrb active={isThinking} affect={activeAffect} speaking={speakingId !== null} listening={isVoiceMode} color={accent} />
