  const handleStartEdit = (msg: Message) => {
    setEditingId(msg.id);
    setEditValue(msg.content);
    setContextMenuId(null);
  };

  const handleSaveEdit = () => {
    if (editingId && onEditMessage) onEditMessage(editingId, editValue);
    setEditingId(null);
  };

  const handleTouchStart = (msgId: string) => {
    longPressTimer.current = setTimeout(() => {
      setContextMenuId(msgId);
      if (window.navigator.vibrate) window.navigator.vibrate(50);
    }, 600);
  };

  const handleTouchEnd = () => { if (longPressTimer.current) clearTimeout(longPressTimer.current); };

  const isPro = userTier === SubscriptionTier.PRO || isOwnerView;

  return (
    <div ref={scrollContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-8 pt-10 pb-20 space-y-10 max-w-5xl mx-auto w-full scroll-smooth no-scrollbar relative z-10 touch-pan-y">
      {messages.map((msg, index) => {
        const isUser = msg.role === 'user';
        const isAnora = msg.role === 'anora';
        const isSpeaking = speakingId === msg.id;
        const isEditing = editingId === msg.id;
        const isMenuOpen = contextMenuId === msg.id;

        let bubbleClass = isUser 
          ? (isOwnerView ? "bg-zinc-900 border-amber-500/50 text-white shadow-xl rounded-tr-none" : isPro ? "bg-indigo-600 border-indigo-500 text-white rounded-tr-none" : "bg-zinc-800 text-white border-zinc-700 rounded-tr-none")
          : (isOwnerView ? "bg-zinc-50 border-amber-500/10 text-zinc-900 rounded-tl-none backdrop-blur-3xl shadow-sm" : "bg-zinc-100/50 text-zinc-800 border-zinc-200/50 rounded-tl-none backdrop-blur-3xl");

        return (
          <div key={msg.id} className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-1000 relative`} style={{ animationDelay: `${index * 30}ms` }}>
            <div className={`max-w-[92%] sm:max-w-[85%] group relative ${isMenuOpen ? 'z-[100] scale-[1.02]' : 'z-10'} transition-all duration-300`}>
              <div className={`flex items-center gap-3 mb-2 px-2 transition-all opacity-60 group-hover:opacity-100 ${isUser ? 'flex-row-reverse' : ''}`}>
                <span className={`text-[9px] font-bold uppercase tracking-[0.2em] ${isUser ? (isOwnerView ? 'text-amber-600' : isPro ? 'text-indigo-600' : 'text-zinc-600') : 'text-zinc-400'}`}>
                  {isUser ? (isOwnerView ? 'Sovereign' : isPro ? 'Neural Pro' : ownerName.split(' ')[0]) : (msg.images && msg.images.length > 0 ? 'Synthesis' : 'Anora')}
                </span>
                <span className="text-[8px] text-zinc-300 font-bold uppercase tracking-widest">{new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>

              {msg.images && msg.images.length > 0 && !isEditing && (
                <div className={`grid gap-2 mb-3 animate-in zoom-in-95 duration-700 ${msg.images.length === 4 ? 'grid-cols-2' : 'flex flex-wrap'} ${isUser ? 'justify-end' : 'justify-start'}`}>
                  {msg.images.map((img, i) => (
                    <div key={i} className={`relative group/img overflow-hidden rounded-[1.8rem] sm:rounded-[2.5rem] border shadow-md transition-all hover:border-zinc-400 ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-200'} ${msg.images && msg.images.length === 1 ? 'w-64 h-64 sm:w-80 sm:h-80' : 'w-full aspect-square'}`}>
                      <img src={img} alt="V" className="w-full h-full object-cover transition-transform duration-[2s] group-hover/img:scale-110" />
                      <a href={img} download={`anora_full_res_${Date.now()}.png`} className="absolute bottom-4 right-4 flex items-center gap-2 px-4 py-3 bg-white/90 backdrop-blur-md rounded-2xl text-zinc-900 opacity-0 group-hover/img:opacity-100 transition-all shadow-2xl active:scale-90"><span className="text-[8px] font-black uppercase tracking-widest">Full Quality</span></a>
                    </div>
                  ))}
                </div>
              )}

              <div onMouseDown={() => handleTouchStart(msg.id)} onMouseUp={handleTouchEnd} onMouseLeave={handleTouchEnd} onTouchStart={() => handleTouchStart(msg.id)} onTouchEnd={handleTouchEnd} className={`rounded-[2rem] sm:rounded-[3rem] px-6 sm:px-10 py-5 sm:py-8 text-sm sm:text-base leading-relaxed shadow-sm transition-all duration-700 relative ring-1 ring-black/5 select-none touch-pan-y ${bubbleClass} ${isMenuOpen ? 'ring-2 ring-zinc-900/10' : ''}`}>
                {isEditing ? (
                  <div className="space-y-4 py-2 animate-in fade-in duration-300">
                    <textarea value={editValue} onChange={(e) => setEditValue(e.target.value)} className="w-full bg-white/40 border border-zinc-200 rounded-2xl p-4 text-zinc-900 outline-none focus:border-zinc-400 transition-all resize-none min-h-[100px]" autoFocus />
                    <div className="flex gap-2 justify-end">
                      <button onClick={() => setEditingId(null)} className="px-4 py-2 text-[10px] font-bold uppercase tracking-widest text-zinc-400 hover:text-zinc-900 transition-colors">Abort</button>
                      <button onClick={handleSaveEdit} className={`px-6 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest active:scale-95 transition-all ${isOwnerView ? 'bg-amber-500 text-black' : 'bg-zinc-900 text-white'}`}>Sync</button>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <div className="prose prose-zinc max-w-none whitespace-pre-wrap font-medium tracking-tight">{msg.content}</div>
                    {msg.audioUrl && <VocalPlayer audioUrl={msg.audioUrl} msgId={msg.id} />}
                    {isAnora && msg.sources && <GroundingSources sources={msg.sources} />}
                  </div>
                )}

                {isAnora && onVocalize && !isEditing && (
                  <div className="absolute top-4 -right-12 flex flex-col gap-2 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-all duration-300 translate-x-4 sm:group-hover:translate-x-0">
                    <button onClick={() => onVocalize(msg.id, msg.content, msg.affect)} className={`p-3 rounded-2xl border transition-all hover:scale-110 active:scale-90 shadow-md ${isSpeaking ? (isOwnerView ? 'text-amber-500 border-amber-500/50' : 'text-indigo-600 border-indigo-500/50') : 'text-zinc-400 border-zinc-100 bg-white hover:text-zinc-900'}`}><svg className={`w-5 h-5 ${isSpeaking ? 'animate-pulse' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg></button>
                  </div>
                )}

                {isMenuOpen && (
                  <div className="absolute z-[150] top-0 left-0 w-full h-full flex items-center justify-center pointer-events-none">
                    <div className="bg-white/95 backdrop-blur-xl border border-zinc-100 rounded-[2.5rem] shadow-2xl flex flex-col p-2 min-w-[200px] animate-in zoom-in duration-300 pointer-events-auto">
                      <button onClick={() => { navigator.clipboard.writeText(msg.content); setContextMenuId(null); }} className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item text-left w-full"><span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Copy Intel</span></button>
                      {onSaveToMemory && <button onClick={() => { onSaveToMemory(msg.content); setContextMenuId(null); }} className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item text-left w-full"><span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Sync to Memory</span></button>}
                      {isUser && onEditMessage && <button onClick={() => handleStartEdit(msg)} className="flex items-center gap-4 px-6 py-4 hover:bg-zinc-50 rounded-[1.8rem] transition-colors group/item text-left w-full"><span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">Refine Intent</span></button>}
                      <button onClick={() => { if (onDeleteMessage) onDeleteMessage(msg.id); setContextMenuId(null); }} className="flex items-center gap-4 px-6 py-4 hover:bg-red-50 rounded-[1.8rem] transition-colors group/item text-left w-full"><span className="text-[10px] font-black uppercase tracking-widest text-red-500">Purge Synapse</span></button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}
      {isThinking && <div className="flex justify-start animate-in fade-in slide-in-from-left-2 duration-700"><div className={`bg-white border rounded-[1.8rem] rounded-tl-none px-6 py-4 shadow-sm ring-1 ring-black/5 ${isOwnerView ? 'border-amber-500/20' : 'border-zinc-100'}`}><div className="flex gap-1.5"><div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.3s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div><div className={`w-1.5 h-1.5 rounded-full animate-bounce [animation-delay:-0.15s] ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div><div className={`w-1.5 h-1.5 rounded-full animate-bounce ${isOwnerView ? 'bg-amber-500' : 'bg-zinc-300'}`}></div></div></div></div>}
      {contextMenuId && <div onClick={() => setContextMenuId(null)} className="fixed inset-0 z-50 bg-black/5 backdrop-blur-sm animate-in fade-in duration-300"></div>}
      <div ref={bottomRef} className="h-10" />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, AiMood, IntelligenceLevel } from '../types';
import { OWNER_EMAIL, OWNER_PASSWORD, ARJUN_DETAILED_BIO } from '../constants';
import { AnoraLogo } from './AnoraLogo';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [phase, setPhase] = useState(0); // 0: Start, 1: Form, 2: Neural Booting, 3: Recovery
  const [recoverySuccess, setRecoverySuccess] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setPhase(1), 800);
    return () => clearTimeout(timer);
  }, []);

  const getUsers = (): User[] => {
    const data = localStorage.getItem('anora_users_db');
    return data ? JSON.parse(data) : [];
  };

  const saveUser = (user: User) => {
    const users = getUsers();
    users.push(user);
    localStorage.setItem('anora_users_db', JSON.stringify(users));
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const updateUsers = (updatedUsers: User[]) => {
    localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
    window.dispatchEvent(new Event('anora_database_updated'));
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    setTimeout(() => {
      const users = getUsers();
      const emailLower = email.toLowerCase().trim();

      if (isLogin) {
        if (emailLower === OWNER_EMAIL && password === OWNER_PASSWORD) {
          let owner = users.find(u => u.email.toLowerCase() === OWNER_EMAIL);
          if (!owner) {
            owner = {
              id: 'sovereign_arj',
              name: "Arjun Bharti Mina",
              email: OWNER_EMAIL,
              password: OWNER_PASSWORD,
              role: Role.OWNER,
              tier: SubscriptionTier.LIFETIME,
              bio: ARJUN_DETAILED_BIO,
              preferences: { 
                accentColor: '#d4af37', 
                aiMood: 'CREATIVE' as AiMood, 
                voiceName: 'Kore',
                autoRead: false,
                continuousListening: false,
                intelligenceLevel: 'DEEP' as IntelligenceLevel,
                language: 'English',
                theme: 'OBSIDIAN',
                font: 'OUTFIT',
                soundEnabled: true,
                persona: 'DEFAULT',
                colorMode: 'WHITE'
              },
              createdAt: new Date().toISOString(),
              reminders: [],
              notes: [],
              memory: [],
              projects: []
            };
            saveUser(owner);
          }
          setPhase(2);
          setTimeout(() => onLogin(owner!), 2500);
          return;
        }

        const found = users.find(u => u.email.toLowerCase() === emailLower);
        if (!found) {
          setError('Neural ID not recognized in database.');
        } else if (found.password !== password) {
          setError('Security mismatch. Verify encryption key.');
        } else {
          setPhase(2);
          setTimeout(() => onLogin(found), 2000);
        }
      } else {
        if (password !== confirmPassword) {
          setError('Encryption keys must be identical.');
        } else if (users.some(u => u.email.toLowerCase() === emailLower)) {
          setError('Neural ID already established.');
        } else if (password.length < 6) {
          setError('Key complexity requirements not met.');
        } else {
          const newUser: User = {
            id: Math.random().toString(36).substr(2, 9),
            name: name || 'Neural Link User',
            email: emailLower,
            password: password,
            role: Role.USER,
            tier: SubscriptionTier.FREE,
            preferences: { 
              accentColor: '#3f3f46', 
              aiMood: 'CALM' as AiMood, 
              voiceName: 'Kore',
              autoRead: false,
              continuousListening: false,
              intelligenceLevel: 'BALANCED' as IntelligenceLevel,
              language: 'English',
              theme: 'OBSIDIAN',
              font: 'INTER',
              soundEnabled: true,
              persona: 'DEFAULT',
              colorMode: 'WHITE'
            },
            createdAt: new Date().toISOString(),
            reminders: [],
            notes: [],
            memory: [],
            projects: []
          };
          saveUser(newUser);
          setPhase(2);
          setTimeout(() => onLogin(newUser), 2000);
        }
      }
      setLoading(false);
    }, 1800);
  };

  const handleRecovery = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    setTimeout(() => {
      const users = getUsers();
      const emailLower = email.toLowerCase().trim();
      const foundIdx = users.findIndex(u => u.email.toLowerCase() === emailLower);

      if (foundIdx === -1) {
        setError("Neural ID not found in database.");
        setLoading(false);
      } else if (emailLower === OWNER_EMAIL) {
        setError("Sovereign recovery requires manual protocol. Reference 'aman1887'.");
        setLoading(false);
      } else {
        const updatedUsers = [...users];
        updatedUsers[foundIdx] = { ...updatedUsers[foundIdx], password: password };
        updateUsers(updatedUsers);
        setRecoverySuccess(true);
        setLoading(false);
        setTimeout(() => {
          setPhase(1);
          setRecoverySuccess(false);
          setIsLogin(true);
        }, 3000);
      }
    }, 2000);
  };

  if (phase === 2) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-8 space-y-12 font-outfit overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(0,0,0,0.02)_0%,_transparent_70%)] animate-pulse"></div>

        <div className="animate-bounce transition-all duration-1000 scale-125">
          <AnoraLogo size={140} color="#000" showName={false} />
        </div>

        <div className="text-center space-y-8 relative z-10 w-full max-sm:max-w-xs max-w-sm">
          <div className="space-y-2">
            <h2 className="text-zinc-900 text-2xl font-bold tracking-[0.5em] animate-pulse">BOOTING ANORA CORE</h2>
            <p className="text-zinc-400 text-[10px] font-bold uppercase tracking-[0.3em]">Neural Integration in progress...</p>
          </div>

          <div className="w-full h-1 bg-zinc-100 rounded-full overflow-hidden border border-zinc-200 shadow-sm">
            <div className="h-full bg-zinc-900 animate-neural-progress"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white flex items-center justify-center p-6 relative overflow-hidden font-outfit">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_#f9f9f9_0%,_#fff_100%)]"></div>

      <div className={`w-full max-w-md transition-all duration-1000 transform ${phase === 1 || phase === 3 ? 'translate-y-0 opacity-100' : 'translate-y-16 opacity-0'}`}>
        <div className="text-center mb-16 space-y-4 animate-in fade-in slide-in-from-top-4 duration-1000">
          <div className="flex justify-center transform hover:scale-110 transition-transform duration-700">
            <AnoraLogo size={80} color="#000" showName={false} />
          </div>
          <div className="space-y-1">
            <h1 className="text-4xl font-bold tracking-[0.4em] text-zinc-900">ANORA</h1>
            <p className="text-zinc-400 text-[10px] font-bold uppercase tracking-[0.6em] animate-pulse">Sovereign Intel v3.5</p>
          </div>
        </div>

        <div className="bg-zinc-50 border border-zinc-100 p-10 sm:p-12 rounded-[4rem] shadow-xl ring-1 ring-black/5 relative group animate-in zoom-in-95 duration-700">

          {phase === 1 ? (
            <>
              <div className="flex bg-zinc-100/50 p-2 rounded-2xl border border-zinc-200 mb-10 relative z-10">
                <button 
                  type="button"
                  onClick={() => { setIsLogin(true); setError(''); }}
                  className={`flex-1 py-3.5 text-[10px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all duration-700 ${isLogin ? 'bg-white text-zinc-900 shadow-sm' : 'text-zinc-400 hover:text-zinc-600'}`}
                >
                  Access Core
                </button>
                <button 
                  type="button"
                  onClick={() => { setIsLogin(false); setError(''); }}
                  className={`flex-1 py-3.5 text-[10px] font-bold uppercase tracking-[0.2em] rounded-xl transition-all duration-700 ${!isLogin ? 'bg-white text-zinc-900 shadow-sm' : 'text-zinc-400 hover:text-zinc-600'}`}
                >
                  Establish Link
                </button>
              </div>

              <form onSubmit={handleAuth} className="space-y-6 relative z-10">
                {error && (
                  <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl animate-in shake-in duration-500">
                    <p className="text-red-600 text-[9px] font-bold uppercase tracking-widest text-center">{error}</p>
                  </div>
                )}

                <div className="space-y-5">
                  {!isLogin && (
                    <div className="animate-in fade-in slide-in-from-top-1 duration-300">
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Identity Signature</label>
                      <input
                        type="text" required value={name} onChange={(e) => setName(e.target.value)}
                        className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none focus:ring-1 focus:ring-black/10 transition-all text-sm placeholder:text-zinc-300"
                        placeholder="E.g. Arjun"
                      />
                    </div>
                  )}

                  <div className="animate-in fade-in slide-in-from-top-1 duration-500">
                    <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Neural ID (Email)</label>
                    <input
                      type="email" required value={email} onChange={(e) => setEmail(e.target.value)}
                      className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none focus:ring-1 focus:ring-black/10 transition-all text-sm placeholder:text-zinc-300"
                      placeholder="identity@neural.link"
                    />
                  </div>

                  <div className="animate-in fade-in slide-in-from-top-1 duration-700">
                    <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Access Key (Password)</label>
                    <input
                      type="password" required value={password} onChange={(e) => setPassword(e.target.value)}
                      className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none focus:ring-1 focus:ring-black/10 transition-all text-sm placeholder:text-zinc-300"
                      placeholder="••••••••"
                    />
                  </div>

                  {!isLogin && (
                    <div className="animate-in fade-in slide-in-from-top-1 duration-900">
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Verify Encryption Key</label>
                      <input
                        type="password" required value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)}
                        className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none focus:ring-1 focus:ring-black/10 transition-all text-sm placeholder:text-zinc-300"
                        placeholder="••••••••"
                      />
                    </div>
                  )}
                </div>

                {isLogin && (
                  <div className="flex justify-end px-2">
                    <button type="button" onClick={() => setPhase(3)} className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest hover:text-zinc-600 transition-colors">
                      Forgot Access Key?
                    </button>
                  </div>
                )}

                <button
                  type="submit" disabled={loading}
                  className="w-full bg-zinc-900 text-white font-bold py-5 rounded-[2rem] hover:bg-black transition-all active:scale-[0.98] disabled:opacity-50 mt-6 overflow-hidden relative shadow-lg"
                >
                  {loading ? "Synthesizing..." : (isLogin ? "Neural Sync" : "Initialize Link")}
                </button>
              </form>
            </>
          ) : (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
              <h3 className="text-zinc-900 text-center text-sm font-bold uppercase tracking-[0.3em] mb-8">Neural Key Recovery</h3>

              {recoverySuccess ? (
                <div className="text-center space-y-4 py-8 animate-in zoom-in duration-500">
                   <div className="w-16 h-16 bg-green-500/10 border border-green-500/20 rounded-full mx-auto flex items-center justify-center">
                     <svg className="w-8 h-8 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                   </div>
                   <p className="text-green-600 text-[10px] font-bold uppercase tracking-widest">Access Key Re-Synchronized</p>
                   <p className="text-zinc-400 text-[8px] font-bold uppercase tracking-widest">Returning to Core Access...</p>
                </div>
              ) : (
                <form onSubmit={handleRecovery} className="space-y-6">
                  {error && (
                    <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl text-center">
                      <p className="text-red-600 text-[9px] font-bold uppercase tracking-widest">{error}</p>
                    </div>
                  )}
                  <div className="space-y-5">
                    <div>
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">Neural ID (Email)</label>
                      <input
                        type="email" required value={email} onChange={(e) => setEmail(e.target.value)}
                        className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none focus:ring-1 focus:ring-black/10 transition-all text-sm"
                        placeholder="Verify email associated with link..."
                      />
                    </div>
                    <div>
                      <label className="block text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-2 ml-2">New Access Key</label>
                      <input
                        type="password" required value={password} onChange={(e) => setPassword(e.target.value)}
                        className="w-full bg-white border border-zinc-200 rounded-2xl px-6 py-4.5 text-zinc-900 outline-none focus:ring-1 focus:ring-black/10 transition-all text-sm"
                        placeholder="Define new encryption sequence..."
                      />
                    </div>
                  </div>
                  <div className="pt-4 flex flex-col gap-4">
                    <button type="submit" disabled={loading} className="w-full bg-zinc-900 text-white font-bold py-5 rounded-[2rem] uppercase text-[9px] tracking-widest hover:bg-black transition-all">
                      {loading ? "Validating Neural ID..." : "Reset Encryption Key"}
                    </button>
                    <button type="button" onClick={() => setPhase(1)} className="w-full text-zinc-400 font-bold uppercase text-[9px] tracking-widest hover:text-zinc-600 transition-colors">
                      Return to Sync
                    </button>
                  </div>
                </form>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

