    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (list === 'memory') updated.memory = (updated.memory || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'vault') updated.vault = (updated.vault || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const updateMemoryCategory = (id: string, category: NeuralMemoryItem['category']) => {
    const updated = { ...user };
    updated.memory = (updated.memory || []).map(m => m.id === id ? { ...m, category } : m);
    onUpdate(updated);
  };

  const setLanguage = (lang: string) => {
    onUpdate({
      ...user,
      preferences: { ...user.preferences, language: lang }
    });
  };

  const isOwner = user.role === Role.OWNER;
  const isPremium = user.tier !== SubscriptionTier.FREE || isOwner;
  const isLifetime = user.tier === SubscriptionTier.LIFETIME;

  // RE-ARRANGED Logic categories:
  // Sector 1: Status & Growth
  // Sector 2: Operations (Timeline/Projects)
  // Sector 3: Assets (Memory/Vault)
  // Sector 4: Specialized (Site Logs/Lyrics)
  // Sector 5: Neural Admin
  const activeTabs = isOwner 
    ? (['ANALYTICS', 'UPGRADE', 'TIMELINE', 'PROJECTS', 'NEURAL_MEMORY', 'VAULT', 'SITE_LOGS', 'LYRIC_STUDIO', 'PROTOCOLS', 'USERS', 'REQUESTS'] as const)
    : isPremium
      ? (['ANALYTICS', 'UPGRADE', 'TIMELINE', 'PROJECTS', 'NEURAL_MEMORY', 'VAULT', 'SITE_LOGS', 'LYRIC_STUDIO', 'PROTOCOLS'] as const)
      : (['ANALYTICS', 'UPGRADE', 'TIMELINE', 'PROJECTS', 'NEURAL_MEMORY', 'PROTOCOLS'] as const);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[150] flex items-end sm:items-stretch justify-end bg-black/10 backdrop-blur-xl animate-in fade-in slide-in-from-right duration-300">
      <div className="w-full max-w-xl h-[95dvh] sm:h-full bg-white border-l border-zinc-100 flex flex-col shadow-2xl overflow-hidden rounded-t-[3rem] sm:rounded-none">

        <div className="px-8 py-8 border-b border-zinc-50 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 rounded-2xl bg-zinc-50 flex items-center justify-center border border-zinc-100 shadow-sm">
               <svg className="w-5 h-5 text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
             </div>
             <div>
                <h2 className="text-xl font-black font-outfit text-zinc-900">Neural Hub</h2>
                <p className="text-[9px] uppercase tracking-[0.3em] font-bold text-zinc-400 mt-1">Refined Neural Sectors</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 text-zinc-300 hover:text-zinc-900 transition-colors bg-zinc-50 rounded-2xl shadow-sm border border-zinc-100">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="px-8 py-4 border-b border-zinc-50 flex items-center gap-4 overflow-hidden shrink-0">
          <span className="text-[8px] font-black uppercase tracking-widest text-zinc-300 whitespace-nowrap">Matrix Dialect:</span>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1 grow">
            {LANGUAGES.map(lang => (
              <button 
                key={lang}
                onClick={() => setLanguage(lang)}
                className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest transition-all border whitespace-nowrap ${user.preferences.language === lang ? 'bg-zinc-900 text-white border-zinc-900 shadow-md scale-105' : 'bg-zinc-50 text-zinc-400 border-zinc-100 hover:border-zinc-300'}`}
              >
                {lang}
              </button>
            ))}
          </div>
        </div>

        {/* Tab Scroller */}
        <div className="flex bg-zinc-50 p-1.5 mx-6 mt-6 rounded-2xl border border-zinc-100 overflow-x-auto no-scrollbar gap-1 shrink-0 shadow-sm">
          {activeTabs.map(t => (
            <button key={t} onClick={() => setTab(t as any)} className={`flex-1 min-w-[95px] py-2.5 text-[8px] font-black uppercase tracking-widest rounded-xl transition-all ${tab === t ? 'bg-zinc-900 text-white shadow-md' : 'text-zinc-400 hover:text-zinc-600'}`}>
              {t.replace('_', ' ')}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-10 no-scrollbar pb-32">
          {tab === 'ANALYTICS' && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <div className="p-8 bg-zinc-900 rounded-[3rem] text-white space-y-4 shadow-xl">
                  <h3 className="text-xl font-black uppercase tracking-widest font-outfit">Sovereign Pulse</h3>
                  <div className="grid grid-cols-2 gap-4 pt-4">
                     <div className="p-4 bg-white/5 rounded-2xl border border-white/10">
                        <p className="text-[8px] font-black uppercase text-zinc-500 mb-1">Total Synapses</p>
                        <p className="text-2xl font-black">{messagesCount}</p>
                     </div>
                     <div className={`p-4 bg-white/5 rounded-2xl border border-white/10 ${isOwner ? 'border-amber-500/20' : ''}`}>
                        <p className="text-[8px] font-black uppercase text-zinc-500 mb-1">Neural Rank</p>
                        <p className="text-sm font-black text-amber-500 uppercase">{user.tier}</p>
                     </div>
                  </div>
               </div>
               <div className="p-6 bg-zinc-50 border border-zinc-100 rounded-[2.5rem] shadow-sm">
                  <h4 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest mb-4">Core Efficiencies</h4>
                  <div className="space-y-3">
                     {[
                       { label: "Neural Flow", val: isOwner ? 100 : 85 },
                       { label: "Synthesis Rate", val: isOwner ? 100 : 70 },
                       { label: "Recall Stability", val: isOwner ? 100 : 95 }
                     ].map((s, i) => (
                       <div key={i} className="space-y-1">
                          <div className="flex justify-between text-[8px] font-black uppercase">
                             <span className="text-zinc-400">{s.label}</span>
                             <span className="text-zinc-900">{s.val}%</span>
                          </div>
                          <div className="h-1 bg-zinc-200 rounded-full overflow-hidden">
                             <div className="h-full bg-zinc-900" style={{ width: `${s.val}%` }}></div>
                          </div>
                       </div>
                     ))}
                  </div>
               </div>
            </div>
          )}

          {tab === 'UPGRADE' && !isOwner && !isLifetime && (
            <div className="space-y-8 animate-in fade-in duration-500 pb-10">
               <div className="p-8 bg-zinc-900 rounded-[3rem] text-white space-y-4 shadow-xl relative overflow-hidden">
                  <h3 className="text-xl font-black font-outfit uppercase tracking-tighter relative z-10">Neural Elevation</h3>
                  <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest leading-relaxed relative z-10">
                    Unlock deep intelligence cores and unrestricted synthesis.
                  </p>
               </div>
               {/* Rest of upgrade content remains same as original but logically placed here */}
               <div className="flex bg-zinc-100/50 p-1.5 rounded-2xl border border-zinc-200">
                  <button onClick={() => { setPaymentMode('PAY'); setPaymentPhase('SELECT'); }} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest rounded-xl transition-all ${paymentMode === 'PAY' ? 'bg-white text-zinc-900 shadow-sm' : 'text-zinc-400'}`}>Direct Payment</button>
                  <button onClick={() => setPaymentMode('REQUEST')} className={`flex-1 py-3 text-[9px] font-black uppercase tracking-widest rounded-xl transition-all ${paymentMode === 'REQUEST' ? 'bg-white text-zinc-900 shadow-sm' : 'text-zinc-400'}`}>Owner Review</button>
               </div>
               {/* Simplified plan button for Hub view */}
               {paymentMode === 'PAY' && paymentPhase === 'SELECT' && (
                 <button onClick={() => initiatePayment(SubscriptionTier.PRO, 499)} className="w-full p-6 bg-zinc-900 text-white rounded-[2.5rem] shadow-xl text-left flex justify-between items-center group active:scale-95 transition-all">
                    <div>
                      <p className="text-[11px] font-black uppercase">Neural Pro Activation</p>
                      <p className="text-[8px] font-bold text-zinc-400 uppercase">One month unrestricted access</p>
                    </div>
                    <span className="text-xl font-black">₹499</span>
                 </button>
               )}
            </div>
          )}

          {tab === 'TIMELINE' && (
            <div className="space-y-8 animate-in fade-in duration-500">
               <div className="flex gap-2">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="New timeline directive..." className="flex-1 bg-zinc-50 border border-zinc-100 rounded-2xl px-5 py-3.5 text-xs font-bold text-zinc-900 outline-none" />
                  <button onClick={addItem} className="p-4 rounded-2xl bg-zinc-900 text-white shadow-lg"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg></button>
               </div>
               <div className="grid gap-3">
                  {user.reminders.map(r => (
                    <div key={r.id} className="p-5 bg-white border border-zinc-100 rounded-[1.8rem] shadow-sm flex items-center justify-between group">
                       <div className="flex items-center gap-3">
                          <div className={`w-1.5 h-1.5 rounded-full ${r.completed ? 'bg-zinc-200' : 'bg-zinc-900'}`} />
                          <p className={`text-[11px] font-bold uppercase tracking-tight ${r.completed ? 'text-zinc-300 line-through' : 'text-zinc-800'}`}>{r.text}</p>
                       </div>
                       <button onClick={() => removeItem(r.id, 'reminders')} className="p-2 text-zinc-200 hover:text-red-500 transition-colors"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'PROJECTS' && (
            <div className="space-y-8 animate-in fade-in duration-500">
               <div className="bg-zinc-50 border border-zinc-100 p-6 rounded-[2.5rem] space-y-4">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Project Signature" className="w-full bg-white border border-zinc-100 rounded-xl px-4 py-3 text-xs font-bold" />
                  <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Scope & Goals..." className="w-full bg-white border border-zinc-100 rounded-xl px-4 py-3 text-xs font-bold h-20 resize-none" />
                  <button onClick={addItem} className="w-full py-3 bg-zinc-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg">Initialize Project</button>
               </div>
               <div className="grid gap-4">
                  {user.projects.map(p => (
                    <div key={p.id} className="p-6 bg-white border border-zinc-100 rounded-[2.2rem] shadow-sm">
                       <h4 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest">{p.name}</h4>
                       <p className="text-[9px] text-zinc-400 font-bold leading-relaxed mt-1">{p.description}</p>
                       <button onClick={() => removeItem(p.id, 'projects')} className="mt-4 text-[7px] font-black text-red-400 uppercase tracking-widest">Terminate Project</button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'NEURAL_MEMORY' && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <div className="grid gap-4">
                  {(user.memory || []).length > 0 ? (user.memory || []).map(m => (
                    <div key={m.id} className="p-6 bg-white border border-zinc-100 rounded-[2rem] shadow-sm space-y-4 group">
                       <div className="flex justify-between items-start">
                          <span className="px-2 py-0.5 rounded bg-zinc-900 text-white text-[7px] font-black uppercase tracking-widest">{m.category}</span>
                          <button onClick={() => removeItem(m.id, 'memory')} className="p-1 text-zinc-200 hover:text-red-500 transition-colors"><svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                       </div>
                       <p className="text-xs text-zinc-800 font-medium leading-relaxed">{m.content}</p>
                       <div className="flex justify-between items-center pt-2">
                          <span className="text-[7px] font-black text-zinc-300 uppercase tracking-widest">RECALL STRENGTH: {m.strength}/5</span>
                       </div>
                    </div>
                  )) : (
                    <div className="py-20 text-center border-2 border-dashed border-zinc-100 rounded-[3rem] text-[9px] font-black text-zinc-200 uppercase tracking-[0.5em]">Memory Banks Empty</div>
                  )}
               </div>
            </div>
          )}

          {tab === 'VAULT' && isPremium && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <div className="bg-zinc-50 border border-zinc-100 p-6 rounded-[2.5rem] space-y-4">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Intel Header" className="w-full bg-white border border-zinc-100 rounded-xl px-4 py-3 text-xs font-bold" />
                  <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Encrypted content..." className="w-full bg-white border border-zinc-100 rounded-xl px-4 py-3 text-xs font-bold h-20 resize-none" />
                  <button onClick={addItem} className="w-full py-3 bg-zinc-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg">Seal Into Vault</button>
               </div>
               <div className="grid gap-3">
                  {(user.vault || []).map(item => (
                    <div key={item.id} className="p-5 bg-white border border-zinc-100 rounded-[1.8rem] shadow-sm flex items-center justify-between group">
                       <div className="flex items-center gap-3">
                          <div className="w-7 h-7 rounded-full bg-zinc-50 border border-zinc-100 flex items-center justify-center"><svg className="w-3 h-3 text-zinc-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg></div>
                          <p className="text-[10px] font-black text-zinc-900 uppercase tracking-widest">{item.title}</p>
                       </div>
                       <button onClick={() => removeItem(item.id, 'vault')} className="text-[8px] font-black text-red-300 hover:text-red-500 uppercase">Purge</button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'SITE_LOGS' && isPremium && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <div className="bg-zinc-50 border border-zinc-100 p-6 rounded-[2.5rem] space-y-4">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="RHB Site Code / Project" className="w-full bg-white border border-zinc-100 rounded-xl px-4 py-3 text-xs font-bold" />
                  <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Site observation details..." className="w-full bg-white border border-zinc-100 rounded-xl px-4 py-3 text-xs font-bold h-24 resize-none" />
                  <button onClick={addItem} className="w-full py-3 bg-zinc-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg">Manifest Site Log</button>
               </div>
               <div className="grid gap-4">
                  {(user.siteLogs || []).map(log => (
                    <div key={log.id} className="p-6 bg-white border border-zinc-100 rounded-[2.2rem] shadow-sm">
                       <h4 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest">{log.project}</h4>
                       <p className="text-[9px] text-zinc-600 font-bold leading-relaxed mt-2">{log.details}</p>
                       <div className="flex gap-2 mt-4"><button onClick={() => removeItem(log.id, 'siteLogs')} className="text-[7px] font-black text-red-400 uppercase">Purge Log</button></div>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'LYRIC_STUDIO' && isPremium && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <div className="bg-zinc-50 border border-zinc-100 p-6 rounded-[2.5rem] space-y-4">
                  <input value={newItem} onChange={e => setNewItem(e.target.value)} placeholder="Lyric Draft Title" className="w-full bg-white border border-zinc-100 rounded-xl px-4 py-3 text-xs font-bold" />
                  <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Draft lyrics here..." className="w-full bg-white border border-zinc-100 rounded-xl px-4 py-3 text-xs font-bold h-32 resize-none font-serif italic" />
                  <button onClick={addItem} className="w-full py-3 bg-zinc-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg">Synth Lyric Fragment</button>
               </div>
               <div className="grid gap-4">
                  {(user.lyrics || []).map(lyric => (
                    <div key={lyric.id} className="p-6 bg-white border border-zinc-100 rounded-[2.2rem] shadow-sm">
                       <h4 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest">{lyric.title}</h4>
                       <p className="text-[9px] text-zinc-500 font-serif leading-relaxed italic mt-2">"{lyric.content}"</p>
                       <button onClick={() => removeItem(lyric.id, 'lyrics')} className="mt-4 text-[7px] font-black text-red-400 uppercase">Burn Draft</button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'PROTOCOLS' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 animate-in fade-in duration-500">
               {[
                 { title: "Sovereign Architect", detail: "Arjun Bharti Mina: The mastermind behind the neural fabric.", icon: "M13 10V3L4 14h7v7l9-11h-7z" },
                 { title: "Linguistic Engine", detail: "Cross-dialect neural translation active for 28+ matrix nodes.", icon: "M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129" }
               ].map((p, i) => (
                 <div key={i} className="p-6 bg-zinc-50 border border-zinc-100 rounded-[2.5rem] shadow-sm">
                    <div className="w-8 h-8 rounded-lg bg-white border border-zinc-100 flex items-center justify-center mb-3"><svg className="w-4 h-4 text-zinc-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={p.icon} /></svg></div>
                    <h4 className="text-[10px] font-black text-zinc-900 uppercase tracking-widest mb-1">{p.title}</h4>
                    <p className="text-[8px] text-zinc-400 font-bold leading-relaxed uppercase">{p.detail}</p>
                 </div>
               ))}
            </div>
          )}

          {tab === 'USERS' && isOwner && (
            <div className="space-y-6 animate-in fade-in duration-500">
               <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search node directory..." className="w-full bg-zinc-50 border border-zinc-100 rounded-2xl px-6 py-4 text-xs font-bold text-zinc-900 outline-none shadow-sm" />
               <div className="grid gap-3">
                  {allUsers.filter(u => u.name.toLowerCase().includes(searchTerm.toLowerCase())).map(u => (
                    <div key={u.id} className="p-5 bg-white border border-zinc-100 rounded-[2rem] shadow-sm flex items-center justify-between">
                       <div className="flex items-center gap-4">
                          <div className="w-9 h-9 rounded-full bg-zinc-900 text-white flex items-center justify-center font-black text-[10px]">{u.name.charAt(0)}</div>
                          <div>
                             <p className="text-[11px] font-black text-zinc-900 uppercase tracking-tight">{u.name}</p>
                             <p className="text-[8px] font-black text-zinc-400 uppercase tracking-widest">{u.tier}</p>
                          </div>
                       </div>
                       <span className="text-[8px] font-black text-zinc-300 uppercase">{u.role}</span>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {tab === 'REQUESTS' && isOwner && (
            <div className="space-y-6 animate-in fade-in duration-500">
               {upgradeRequests.length > 0 ? upgradeRequests.filter(r => r.status === 'PENDING').map(req => (
                 <div key={req.id} className="p-6 bg-white border border-zinc-100 rounded-[2.5rem] shadow-sm space-y-4">
                    <div className="flex justify-between items-start">
                       <div><p className="text-[11px] font-black text-zinc-900 uppercase">{req.userName}</p><p className="text-[8px] text-zinc-400 font-bold uppercase">{req.userEmail}</p></div>
                       <span className="text-[7px] px-2 py-0.5 bg-amber-50 text-amber-600 rounded-full font-black uppercase">REQ: {req.requestedTier}</span>
                    </div>
                    <div className="p-3 bg-zinc-50 rounded-xl text-[9px] text-zinc-600 italic border border-zinc-100">"{req.message}"</div>
                    <div className="flex gap-2">
                       <button onClick={() => handleActionRequest(req.id, true)} className="flex-1 py-3 bg-zinc-900 text-white rounded-xl text-[8px] font-black uppercase">Approve</button>
                       <button onClick={() => handleActionRequest(req.id, false)} className="flex-1 py-3 border border-red-100 text-red-500 rounded-xl text-[8px] font-black uppercase">Deny</button>
                    </div>
                 </div>
               )) : (
                 <div className="py-20 text-center border-2 border-dashed border-zinc-100 rounded-[3rem] text-[9px] font-black text-zinc-200 uppercase">Queue Clear</div>
               )}
            </div>
          )}
        </div>

        <div className="shrink-0 p-8 border-t border-zinc-50 bg-white z-20">
          <button 
            onClick={() => { if(window.confirm("Purge thread context?")) { onClearHistory(); onClose(); } }}
            className="w-full py-5 rounded-[2rem] bg-zinc-900 text-white font-black uppercase text-[10px] tracking-[0.4em] active:scale-[0.98] transition-all shadow-xl flex items-center justify-center gap-3"
          >
            Establish New Thread
          </button>
        </div>
      </div>
    </div>
  );
};
